--
-- Name: add_tenant_note(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_tenant_note(p_tenant_id uuid, p_body text) RETURNS public.tenant_notes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.tenant_notes;
begin
  if not is_platform_admin() then
    raise exception 'PLATFORM_ADMIN_REQUIRED: Only platform admins can add company notes';
  end if;
  if not exists (select 1 from tenants where id = p_tenant_id) then
    raise exception 'tenant not found';
  end if;
  if length(btrim(coalesce(p_body, ''))) = 0 then
    raise exception 'Note cannot be blank';
  end if;

  insert into tenant_notes (tenant_id, author_id, author_email, body)
  values (
    p_tenant_id,
    auth.uid(),
    (select email from auth.users where id = auth.uid()),
    btrim(p_body)
  )
  returning * into v_row;
  return v_row;
end;
$$;


