--
-- Name: app_users_platform_admin_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_users_platform_admin_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_req_role text := platform_request_role();
  v_others   integer;
begin
  if v_req_role is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.is_platform_admin is not distinct from old.is_platform_admin then
    return new;
  end if;
  if tg_op = 'INSERT' and not new.is_platform_admin then
    return new;
  end if;

  -- Path 1: set_platform_admin() marks the transaction with the id it is
  -- changing. Anything else from an ordinary session is refused below.
  if current_setting('platform.admin_change', true) = new.id::text then
    return new;
  end if;

  if v_req_role = 'service_role' then
    if new.is_platform_admin then
      -- Path 2: bootstrap. Serialise concurrent claims and allow only
      -- while nobody holds the flag. Same errcode + constraint name the
      -- old partial unique index produced, so bootstrap-admin's existing
      -- 23505 handling keeps working unchanged.
      perform pg_advisory_xact_lock(hashtext('app_users_single_platform_admin'));
      select count(*) into v_others from app_users u where u.is_platform_admin and u.id <> new.id;
      if v_others > 0 then
        raise exception 'duplicate key value violates unique constraint "app_users_single_platform_admin": a platform admin already exists; further grants go through set_platform_admin()'
          using errcode = '23505';
      end if;
      return new;
    else
      select count(*) into v_others from app_users u where u.is_platform_admin and u.id <> new.id;
      if v_others = 0 then
        raise exception 'PLATFORM_LAST_ADMIN: cannot remove the only platform admin'
          using errcode = '23514';
      end if;
      return new;
    end if;
  end if;

  raise exception 'PLATFORM_ADMIN_GUARD: platform admin status is changed from the operator console (set_platform_admin), not by editing the user'
    using errcode = '42501';
end;
$$;


--
-- Name: apply_stock_movement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stock_movement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_delta numeric := CASE WHEN NEW.movement_type = 'in' THEN NEW.quantity ELSE -NEW.quantity END;
BEGIN
  INSERT INTO stock_balances (tenant_id, warehouse_id, material_catalog_id, material_name, unit, quantity_on_hand, updated_at)
  VALUES (NEW.tenant_id, NEW.warehouse_id, NEW.material_catalog_id, NEW.material_name, NEW.unit, v_delta, now())
  ON CONFLICT (warehouse_id, stock_key) DO UPDATE
    SET quantity_on_hand = stock_balances.quantity_on_hand + v_delta,
        updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: apply_template(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_template(p_tenant_id uuid, p_template_key text, p_mode text DEFAULT 'preview'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_write  boolean := (p_mode = 'fill');
begin
  perform require_platform_admin('Applying an industry template');

  if p_mode is null or p_mode not in ('preview', 'fill') then
    raise exception 'TEMPLATE_MODE_INVALID: mode must be preview or fill';
  end if;
  if not exists (select 1 from tenants where id = p_tenant_id) then
    raise exception 'TENANT_NOT_FOUND: no such company';
  end if;
  if not exists (select 1 from industry_templates where key = p_template_key and is_active) then
    raise exception 'TEMPLATE_NOT_FOUND: no active template %', p_template_key;
  end if;
  if v_write and coalesce(length(btrim(p_reason)), 0) < 5 then
    raise exception 'REASON_REQUIRED: give a reason (at least 5 characters) - it goes in the audit log';
  end if;

  v_result := platform_apply_template_items(
    p_tenant_id, p_template_key,
    array['module', 'department', 'feature_flag', 'gl_account', 'posting_rule'],
    v_write
  );

  if v_write then
    perform log_platform_event('tenant.template.apply', p_tenant_id, 'tenant', p_tenant_id::text, p_reason,
      null, jsonb_build_object('template', p_template_key, 'added', v_result - 'conflicts',
                               'conflicts', v_result -> 'conflicts'));
  end if;

  return v_result || jsonb_build_object('mode', p_mode, 'template', p_template_key, 'applied', v_write);
end;
$$;


--
-- Name: apply_tenant_read_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_tenant_read_only_guard() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_count integer := 0;
begin
  for r in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    join pg_attribute a on a.attrelid = c.oid and a.attname = 'tenant_id' and not a.attisdropped
    where n.nspname = 'public'
      and c.relkind = 'r'
      and c.relname not in (
        'platform_audit_events', 'impersonation_sessions', 'impersonation_logs', 'tenant_notes',
        'notifications',
        'app_users',
        'platform_digests',
        'platform_job_runs'
      )
  loop
    execute format('drop trigger if exists tenant_read_only_guard on public.%I', r.relname);
    execute format(
      'create trigger tenant_read_only_guard before insert or update or delete on public.%I '
      'for each row execute function public.tenant_read_only_guard()',
      r.relname
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


--
-- Name: apply_workflow_template(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_workflow_template(p_tenant_id uuid, p_template_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_open   integer;
  v_before jsonb;
  v_n      integer;
begin
  perform require_platform_admin('Applying a workflow template');
  if coalesce(length(btrim(p_reason)), 0) < 5 then
    raise exception 'REASON_REQUIRED: give a reason (at least 5 characters) - it goes in the audit log';
  end if;
  if not exists (select 1 from industry_templates where key = p_template_key and is_active) then
    raise exception 'TEMPLATE_NOT_FOUND: no active template %', p_template_key;
  end if;

  select count(*) into v_open
  from requests r
  where r.tenant_id = p_tenant_id and r.status = 'open' and r.current_stage_id is not null;
  if v_open > 0 then
    raise exception 'WORKFLOW_IN_USE: % open request(s) are mid-approval - wait for them to finish or cancel them first', v_open;
  end if;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.sequence_order), '[]'::jsonb) into v_before
  from workflow_stages s where s.tenant_id = p_tenant_id and s.applies_to = 'requests';

  -- Retire the old pipeline rather than deleting: history rows
  -- (approvals, request_stage_events) still reference the ids.
  update workflow_stages set is_active = false where tenant_id = p_tenant_id and applies_to = 'requests' and is_active;
  v_n := platform_seed_workflow_from_template(p_tenant_id, p_template_key, 'requests');

  perform log_platform_event('tenant.workflow.apply_template', p_tenant_id, 'tenant', p_tenant_id::text, p_reason,
    jsonb_build_object('stages', v_before),
    jsonb_build_object('template', p_template_key, 'stages_created', v_n));

  return jsonb_build_object('stages_created', v_n, 'stages_retired', jsonb_array_length(v_before));
end;
$$;


