--
-- Name: approve_all_material_request_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_all_material_request_items(p_batch_id uuid) RETURNS SETOF public.material_catalog
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  for v_item_id in
    select id from material_request_items
    where batch_id = p_batch_id and tenant_id = get_my_tenant_id() and status = 'pending'
  loop
    return next approve_material_request_item(v_item_id);
  end loop;
end;
$$;


