--
-- Name: approve_line_item_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_line_item_receipt(p_receipt_id uuid) RETURNS public.line_item_receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row line_item_receipts%ROWTYPE;
BEGIN
  IF NOT is_finance_team_member(NULL) THEN
    RAISE EXCEPTION 'not authorized to approve a goods receipt';
  END IF;

  UPDATE line_item_receipts
  SET approved_by = auth.uid(), approved_at = now()
  WHERE id = p_receipt_id
    AND EXISTS (
      SELECT 1 FROM request_line_items rli JOIN requests r ON r.id = rli.request_id
      WHERE rli.id = line_item_receipts.line_item_id AND r.tenant_id = get_my_tenant_id()
    )
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'receipt not found';
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: approve_material_request_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_material_request_item(p_item_id uuid) RETURNS public.material_catalog
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item material_request_items%rowtype;
  v_batch material_request_batches%rowtype;
  v_catalog material_catalog%rowtype;
begin
  if not has_po_access() then
    raise exception 'not authorized to approve material requests';
  end if;

  select * into v_item from material_request_items
  where id = p_item_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'material request item not found';
  end if;

  if v_item.status <> 'pending' then
    raise exception 'this item has already been decided';
  end if;

  insert into material_catalog (
    tenant_id, name, code, unit, material_type_id, material_group_id,
    external_material_group_id, description_tr, description_en, description_fr,
    old_material_code, is_active
  )
  values (
    v_item.tenant_id, v_item.name, next_material_catalog_code(v_item.tenant_id), v_item.unit,
    v_item.material_type_id, v_item.material_group_id, v_item.external_material_group_id,
    v_item.description_tr, v_item.description_en, v_item.description_fr,
    v_item.old_material_code, true
  )
  returning * into v_catalog;

  update material_request_items
  set status = 'approved', material_catalog_id = v_catalog.id, decided_by = auth.uid(), decided_at = now()
  where id = p_item_id;

  select * into v_batch from material_request_batches where id = v_item.batch_id;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    v_item.tenant_id, v_batch.requester_id, 'material_request_approved',
    'Material request approved',
    format('"%s" was approved and added to the material catalog as %s.', v_item.name, v_catalog.code)
  );

  return v_catalog;
end;
$$;


--
-- Name: hr_payroll_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_payroll_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    period text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    prepared_by uuid NOT NULL,
    submitted_at timestamp with time zone,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_reason text,
    amount_disbursed numeric DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    effective_user_id uuid,
    impersonation_session_id uuid,
    CONSTRAINT hr_payroll_runs_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'disbursed'::text])))
);


--
-- Name: approve_payroll_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payroll_run(p_run_id uuid) RETURNS public.hr_payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row       hr_payroll_runs%rowtype;
  v_effective uuid := effective_user_id();
  v_session   uuid;
begin
  if not is_payroll_approver() then
    raise exception 'not authorized to approve payroll';
  end if;
  if exists (select 1 from hr_payroll_runs where id = p_run_id and tenant_id = get_my_tenant_id()
             and (prepared_by = v_effective or prepared_by = auth.uid())) then
    raise exception 'the preparer of a payroll run cannot approve it';
  end if;

  select id into v_session from impersonation_sessions
  where platform_admin_id = auth.uid() and ended_at is null and expires_at > now()
  order by started_at desc limit 1;

  update hr_payroll_runs
  set status = 'approved', approved_by = auth.uid(), approved_at = now(),
      effective_user_id = v_effective, impersonation_session_id = v_session
  where id = p_run_id and tenant_id = get_my_tenant_id() and status = 'pending_approval'
  returning * into v_row;

  if v_row.id is null then
    raise exception 'payroll run not found, or not pending approval';
  end if;

  if v_row.prepared_by is not null then
    insert into notifications (tenant_id, recipient_id, type, title, body)
    values (v_row.tenant_id, v_row.prepared_by, 'payroll_run_approved', 'Payroll run approved: ' || v_row.period,
            format('The %s payroll run has been approved.', v_row.period));
  end if;

  return v_row;
end;
$$;


--
-- Name: assert_tenant_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_tenant_access(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Trusted contexts (service_role, cron, owner connections) have no user session.
  -- Client-facing API roles (anon, authenticated) never legitimately lack one: an
  -- anonymous session, or an `authenticated` token without a `sub`, would otherwise
  -- look like a trusted context. Refuse both explicitly rather than relying only on
  -- the EXECUTE grants (defence in depth).
  if auth.uid() is null then
    if current_setting('role', true) in ('anon', 'authenticated') then
      raise exception 'not authorized to generate numbers'
        using errcode = '42501';
    end if;
    return;
  end if;

  if p_tenant_id is not null
     and p_tenant_id is not distinct from public.get_my_tenant_id() then
    return;
  end if;

  -- Platform admin acting as themselves (not impersonating a user).
  if public.platform_admin_bypass() then
    return;
  end if;

  raise exception 'not authorized to generate numbers for this tenant'
    using errcode = '42501';
end;
$$;


