--
-- Name: assign_ticket(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_ticket(p_ticket_id uuid, p_assignee_id uuid DEFAULT NULL::uuid) RETURNS public.it_tickets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ticket public.it_tickets%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to assign tickets';
  end if;

  select * into v_ticket from it_tickets where id = p_ticket_id for update;
  if not found then
    raise exception 'ticket not found';
  end if;
  if v_ticket.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this ticket';
  end if;
  if v_ticket.approval_status = 'pending' then
    raise exception 'ticket is awaiting approval and cannot be assigned yet';
  end if;

  if p_assignee_id is not null and not exists (
    select 1 from app_users u
    where u.id = p_assignee_id
      and (
        coalesce(u.is_platform_admin, false)
        or exists (
          select 1 from departments d
          where d.id = u.department_id and d.name = 'IT Support'
        )
      )
  ) then
    raise exception 'assignee must be IT Support staff';
  end if;

  update it_tickets
  set assignee_id = p_assignee_id,
      status = case when status = 'open' and p_assignee_id is not null then 'in_progress' else status end,
      updated_at = now()
  where id = p_ticket_id
  returning * into v_ticket;

  if p_assignee_id is not null then
    insert into notifications (tenant_id, recipient_id, type, title, body)
    values (
      v_ticket.tenant_id,
      p_assignee_id,
      'ticket_assigned',
      'Ticket ' || v_ticket.ticket_number || ' assigned to you',
      format('"%s" has been assigned to you.', v_ticket.subject)
    );
  end if;

  return v_ticket;
end;
$$;


--
-- Name: auto_match_bank_statement(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_match_bank_statement(p_bank_account text, p_date_from date, p_date_to date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare tid uuid:=get_my_tenant_id(); line record; n integer; src text; candidate uuid; matched integer:=0;
begin
  if not is_finance_team_member('finance') then raise exception 'not authorized to auto-match bank transactions'; end if;
  for line in select l.id from bank_statement_lines l left join bank_reconciliations r on r.bank_statement_line_id=l.id
    where l.tenant_id=tid and l.bank_account=p_bank_account and l.statement_date between p_date_from and p_date_to
      and r.id is null order by l.statement_date,l.imported_at,l.id
  loop
    select count(*),min(c.source),(array_agg(c.candidate_id))[1] into n,src,candidate
      from fin_bank_line_candidates(line.id,tid) c;
    if n<>1 then continue; end if;
    if src='settlement' and exists(select 1 from fin_allocations a join ins_policy_cash_items i on i.id=a.open_item_id
      where a.settlement_id=candidate and i.source_type in ('ins_policy_premium','ins_policy_insurer')) then
      if effective_user_id() is distinct from auth.uid() or auth.uid() is null
        or exists(select 1 from fin_settlements s where s.id=candidate and s.created_by=auth.uid())
        or exists(select 1 from ins_policy_cash_requests q where q.settlement_id=candidate
                    and auth.uid() in (q.maker_id,q.checker_id)) then continue; end if;
    end if;
    if src='settlement' and exists(select 1 from ins_cancellation_cash_requests q where candidate in(q.settlement_id,q.to_settlement_id) and (effective_user_id() is distinct from auth.uid() or auth.uid() in(q.maker_id,q.checker_id))) then continue; end if;
    if src='settlement' then
      insert into bank_reconciliations(tenant_id,bank_statement_line_id,settlement_id,match_type,variance,matched_by)
        values(tid,line.id,candidate,'auto',0,auth.uid());
    elsif src in ('transfer_from','transfer_to') then
      insert into bank_reconciliations(tenant_id,bank_statement_line_id,commission_transfer_id,transfer_side,match_type,variance,matched_by)
        values(tid,line.id,candidate,substr(src,10),'auto',0,auth.uid());
    else
      insert into bank_reconciliations(tenant_id,bank_statement_line_id,cash_bank_transaction_id,match_type,variance,matched_by)
        values(tid,line.id,candidate,'auto',0,auth.uid());
    end if;
    matched:=matched+1;
  end loop;
  return matched;
end $$;


--
-- Name: bd_pipeline_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bd_pipeline_summary() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with params as (
    select get_my_tenant_id() as tenant_id
    where has_module_role('bd', array['admin', 'manager', 'member'])
  ), stages as (
    select s.stage, s.label, s.color, s.order_index, s.probability_default
    from bd_opportunity_stages s, params p
    where s.tenant_id = p.tenant_id and s.is_active
  ), opps as (
    select o.*
    from bd_opportunities o, params p
    where o.tenant_id = p.tenant_id
  ), agg as (
    select
      s.stage, s.label, s.color, s.order_index,
      count(o.id) as count,
      coalesce(sum(coalesce(o.estimated_value, 0)), 0) as total,
      coalesce(sum(coalesce(o.estimated_value, 0) * coalesce(o.probability, s.probability_default)::numeric / 100), 0) as weighted,
      case when count(o.id) = 0 then null
           else round(avg(coalesce(o.probability, s.probability_default)))
      end as avg_probability
    from stages s
    left join opps o on o.stage = s.stage
    group by s.stage, s.label, s.color, s.order_index
  )
  select jsonb_build_object(
    'stages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'stage', a.stage, 'label', a.label, 'color', a.color,
          'order_index', a.order_index, 'count', a.count,
          'total', a.total, 'weighted', a.weighted,
          'avg_probability', a.avg_probability)
        order by a.order_index)
      from agg a), '[]'::jsonb),
    'totals', (
      select jsonb_build_object(
        'count', coalesce(sum(a.count), 0), 'total', coalesce(sum(a.total), 0),
        'weighted', coalesce(sum(a.weighted), 0))
      from agg a)
  )
$$;


--
-- Name: calculate_statutory_deductions(numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_statutory_deductions(p_gross numeric, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS TABLE(paye_amount numeric, nssf_employee numeric, nssf_employer numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_paye numeric := 0;
  v_nssf_employee_rate numeric;
  v_nssf_employer_rate numeric;
  v_band record;
begin
  select rt.rate, rt.base_tax, rt.lower_bound into v_band
  from statutory_rate_tables rt
  where rt.tenant_id = v_tenant_id
    and rt.rate_type = 'paye'
    and rt.effective_date <= p_as_of_date
    and p_gross > rt.lower_bound
    and (rt.upper_bound is null or p_gross <= rt.upper_bound)
  order by rt.effective_date desc, rt.band_order desc
  limit 1;

  if found then
    v_paye := v_band.base_tax + (p_gross - v_band.lower_bound) * v_band.rate / 100;
  end if;

  select rate into v_nssf_employee_rate
  from statutory_rate_tables
  where tenant_id = v_tenant_id and rate_type = 'nssf_employee' and effective_date <= p_as_of_date
  order by effective_date desc limit 1;

  select rate into v_nssf_employer_rate
  from statutory_rate_tables
  where tenant_id = v_tenant_id and rate_type = 'nssf_employer' and effective_date <= p_as_of_date
  order by effective_date desc limit 1;

  return query select
    round(coalesce(v_paye, 0), 2),
    round(p_gross * coalesce(v_nssf_employee_rate, 0) / 100, 2),
    round(p_gross * coalesce(v_nssf_employer_rate, 0) / 100, 2);
end;
$$;


