--
-- Name: cancel_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_request(p_request_id uuid, p_reason text) RETURNS TABLE(out_request_id uuid, out_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request      requests%ROWTYPE;
  v_is_requester boolean;
  v_can_act      boolean;
BEGIN
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'a reason is required to cancel a request';
  END IF;

  SELECT * INTO v_request FROM requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request not found';
  END IF;
  IF v_request.tenant_id != get_my_tenant_id() THEN
    RAISE EXCEPTION 'not authorized for this request';
  END IF;
  IF v_request.status != 'open' THEN
    RAISE EXCEPTION 'only open requests can be cancelled (status: %)', v_request.status;
  END IF;

  v_is_requester := v_request.requester_id = auth.uid();
  v_can_act := v_request.current_stage_id IS NOT NULL AND can_act_on_stage(v_request.current_stage_id);

  IF NOT (v_is_requester OR v_can_act) THEN
    RAISE EXCEPTION 'not authorized to cancel this request';
  END IF;

  -- Audit trail, reusing approval_actions rather than a new table --
  -- same shape as an approve/reject decision, just a different
  -- decision value.
  INSERT INTO approval_actions
    (request_id, workflow_stage_id, approver_id, decision, comment)
  VALUES
    (p_request_id, v_request.current_stage_id, auth.uid(), 'cancelled', p_reason);

  UPDATE requests
  SET status = 'cancelled', current_stage_id = NULL, updated_at = now()
  WHERE id = p_request_id;

  IF v_is_requester THEN
    -- Requester withdrew it -- notify whoever currently held it.
    INSERT INTO notifications (tenant_id, recipient_id, type, title, body, request_id)
    SELECT DISTINCT
      v_request.tenant_id,
      recipient_id,
      'request_cancelled',
      'Request withdrawn',
      format('Request "%s" was withdrawn by the requester: %s', v_request.item_description, p_reason),
      p_request_id
    FROM (
      SELECT aa.user_id AS recipient_id
      FROM approval_assignments aa
      WHERE aa.workflow_stage_id = v_request.current_stage_id

      UNION

      SELECT d.delegate_user_id AS recipient_id
      FROM approval_delegations d
      JOIN approval_assignments aa ON aa.user_id = d.delegator_user_id
      WHERE d.status = 'active'
        AND now() BETWEEN d.starts_at AND d.ends_at
        AND aa.workflow_stage_id = v_request.current_stage_id
        AND (d.workflow_stage_id IS NULL OR d.workflow_stage_id = v_request.current_stage_id)
    ) recipients;
  ELSE
    -- An approver/assignee cancelled it -- notify the requester.
    INSERT INTO notifications (tenant_id, recipient_id, type, title, body, request_id)
    VALUES (
      v_request.tenant_id,
      v_request.requester_id,
      'request_cancelled',
      'Request cancelled',
      format('Your request "%s" was cancelled: %s', v_request.item_description, p_reason),
      p_request_id
    );
  END IF;

  RETURN QUERY SELECT p_request_id, 'cancelled'::text;
END;
$$;


--
-- Name: check_accounting_period_no_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_accounting_period_no_overlap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1 from accounting_periods
    where tenant_id = new.tenant_id
      and id != new.id
      and period_start <= new.period_end
      and period_end >= new.period_start
  ) then
    raise exception 'accounting period % to % overlaps an existing period for this tenant', new.period_start, new.period_end;
  end if;
  return new;
end;
$$;


--
-- Name: check_journal_entry_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_journal_entry_balanced() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_entry_id   uuid;
  v_tenant     uuid;
  v_diff       numeric;
  v_base       numeric;
  v_currencies integer;
  v_foreign    integer;
  v_tolerance  numeric;
  v_account    uuid;
begin
  v_entry_id := coalesce(new.journal_entry_id, old.journal_entry_id);
  v_tenant   := coalesce(new.tenant_id, old.tenant_id);

  select coalesce(sum(debit), 0) - coalesce(sum(credit), 0),
         coalesce(sum(base_debit), 0) - coalesce(sum(base_credit), 0),
         count(distinct currency),
         count(*) filter (where fx_rate <> 1)
    into v_diff, v_base, v_currencies, v_foreign
    from journal_entry_lines
   where journal_entry_id = v_entry_id;

  -- One currency on every line: balance in that currency, message unchanged.
  if v_currencies <= 1 and v_diff <> 0 then
    raise exception 'journal entry % is not balanced (debit-credit = %)', v_entry_id, v_diff;
  end if;

  if v_base <> 0 then
    -- Most that per-line rounding to 2 places can leave: half a cent per foreign line.
    v_tolerance := ceil(v_foreign * 0.5) * 0.01;
    if v_foreign = 0 or abs(v_base) > v_tolerance then
      raise exception 'JOURNAL_BASE_UNBALANCED: journal entry % does not balance in base currency (difference %)', v_entry_id, v_base;
    end if;

    select gl_account_id into v_account
      from gl_posting_rules
     where tenant_id = v_tenant and account_role = 'fx_rounding';
    if v_account is null then
      raise exception 'JOURNAL_ROUNDING_ACCOUNT_MISSING: journal entry % differs by % in base currency from rounding, and this company has no fx_rounding account under posting rules', v_entry_id, v_base;
    end if;

    perform set_config('fin.rounding_line', 'on', true);
    insert into journal_entry_lines
      (journal_entry_id, tenant_id, gl_account_id, debit, credit, currency, description)
    values
      (v_entry_id, v_tenant, v_account,
       greatest(-v_base, 0), greatest(v_base, 0),
       fin_ledger_currency(v_tenant), 'Base-currency rounding');
    perform set_config('fin.rounding_line', 'off', true);
  end if;

  return null;
end;
$$;


--
-- Name: check_payment_against_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_payment_against_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cap numeric;
  v_already_paid numeric;
  v_invoice supplier_invoices%ROWTYPE;
BEGIN
  IF NEW.reference_type != 'supplier_invoice' OR NEW.transaction_type != 'payment' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_invoice FROM supplier_invoices WHERE id = NEW.reference_id;
  IF NOT FOUND THEN
    RETURN NEW; -- unrelated reference_id / bad data -- not this trigger's job to police
  END IF;

  IF v_invoice.purchase_order_id IS NULL THEN
    RETURN NEW; -- non-PO invoice: no goods-receipt trail to match against
  END IF;

  v_cap := supplier_invoice_receipt_cap(v_invoice.id);
  v_already_paid := v_invoice.amount_incl_vat - supplier_invoice_outstanding(v_invoice.id);

  IF v_already_paid + NEW.amount > v_cap + 0.01 THEN -- small epsilon for rounding
    RAISE EXCEPTION
      'payment blocked: only % of % has been confirmed received for this invoice (already paid %, this payment %)',
      round(v_cap, 2), v_invoice.amount_incl_vat, round(v_already_paid, 2), NEW.amount;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: check_payroll_disbursement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_payroll_disbursement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_run hr_payroll_runs%ROWTYPE;
  v_total_net numeric;
BEGIN
  IF NEW.reference_type != 'payroll_run' OR NEW.transaction_type != 'payment' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_run FROM hr_payroll_runs WHERE id = NEW.reference_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF v_run.status NOT IN ('approved', 'disbursed') THEN
    RAISE EXCEPTION 'payroll run must be approved before it can be disbursed';
  END IF;

  SELECT COALESCE(SUM(net_pay), 0) INTO v_total_net FROM hr_payroll_items WHERE payroll_run_id = v_run.id;

  IF v_run.amount_disbursed + NEW.amount > v_total_net + 0.01 THEN
    RAISE EXCEPTION
      'payment blocked: run total is %, already disbursed %, this payment %',
      round(v_total_net, 2), round(v_run.amount_disbursed, 2), NEW.amount;
  END IF;

  UPDATE hr_payroll_runs
  SET amount_disbursed = amount_disbursed + NEW.amount,
      status = CASE WHEN amount_disbursed + NEW.amount >= v_total_net - 0.01 THEN 'disbursed' ELSE 'approved' END
  WHERE id = v_run.id;

  RETURN NEW;
END;
$$;


