    client_name text,
    status text DEFAULT 'not_started'::text NOT NULL,
    budget numeric,
    currency text DEFAULT 'USD'::text NOT NULL,
    start_date date,
    end_date date,
    manager_id uuid,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT pmo_projects_status_check CHECK ((status = ANY (ARRAY['not_started'::text, 'pending_approval'::text, 'in_progress'::text, 'on_hold'::text, 'completed'::text, 'cancelled'::text, 'rejected'::text])))
);


--
-- Name: decide_pmo_project(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_pmo_project(p_project_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS public.pmo_projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project public.pmo_projects%rowtype;
begin
  if not has_module_role('pmo', array['admin', 'manager']) then
    raise exception 'not authorized: project approval requires a pmo admin or manager role';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'p_decision must be ''approved'' or ''rejected''';
  end if;

  if p_decision = 'rejected' and (p_notes is null or btrim(p_notes) = '') then
    raise exception 'rejection requires notes explaining why';
  end if;

  select * into v_project from pmo_projects
  where id = p_project_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'project not found in this tenant';
  end if;
  if v_project.status <> 'pending_approval' then
    raise exception 'only projects pending approval can be decided (current status: %)', v_project.status;
  end if;

  -- Separation of duties: the originator of a project must not be the one
  -- approving its budget/resources, even with an approver role.
  if v_project.created_by is not null and v_project.created_by = auth.uid() then
    raise exception 'you cannot decide a project you created -- another pmo admin/manager must approve it';
  end if;

  update pmo_projects
  set status = case p_decision when 'approved' then 'in_progress' else 'rejected' end,
      updated_at = now()
  where id = v_project.id
  returning * into v_project;

  insert into pmo_project_decisions (tenant_id, project_id, decision, decided_by, notes)
  values (v_project.tenant_id, v_project.id, p_decision, auth.uid(), nullif(btrim(coalesce(p_notes, '')), ''));

  if v_project.created_by is not null then
    insert into notifications (tenant_id, recipient_id, type, title, body)
    values (
      v_project.tenant_id,
      v_project.created_by,
      'pmo_project_' || p_decision,
      (case p_decision when 'approved' then 'Project approved: ' else 'Project rejected: ' end) || v_project.project_no,
      case p_decision
        when 'approved' then format('Project "%s" (%s) has been approved and is now in progress.', v_project.name, v_project.project_no)
        else format('Project "%s" (%s) was rejected.%s', v_project.name, v_project.project_no,
                    case when nullif(btrim(coalesce(p_notes, '')), '') is not null
                         then ' Reason: ' || btrim(p_notes) else '' end)
      end
    );
  end if;

  return v_project;
end;
$$;


--
-- Name: delete_empty_tenant(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_empty_tenant(p_tenant_id uuid, p_confirm_name text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_tenant public.tenants;
  v_reason text := nullif(btrim(p_reason), '');
  v_has    boolean;
  r        record;
  -- Seeded at company creation or pure operator metadata; safe to cascade.
  v_seed   text[] := array[
    'gl_accounts', 'gl_posting_rules', 'departments', 'tenant_modules',
    'tenant_notes', 'tenant_feature_flags', 'platform_announcements',
    'platform_job_runs', 'platform_audit_events', 'doc_sequences',
    'workflow_stages'
  ];
begin
  perform require_platform_admin('Deleting a company');

  select * into v_tenant from tenants where id = p_tenant_id for update;
  if not found then
    raise exception 'tenant not found';
  end if;

  if btrim(coalesce(p_confirm_name, '')) is distinct from v_tenant.name then
    raise exception 'Confirmation name does not match the company name';
  end if;

  for r in
    select distinct c.conrelid::regclass::text as tbl
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
    where c.contype = 'f'
      and c.confrelid = 'public.tenants'::regclass
      and a.attname = 'tenant_id'
      and c.conrelid::regclass::text <> all (v_seed)
    order by 1
  loop
    execute format('select exists (select 1 from %s where tenant_id = $1)', r.tbl)
      into v_has using p_tenant_id;
    if v_has then
      if r.tbl = 'invitations' then
        raise exception 'This company still has invitations. Revoke them first, then delete.';
      elsif r.tbl = 'app_users' then
        raise exception 'This company has users, so it cannot be deleted. Suspend it instead.';
      end if;
      raise exception 'This company has data in "%" so it cannot be deleted. Suspend it instead.', r.tbl;
    end if;
  end loop;

  perform log_platform_event(
    'tenant.delete', null, 'tenant', p_tenant_id::text, v_reason,
    jsonb_build_object(
      'tenant_name', v_tenant.name,
      'status', v_tenant.status,
      'created_at', v_tenant.created_at
    ),
    null
  );

  delete from tenants where id = p_tenant_id;
end;
$_$;


--
-- Name: delete_feature_flag(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_feature_flag(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb;
begin
  perform require_platform_admin('Deleting feature flags');
  select to_jsonb(f) into v_before from platform_feature_flags f where f.key = p_key;
  if v_before is null then return; end if;
  delete from platform_feature_flags where key = p_key;
  perform log_platform_event('feature_flag.delete', null, 'feature_flag', p_key, null, v_before, null);
end;
$$;


--
-- Name: delete_industry_template(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_industry_template(p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb;
begin
  perform require_platform_admin('Deleting an industry template');
  if exists (select 1 from tenants where industry_template = p_key) then
    raise exception 'TEMPLATE_IN_USE: companies were created from this template - deactivate it instead of deleting';
  end if;
  if exists (select 1 from industry_templates where key = p_key and is_default) then
    raise exception 'TEMPLATE_IS_DEFAULT: choose another default first';
  end if;
  select to_jsonb(t) into v_before from industry_templates t where t.key = p_key;
  if v_before is null then return; end if;
  delete from industry_templates where key = p_key;
  perform log_platform_event('industry_template.delete', null, 'industry_template', p_key, null, v_before, null);
end;
$$;


--
-- Name: delete_platform_announcement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_platform_announcement(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb;
begin
  perform require_platform_admin('Deleting announcements');
  select to_jsonb(a) into v_before from platform_announcements a where a.id = p_id;
  if v_before is null then return; end if;
  delete from platform_announcements where id = p_id;
  perform log_platform_event('announcement.delete', (v_before ->> 'tenant_id')::uuid, 'announcement', p_id::text, null, v_before, null);
end;
$$;


--
-- Name: dismiss_announcement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_announcement(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from platform_announcements a where a.id = p_id and a.dismissible and a.severity <> 'critical') then
    raise exception 'ANNOUNCEMENT_NOT_DISMISSIBLE';
  end if;
  insert into platform_announcement_dismissals (announcement_id, user_id)
  values (p_id, auth.uid())
  on conflict do nothing;
end;
$$;


--
-- Name: documents_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.documents_via_rpc() then
    raise exception 'DOCUMENTS_RPC_ONLY: register documents with documents_register()' using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;


--
-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    doc_kind text DEFAULT 'attachment'::text NOT NULL,
    bucket text NOT NULL,
    path text NOT NULL,
    file_name text NOT NULL,
    mime_type text DEFAULT 'application/pdf'::text NOT NULL,
    byte_size bigint NOT NULL,
    content_hash text NOT NULL,
    template_code text,
    template_version integer,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT documents_byte_size_check CHECK ((byte_size >= 0)),
    CONSTRAINT documents_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: documents_register(text, uuid, text, text, text, text, bigint, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_register(p_entity_type text, p_entity_id uuid, p_bucket text, p_path text, p_file_name text, p_content_hash text, p_byte_size bigint, p_mime_type text DEFAULT 'application/pdf'::text, p_doc_kind text DEFAULT 'attachment'::text, p_template_code text DEFAULT NULL::text, p_template_version integer DEFAULT NULL::integer) RETURNS public.documents
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_tenant uuid := public.get_my_tenant_id();
  v_row    public.documents;
begin
  if v_tenant is null then
    raise exception 'DOCUMENTS_NO_TENANT: caller has no tenant' using errcode = '42501';
  end if;
  if p_entity_type is null or btrim(p_entity_type) = '' then
    raise exception 'DOCUMENTS_ENTITY: entity type is required' using errcode = 'P0001';
  end if;
  if p_entity_id is null then
    raise exception 'DOCUMENTS_ENTITY: entity id is required' using errcode = 'P0001';
  end if;
  if p_bucket is distinct from 'tenant-documents' then
    raise exception 'DOCUMENTS_BUCKET: documents live in the tenant-documents bucket' using errcode = 'P0001';
  end if;
  if p_path is null or (storage.foldername(p_path))[1] is distinct from v_tenant::text then
    raise exception 'DOCUMENTS_PATH: path must live in the caller''s tenant folder' using errcode = 'P0001';
  end if;
  if p_file_name is null or btrim(p_file_name) = '' then
    raise exception 'DOCUMENTS_NAME: file name is required' using errcode = 'P0001';
  end if;
  if p_content_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'DOCUMENTS_HASH: content hash must be lower-case sha-256 hex' using errcode = 'P0001';
  end if;
  if p_byte_size is null or p_byte_size < 0 then
    raise exception 'DOCUMENTS_SIZE: byte size must be zero or more' using errcode = 'P0001';
  end if;
  if p_doc_kind is null or btrim(p_doc_kind) = '' then
    raise exception 'DOCUMENTS_KIND: doc kind is required' using errcode = 'P0001';
  end if;

  perform set_config('documents.via_rpc', 'on', true);
  insert into public.documents (
    tenant_id, entity_type, entity_id, doc_kind, bucket, path, file_name,
    mime_type, byte_size, content_hash, template_code, template_version, created_by
  ) values (
    v_tenant, p_entity_type, p_entity_id, p_doc_kind, p_bucket, p_path,
    btrim(p_file_name), coalesce(p_mime_type, 'application/pdf'), p_byte_size,
    p_content_hash, p_template_code, p_template_version, auth.uid()
  )
  returning * into v_row;
  perform set_config('documents.via_rpc', 'off', true);
  return v_row;
end;
$_$;


--
-- Name: documents_via_rpc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.documents_via_rpc() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(current_setting('documents.via_rpc', true), '') = 'on';
$$;


--
-- Name: po_edits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.po_edits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    purchase_order_id uuid NOT NULL,
    edited_by uuid NOT NULL,
    edited_at timestamp with time zone DEFAULT now() NOT NULL,
    reason text NOT NULL,
    changes jsonb NOT NULL
);


--
-- Name: edit_purchase_order(uuid, text, numeric, text, text, text, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_purchase_order(p_purchase_order_id uuid, p_vendor_name text, p_amount numeric, p_reason text, p_initial_po_number text DEFAULT NULL::text, p_currency text DEFAULT NULL::text, p_delivery_date date DEFAULT NULL::date, p_project_sap_no text DEFAULT NULL::text, p_payment_conditions text DEFAULT NULL::text, p_terms_of_delivery text DEFAULT NULL::text) RETURNS public.po_edits
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_po      purchase_orders%rowtype;
  v_request requests%rowtype;
  v_changes jsonb := '{}'::jsonb;
  v_edit    po_edits%rowtype;
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required for every PO edit';
  end if;
  if p_vendor_name is null or btrim(p_vendor_name) = '' then
    raise exception 'vendor name cannot be empty';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be greater than zero';
  end if;

  select po.* into v_po
  from purchase_orders po
  join requests r on r.id = po.request_id
  where po.id = p_purchase_order_id
    and r.tenant_id = get_my_tenant_id()
  for update of po;

  if not found then
    raise exception 'purchase order not found';
  end if;
  if not has_po_access() then
    raise exception 'not authorized to edit purchase orders';
  end if;

  select * into v_request from requests where id = v_po.request_id;

  if p_vendor_name is distinct from v_po.vendor_name then
    v_changes := v_changes || jsonb_build_object(
      'vendor_name', jsonb_build_object('old', v_po.vendor_name, 'new', p_vendor_name)
    );
  end if;
  if p_amount is distinct from v_po.amount then
    v_changes := v_changes || jsonb_build_object(
      'amount', jsonb_build_object('old', v_po.amount, 'new', p_amount)
    );
  end if;
  if p_initial_po_number is not null and p_initial_po_number is distinct from v_po.initial_po_number then
    v_changes := v_changes || jsonb_build_object(
      'initial_po_number', jsonb_build_object('old', v_po.initial_po_number, 'new', p_initial_po_number)
    );
  end if;
  if p_currency is not null and p_currency is distinct from v_po.currency then
    v_changes := v_changes || jsonb_build_object(
      'currency', jsonb_build_object('old', v_po.currency, 'new', p_currency)
    );
  end if;
  if p_delivery_date is not null and p_delivery_date is distinct from v_request.delivery_date then
    v_changes := v_changes || jsonb_build_object(
      'delivery_date', jsonb_build_object('old', v_request.delivery_date, 'new', p_delivery_date)
    );
  end if;
  if p_project_sap_no is not null and p_project_sap_no is distinct from v_po.project_sap_no then
    v_changes := v_changes || jsonb_build_object(
      'project_sap_no', jsonb_build_object('old', v_po.project_sap_no, 'new', p_project_sap_no)
    );
  end if;
  if p_payment_conditions is not null and p_payment_conditions is distinct from v_po.payment_conditions then
    v_changes := v_changes || jsonb_build_object(
      'payment_conditions', jsonb_build_object('old', v_po.payment_conditions, 'new', p_payment_conditions)
    );
  end if;
  if p_terms_of_delivery is not null and p_terms_of_delivery is distinct from v_po.terms_of_delivery then
    v_changes := v_changes || jsonb_build_object(
      'terms_of_delivery', jsonb_build_object('old', v_po.terms_of_delivery, 'new', p_terms_of_delivery)
    );
  end if;

  if v_changes = '{}'::jsonb then
    raise exception 'nothing has changed -- update a field, or cancel';
  end if;

  insert into po_edits (purchase_order_id, edited_by, reason, changes)
  values (p_purchase_order_id, auth.uid(), p_reason, v_changes)
  returning * into v_edit;

  -- Open the narrow escape hatch just for this statement, then update.
  perform set_config('vestateck.allow_po_financial_edit', 'on', true);
  update purchase_orders
  set
    vendor_name = p_vendor_name,
    amount = p_amount,
    initial_po_number = coalesce(p_initial_po_number, initial_po_number),
    currency = coalesce(p_currency, currency),
    project_sap_no = coalesce(p_project_sap_no, project_sap_no),
    payment_conditions = coalesce(p_payment_conditions, payment_conditions),
    terms_of_delivery = coalesce(p_terms_of_delivery, terms_of_delivery)
  where id = p_purchase_order_id;
  perform set_config('vestateck.allow_po_financial_edit', 'off', true);

  if p_delivery_date is not null then
    update requests set delivery_date = p_delivery_date, updated_at = now() where id = v_po.request_id;
  end if;

  return v_edit;
end;
$$;


--
-- Name: effective_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effective_user_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(impersonated_user_id(), auth.uid());
$$;


--
-- Name: end_impersonation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_impersonation() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_session impersonation_sessions%rowtype;
begin
  select * into v_session
  from impersonation_sessions
  where platform_admin_id = auth.uid() and ended_at is null
  order by started_at desc
  limit 1;

  update impersonation_sessions
  set ended_at = now()
  where platform_admin_id = auth.uid() and ended_at is null;

  insert into impersonation_logs (platform_admin_id, platform_admin_email, tenant_id, action)
  values (auth.uid(), (select email from auth.users where id = auth.uid()), v_session.tenant_id, 'end');

  if v_session.id is not null then
    perform log_platform_event(
      'impersonation.end', v_session.tenant_id, 'tenant', v_session.tenant_id::text, null,
      jsonb_build_object('session_id', v_session.id, 'started_at', v_session.started_at),
      jsonb_build_object('ended_at', now())
    );
  end if;
end;
$$;


--
-- Name: enforce_tenant_entitled_module(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tenant_entitled_module() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Only blocks keys that ARE registered but not entitlable. Unknown keys fall
  -- through so the foreign key reports them (foreign_key_violation).
  if exists (
    select 1 from platform_modules m
    where m.key = new.module and not m.tenant_entitled
  ) then
    raise exception 'MODULE_NOT_ENTITLABLE: % cannot be entitled to a tenant or given staff roles', new.module
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: feature_enabled(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feature_enabled(p_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select tf.enabled from tenant_feature_flags tf where tf.flag_key = p_key and tf.tenant_id = get_my_tenant_id()),
    (select f.default_enabled from platform_feature_flags f where f.key = p_key),
    false);
$$;


--
-- Name: fin_allocations_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_allocations_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_s fin_settlements%rowtype;
  v_i fin_open_items%rowtype;
  v_item_consumed numeric;
  v_settle_alloc numeric;
begin
  if tg_op = 'UPDATE' then
    raise exception 'ALLOCATION_IMMUTABLE: allocations cannot be changed; void the settlement instead';
  end if;

  select * into v_s from fin_settlements where id = new.settlement_id and tenant_id = new.tenant_id;
  if not found then
    raise exception 'ALLOCATION_SETTLEMENT: settlement not found in this company';
  end if;
  if v_s.status <> 'posted' then
    raise exception 'ALLOCATION_SETTLEMENT: cannot allocate against a void settlement';
  end if;

  select * into v_i from fin_open_items where id = new.open_item_id and tenant_id = new.tenant_id for update;
  if not found then
    raise exception 'ALLOCATION_ITEM: open item not found in this company';
  end if;

  if v_i.party_account_id <> v_s.party_account_id then
    raise exception 'ALLOCATION_PARTY: item % belongs to a different party than the settlement', v_i.document_no;
  end if;
  if (v_s.direction = 'in') <> (v_i.side = 'receivable') then
    raise exception 'ALLOCATION_DIRECTION: money % cannot settle a % item (%)',
      case v_s.direction when 'in' then 'in' else 'out' end, v_i.side, v_i.document_no;
  end if;
  if v_i.currency <> v_s.currency then
    raise exception 'ALLOCATION_CURRENCY: item % is in %, settlement is in %', v_i.document_no, v_i.currency, v_s.currency;
  end if;

  v_item_consumed := fin_open_item_consumed(v_i.id);
  if v_item_consumed + new.amount > v_i.amount then
    raise exception 'ALLOCATION_EXCEEDS_ITEM: % has % outstanding, % cannot be applied',
      v_i.document_no, v_i.amount - v_item_consumed, new.amount;
  end if;

  select coalesce(sum(amount), 0) into v_settle_alloc from fin_allocations where settlement_id = v_s.id;
  if v_settle_alloc + new.amount > v_s.amount then
    raise exception 'ALLOCATION_EXCEEDS_SETTLEMENT: allocations would exceed the settlement amount of %', v_s.amount;
  end if;

  return new;
end;
$$;


--
-- Name: fin_bank_accounts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_bank_accounts_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_acct gl_accounts%rowtype;
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'BANK_ACCOUNT_TENANT_IMMUTABLE: a bank account cannot move to another company';
    end if;
    if new.name is distinct from old.name then
      raise exception 'BANK_ACCOUNT_NAME_IMMUTABLE: the name links this account to its transactions and statements; deactivate it and register a new one instead';
    end if;
    if new.kind is distinct from old.kind then
      raise exception 'BANK_ACCOUNT_KIND_IMMUTABLE: an account cannot change between operating and client money; deactivate it and register a new one instead';
    end if;
    if old.gl_account_id is not null and new.gl_account_id is distinct from old.gl_account_id then
      raise exception 'BANK_ACCOUNT_GL_IMMUTABLE: a mapped GL account cannot be changed; deactivate this account and register a new one instead';
    end if;
  end if;

  if new.gl_account_id is not null
     and (tg_op = 'INSERT' or new.gl_account_id is distinct from old.gl_account_id) then
    select * into v_acct from gl_accounts where id = new.gl_account_id;
    if not found or v_acct.tenant_id <> new.tenant_id then
      raise exception 'BANK_ACCOUNT_GL_INVALID: the GL account must belong to the same company';
    end if;
    if v_acct.account_type <> 'asset' then
      raise exception 'BANK_ACCOUNT_GL_INVALID: a bank account must map to an asset GL account (% is %)',
        v_acct.account_code, v_acct.account_type;
    end if;
    if not v_acct.is_active then
      raise exception 'BANK_ACCOUNT_GL_INVALID: GL account % is inactive', v_acct.account_code;
    end if;

    -- Client money and operating money must never share a GL account.
    if exists (
      select 1 from fin_bank_accounts b
      where b.tenant_id = new.tenant_id
        and b.gl_account_id = new.gl_account_id
        and b.kind <> new.kind
        and b.id <> new.id
    ) then
      raise exception 'BANK_ACCOUNT_SEGREGATION: GL account % is already used by a % bank account; client money and operating money need separate GL accounts',
        v_acct.account_code,
        case new.kind when 'client_money' then 'operating' else 'client money' end;
    end if;

    -- ...nor may a client-money account sit on the operating posting roles,
    -- or an operating account on the client-money role.
    if new.kind = 'client_money' and exists (
      select 1 from gl_posting_rules r
      where r.tenant_id = new.tenant_id
        and r.gl_account_id = new.gl_account_id
        and r.account_role in ('bank', 'cash')
    ) then
      raise exception 'BANK_ACCOUNT_SEGREGATION: GL account % is the operating bank/cash posting account and cannot hold client money', v_acct.account_code;
    end if;
    if new.kind = 'operating' and exists (
      select 1 from gl_posting_rules r
      where r.tenant_id = new.tenant_id
        and r.gl_account_id = new.gl_account_id
        and r.account_role = 'client_money_bank'
    ) then
      raise exception 'BANK_ACCOUNT_SEGREGATION: GL account % is the client-money posting account and cannot be used by an operating bank account', v_acct.account_code;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: fin_bank_line_candidates(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_bank_line_candidates(p_line_id uuid, p_tenant_id uuid) RETURNS TABLE(source text, candidate_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select 'cash_bank'::text, t.id
  from bank_statement_lines l
  join cash_bank_transactions t
    on t.tenant_id = l.tenant_id
   and t.payment_method = 'bank'
   and t.bank_account = l.bank_account
   and t.currency = l.currency
  where l.id = p_line_id
    and l.tenant_id = p_tenant_id
    and (case when t.transaction_type = 'receipt' then t.amount else -t.amount end) = l.amount
    and abs(t.transaction_date - l.statement_date) <= 5
    and not exists (select 1 from bank_reconciliations r where r.cash_bank_transaction_id = t.id)
  union all
  select 'settlement'::text, s.id
  from bank_statement_lines l
  join fin_bank_accounts b
    on b.tenant_id = l.tenant_id
   and b.name = l.bank_account
  join fin_settlements s
    on s.tenant_id = l.tenant_id
   and s.bank_account_id = b.id
  where l.id = p_line_id
    and l.tenant_id = p_tenant_id
    and s.status = 'posted'
    and s.currency = l.currency
    and (case when s.direction = 'in' then s.amount else -s.amount end) = l.amount
    and abs(s.settlement_date - l.statement_date) <= 5
    and not exists (select 1 from bank_reconciliations r where r.settlement_id = s.id)
  union all
  -- The client-money side of a commission transfer: money leaves, so the line is negative.
  select 'transfer_from'::text, ct.id
  from bank_statement_lines l
  join fin_bank_accounts b
    on b.tenant_id = l.tenant_id
   and b.name = l.bank_account
  join ins_commission_transfers ct
    on ct.tenant_id = l.tenant_id
   and ct.from_bank_account_id = b.id
  where l.id = p_line_id
    and l.tenant_id = p_tenant_id
    and ct.status = 'posted'
    and ct.currency = l.currency
    and -ct.amount = l.amount
    and abs(ct.transfer_date - l.statement_date) <= 5
    and not exists (select 1 from bank_reconciliations r where r.commission_transfer_id = ct.id and r.transfer_side = 'from')
  union all
  -- The operating side: money arrives, so the line is positive.
  select 'transfer_to'::text, ct.id
  from bank_statement_lines l
  join fin_bank_accounts b
    on b.tenant_id = l.tenant_id
   and b.name = l.bank_account
  join ins_commission_transfers ct
    on ct.tenant_id = l.tenant_id
   and ct.to_bank_account_id = b.id
  where l.id = p_line_id
    and l.tenant_id = p_tenant_id
    and ct.status = 'posted'
    and ct.currency = l.currency
    and ct.amount = l.amount
    and abs(ct.transfer_date - l.statement_date) <= 5
    and not exists (select 1 from bank_reconciliations r where r.commission_transfer_id = ct.id and r.transfer_side = 'to');
$$;


--
-- Name: fin_bank_reconciliation_position(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_bank_reconciliation_position(p_bank_account_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(line_order integer, component text, label text, amount numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_bank fin_bank_accounts%rowtype;
  v_functional text;
  v_foreign boolean;
  v_gl numeric;
  v_gl_fx numeric;
  v_book_all numeric;
  v_book_unmatched numeric;
  v_stmt_unmatched numeric;
begin
  select * into v_bank from fin_bank_accounts
   where id = p_bank_account_id and tenant_id = v_tenant_id;
  if not found then
    raise exception 'bank account not found';
  end if;

  v_functional := fin_ledger_currency(v_tenant_id);
  v_foreign := v_bank.currency is not null and v_bank.currency <> v_functional;

  if v_bank.gl_account_id is not null then
    -- On a foreign account only the legs booked in the account's own currency
    -- can reconcile to its statement; the revaluation and realised-FX legs
    -- (3b/3e) are functional-currency side-effects, reported separately below.
    select coalesce(sum(l.debit - l.credit) filter (where not v_foreign or l.currency = v_bank.currency), 0),
           coalesce(sum(l.base_debit - l.base_credit) filter (where v_foreign and l.currency <> v_bank.currency), 0)
      into v_gl, v_gl_fx
      from journal_entry_lines l
      join journal_entries e on e.id = l.journal_entry_id
     where l.tenant_id = v_tenant_id
       and l.gl_account_id = v_bank.gl_account_id
       and e.tenant_id = v_tenant_id
       and e.status = 'posted'
       and e.entry_date <= p_as_of;
  end if;

  with book as (
    select (case when s.direction = 'in' then s.amount else -s.amount end) as signed,
           exists (select 1 from bank_reconciliations r where r.settlement_id = s.id) as reconciled
      from fin_settlements s
     where s.tenant_id = v_tenant_id
       and s.bank_account_id = v_bank.id
       and s.status = 'posted'
       and s.settlement_date <= p_as_of
    union all
    select (case when t.transaction_type = 'receipt' then t.amount else -t.amount end),
           exists (select 1 from bank_reconciliations r where r.cash_bank_transaction_id = t.id)
      from cash_bank_transactions t
     where t.tenant_id = v_tenant_id
       and t.payment_method = 'bank'
       and t.bank_account = v_bank.name
       and t.transaction_date <= p_as_of
    union all
    select (case when ct.to_bank_account_id = v_bank.id then ct.amount else -ct.amount end),
           exists (
             select 1 from bank_reconciliations r
              where r.commission_transfer_id = ct.id
                and r.transfer_side = case when ct.to_bank_account_id = v_bank.id then 'to' else 'from' end)
      from ins_commission_transfers ct
     where ct.tenant_id = v_tenant_id
       and ct.status = 'posted'
       and ct.transfer_date <= p_as_of
       and (ct.from_bank_account_id = v_bank.id or ct.to_bank_account_id = v_bank.id)
  )
  select coalesce(sum(signed), 0),
         coalesce(sum(signed) filter (where not reconciled), 0)
    into v_book_all, v_book_unmatched
    from book;

  select coalesce(sum(l.amount), 0) into v_stmt_unmatched
    from bank_statement_lines l
   where l.tenant_id = v_tenant_id
     and l.bank_account = v_bank.name
     and l.statement_date <= p_as_of
     and not exists (select 1 from bank_reconciliations r where r.bank_statement_line_id = l.id);

  return query values
    (1, 'gl_balance', 'GL balance', v_gl),
    (2, 'unmatched_book_items', 'Book items not on the statement', v_book_unmatched),
    (3, 'unmatched_statement_lines', 'Statement lines with no book entry', v_stmt_unmatched),
    (4, 'expected_statement_balance', 'Expected statement closing balance',
        case when v_gl is null then null else v_gl - v_book_unmatched + v_stmt_unmatched end),
    (5, 'unexplained_difference', 'Unexplained difference (GL movement reconciliation cannot see)',
        case when v_gl is null then null else v_gl - v_book_all end);

  if v_foreign and v_gl_fx is not null then
    return query values
      (6, 'fx_gl_movements', 'FX revaluation and realised legs on the GL (functional currency)', v_gl_fx);
  end if;
end;
$$;


--
-- Name: fin_open_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fin_open_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    party_account_id uuid NOT NULL,
    side text NOT NULL,
    control_role text NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    document_no text NOT NULL,
    document_date date NOT NULL,
    due_date date,
    currency text NOT NULL,
    amount numeric NOT NULL,
    description text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    fx_rate numeric(20,8) DEFAULT 1 NOT NULL,
    journal_entry_id uuid,
    base_amount numeric GENERATED ALWAYS AS (round((amount * fx_rate), 2)) STORED,
    CONSTRAINT fin_open_items_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT fin_open_items_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fin_open_items_document_no_check CHECK (((document_no <> ''::text) AND (document_no = btrim(document_no)))),
    CONSTRAINT fin_open_items_fx_rate_check CHECK ((fx_rate > (0)::numeric)),
    CONSTRAINT fin_open_items_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT fin_open_items_role_check CHECK ((control_role = ANY (ARRAY['ar_control'::text, 'commission_receivable'::text, 'ap_control'::text, 'insurer_payable'::text, 'insurer_claim_receivable'::text, 'client_claim_payable'::text]))),
    CONSTRAINT fin_open_items_side_check CHECK ((side = ANY (ARRAY['receivable'::text, 'payable'::text]))),
    CONSTRAINT fin_open_items_side_role_check CHECK ((((side = 'receivable'::text) AND (control_role = ANY (ARRAY['ar_control'::text, 'commission_receivable'::text, 'insurer_claim_receivable'::text]))) OR ((side = 'payable'::text) AND (control_role = ANY (ARRAY['ap_control'::text, 'insurer_payable'::text, 'client_claim_payable'::text]))))),
    CONSTRAINT fin_open_items_source_type_check CHECK (((source_type <> ''::text) AND (source_type = btrim(source_type))))
);


--
-- Name: fin_create_open_item(uuid, uuid, text, text, uuid, text, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_create_open_item(p_tenant_id uuid, p_party_account_id uuid, p_control_role text, p_source_type text, p_source_id uuid, p_document_no text, p_document_date date, p_due_date date, p_amount numeric, p_description text DEFAULT NULL::text) RETURNS public.fin_open_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row fin_open_items%rowtype;
begin
  if p_tenant_id is null then
    raise exception 'tenant id is required';
  end if;
  if auth.uid() is not null and p_tenant_id is distinct from public.get_my_tenant_id() then
    raise exception 'not authorized to create open items for this tenant' using errcode = '42501';
  end if;

  insert into fin_open_items (
    tenant_id, party_account_id, side, control_role, source_type, source_id,
    document_no, document_date, due_date, currency, amount, description
  ) values (
    p_tenant_id, p_party_account_id,
    case when p_control_role in ('ar_control', 'commission_receivable', 'insurer_claim_receivable') then 'receivable' else 'payable' end,
    p_control_role, p_source_type, p_source_id,
    p_document_no, p_document_date, p_due_date, fin_ledger_currency(p_tenant_id), p_amount, p_description
  )
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: fin_create_open_item_fx(uuid, uuid, text, text, uuid, text, date, date, numeric, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_create_open_item_fx(p_tenant_id uuid, p_party_account_id uuid, p_control_role text, p_source_type text, p_source_id uuid, p_document_no text, p_document_date date, p_due_date date, p_amount numeric, p_description text, p_currency text, p_journal_entry_id uuid) RETURNS public.fin_open_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row        fin_open_items%rowtype;
  v_functional text;
  v_ccy        text;
  v_rate       numeric := 1;
  v_control    uuid;
begin
  if p_tenant_id is null then
    raise exception 'tenant id is required';
  end if;
  if auth.uid() is not null and p_tenant_id is distinct from public.get_my_tenant_id() then
    raise exception 'not authorized to create open items for this tenant' using errcode = '42501';
  end if;

  v_functional := fin_ledger_currency(p_tenant_id);
  v_ccy := coalesce(nullif(btrim(p_currency), ''), v_functional);

  if v_ccy <> v_functional then
    if p_journal_entry_id is null then
      raise exception 'OPEN_ITEM_RATE: a % item must name the journal entry that booked it', v_ccy;
    end if;
    v_control := get_posting_account(p_tenant_id, p_control_role);
    select l.fx_rate into v_rate
      from journal_entry_lines l
     where l.journal_entry_id = p_journal_entry_id
       and l.tenant_id = p_tenant_id
       and l.gl_account_id = v_control
       and l.currency = v_ccy
     order by l.id
     limit 1;
    if v_rate is null then
      raise exception 'OPEN_ITEM_RATE: the booking entry has no % line on the % account', v_ccy, p_control_role;
    end if;
  end if;

  insert into fin_open_items (
    tenant_id, party_account_id, side, control_role, source_type, source_id,
    document_no, document_date, due_date, currency, amount, description, fx_rate, journal_entry_id
  ) values (
    p_tenant_id, p_party_account_id,
    case when p_control_role in ('ar_control', 'commission_receivable', 'insurer_claim_receivable') then 'receivable' else 'payable' end,
    p_control_role, p_source_type, p_source_id,
    p_document_no, p_document_date, p_due_date, v_ccy, p_amount, p_description, v_rate, p_journal_entry_id
  )
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: fin_credit_applications_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_credit_applications_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_c fin_credit_notes%rowtype;
  v_i fin_open_items%rowtype;
  v_consumed numeric;
  v_note_applied numeric;
begin
  if tg_op = 'UPDATE' then
    raise exception 'CREDIT_APPLICATION_IMMUTABLE: applications cannot be changed; void the credit note instead';
  end if;

  select * into v_c from fin_credit_notes where id = new.credit_note_id and tenant_id = new.tenant_id;
  if not found then
    raise exception 'CREDIT_APPLICATION_NOTE: credit note not found in this company';
  end if;
  if v_c.status <> 'posted' then
    raise exception 'CREDIT_APPLICATION_NOTE: cannot apply a void credit note';
  end if;

  select * into v_i from fin_open_items where id = new.open_item_id and tenant_id = new.tenant_id for update;
  if not found then
    raise exception 'CREDIT_APPLICATION_ITEM: open item not found in this company';
  end if;

  if v_i.party_account_id <> v_c.party_account_id then
    raise exception 'CREDIT_APPLICATION_PARTY: item % belongs to a different party than the credit note', v_i.document_no;
  end if;
  if v_i.side <> v_c.side or v_i.control_role <> v_c.control_role then
    raise exception 'CREDIT_APPLICATION_ROLE: a % credit note cannot be applied to a % item (%)',
      v_c.control_role, v_i.control_role, v_i.document_no;
  end if;
  if v_i.currency <> v_c.currency then
    raise exception 'CREDIT_APPLICATION_CURRENCY: item % is in %, credit note is in %', v_i.document_no, v_i.currency, v_c.currency;
  end if;

  v_consumed := fin_open_item_consumed(v_i.id);
  if v_consumed + new.amount > v_i.amount then
    raise exception 'CREDIT_EXCEEDS_ITEM: % has % outstanding, % cannot be applied',
      v_i.document_no, v_i.amount - v_consumed, new.amount;
  end if;

  select coalesce(sum(amount), 0) into v_note_applied from fin_credit_applications where credit_note_id = v_c.id;
  if v_note_applied + new.amount > v_c.amount then
    raise exception 'CREDIT_EXCEEDS_NOTE: applications would exceed the credit note amount of %', v_c.amount;
  end if;

  return new;
end;
$$;


--
-- Name: fin_credit_notes_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_credit_notes_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_keys constant text[] := array['journal_entry_id', 'status', 'void_journal_entry_id', 'voided_at', 'voided_by', 'void_reason', 'base_amount'];
  v_functional text;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'posted' or new.journal_entry_id is not null or new.void_journal_entry_id is not null then
      raise exception 'CREDIT_NOTE_STATE: a credit note is created posted, with its journal attached afterwards';
    end if;
    if not exists (select 1 from accounts a where a.id = new.party_account_id and a.tenant_id = new.tenant_id) then
      raise exception 'CREDIT_NOTE_PARTY_INVALID: the party must be an account of the same company';
    end if;
    if not exists (select 1 from gl_accounts g where g.id = new.offset_gl_account_id and g.tenant_id = new.tenant_id) then
      raise exception 'CREDIT_NOTE_OFFSET: the offset account must be a GL account of the same company';
    end if;

    v_functional := fin_ledger_currency(new.tenant_id);
    if new.currency = v_functional then
      if new.fx_rate <> 1 or new.realised_result <> 0 then
        raise exception 'CREDIT_NOTE_RATE: a credit note in the functional currency (%) is at rate 1 with no realised result', v_functional;
      end if;
    elsif new.fx_rate is distinct from round((platform_fx_rate(new.tenant_id, new.currency, new.credit_date)).rate, 8) then
      raise exception 'CREDIT_NOTE_RATE: the credit note rate must be the approved % rate for %', new.currency, new.credit_date;
    end if;
    return new;
  end if;

  if (to_jsonb(new) - v_keys) is distinct from (to_jsonb(old) - v_keys) then
    raise exception 'CREDIT_NOTE_IMMUTABLE: a raised credit note cannot be edited; void it and raise a new one';
  end if;
  if old.journal_entry_id is not null and new.journal_entry_id is distinct from old.journal_entry_id then
    raise exception 'CREDIT_NOTE_IMMUTABLE: the posted journal cannot be changed';
  end if;
  if old.status = 'void' then
    raise exception 'CREDIT_NOTE_VOID: a void credit note cannot change';
  end if;
  if new.status = 'void' and (new.void_journal_entry_id is null or new.void_reason is null or new.voided_at is null) then
    raise exception 'CREDIT_NOTE_VOID: a void needs its reversing journal, reason and time';
  end if;
  return new;
end;
$$;


--
-- Name: fin_ledger_currency(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_ledger_currency(p_tenant_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select functional_currency from tenant_ledger_settings where tenant_id = p_tenant_id),
    'UGX'::text);
$$;


--
-- Name: fin_open_item_consumed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_open_item_consumed(p_open_item_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce((
           select sum(a.amount) from fin_allocations a
             join fin_settlements s on s.id = a.settlement_id
            where a.open_item_id = p_open_item_id and s.status = 'posted'), 0)
       + coalesce((
           select sum(ca.amount) from fin_credit_applications ca
             join fin_credit_notes c on c.id = ca.credit_note_id
            where ca.open_item_id = p_open_item_id and c.status = 'posted'), 0)
$$;


--
-- Name: fin_open_items_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_open_items_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_functional text;
  v_control    uuid;
begin
  if tg_op = 'UPDATE' then
    raise exception 'OPEN_ITEM_IMMUTABLE: an open item cannot be changed; settle it, or use a credit note';
  end if;
  if not exists (select 1 from accounts a where a.id = new.party_account_id and a.tenant_id = new.tenant_id) then
    raise exception 'OPEN_ITEM_PARTY_INVALID: the party must be an account of the same company';
  end if;

  v_functional := fin_ledger_currency(new.tenant_id);
  if new.currency = v_functional then
    if new.fx_rate <> 1 then
      raise exception 'OPEN_ITEM_RATE: an item in the functional currency (%) is at rate 1, not %', v_functional, new.fx_rate;
    end if;
  else
    if new.journal_entry_id is null then
      raise exception 'OPEN_ITEM_RATE: a % item must name the journal entry that booked it', new.currency;
    end if;
    v_control := get_posting_account(new.tenant_id, new.control_role);
    if v_control is null
       or not exists (
         select 1 from journal_entry_lines l
          where l.journal_entry_id = new.journal_entry_id
            and l.tenant_id = new.tenant_id
            and l.gl_account_id = v_control
            and l.currency = new.currency
            and l.fx_rate = new.fx_rate
       ) then
      raise exception 'OPEN_ITEM_RATE: the booking entry has no % line on the % account at rate %',
        new.currency, new.control_role, new.fx_rate;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: fin_credit_notes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fin_credit_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    credit_note_no text NOT NULL,
    side text NOT NULL,
    control_role text NOT NULL,
    party_account_id uuid NOT NULL,
    offset_gl_account_id uuid NOT NULL,
    amount numeric NOT NULL,
    currency text NOT NULL,
    credit_date date NOT NULL,
    reason text NOT NULL,
    reference text,
    status text DEFAULT 'posted'::text NOT NULL,
    journal_entry_id uuid,
    void_journal_entry_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    fx_rate numeric(20,8) DEFAULT 1 NOT NULL,
    realised_result numeric(20,2) DEFAULT 0 NOT NULL,
    base_amount numeric GENERATED ALWAYS AS (round((amount * fx_rate), 2)) STORED,
    CONSTRAINT fin_credit_notes_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT fin_credit_notes_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fin_credit_notes_fx_rate_check CHECK ((fx_rate > (0)::numeric)),
    CONSTRAINT fin_credit_notes_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT fin_credit_notes_reason_check CHECK ((length(btrim(reason)) >= 5)),
    CONSTRAINT fin_credit_notes_role_check CHECK ((control_role = ANY (ARRAY['ar_control'::text, 'commission_receivable'::text, 'ap_control'::text, 'insurer_payable'::text]))),
    CONSTRAINT fin_credit_notes_side_check CHECK ((side = ANY (ARRAY['receivable'::text, 'payable'::text]))),
    CONSTRAINT fin_credit_notes_side_role_check CHECK ((((side = 'receivable'::text) AND (control_role = ANY (ARRAY['ar_control'::text, 'commission_receivable'::text]))) OR ((side = 'payable'::text) AND (control_role = ANY (ARRAY['ap_control'::text, 'insurer_payable'::text]))))),
    CONSTRAINT fin_credit_notes_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'void'::text]))),
    CONSTRAINT fin_credit_notes_void_fields_check CHECK ((((status = 'posted'::text) AND (voided_at IS NULL) AND (void_reason IS NULL) AND (void_journal_entry_id IS NULL)) OR ((status = 'void'::text) AND (voided_at IS NOT NULL) AND (void_reason IS NOT NULL) AND (void_journal_entry_id IS NOT NULL))))
);


--
-- Name: fin_raise_credit_note(text, uuid, numeric, date, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fin_raise_credit_note(p_control_role text, p_party_account_id uuid, p_amount numeric, p_credit_date date, p_offset_gl_account_id uuid, p_applications jsonb, p_reason text, p_reference text DEFAULT NULL::text) RETURNS public.fin_credit_notes
