end;
$$;


--
-- Name: fin_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fin_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    settlement_no text NOT NULL,
    direction text NOT NULL,
    bank_account_id uuid NOT NULL,
    party_account_id uuid NOT NULL,
    amount numeric NOT NULL,
    currency text NOT NULL,
    settlement_date date NOT NULL,
    reference text,
    notes text,
    status text DEFAULT 'posted'::text NOT NULL,
    journal_entry_id uuid,
    void_journal_entry_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    fx_rate numeric(20,8) DEFAULT 1 NOT NULL,
    realised_result numeric(20,2) DEFAULT 0 NOT NULL,
    base_amount numeric GENERATED ALWAYS AS (round((amount * fx_rate), 2)) STORED,
    CONSTRAINT fin_settlements_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT fin_settlements_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fin_settlements_direction_check CHECK ((direction = ANY (ARRAY['in'::text, 'out'::text]))),
    CONSTRAINT fin_settlements_fx_rate_8dp CHECK ((fx_rate = round(fx_rate, 8))),
    CONSTRAINT fin_settlements_fx_rate_check CHECK ((fx_rate > (0)::numeric)),
    CONSTRAINT fin_settlements_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT fin_settlements_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'void'::text]))),
    CONSTRAINT fin_settlements_void_fields_check CHECK ((((status = 'posted'::text) AND (voided_at IS NULL) AND (void_reason IS NULL) AND (void_journal_entry_id IS NULL)) OR ((status = 'void'::text) AND (voided_at IS NOT NULL) AND (void_reason IS NOT NULL) AND (void_journal_entry_id IS NOT NULL))))
);


