$$;


--
-- Name: fulfill_asset_request(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_asset_request(p_request_id uuid, p_asset_id uuid, p_notes text DEFAULT NULL::text) RETURNS public.asset_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request public.asset_requests%rowtype;
  v_asset public.assets%rowtype;
  v_assignment public.asset_assignments%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to fulfill asset requests';
  end if;

  select * into v_request from asset_requests where id = p_request_id for update;
  if not found then
    raise exception 'request not found';
  end if;
  if v_request.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this request';
  end if;
  if v_request.status != 'approved' then
    raise exception 'request must be approved before fulfillment (status: %)', v_request.status;
  end if;

  select * into v_asset from assets where id = p_asset_id for update;
  if not found then
    raise exception 'asset not found';
  end if;
  if v_asset.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this asset';
  end if;
  if v_asset.type != v_request.asset_type then
    raise exception 'asset type (%) does not match requested type (%)', v_asset.type, v_request.asset_type;
  end if;
  if v_asset.status != 'in_stock' then
    raise exception 'asset is not available (status: %)', v_asset.status;
  end if;

  insert into asset_assignments (tenant_id, asset_id, assigned_to, assigned_by, notes)
  values (v_asset.tenant_id, p_asset_id, v_request.requested_by, auth.uid(), p_notes)
  returning * into v_assignment;

  update assets set status = 'assigned', updated_at = now() where id = p_asset_id;

  update asset_requests
  set status = 'fulfilled',
      fulfilled_asset_id = p_asset_id,
      fulfilled_assignment_id = v_assignment.id,
      updated_at = now()
  where id = p_request_id
  returning * into v_request;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    v_asset.tenant_id,
    v_request.requested_by,
    'asset_request_fulfilled',
    'Asset request fulfilled: ' || v_asset.asset_tag,
    format('"%s" (%s) has been assigned to you.', v_asset.name, v_asset.asset_tag)
  );

  return v_request;
end;
$$;


--
-- Name: fx_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fx_rates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    currency text NOT NULL,
    rate_date date NOT NULL,
    rate numeric(24,10) NOT NULL,
    source text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    entered_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    withdrawn_reason text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fx_rates_approved_check CHECK (((status <> 'approved'::text) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT fx_rates_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fx_rates_rate_8dp CHECK ((rate = round(rate, 8))),
    CONSTRAINT fx_rates_rate_check CHECK ((rate > (0)::numeric)),
    CONSTRAINT fx_rates_source_check CHECK ((btrim(source) <> ''::text)),
    CONSTRAINT fx_rates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'withdrawn'::text])))
);


--
-- Name: fx_get_rate(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_get_rate(p_currency text, p_on date DEFAULT CURRENT_DATE) RETURNS public.fx_rates
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not (is_tenant_admin() or is_finance_team_member(null::text) or can_access_insurance()) then
    raise exception 'FX_RATE_FORBIDDEN: exchange rates are visible to company admins, finance and insurance users' using errcode = '42501';
  end if;
  return platform_fx_rate(get_my_tenant_id(), p_currency, p_on);
end;
$$;


--
-- Name: fx_rate_approve(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_rate_approve(p_id uuid) RETURNS public.fx_rates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row fx_rates%rowtype;
  v_uid uuid := auth.uid();
begin
  select * into v_row from fx_rates
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'FX_RATE_NOT_FOUND: rate not found';
  end if;
  if not (is_tenant_admin() or is_finance_team_member('finance'::text)) then
    raise exception 'FX_RATE_FORBIDDEN: only a company admin or finance user can approve a rate' using errcode = '42501';
  end if;
  if v_row.status <> 'draft' then
    raise exception 'FX_RATE_NOT_DRAFT: only a draft can be approved (this one is %)', v_row.status;
  end if;
  if v_row.entered_by is not distinct from v_uid then
    raise exception 'FX_RATE_SELF_APPROVAL: the person who entered a rate cannot approve it';
  end if;

  perform set_config('fx.via_rpc', 'on', true);
  update fx_rates
     set status = 'approved', approved_by = v_uid, approved_at = now()
   where id = p_id
   returning * into v_row;
  perform set_config('fx.via_rpc', 'off', true);
  return v_row;
end;
$$;


--
-- Name: fx_rate_withdraw(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_rate_withdraw(p_id uuid, p_reason text) RETURNS public.fx_rates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row    fx_rates%rowtype;
  v_uid    uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into v_row from fx_rates
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'FX_RATE_NOT_FOUND: rate not found';
  end if;
  if length(v_reason) < 5 then
    raise exception 'FX_RATE_REASON: give a reason of at least five characters';
  end if;
  if v_row.status <> 'draft' then
    raise exception 'FX_RATE_NOT_DRAFT: only a draft can be withdrawn (this one is %)', v_row.status;
  end if;
  if not (is_tenant_admin() or v_row.entered_by is not distinct from v_uid) then
    raise exception 'FX_RATE_FORBIDDEN: only the person who entered a draft or a company admin can withdraw it' using errcode = '42501';
  end if;

  perform set_config('fx.via_rpc', 'on', true);
  update fx_rates
     set status = 'withdrawn', withdrawn_reason = v_reason
   where id = p_id
   returning * into v_row;
  perform set_config('fx.via_rpc', 'off', true);
  return v_row;
end;
$$;


--
-- Name: fx_rates_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_rates_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_via boolean := coalesce(current_setting('fx.via_rpc', true), '') = 'on';
begin
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'FX_RATE_STATUS: a new rate starts as a draft; approval is a separate step by a different person';
    end if;
    if new.approved_by is not null or new.approved_at is not null or new.withdrawn_reason is not null then
      raise exception 'FX_RATE_STATUS: approval and withdrawal fields cannot be set on a new draft';
    end if;
  else
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'FX_RATE_TENANT_IMMUTABLE: a rate cannot move to another company';
    end if;
    if old.status in ('approved', 'withdrawn') then
      raise exception 'FX_RATE_IMMUTABLE: an % rate cannot be changed; correct it with a correcting entry', old.status;
    end if;
    if new.status is distinct from old.status and not v_via then
      raise exception 'FX_RATE_STATUS_VIA_RPC: change status with fx_rate_approve or fx_rate_withdraw';
    end if;
  end if;

  if new.currency = fin_ledger_currency(new.tenant_id) then
    raise exception 'FX_RATE_CURRENCY: % is this company''s own functional currency; its rate is always 1', new.currency;
  end if;
  if new.rate_date > current_date then
    raise exception 'FX_RATE_FUTURE: a rate cannot be dated in the future (%)', new.rate_date;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: fx_rates_round_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_rates_round_rate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Lines and the guards round to 8; approval rounds the same way, so a
  -- key-in rate with more precision is normalised at the door rather than
  -- stored more precisely than it will ever be used.
  new.rate := round(new.rate, 8);
  return new;
end;
$$;


