--
-- Name: hr_payroll_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_payroll_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payroll_run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    basic_salary numeric NOT NULL,
    allowances numeric DEFAULT 0 NOT NULL,
    deductions numeric DEFAULT 0 NOT NULL,
    note text,
    paye_amount numeric DEFAULT 0 NOT NULL,
    nssf_employee numeric DEFAULT 0 NOT NULL,
    nssf_employer numeric DEFAULT 0 NOT NULL,
    net_pay numeric GENERATED ALWAYS AS (((((basic_salary + allowances) - deductions) - paye_amount) - nssf_employee)) STORED,
    CONSTRAINT hr_payroll_items_allowances_check CHECK ((allowances >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_basic_salary_check CHECK ((basic_salary >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_deductions_check CHECK ((deductions >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_nssf_employee_check CHECK ((nssf_employee >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_nssf_employer_check CHECK ((nssf_employer >= (0)::numeric)),
    CONSTRAINT hr_payroll_items_paye_amount_check CHECK ((paye_amount >= (0)::numeric))
);


--
-- Name: generate_payroll_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_payroll_items(p_run_id uuid) RETURNS SETOF public.hr_payroll_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run hr_payroll_runs%rowtype;
  v_calc record;
begin
  if not is_hr_team_member() then
    raise exception 'not authorized to prepare payroll';
  end if;

  select * into v_run from hr_payroll_runs where id = p_run_id and tenant_id = get_my_tenant_id();
  if not found then
    raise exception 'payroll run not found';
  end if;
  if v_run.status != 'draft' then
    raise exception 'can only generate items while the run is in draft';
  end if;

  return query
  with new_employees as (
    select e.id as employee_id, cc.basic_salary
    from hr_employees e
    join hr_employee_current_compensation cc on cc.employee_id = e.id
    where e.tenant_id = get_my_tenant_id()
      and e.is_active
      and not exists (select 1 from hr_payroll_items i where i.payroll_run_id = p_run_id and i.employee_id = e.id)
  )
  insert into hr_payroll_items (payroll_run_id, employee_id, basic_salary, paye_amount, nssf_employee, nssf_employer)
  select
    p_run_id,
    ne.employee_id,
    ne.basic_salary,
    (calc).paye_amount,
    (calc).nssf_employee,
    (calc).nssf_employer
  from new_employees ne
  cross join lateral calculate_statutory_deductions(ne.basic_salary) as calc
  on conflict (payroll_run_id, employee_id) do nothing
  returning *;
end;
$$;


