--
-- Name: get_access_requests(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_access_requests(p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, requested_by uuid, requester_name text, resource text, access_level text, justification text, status text, decided_by uuid, decided_at timestamp with time zone, decision_notes text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to view access requests';
  end if;

  return query
  select r.id, r.requested_by, u.name, r.resource, r.access_level, r.justification,
         r.status, r.decided_by, r.decided_at, r.decision_notes, r.created_at
  from access_requests r
  join app_users u on u.id = r.requested_by
  where r.tenant_id = get_my_tenant_id()
    and (p_status is null or r.status = p_status)
  order by r.created_at desc;
end;
$$;


--
-- Name: get_active_announcements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_announcements() RETURNS TABLE(id uuid, title text, body text, severity text, starts_at timestamp with time zone, ends_at timestamp with time zone, dismissible boolean, link_url text, link_label text, is_global boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select a.id, a.title, a.body, a.severity, a.starts_at, a.ends_at,
         (a.dismissible and a.severity <> 'critical') as dismissible,
         a.link_url, a.link_label, (a.tenant_id is null) as is_global
  from platform_announcements a
  where a.is_active
    and a.starts_at <= now()
    and (a.ends_at is null or a.ends_at > now())
    and (a.tenant_id is null or a.tenant_id = get_my_tenant_id())
    and not exists (select 1 from platform_announcement_dismissals d
                    where d.announcement_id = a.id and d.user_id = effective_user_id())
  order by case a.severity when 'critical' then 0 when 'warning' then 1 else 2 end, a.starts_at desc;
$$;


--
-- Name: get_active_impersonation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_impersonation() RETURNS TABLE(tenant_id uuid, tenant_name text, reason text, started_at timestamp with time zone, expires_at timestamp with time zone, impersonated_user_id uuid, impersonated_user_name text, impersonated_user_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.id, t.name, s.reason, s.started_at, s.expires_at, s.impersonated_user_id, u.name, u.email
  from impersonation_sessions s
  join tenants t on t.id = s.tenant_id
  left join app_users u on u.id = s.impersonated_user_id
  where s.platform_admin_id = auth.uid()
    and s.ended_at is null
    and s.expires_at > now()
  order by s.started_at desc
  limit 1;
$$;


--
-- Name: get_all_tickets(); Type: FUNCTION; Schema: public; Owner: -
