CREATE FUNCTION public.get_all_tickets() RETURNS SETOF public.it_tickets
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from it_tickets
  where tenant_id = get_my_tenant_id() and is_it_support()
  order by
    case status when 'open' then 0 when 'in_progress' then 1 when 'resolved' then 2 else 3 end,
    created_at desc;
$$;


--
-- Name: get_asset_assignments(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_asset_assignments(p_active_only boolean DEFAULT true) RETURNS TABLE(id uuid, asset_id uuid, asset_tag text, asset_name text, asset_type text, assigned_to uuid, assigned_to_name text, assigned_by uuid, assigned_at timestamp with time zone, returned_at timestamp with time zone, notes text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    aa.id, aa.asset_id, a.asset_tag, a.name as asset_name, a.type as asset_type,
    aa.assigned_to, u.name as assigned_to_name, aa.assigned_by, aa.assigned_at, aa.returned_at, aa.notes
  from asset_assignments aa
  join assets a on a.id = aa.asset_id
  join app_users u on u.id = aa.assigned_to
  where aa.tenant_id = get_my_tenant_id() and is_it_support()
    and (not p_active_only or aa.returned_at is null)
  order by aa.assigned_at desc;
$$;


--
-- Name: get_asset_requests(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_asset_requests(p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, requested_by uuid, requester_name text, asset_type text, item_description text, justification text, status text, decided_by uuid, decided_at timestamp with time zone, decision_notes text, fulfilled_asset_id uuid, fulfilled_asset_tag text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to view asset requests';
  end if;

  return query
  select
    r.id, r.requested_by, u.name, r.asset_type, r.item_description, r.justification,
    r.status, r.decided_by, r.decided_at, r.decision_notes,
    r.fulfilled_asset_id, a.asset_tag, r.created_at
  from asset_requests r
  join app_users u on u.id = r.requested_by
  left join assets a on a.id = r.fulfilled_asset_id
  where r.tenant_id = get_my_tenant_id()
    and (p_status is null or r.status = p_status)
  order by r.created_at desc;
end;
$$;


--
-- Name: get_assets(text); Type: FUNCTION; Schema: public; Owner: -
