--
-- Name: get_companies_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_companies_overview() RETURNS TABLE(tenant_id uuid, name text, status text, created_at timestamp with time zone, member_count bigint, module_count bigint, request_count_30d bigint, pending_request_count bigint, plan text, subscription_status text, seat_limit integer, trial_ends_at timestamp with time zone, read_only boolean, contact_email text, last_activity_at timestamp with time zone, onboarding_stage text, onboarding_next_step text, onboarding_stalled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    t.id,
    t.name,
    t.status,
    t.created_at,
    (select count(*) from app_users u where u.tenant_id = t.id),
    (select count(*) from tenant_modules tm where tm.tenant_id = t.id),
    (select count(*) from requests r where r.tenant_id = t.id and r.created_at >= now() - interval '30 days'),
    (select count(*) from requests r where r.tenant_id = t.id and r.status = 'open'),
    t.plan,
    t.subscription_status,
    t.seat_limit,
    t.trial_ends_at,
    t.read_only,
    t.contact_email,
    o.last_activity_at,
    o.stage_key,
    o.next_step,
    o.stalled
  from tenants t
  left join get_tenant_onboarding_status() o on o.tenant_id = t.id
  where public.platform_admin_mfa_gate('get companies overview')
  order by t.created_at desc;
$$;


--
-- Name: get_company_analytics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_company_analytics(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
  v_extra  jsonb;
begin
  if not is_platform_admin() then
    raise exception 'Only platform admins can view company analytics';
  end if;
  perform require_platform_admin('get company analytics');

  if not exists (select 1 from tenants where id = p_tenant_id) then
    raise exception 'tenant not found';
  end if;

  select jsonb_build_object(
    'requests_by_status', (
      select coalesce(jsonb_agg(jsonb_build_object('status', status, 'count', cnt) order by cnt desc), '[]'::jsonb)
      from (
        select status, count(*) as cnt
        from requests
        where tenant_id = p_tenant_id
        group by status
      ) s
    ),
    'requests_by_month', (
      select coalesce(jsonb_agg(jsonb_build_object('month', month, 'count', cnt) order by month), '[]'::jsonb)
      from (
        select to_char(date_trunc('month', created_at), 'YYYY-MM') as month, count(*) as cnt
        from requests
        where tenant_id = p_tenant_id
          and created_at >= date_trunc('month', now()) - interval '5 months'
        group by 1
      ) m
    ),
    'purchase_orders', (
      select jsonb_build_object(
        'count', count(*),
        'total_value', coalesce(sum(po.amount), 0)
      )
      from purchase_orders po
      join requests r on r.id = po.request_id
      where r.tenant_id = p_tenant_id
    ),
    'members_by_department', (
      select coalesce(jsonb_agg(jsonb_build_object('department', dept, 'count', cnt) order by cnt desc), '[]'::jsonb)
      from (
        select coalesce(d.name, 'Unassigned') as dept, count(*) as cnt
        from app_users u
        left join departments d on d.id = u.department_id
        where u.tenant_id = p_tenant_id
        group by 1
      ) dm
    ),
    'top_requesters', (
      select coalesce(jsonb_agg(jsonb_build_object('name', uname, 'count', cnt) order by cnt desc), '[]'::jsonb)
      from (
        select u.name as uname, count(*) as cnt
        from requests r
        join app_users u on u.id = r.requester_id
        where r.tenant_id = p_tenant_id
        group by u.name
        order by count(*) desc
        limit 5
      ) tr
    )
  )
  into v_result;

  select jsonb_build_object(
    'module_usage', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'module', m.module,
        'enabled', (m.module = 'finance'
                    or exists (select 1 from tenant_modules tm where tm.tenant_id = p_tenant_id and tm.module = m.module)),
        'events_30d', coalesce(a.events, 0),
        'events_prev_30d', coalesce(a.events_prev, 0),
        'first_event_at', a.first_event_at,
        'last_event_at', a.last_event_at
      ) order by m.ord), '[]'::jsonb)
      from (values
        (1, 'procurement'), (2, 'finance'), (3, 'hr'), (4, 'legal'), (5, 'bd'),
        (6, 'it'), (7, 'pmo'), (8, 'machine_operation'), (9, 'sustainability')
      ) as m(ord, module)
      left join (select * from platform_module_activity(30) x where x.tenant_id = p_tenant_id) a on a.module = m.module
    ),
    'onboarding', (
      select to_jsonb(o) - 'tenant_id' - 'name' - 'status' - 'plan' - 'subscription_status'
             - 'trial_ends_at' - 'contact_email' - 'is_internal' - 'member_count'
      from get_tenant_onboarding_status() o
      where o.tenant_id = p_tenant_id
    ),
    'last_activity_at', (
      select o.last_activity_at from get_tenant_onboarding_status() o where o.tenant_id = p_tenant_id
    )
  ) into v_extra;

  return v_result || v_extra;
end;
$$;


--
-- Name: get_faqs(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_faqs(p_category text DEFAULT NULL::text) RETURNS SETOF public.faqs
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from faqs
  where tenant_id = get_my_tenant_id()
    and (is_published or is_it_support())
    and (p_category is null or category = p_category)
  order by sort_order, created_at;
$$;


--
-- Name: get_group_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_group_members(p_group_id uuid) RETURNS TABLE(user_id uuid, name text, email text, added_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to view group members';
  end if;
  return query
  select u.id, u.name, u.email, m.added_at
  from user_group_members m
  join app_users u on u.id = m.user_id
  join user_groups g on g.id = m.group_id
  where m.group_id = p_group_id and g.tenant_id = get_my_tenant_id()
  order by u.name;
end;
$$;


--
-- Name: get_groups(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_groups() RETURNS TABLE(id uuid, name text, description text, member_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to view groups';
  end if;
  return query
  select g.id, g.name, g.description, count(m.user_id), g.created_at
  from user_groups g
  left join user_group_members m on m.group_id = g.id
  where g.tenant_id = get_my_tenant_id()
  group by g.id
  order by g.name;
end;
$$;


