CREATE FUNCTION public.get_licenses() RETURNS TABLE(id uuid, asset_id uuid, asset_tag text, asset_name text, license_key text, seats_total integer, seats_used bigint, vendor text, expiry_date date, notes text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    l.id, l.asset_id, a.asset_tag, a.name as asset_name, l.license_key, l.seats_total,
    (select count(*) from asset_assignments aa where aa.asset_id = l.asset_id and aa.returned_at is null) as seats_used,
