--
-- Name: get_my_approval_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_approval_queue() RETURNS TABLE(id uuid, tenant_id uuid, requester_id uuid, department_id uuid, cost_center_id uuid, current_stage_id uuid, item_description text, quantity integer, status text, created_at timestamp with time zone, cost_center jsonb, department jsonb, requester jsonb, current_stage jsonb, acting_on_behalf_of jsonb, offers jsonb, selected_offer jsonb, purchase_order jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with direct_stages as (
    select workflow_stage_id, null::uuid as delegator_user_id
    from approval_assignments
    where user_id = auth.uid()
  ),
  delegated_stages as (
    select coalesce(d.workflow_stage_id, aa.workflow_stage_id) as workflow_stage_id,
           d.delegator_user_id
    from approval_delegations d
    join approval_assignments aa on aa.user_id = d.delegator_user_id
    where d.delegate_user_id = auth.uid()
      and d.status = 'active'
      and now() between d.starts_at and d.ends_at
      and (d.workflow_stage_id is null or d.workflow_stage_id = aa.workflow_stage_id)
  ),
  my_stages as (
    select * from direct_stages
    union all
    select * from delegated_stages
  ),
  offers_by_request as (
    select
      ro.request_id,
      jsonb_agg(
        jsonb_build_object(
          'id', ro.id,
          'vendor_name', ro.vendor_name,
          'quotation_amount', ro.quotation_amount,
          'quantity', ro.quantity,
          'submitted_by', ro.submitted_by,
          'submitted_at', ro.submitted_at,
          'is_selected', ro.is_selected
        ) order by ro.submitted_at asc
      ) as offers,
      jsonb_agg(
        jsonb_build_object(
          'id', ro.id,
          'vendor_name', ro.vendor_name,
          'quotation_amount', ro.quotation_amount,
          'quantity', ro.quantity,
          'submitted_by', ro.submitted_by,
          'submitted_at', ro.submitted_at,
          'is_selected', ro.is_selected
        )
      ) filter (where ro.is_selected) as selected_offer_arr
    from request_offers ro
    group by ro.request_id
  )
  select
    r.id, r.tenant_id, r.requester_id, r.department_id, r.cost_center_id,
    r.current_stage_id, r.item_description, r.quantity, r.status, r.created_at,
    jsonb_build_object('id', cc.id, 'name', cc.name, 'project_code', cc.project_code) as cost_center,
    case when dept.id is not null
      then jsonb_build_object('id', dept.id, 'name', dept.name)
      else null
    end as department,
    jsonb_build_object('id', req.id, 'name', req.name) as requester,
    jsonb_build_object(
      'id', ws.id,
      'name', ws.name,
      'approver_role', ws.approver_role,
      'threshold_amount', ws.threshold_amount,
      'requires_offer_entry', ws.requires_offer_entry,
      'requires_offer_selection', ws.requires_offer_selection,
      'blocks_offer_submitter_approval', ws.blocks_offer_submitter_approval,
      'is_finance_terminal_stage', ws.is_finance_terminal_stage
    ) as current_stage,
    case when ms.delegator_user_id is not null
      then jsonb_build_object('id', delegator.id, 'name', delegator.name)
      else null
    end as acting_on_behalf_of,
    coalesce(ofr.offers, '[]'::jsonb) as offers,
    (ofr.selected_offer_arr -> 0) as selected_offer,
    case when po.id is not null
      then jsonb_build_object(
        'id', po.id,
        'po_number', po.po_number,
        'vendor_name', po.vendor_name,
        'amount', po.amount,
        'shared_with_supplier', po.shared_with_supplier
      )
      else null
    end as purchase_order
  from requests r
  join my_stages ms on ms.workflow_stage_id = r.current_stage_id
  join cost_centers cc on cc.id = r.cost_center_id
  left join departments dept on dept.id = r.department_id
  join app_users req on req.id = r.requester_id
  join workflow_stages ws on ws.id = r.current_stage_id
  left join app_users delegator on delegator.id = ms.delegator_user_id
  left join offers_by_request ofr on ofr.request_id = r.id
  left join purchase_orders po on po.request_id = r.id
  where r.status = 'open'
    and r.tenant_id = get_my_tenant_id()
  order by r.created_at asc;
$$;


--
-- Name: get_my_asset_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_asset_requests() RETURNS TABLE(id uuid, asset_type text, item_description text, justification text, status text, decision_notes text, decided_at timestamp with time zone, fulfilled_asset_id uuid, fulfilled_asset_tag text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    r.id, r.asset_type, r.item_description, r.justification, r.status,
    r.decision_notes, r.decided_at, r.fulfilled_asset_id, a.asset_tag, r.created_at
  from asset_requests r
  left join assets a on a.id = r.fulfilled_asset_id
  where r.requested_by = auth.uid()
  order by r.created_at desc;
$$;


--
-- Name: get_my_feature_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_feature_flags() RETURNS TABLE(key text, enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.key, coalesce(tf.enabled, f.default_enabled)
  from platform_feature_flags f
  left join tenant_feature_flags tf on tf.flag_key = f.key and tf.tenant_id = get_my_tenant_id()
  order by f.key;
$$;


--
-- Name: get_my_invoice_approval_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_invoice_approval_queue() RETURNS TABLE(id uuid, tenant_id uuid, requester_id uuid, department_id uuid, cost_center_id uuid, current_stage_id uuid, vendor_name text, description text, amount numeric, status text, created_at timestamp with time zone, department jsonb, requester jsonb, current_stage jsonb, acting_on_behalf_of jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH direct_stages AS (
    SELECT workflow_stage_id, NULL::uuid AS delegator_user_id
    FROM approval_assignments
    WHERE user_id = auth.uid()
  ),
  delegated_stages AS (
    SELECT COALESCE(d.workflow_stage_id, aa.workflow_stage_id) AS workflow_stage_id,
           d.delegator_user_id
    FROM approval_delegations d
    JOIN approval_assignments aa ON aa.user_id = d.delegator_user_id
    WHERE d.delegate_user_id = auth.uid()
      AND d.status = 'active'
      AND now() BETWEEN d.starts_at AND d.ends_at
      AND (d.workflow_stage_id IS NULL OR d.workflow_stage_id = aa.workflow_stage_id)
  ),
  my_stages AS (
    SELECT * FROM direct_stages
    UNION ALL
    SELECT * FROM delegated_stages
  )
  SELECT
    ir.id, ir.tenant_id, ir.requester_id, ir.department_id, ir.cost_center_id,
    ir.current_stage_id, ir.vendor_name, ir.description, ir.amount, ir.status, ir.created_at,
    jsonb_build_object('id', dept.id, 'name', dept.name) AS department,
    jsonb_build_object('id', req.id, 'name', req.name) AS requester,
    jsonb_build_object(
      'id', ws.id,
      'name', ws.name,
      'approver_role', ws.approver_role,
      'threshold_amount', ws.threshold_amount,
      'is_finance_terminal_stage', ws.is_finance_terminal_stage
    ) AS current_stage,
    CASE WHEN ms.delegator_user_id IS NOT NULL
      THEN jsonb_build_object('id', delegator.id, 'name', delegator.name)
      ELSE NULL
    END AS acting_on_behalf_of
  FROM invoice_requests ir
  JOIN my_stages ms ON ms.workflow_stage_id = ir.current_stage_id
  LEFT JOIN departments dept ON dept.id = ir.department_id
  JOIN app_users req ON req.id = ir.requester_id
  JOIN workflow_stages ws ON ws.id = ir.current_stage_id
  LEFT JOIN app_users delegator ON delegator.id = ms.delegator_user_id
  WHERE ir.status = 'open'
    AND ir.tenant_id = get_my_tenant_id()
  ORDER BY ir.created_at ASC;
$$;


--
-- Name: get_my_procurement_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_procurement_orders() RETURNS TABLE(id uuid, po_number text, item_description text, vendor_name text, amount numeric, request_id uuid, shared_with_supplier boolean, delivered_at timestamp with time zone, completed_at timestamp with time zone, request_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    po.id,
    po.po_number,
    req.item_description,
    po.vendor_name,
    po.amount,
    po.request_id,
    COALESCE(po.shared_with_supplier, false)::boolean AS shared_with_supplier,
    po.delivered_at,
    po.completed_at,
    req.status AS request_status
  FROM public.purchase_orders po
  INNER JOIN public.requests req ON req.id = po.request_id
  INNER JOIN public.request_offers ro ON ro.request_id = req.id
  WHERE ro.submitted_by = auth.uid()
    AND req.status = 'closed'
  ORDER BY po.generated_at DESC;
END;
$$;


--
-- Name: get_my_purchase_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_purchase_orders() RETURNS TABLE(id uuid, request_id uuid, po_number text, initial_po_number text, vendor_name text, amount numeric, currency text, generated_by jsonb, generated_at timestamp with time zone, delivery_date date, shared_with_supplier boolean, delivered_at timestamp with time zone, completed_at timestamp with time zone, request jsonb, requester jsonb, department jsonb, cost_center jsonb, organization jsonb, mr_number text, project_sap_no text, payment_conditions text, terms_of_delivery text, edit_count integer, last_edited_at timestamp with time zone, last_edited_by jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with last_edit as (
    select
      pe.purchase_order_id,
      pe.edited_at,
      pe.edited_by,
      row_number() over (partition by pe.purchase_order_id order by pe.edited_at desc) as rn
    from po_edits pe
  ),
  edit_counts as (
    select purchase_order_id, count(*) as cnt
    from po_edits
    group by purchase_order_id
  )
  select
    po.id, po.request_id, po.po_number, po.initial_po_number, po.vendor_name, po.amount, po.currency,
    jsonb_build_object('id', gen.id, 'name', gen.name) as generated_by,
    po.generated_at,
    r.delivery_date,
    coalesce(po.shared_with_supplier, false) as shared_with_supplier,
    po.delivered_at,
    po.completed_at,
    jsonb_build_object('id', r.id, 'item_description', r.item_description, 'quantity', r.quantity, 'status', r.status) as request,
    jsonb_build_object('id', req.id, 'name', req.name) as requester,
    case when dept.id is not null
      then jsonb_build_object('id', dept.id, 'name', dept.name)
      else null
    end as department,
    jsonb_build_object('id', cc.id, 'name', cc.name, 'project_code', cc.project_code) as cost_center,
    case when org.id is not null
      then jsonb_build_object('id', org.id, 'company_code', org.company_code, 'site_name', org.site_name)
      else null
    end as organization,
    r.mr_number,
    po.project_sap_no,
    po.payment_conditions,
    po.terms_of_delivery,
    coalesce(ec.cnt, 0)::int as edit_count,
    le.edited_at as last_edited_at,
    case when le.edited_by is not null
      then jsonb_build_object('id', editor.id, 'name', editor.name)
      else null
    end as last_edited_by
  from purchase_orders po
  join requests r on r.id = po.request_id
  join app_users req on req.id = r.requester_id
  left join departments dept on dept.id = r.department_id
  join cost_centers cc on cc.id = r.cost_center_id
  join app_users gen on gen.id = po.generated_by
  left join organizations org on org.id = r.organization_id
  left join last_edit le on le.purchase_order_id = po.id and le.rn = 1
  left join app_users editor on editor.id = le.edited_by
  left join edit_counts ec on ec.purchase_order_id = po.id
  where has_po_access()
    and r.tenant_id = get_my_tenant_id()
  order by po.generated_at desc;
$$;


--
-- Name: get_my_tenant_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tenant_access() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'tenant_id',           t.id,
    'name',                t.name,
    'status',              t.status,
    'read_only',           t.read_only,
    'read_only_reason',    t.read_only_reason,
    'plan',                t.plan,
    'subscription_status', t.subscription_status,
    'trial_ends_at',       t.trial_ends_at
  )
  from tenants t
  where t.id = get_my_tenant_id();
$$;


--
-- Name: get_my_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select tenant_id from impersonation_sessions
     where platform_admin_id = auth.uid()
       and ended_at is null
       and expires_at > now()
     limit 1),
    (select u.tenant_id
     from app_users u
     join tenants t on t.id = u.tenant_id
     where u.id = auth.uid()
       and t.status != 'suspended')
  );
$$;


--
-- Name: get_my_tenant_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tenant_status() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.status
  from app_users u
  join tenants t on t.id = u.tenant_id
  where u.id = auth.uid();
$$;


--
-- Name: get_my_tickets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tickets() RETURNS SETOF public.it_tickets
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from it_tickets
  where tenant_id = get_my_tenant_id() and requester_id = auth.uid()
  order by created_at desc;
$$;


--
-- Name: get_offer_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_offer_detail(p_request_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'request', (
      select jsonb_build_object(
        'mr_number', r.mr_number,
        'item_description', r.item_description,
        'requester_name', ru.name,
        'created_at', r.created_at
      )
      from requests r
      join app_users ru on ru.id = r.requester_id
      where r.id = p_request_id
        and r.tenant_id = get_my_tenant_id()
    ),
    'offers', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', ro.id,
        'vendor_name', ro.vendor_name,
        'quotation_amount', ro.quotation_amount,
        'quantity', ro.quantity,
        'submitted_at', ro.submitted_at,
        'submitted_by_name', su.name,
        'is_selected', ro.is_selected
      ) order by ro.submitted_at asc), '[]'::jsonb)
      from request_offers ro
      join requests r on r.id = ro.request_id
      left join app_users su on su.id = ro.submitted_by
      where ro.request_id = p_request_id
        and r.tenant_id = get_my_tenant_id()
    ),
    'items', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', rli.id,
        'material_service', rli.material_service,
        'cost_code', rli.cost_code,
        'group_code', rli.group_code,
        'place_of_use', rli.place_of_use,
        'quantity', rli.quantity,
        'unit_price', rli.unit_price,
        'total', rli.total,
        'currency', rli.currency
      ) order by rli.created_at), '[]'::jsonb)
      from request_line_items rli
      join requests r on r.id = rli.request_id
      where rli.request_id = p_request_id
        and r.tenant_id = get_my_tenant_id()
    )
  );
$$;


--
-- Name: get_pending_material_request_batches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_material_request_batches() RETURNS TABLE(batch_id uuid, requester_id uuid, requester_name text, requested_at timestamp with time zone, pending_item_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select b.id, b.requester_id, u.name, b.created_at, count(i.id)
  from material_request_batches b
  join app_users u on u.id = b.requester_id
  join material_request_items i on i.batch_id = b.id and i.status = 'pending'
  where b.tenant_id = get_my_tenant_id() and has_po_access()
  group by b.id, b.requester_id, u.name, b.created_at
  order by b.created_at;
$$;


--
-- Name: get_pending_ticket_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_ticket_approvals() RETURNS SETOF public.it_tickets
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from it_tickets
  where tenant_id = get_my_tenant_id() and is_it_support() and approval_status = 'pending'
  order by created_at asc;
$$;


--
-- Name: get_platform_admin_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_admin_session() RETURNS TABLE(is_platform_admin boolean, has_mfa_factor boolean, session_is_mfa boolean, can_act boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    is_platform_admin(),
    platform_admin_has_mfa_factor(),
    platform_session_is_mfa(),
    is_platform_admin()
      and (not platform_admin_has_mfa_factor() or platform_session_is_mfa());
$$;


--
-- Name: get_platform_branding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_branding() RETURNS TABLE(platform_name text, logo_url text, primary_color text, support_email text, tagline text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with b as (
    select coalesce((select branding from platform_settings where id = true), '{}'::jsonb) as j
  )
  select
    coalesce(nullif(btrim(j ->> 'platform_name'), ''), 'VestaPortal'),
    -- Only http(s) URLs; anything else (javascript:, data:) is dropped.
    case when (j ->> 'logo_url') ~* '^https?://' then btrim(j ->> 'logo_url') else '' end,
    -- Must be a 6-digit hex colour or the brand default is used; this
    -- value ends up inside a style attribute and an email template.
    case when (j ->> 'primary_color') ~ '^#[0-9A-Fa-f]{6}$' then upper(j ->> 'primary_color') else '#1B5560' end,
    case when (j ->> 'support_email') ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then lower(btrim(j ->> 'support_email')) else '' end,
    coalesce(nullif(btrim(j ->> 'tagline'), ''), 'Multi-department ERP')
  from b;
$_$;


--
-- Name: get_platform_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_dashboard_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
  v_extra  jsonb;
begin
  if not is_platform_admin() then
    raise exception 'Only platform admins can view platform dashboard stats';
  end if;
  perform require_platform_admin('get platform dashboard stats');

  select jsonb_build_object(
    'totals', jsonb_build_object(
      'total_companies', (select count(*) from tenants),
      'active_companies', (select count(*) from tenants where status = 'active'),
      'pending_companies', (select count(*) from tenants where status = 'pending'),
      'suspended_companies', (select count(*) from tenants where status = 'suspended'),
      'total_members', (select count(*) from app_users),
      'total_pos', (select count(*) from purchase_orders),
      'total_po_value', coalesce((select sum(amount) from purchase_orders), 0),
      'total_requests', (select count(*) from requests),
      'requests_30d', (select count(*) from requests where created_at >= now() - interval '30 days'),
      'pending_requests', (select count(*) from requests where status = 'open'),
      'pending_invites', (select count(*) from invitations where status = 'pending' and role_bundle = 'company_admin')
    ),
    'by_status', (
      select coalesce(jsonb_agg(jsonb_build_object('status', status, 'count', cnt) order by cnt desc), '[]'::jsonb)
      from (select status, count(*) as cnt from tenants group by status) s
    ),
    'companies_by_month', (
      select coalesce(jsonb_agg(jsonb_build_object('month', month, 'count', cnt) order by month), '[]'::jsonb)
      from (
        select to_char(date_trunc('month', created_at), 'YYYY-MM') as month, count(*) as cnt
        from tenants
        where created_at >= date_trunc('month', now()) - interval '5 months'
        group by 1
      ) m
    ),
    'requests_by_month', (
      select coalesce(jsonb_agg(jsonb_build_object('month', month, 'count', cnt) order by month), '[]'::jsonb)
      from (
        select to_char(date_trunc('month', created_at), 'YYYY-MM') as month, count(*) as cnt
        from requests
        where created_at >= date_trunc('month', now()) - interval '5 months'
        group by 1
      ) m
    ),
    'module_adoption', (
      select coalesce(jsonb_agg(jsonb_build_object('module', module, 'count', cnt) order by cnt desc), '[]'::jsonb)
      from (
        select module, count(distinct tenant_id) as cnt
        from tenant_modules
        group by module
      ) ma
    ),
    'recent_companies', (
      select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'status', status, 'created_at', created_at) order by created_at desc), '[]'::jsonb)
      from (select id, name, status, created_at from tenants order by created_at desc limit 5) rc
    ),
    'top_companies_by_requests', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'count', cnt, 'tenant_id', tenant_id) order by cnt desc), '[]'::jsonb)
      from (
        select t.name, r.tenant_id, count(*) as cnt
        from requests r join tenants t on t.id = r.tenant_id
        group by t.name, r.tenant_id
        order by cnt desc
        limit 5
      ) tr
    ),
    'pending_invites_list', (
      select coalesce(jsonb_agg(jsonb_build_object('id', id, 'email', email, 'tenant_id', tenant_id, 'created_at', created_at) order by created_at desc), '[]'::jsonb)
      from (select id, email, tenant_id, created_at from invitations where status = 'pending' and role_bundle = 'company_admin' order by created_at desc limit 10) pi
    ),
    'pending_companies_list', (
      select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'created_at', created_at) order by created_at asc), '[]'::jsonb)
      from (select id, name, created_at from tenants where status = 'pending' order by created_at asc limit 25) pc
    ),
    'suspended_companies_list', (
      select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'created_at', created_at) order by created_at asc), '[]'::jsonb)
      from (select id, name, created_at from tenants where status = 'suspended' order by created_at asc limit 25) sc
    )
  ) into v_result;

  -- Item 5 additions. The onboarding view and the activity scan are
  -- each computed once (MATERIALIZED) and shared by every key below.
  with _dash_onb as materialized (
    select * from get_tenant_onboarding_status() where not is_internal
  ),
  _dash_act as materialized (
    select a.* from platform_module_activity(30) a
    join _dash_onb o on o.tenant_id = a.tenant_id
  )
  select jsonb_build_object(
    'onboarding_funnel', (
      select coalesce(jsonb_agg(jsonb_build_object('stage', st.stage, 'stage_key', st.stage_key, 'count', coalesce(c.cnt, 0)) order by st.stage), '[]'::jsonb)
      from (values
        (0, 'created'), (1, 'admin_invited'), (2, 'admin_joined'), (3, 'modules_enabled'),
        (4, 'team_invited'), (5, 'first_activity'), (6, 'live')
      ) as st(stage, stage_key)
      left join (select stage, count(*) as cnt from _dash_onb where status <> 'suspended' group by stage) c on c.stage = st.stage
    ),
    'stalled_onboarding', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', o.tenant_id, 'name', o.name, 'status', o.status, 'stage', o.stage, 'stage_key', o.stage_key,
        'next_step', o.next_step, 'days_in_stage', o.days_in_stage, 'created_at', o.created_at,
        'contact_email', o.contact_email
      ) order by o.days_in_stage desc), '[]'::jsonb)
      from (select * from _dash_onb where stalled order by days_in_stage desc limit 25) o
    ),
    'quiet_tenants', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', o.tenant_id, 'name', o.name, 'plan', o.plan, 'subscription_status', o.subscription_status,
        'member_count', o.member_count, 'last_activity_at', o.last_activity_at,
        'days_quiet', greatest(0, extract(epoch from (now() - coalesce(o.last_activity_at, o.created_at))) / 86400)::integer,
        'contact_email', o.contact_email
      ) order by coalesce(o.last_activity_at, o.created_at) asc), '[]'::jsonb)
      from (
        select * from _dash_onb
        where status = 'active' and stage = 5
          and created_at < now() - interval '30 days'
        order by coalesce(last_activity_at, created_at) asc
        limit 25
      ) o
    ),
    'module_usage', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'module', m.module,
        'tenants_enabled', case
          when m.module = 'finance' then (select count(*) from _dash_onb)
          else (select count(distinct tm.tenant_id) from tenant_modules tm join _dash_onb o on o.tenant_id = tm.tenant_id where tm.module = m.module)
        end,
        'tenants_active_30d', (select count(distinct a.tenant_id) from _dash_act a where a.module = m.module and a.events > 0),
        'events_30d', coalesce((select sum(a.events) from _dash_act a where a.module = m.module), 0),
        'events_prev_30d', coalesce((select sum(a.events_prev) from _dash_act a where a.module = m.module), 0)
      ) order by m.ord), '[]'::jsonb)
      from (values
        (1, 'procurement'), (2, 'finance'), (3, 'hr'), (4, 'legal'), (5, 'bd'),
        (6, 'it'), (7, 'pmo'), (8, 'machine_operation'), (9, 'sustainability')
      ) as m(ord, module)
    ),
    'trial_ending_soon', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', o.tenant_id, 'name', o.name, 'trial_ends_at', o.trial_ends_at,
        'days_left', greatest(0, ceil(extract(epoch from (o.trial_ends_at - now())) / 86400))::integer,
        'stage_key', o.stage_key, 'member_count', o.member_count, 'contact_email', o.contact_email
      ) order by o.trial_ends_at), '[]'::jsonb)
      from (
        select * from _dash_onb
        where subscription_status = 'trialing' and trial_ends_at is not null
          and trial_ends_at <= now() + interval '14 days'
          and status <> 'suspended'
        order by trial_ends_at
        limit 25
      ) o
    )
  ) into v_extra;

  return v_result || v_extra;
end;
$$;


--
-- Name: get_platform_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v jsonb;
  v_has_cron boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_has_storage boolean := to_regclass('storage.objects') is not null;
  v_storage jsonb := '[]'::jsonb;
  v_cron jsonb := '[]'::jsonb;
  v_migration text;
  v_migration_count integer := 0;
begin
  if not is_platform_admin() then
    raise exception 'PLATFORM_ADMIN_REQUIRED: platform health is restricted to platform admins' using errcode = '42501';
  end if;
  perform require_platform_admin('get platform health');

  if to_regclass('supabase_migrations.schema_migrations') is not null then
    execute 'select max(version), count(*)::int from supabase_migrations.schema_migrations' into v_migration, v_migration_count;
  end if;

  if v_has_storage then
    execute $q$
      select coalesce(jsonb_agg(jsonb_build_object('bucket', bucket_id, 'objects', n, 'bytes', bytes) order by bytes desc), '[]'::jsonb)
      from (select bucket_id, count(*) as n, coalesce(sum((metadata ->> 'size')::bigint), 0) as bytes
            from storage.objects group by bucket_id) s
    $q$ into v_storage;
  end if;

  if v_has_cron then
    execute $q$
      select coalesce(jsonb_agg(jsonb_build_object(
        'jobname', j.jobname, 'schedule', j.schedule, 'active', j.active,
        'last_status', r.status, 'last_start', r.start_time, 'last_end', r.end_time, 'last_message', left(r.return_message, 200)
      ) order by j.jobname), '[]'::jsonb)
      from cron.job j
      left join lateral (select status, start_time, end_time, return_message from cron.job_run_details d
                         where d.jobid = j.jobid order by start_time desc limit 1) r on true
    $q$ into v_cron;
  end if;

  select jsonb_build_object(
    'checked_at', now(),
    'database', jsonb_build_object(
      'version', split_part(version(), ' ', 2),
      'size_bytes', pg_database_size(current_database()),
      'connections', (select count(*) from pg_stat_activity where datname = current_database()),
      'max_connections', current_setting('max_connections')::int
    ),
    'migrations', jsonb_build_object('latest', v_migration, 'count', v_migration_count),
    'cron', jsonb_build_object('installed', v_has_cron, 'jobs', v_cron),
    'jobs', (
      -- Last run per job; the UI decides freshness (sweeps are per tenant
      -- and only run when someone opens the page, so "stale" is a hint
      -- not an alarm; the digest is expected daily).
      select coalesce(jsonb_agg(jsonb_build_object(
        'job', j.job, 'last_run_at', j.last_run_at, 'last_status', j.last_status, 'last_affected', j.last_affected,
        'last_detail', j.last_detail, 'runs_7d', j.runs_7d, 'errors_7d', j.errors_7d, 'tenants_7d', j.tenants_7d
      ) order by j.job), '[]'::jsonb)
      from (
        select r.job,
               max(r.started_at) as last_run_at,
               (array_agg(r.status order by r.started_at desc))[1] as last_status,
               (array_agg(r.affected order by r.started_at desc))[1] as last_affected,
               (array_agg(r.detail order by r.started_at desc))[1] as last_detail,
               count(*) filter (where r.started_at > now() - interval '7 days') as runs_7d,
               count(*) filter (where r.started_at > now() - interval '7 days' and r.status = 'error') as errors_7d,
               count(distinct r.tenant_id) filter (where r.started_at > now() - interval '7 days') as tenants_7d
        from platform_job_runs r
        group by r.job
      ) j
    ),
    'digest', jsonb_build_object(
      'last_generated_at', (select max(generated_at) from platform_digests),
      'failed_7d', (select count(*) from platform_digests where delivery_status = 'failed' and generated_at > now() - interval '7 days'),
      'pending', (select count(*) from platform_digests where delivery_status = 'pending')
    ),
    'stuck_approvals', (
      -- Open requests sitting at a stage for more than 7 days, per company.
      select coalesce(jsonb_agg(jsonb_build_object('tenant_id', s.tenant_id, 'tenant_name', s.name, 'count', s.n, 'oldest_days', s.oldest) order by s.n desc), '[]'::jsonb)
      from (
        select r.tenant_id, t.name, count(*) as n,
               max(extract(epoch from (now() - r.updated_at)) / 86400)::integer as oldest
        from requests r join tenants t on t.id = r.tenant_id
        where r.status = 'open' and r.current_stage_id is not null and r.updated_at < now() - interval '7 days'
        group by r.tenant_id, t.name
        limit 25
      ) s
    ),
    'stale_invites', (
      select coalesce(jsonb_agg(jsonb_build_object('tenant_id', s.tenant_id, 'tenant_name', s.name, 'count', s.n, 'oldest_days', s.oldest) order by s.n desc), '[]'::jsonb)
      from (
        select i.tenant_id, t.name, count(*) as n,
               max(extract(epoch from (now() - i.created_at)) / 86400)::integer as oldest
        from invitations i join tenants t on t.id = i.tenant_id
        where i.status = 'pending' and i.created_at < now() - interval '7 days'
        group by i.tenant_id, t.name
        limit 25
      ) s
    ),
    'read_only_tenants', (select count(*) from tenants where read_only),
    'open_impersonations', (select count(*) from impersonation_sessions where ended_at is null and (expires_at is null or expires_at > now())),
    'storage', jsonb_build_object('available', v_has_storage, 'buckets', v_storage),
    'announcements_live', (select count(*) from platform_announcements a where a.is_active and a.starts_at <= now() and (a.ends_at is null or a.ends_at > now())),
    'feature_flags', (select count(*) from platform_feature_flags)
  ) into v;

  return v;
end;
$_$;


--
-- Name: get_po_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_po_detail(p_purchase_order_id uuid) RETURNS TABLE(purchase_order_id uuid, request_id uuid, po_number text, initial_po_number text, vendor_name text, po_amount numeric, currency text, generated_at timestamp with time zone, generated_by_name text, shared_with_supplier boolean, delivered_at timestamp with time zone, completed_at timestamp with time zone, mr_number text, mr_title text, mr_date date, requester_name text, delivery_date date, project_sap_no text, payment_conditions text, terms_of_delivery text, offer_quotation_amount numeric, offer_quantity integer, offer_submitted_by_name text, offer_submitted_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    po.id as purchase_order_id,
    po.request_id,
    po.po_number,
    po.initial_po_number,
    po.vendor_name,
    po.amount as po_amount,
    po.currency,
    po.generated_at,
    generator.name as generated_by_name,
    po.shared_with_supplier,
    po.delivered_at,
    po.completed_at,
    r.mr_number,
    r.item_description as mr_title,
    r.created_at::date as mr_date,
    requester.name as requester_name,
    r.delivery_date,
    po.project_sap_no,
    po.payment_conditions,
    po.terms_of_delivery,
    ro.quotation_amount as offer_quotation_amount,
    ro.quantity as offer_quantity,
    submitter.name as offer_submitted_by_name,
    ro.submitted_at as offer_submitted_at
  from purchase_orders po
  join requests r on r.id = po.request_id
  join app_users requester on requester.id = r.requester_id
  join app_users generator on generator.id = po.generated_by
  left join request_offers ro
    on ro.request_id = po.request_id
    and ro.vendor_name = po.vendor_name
  left join app_users submitter on submitter.id = ro.submitted_by
  where po.id = p_purchase_order_id
    and r.tenant_id = get_my_tenant_id()
  order by ro.submitted_at desc
  limit 1;
$$;


--
-- Name: get_po_edit_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_po_edit_history(po_id uuid) RETURNS TABLE(id uuid, edited_at timestamp with time zone, reason text, changes jsonb, editor jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    pe.id, pe.edited_at, pe.reason, pe.changes,
    jsonb_build_object('id', au.id, 'name', au.name) as editor
  from po_edits pe
  join app_users au on au.id = pe.edited_by
  join purchase_orders po on po.id = pe.purchase_order_id
  join requests r on r.id = po.request_id
  where pe.purchase_order_id = po_id
    and has_po_access()
    and r.tenant_id = get_my_tenant_id()
  order by pe.edited_at desc;
$$;


--
-- Name: get_po_pdf_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_po_pdf_data(p_purchase_order_id uuid) RETURNS TABLE(purchase_order_id uuid, po_number text, initial_po_number text, company text, po_total numeric, currency text, po_date date, mr_number text, mr_title text, requester_name text, purchaser_name text, delivery_date date, organization_name text, project_sap_no text, payment_conditions text, terms_of_delivery text, primary_cost_code text, line_items jsonb, approvals jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    po.id,
    po.po_number,
    po.initial_po_number,
    po.vendor_name,
    po.amount,
    po.currency,
    po.generated_at::date,
    r.mr_number,
    r.item_description,
    requester.name,
    purchaser.name,
    r.delivery_date,
    o.site_name,
    po.project_sap_no,
    po.payment_conditions,
    po.terms_of_delivery,
    (
      select rli.cost_code
      from request_line_items rli
      where rli.request_id = r.id
      order by rli.created_at
      limit 1
    ),
    coalesce(
      (
        select jsonb_agg(jsonb_build_object(
          'material_service', rli.material_service,
          'cost_code', rli.cost_code,
          'place_of_use', rli.place_of_use,
          'quantity', rli.quantity,
          'unit_price', rli.unit_price,
          'total', rli.total,
          'currency', rli.currency
        ) order by rli.created_at)
        from request_line_items rli
        where rli.request_id = r.id
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(jsonb_build_object(
          'stage_name', ws.name,
          'approver_role', ws.approver_role,
          'approver_name', au.name,
          'sequence_order', ws.sequence_order,
          'acted_at', aa.acted_at
        ) order by ws.sequence_order, aa.acted_at)
        from approval_actions aa
        join workflow_stages ws on ws.id = aa.workflow_stage_id
        join app_users au on au.id = aa.approver_id
        where aa.request_id = r.id
          and aa.decision = 'approved'
          and aa.acted_at = (
            select max(aa2.acted_at)
            from approval_actions aa2
            where aa2.request_id = aa.request_id
              and aa2.workflow_stage_id = aa.workflow_stage_id
              and aa2.decision = 'approved'
          )
      ),
      '[]'::jsonb
    )
  from purchase_orders po
  join requests r on r.id = po.request_id
  join app_users requester on requester.id = r.requester_id
  left join organizations o on o.id = r.organization_id
  left join request_offers ro on ro.request_id = r.id
  left join app_users purchaser on purchaser.id = ro.submitted_by
  where po.id = p_purchase_order_id
    and r.tenant_id = get_my_tenant_id();
$$;


