-- Name: get_problem_tickets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_problem_tickets(p_problem_id uuid) RETURNS SETOF public.it_tickets
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.* from it_tickets t
  join problem_tickets pt on pt.ticket_id = t.id
