--
-- Name: get_support_team_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_support_team_members(p_team_id uuid) RETURNS TABLE(user_id uuid, name text, email text, added_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to view team members';
  end if;
  return query
  select u.id, u.name, u.email, m.added_at
  from support_team_members m
  join app_users u on u.id = m.user_id
  join support_teams st on st.id = m.team_id
  where m.team_id = p_team_id and st.tenant_id = get_my_tenant_id()
  order by u.name;
end;
$$;


--
-- Name: get_support_teams(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_support_teams() RETURNS TABLE(id uuid, name text, description text, is_active boolean, member_count bigint, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select st.id, st.name, st.description, st.is_active, count(m.user_id), st.created_at
  from support_teams st
  left join support_team_members m on m.team_id = st.id
  where st.tenant_id = get_my_tenant_id()
  group by st.id
  order by st.name;
$$;


--
-- Name: get_tenant_feature_flags(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_feature_flags(p_tenant_id uuid) RETURNS TABLE(key text, description text, default_enabled boolean, override boolean, effective boolean, note text, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.key, f.description, f.default_enabled, tf.enabled, coalesce(tf.enabled, f.default_enabled), tf.note, tf.updated_at
  from platform_feature_flags f
  left join tenant_feature_flags tf on tf.flag_key = f.key and tf.tenant_id = p_tenant_id
  where public.platform_admin_mfa_gate('get tenant feature flags')
  order by f.key;
$$;


--
-- Name: get_tenant_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
