-- Name: get_tenant_onboarding_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_onboarding_status() RETURNS TABLE(tenant_id uuid, name text, status text, created_at timestamp with time zone, plan text, subscription_status text, trial_ends_at timestamp with time zone, contact_email text, is_internal boolean, member_count bigint, stage integer, stage_key text, next_step text, stage_reached_at timestamp with time zone, days_in_stage integer, stalled boolean, admin_invited_at timestamp with time zone, admin_joined_at timestamp with time zone, modules_enabled_at timestamp with time zone, team_invited_at timestamp with time zone, first_activity_at timestamp with time zone, last_activity_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
