-- Name: get_ticket_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_categories() RETURNS SETOF public.ticket_categories
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from ticket_categories where tenant_id = get_my_tenant_id() order by name;
$$;


--
-- Name: get_vendor_evaluation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_evaluation() RETURNS TABLE(vendor_account_id uuid, account_code text, vendor_name text, contact_name text, contact_phone text, contact_email text, is_active boolean, total_pos bigint, total_po_value numeric, delivered_pos bigint, avg_days_to_deliver numeric, on_time_delivery_pct numeric, fulfillment_accuracy_pct numeric, over_delivery_pct numeric, under_delivery_pct numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (is_finance_team_member(null) or has_po_access()) then
    raise exception 'not authorized to view vendor evaluation data';
  end if;

  return query
  select
    v.vendor_account_id, v.account_code, v.vendor_name, v.contact_name,
    v.contact_phone, v.contact_email, v.is_active, v.total_pos, v.total_po_value,
    v.delivered_pos, v.avg_days_to_deliver, v.on_time_delivery_pct,
    v.fulfillment_accuracy_pct, v.over_delivery_pct, v.under_delivery_pct
  from v_vendor_evaluation v
  where v.tenant_id = get_my_tenant_id()
  order by v.total_pos desc nulls last, v.vendor_name;
end;
$$;


--
-- Name: approval_delegations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_delegations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    delegator_user_id uuid NOT NULL,
    delegate_user_id uuid NOT NULL,
    workflow_stage_id uuid,
    starts_at timestamp with time zone DEFAULT now() NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approval_delegations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'expired'::text, 'revoked'::text]))),
    CONSTRAINT chk_delegation_window CHECK ((ends_at > starts_at))
);


--
-- Name: grant_delegation(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_delegation(p_delegate_user_id uuid, p_workflow_stage_id uuid DEFAULT NULL::uuid, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.approval_delegations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_delegator_tenant uuid;
  v_delegate_tenant  uuid;
  v_starts_at        timestamptz := coalesce(p_starts_at, now());
  v_created          approval_delegations%ROWTYPE;
BEGIN
  IF p_delegate_user_id IS NULL OR p_ends_at IS NULL THEN
    RAISE EXCEPTION 'delegate_user_id and ends_at are required';
  END IF;
  IF p_delegate_user_id = auth.uid() THEN
    RAISE EXCEPTION 'you cannot delegate to yourself';
  END IF;
  IF p_ends_at <= v_starts_at THEN
    RAISE EXCEPTION 'ends_at must be after starts_at';
  END IF;

  v_delegator_tenant := get_my_tenant_id();
  IF v_delegator_tenant IS NULL THEN
    RAISE EXCEPTION 'delegator profile not found or company access is suspended';
  END IF;

  SELECT tenant_id INTO v_delegate_tenant FROM app_users WHERE id = p_delegate_user_id;
  IF v_delegate_tenant IS NULL THEN
    RAISE EXCEPTION 'delegate user not found';
  END IF;
  IF v_delegate_tenant != v_delegator_tenant THEN
    RAISE EXCEPTION 'delegate must belong to the same tenant';
  END IF;

  IF p_workflow_stage_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM approval_assignments
      WHERE user_id = auth.uid() AND workflow_stage_id = p_workflow_stage_id
    ) THEN
      RAISE EXCEPTION 'you do not hold approval authority for that stage, so you cannot delegate it';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM approval_assignments WHERE user_id = auth.uid()) THEN
      RAISE EXCEPTION 'you do not hold any approval assignments to delegate';
    END IF;
  END IF;

  BEGIN
    INSERT INTO approval_delegations (
      tenant_id, delegator_user_id, delegate_user_id, workflow_stage_id, starts_at, ends_at, status
    ) VALUES (
      v_delegator_tenant, auth.uid(), p_delegate_user_id, p_workflow_stage_id, v_starts_at, p_ends_at, 'active'
    ) RETURNING * INTO v_created;
  EXCEPTION WHEN exclusion_violation THEN
    RAISE EXCEPTION 'an overlapping active delegation already exists for this delegator, delegate, and stage';
  END;

  RETURN v_created;
END;
$$;


--
-- Name: hr_team_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_team_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: grant_hr_team_member(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_hr_team_member(p_user_id uuid, p_role text DEFAULT 'member'::text) RETURNS public.hr_team_members
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.hr_team_members%rowtype;
begin
  if not has_module_role('hr', array['admin']) then
    raise exception 'not authorized to manage the HR team';
  end if;
  if not exists (select 1 from app_users where id = p_user_id and tenant_id = get_my_tenant_id()) then
    raise exception 'user not found in this tenant';
  end if;

  insert into hr_team_members (tenant_id, user_id, role)
  values (get_my_tenant_id(), p_user_id, p_role)
  on conflict (tenant_id, user_id) do update set role = excluded.role
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: payroll_approvers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_approvers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: grant_payroll_approver(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_payroll_approver(p_user_id uuid) RETURNS public.payroll_approvers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.payroll_approvers%rowtype;
begin
  if not has_module_role('hr', array['admin']) then
    raise exception 'not authorized to manage payroll approvers';
  end if;
  if p_user_id = effective_user_id() and not platform_admin_bypass() then
    raise exception 'not authorized: you cannot grant payroll approver access to yourself';
  end if;
  if not exists (select 1 from app_users where id = p_user_id and tenant_id = get_my_tenant_id()) then
    raise exception 'user not found in this tenant';
  end if;

  insert into payroll_approvers (tenant_id, user_id, role, is_active)
  values (get_my_tenant_id(), p_user_id, 'approver', true)
  on conflict (tenant_id, user_id) do update set is_active = true
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: handle_updated_at_generic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_updated_at_generic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  NEW.updated_at = now();
  return NEW;
end;
$$;


--
-- Name: has_module_role(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_module_role(p_module text, p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    public.platform_admin_bypass()
    or (
      exists (
        select 1 from public.tenant_modules
        where tenant_id = public.get_my_tenant_id()
          and module = p_module
      )
      and exists (
        select 1 from public.staff_roles
        where user_id = public.effective_user_id()
          and module = p_module
          and role = any(p_roles)
          and tenant_id = public.get_my_tenant_id()
      )
    );
$$;


--
-- Name: has_po_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_po_access() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    public.platform_admin_bypass()
    or exists (
      select 1
      from approval_assignments aa
      join workflow_stages ws on ws.id = aa.workflow_stage_id
      where aa.user_id = public.effective_user_id()
        and ws.next_stage_low_id is null
        and ws.next_stage_high_id is null
    )
    or exists (
      select 1
      from approval_delegations d
      join approval_assignments aa on aa.user_id = d.delegator_user_id
      join workflow_stages ws on ws.id = aa.workflow_stage_id
      where d.delegate_user_id = public.effective_user_id()
        and d.status = 'active'
        and now() between d.starts_at and d.ends_at
        and ws.next_stage_low_id is null
        and ws.next_stage_high_id is null
        and (d.workflow_stage_id is null or d.workflow_stage_id = ws.id)
    );
$$;


--
-- Name: has_receipt_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_receipt_access() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from material_receipt_assignments
    where user_id = public.effective_user_id() and tenant_id = get_my_tenant_id()
  );
$$;


