-- Name: health_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.health_check() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'status', 'ok',
    'checked_at', now()
  );
$$;


--
-- Name: impersonated_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.impersonated_user_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select s.impersonated_user_id
  from impersonation_sessions s
  where s.platform_admin_id = auth.uid()
    and s.ended_at is null
    and s.expires_at > now()
  order by s.started_at desc
  limit 1;
$$;


--
-- Name: bank_statement_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_statement_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    bank_account text NOT NULL,
    statement_date date NOT NULL,
    description text,
    reference text,
    amount numeric NOT NULL,
    currency text NOT NULL,
    imported_by uuid,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bank_statement_lines_amount_nonzero_check CHECK ((amount <> (0)::numeric))
);


--
-- Name: import_bank_statement_lines(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bank_statement_lines(p_bank_account text, p_lines jsonb) RETURNS SETOF public.bank_statement_lines
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_line jsonb;
  v_account fin_bank_accounts%rowtype;
begin
  if not is_finance_team_member('finance') then
    raise exception 'not authorized to import bank statement lines';
  end if;

  if p_bank_account is null or btrim(p_bank_account) = '' then
    raise exception 'bank_account is required';
  end if;

  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'at least one statement line is required';
  end if;

  -- The registry is the source of truth for an account's currency. A name
  -- that is not registered keeps the legacy free-text behaviour.
  select * into v_account
    from fin_bank_accounts
   where tenant_id = v_tenant_id and name = btrim(p_bank_account);

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    if (v_line ->> 'statement_date') is null or (v_line ->> 'amount') is null then
      raise exception 'each line requires statement_date and amount';
    end if;

    if v_account.id is not null
       and coalesce(nullif(v_line ->> 'currency', ''), v_account.currency)
           is distinct from v_account.currency then
      raise exception 'BANK_STMT_CURRENCY: statement lines for % must be in %, got %',
        v_account.name, v_account.currency, nullif(v_line ->> 'currency', '');
    end if;

    return query
    insert into bank_statement_lines (
      tenant_id, bank_account, statement_date, description, reference, amount, currency, imported_by
    ) values (
      v_tenant_id,
      btrim(p_bank_account),
      (v_line ->> 'statement_date')::date,
      nullif(v_line ->> 'description', ''),
      nullif(v_line ->> 'reference', ''),
      (v_line ->> 'amount')::numeric,
      coalesce(nullif(v_line ->> 'currency', ''), v_account.currency, 'UGX'),
      auth.uid()
    )
    returning *;
  end loop;
end;
$$;


--
-- Name: ins_insurer_product_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_insurer_product_rates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    insurer_id uuid NOT NULL,
    product_line_id uuid NOT NULL,
    rate numeric(5,2) NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    source_ref text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    entered_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    withdrawn_reason text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ins_insurer_product_rates_approved_check CHECK (((status <> 'approved'::text) OR ((approved_by IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT ins_insurer_product_rates_rate_check CHECK (((rate >= (0)::numeric) AND (rate < (100)::numeric))),
    CONSTRAINT ins_insurer_product_rates_source_check CHECK ((btrim(source_ref) <> ''::text)),
    CONSTRAINT ins_insurer_product_rates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'withdrawn'::text]))),
    CONSTRAINT ins_insurer_product_rates_window_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from)))
);


--
-- Name: ins_approve_insurer_product_rate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_approve_insurer_product_rate(p_id uuid) RETURNS public.ins_insurer_product_rates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row ins_insurer_product_rates%rowtype;
  v_uid uuid := auth.uid();
begin
  select * into v_row from ins_insurer_product_rates
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'INS_RATE_NOT_FOUND: rate not found';
  end if;
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers approve commission rates' using errcode = '42501';
  end if;
  if v_row.status <> 'draft' then
    raise exception 'INS_RATE_NOT_DRAFT: only a draft can be approved (this one is %)', v_row.status;
  end if;
  if v_row.entered_by is not distinct from v_uid then
    raise exception 'INS_RATE_SELF_APPROVAL: the person who entered a rate cannot approve it';
  end if;
  -- Exactly one approved rate in force per insurer, product line and date.
  if exists (
    select 1 from ins_insurer_product_rates r2
    where r2.tenant_id = v_row.tenant_id
      and r2.insurer_id = v_row.insurer_id
      and r2.product_line_id = v_row.product_line_id
      and r2.id <> v_row.id
      and r2.status = 'approved'
      and r2.effective_from <= coalesce(v_row.effective_to, 'infinity'::date)
      and coalesce(r2.effective_to, 'infinity'::date) >= v_row.effective_from
  ) then
    raise exception 'INS_RATE_OVERLAP: another approved rate for this insurer and product line already covers part of this window';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  update ins_insurer_product_rates
     set status = 'approved', approved_by = v_uid, approved_at = now()
   where id = p_id
   returning * into v_row;
  perform set_config('ins.via_rpc', 'off', true);
  return v_row;
end;
$$;


--
-- Name: ins_attach_certificate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_attach_certificate(p_policy_id uuid, p_serial_no text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); p ins_policies%rowtype; c ins_certificate_stock%rowtype;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  select * into p from ins_policies where id = p_policy_id and tenant_id = t for update;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  if p.status <> 'draft' then raise exception 'INS_NOT_DRAFT: certificates can only be attached to a draft policy'; end if;
  select * into c from ins_certificate_stock where tenant_id = t and serial_no = btrim(p_serial_no) for update;
  if not found then raise exception 'INS_NOT_FOUND: certificate'; end if;
  if c.status <> 'issued' or c.policy_id is not null then
    raise exception 'INS_CERTIFICATE_STATE: certificate % must be issued and not attached to another policy', c.serial_no;
  end if;
  if not exists (select 1 from ins_policy_risks where policy_id = p_policy_id and risk_id = c.risk_id) then
    raise exception 'INS_CERTIFICATE_RISK: link the certificate''s risk to this policy first';
  end if;
  update ins_certificate_stock set policy_id = null
   where tenant_id = t and policy_id = p_policy_id and status = 'issued';
  update ins_certificate_stock set policy_id = p_policy_id where id = c.id;
end $$;


--
-- Name: ins_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_no text NOT NULL,
    client_id uuid NOT NULL,
    insurer_id uuid NOT NULL,
    product_line_id uuid NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    inception_date date NOT NULL,
    expiry_date date NOT NULL,
    sum_insured numeric(18,2) DEFAULT 0 NOT NULL,
    currency text NOT NULL,
    gross_premium numeric(18,2) DEFAULT 0 NOT NULL,
    commission_rate_pct numeric(5,2) DEFAULT 0 NOT NULL,
    commission_amount numeric(18,2),
    net_premium_to_insurer numeric(18,2),
    bound_at timestamp with time zone,
    bound_by uuid,
    journal_entry_id uuid,
    renewal_of_id uuid,
    risk_description text,
    notes text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    branch_id uuid,
    agent_id uuid,
    transaction_type text DEFAULT 'new_business'::text NOT NULL,
    CONSTRAINT ins_policies_bound_check CHECK (((status = 'draft'::text) OR ((gross_premium > (0)::numeric) AND (commission_amount IS NOT NULL) AND (net_premium_to_insurer IS NOT NULL) AND ((commission_amount + net_premium_to_insurer) = gross_premium) AND (bound_at IS NOT NULL)))),
    CONSTRAINT ins_policies_commission_check CHECK (((commission_rate_pct >= (0)::numeric) AND (commission_rate_pct < (100)::numeric))),
    CONSTRAINT ins_policies_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ins_policies_dates_check CHECK ((expiry_date > inception_date)),
    CONSTRAINT ins_policies_no_self_renewal CHECK (((renewal_of_id IS NULL) OR (renewal_of_id <> id))),
    CONSTRAINT ins_policies_premium_check CHECK ((gross_premium >= (0)::numeric)),
    CONSTRAINT ins_policies_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'renewed'::text, 'reversed'::text, 'cancelled'::text]))),
    CONSTRAINT ins_policies_sum_check CHECK ((sum_insured >= (0)::numeric)),
    CONSTRAINT ins_policies_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['new_business'::text, 'renewal'::text])))
);


--
-- Name: ins_bind_policy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_bind_policy(p_policy_id uuid) RETURNS public.ins_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; is_motor boolean;
begin
  p := platform_ins_bind_policy_risk_legacy_impl(p_policy_id);
  is_motor := public.platform_ins_line_needs_certificate(p.tenant_id, p.product_line_id);
  if is_motor then
    if not exists (select 1 from ins_certificate_stock c where c.tenant_id = p.tenant_id and c.policy_id = p.id and c.status = 'issued') then
      raise exception 'INS_MOTOR_CERTIFICATE_REQUIRED: attach an issued motor certificate to this policy before binding';
    end if;
    update ins_certificate_stock set status = 'used' where tenant_id = p.tenant_id and policy_id = p.id and status = 'issued';
  end if;
  return p;
end $$;


--
-- Name: ins_branch_options(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_branch_options(p_include_inactive boolean DEFAULT false) RETURNS TABLE(id uuid, site_name text, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select o.id, o.site_name, o.is_active
  from public.organizations o
  where o.tenant_id = public.get_my_tenant_id()
    and public.can_access_insurance()
    and (p_include_inactive or o.is_active)
  order by o.site_name;
$$;


--
-- Name: ins_policy_cancellations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_cancellations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    request_key uuid NOT NULL,
    reason text NOT NULL,
    effective_date date NOT NULL,
    insurer_terms jsonb NOT NULL,
    charge_refunds jsonb NOT NULL,
    proposed_by uuid NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    prepared_by uuid,
    prepared_at timestamp with time zone,
    clearing_gl_account_id uuid,
    calculation jsonb NOT NULL,
    checked_by uuid,
    checked_at timestamp with time zone,
    review_note text,
    manual_exception_accepted boolean DEFAULT false NOT NULL,
    cancellation_no text,
    posting_date date,
    journal_entry_id uuid,
    refund_item_id uuid,
    cash_at_posting jsonb,
    accounting_mappings jsonb,
    operation_txid bigint,
    CONSTRAINT ins_policy_cancellations_charge_refunds_check CHECK ((jsonb_typeof(charge_refunds) = 'array'::text)),
    CONSTRAINT ins_policy_cancellations_check CHECK (((checked_by IS NULL) OR ((checked_by IS DISTINCT FROM prepared_by) AND (checked_by IS DISTINCT FROM proposed_by)))),
    CONSTRAINT ins_policy_cancellations_check1 CHECK (((status <> ALL (ARRAY['prepared'::text, 'posting'::text, 'posted'::text])) OR ((prepared_by IS NOT NULL) AND (prepared_at IS NOT NULL) AND (clearing_gl_account_id IS NOT NULL)))),
    CONSTRAINT ins_policy_cancellations_check2 CHECK (((status <> ALL (ARRAY['posting'::text, 'posted'::text])) OR ((checked_by IS NOT NULL) AND (checked_at IS NOT NULL) AND (length(btrim(review_note)) >= 5)))),
    CONSTRAINT ins_policy_cancellations_check3 CHECK (((status = 'posting'::text) = (operation_txid IS NOT NULL))),
    CONSTRAINT ins_policy_cancellations_check4 CHECK (((status <> 'posted'::text) OR ((cancellation_no IS NOT NULL) AND (posting_date IS NOT NULL) AND (cash_at_posting IS NOT NULL)))),
    CONSTRAINT ins_policy_cancellations_insurer_terms_check CHECK ((jsonb_typeof(insurer_terms) = 'array'::text)),
    CONSTRAINT ins_policy_cancellations_reason_check CHECK (((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT ins_policy_cancellations_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'prepared'::text, 'posting'::text, 'posted'::text, 'rejected'::text, 'withdrawn'::text])))
);


--
-- Name: ins_policy_charges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_charges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    kind text NOT NULL,
    description text NOT NULL,
    amount numeric(18,2),
    recipient_mode text NOT NULL,
    recipient_insurer_id uuid,
    vat_mode text DEFAULT 'not_calculated'::text NOT NULL,
    vat_rate_pct numeric(7,4),
    vat_amount numeric(18,2),
    income_gl_account_id uuid,
    reviewed boolean DEFAULT false NOT NULL,
    CONSTRAINT ins_policy_charges_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT ins_policy_charges_check CHECK ((((kind = 'broker_fee'::text) AND (recipient_mode = 'broker'::text) AND (recipient_insurer_id IS NULL)) OR ((kind = 'insurer_pass_through'::text) AND (vat_mode = 'not_calculated'::text) AND (((recipient_mode = 'all_insurers'::text) AND (recipient_insurer_id IS NULL)) OR ((recipient_mode = 'one_insurer'::text) AND (recipient_insurer_id IS NOT NULL)))))),
    CONSTRAINT ins_policy_charges_check1 CHECK ((((vat_mode = 'not_calculated'::text) AND (vat_rate_pct IS NULL)) OR ((vat_mode = 'exclusive'::text) AND (vat_rate_pct > (0)::numeric) AND (vat_rate_pct <= (100)::numeric)))),
    CONSTRAINT ins_policy_charges_description_check CHECK ((length(btrim(description)) > 0)),
    CONSTRAINT ins_policy_charges_kind_check CHECK ((kind = ANY (ARRAY['insurer_pass_through'::text, 'broker_fee'::text]))),
    CONSTRAINT ins_policy_charges_recipient_mode_check CHECK ((recipient_mode = ANY (ARRAY['all_insurers'::text, 'one_insurer'::text, 'broker'::text]))),
    CONSTRAINT ins_policy_charges_vat_mode_check CHECK ((vat_mode = ANY (ARRAY['not_calculated'::text, 'exclusive'::text])))
);


--
-- Name: ins_policy_financial_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_financial_snapshots (
    policy_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    extended boolean NOT NULL,
    invoice_total numeric(18,2) NOT NULL,
    broker_fee_total numeric(18,2) NOT NULL,
    vat_total numeric(18,2) NOT NULL,
    snapshot jsonb NOT NULL,
    journal_entry_id uuid NOT NULL,
    bound_by uuid NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ins_policy_financial_snapshots_invoice_total_check CHECK ((invoice_total > (0)::numeric)),
    CONSTRAINT ins_policy_financial_snapshots_policy_version_check CHECK ((accounting_policy_version >= 1))
);


--
-- Name: ins_broker_fee_tax_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_broker_fee_tax_report WITH (security_invoker='true') AS
 SELECT c.id AS charge_id,
    c.tenant_id,
    c.policy_id,
    p.policy_no,
    p.currency,
    p.inception_date AS invoice_date,
    c.description,
    c.amount AS fee_amount,
    c.vat_mode,
    c.vat_rate_pct,
    COALESCE(c.vat_amount, (0)::numeric) AS vat_amount,
    (c.amount + COALESCE(c.vat_amount, (0)::numeric)) AS invoice_line_total,
    sn.journal_entry_id
   FROM ((public.ins_policy_charges c
     JOIN public.ins_policies p ON (((p.id = c.policy_id) AND (p.tenant_id = c.tenant_id))))
     JOIN public.ins_policy_financial_snapshots sn ON (((sn.policy_id = p.id) AND sn.extended)))
  WHERE (c.kind = 'broker_fee'::text)
UNION ALL
 SELECT ch.id AS charge_id,
    c.tenant_id,
    c.policy_id,
    p.policy_no,
    p.currency,
    c.posting_date AS invoice_date,
    ((('Cancellation credit '::text || c.cancellation_no) || ': '::text) || ch.description) AS description,
    ((- ((x.value ->> 'refund_base'::text))::numeric))::numeric(18,2) AS fee_amount,
    ch.vat_mode,
    ch.vat_rate_pct,
    (- ((x.value ->> 'refund_vat'::text))::numeric) AS vat_amount,
    (- (((x.value ->> 'refund_base'::text))::numeric + ((x.value ->> 'refund_vat'::text))::numeric)) AS invoice_line_total,
    c.journal_entry_id
   FROM (((public.ins_policy_cancellations c
     JOIN public.ins_policies p ON (((p.id = c.policy_id) AND (p.tenant_id = c.tenant_id))))
     CROSS JOIN LATERAL jsonb_array_elements((c.calculation -> 'charges'::text)) x(value))
     JOIN public.ins_policy_charges ch ON (((ch.id = ((x.value ->> 'charge_id'::text))::uuid) AND (ch.tenant_id = c.tenant_id))))
  WHERE ((c.status = 'posted'::text) AND ((x.value ->> 'kind'::text) = 'broker_fee'::text) AND ((((x.value ->> 'refund_base'::text))::numeric > (0)::numeric) OR (((x.value ->> 'refund_vat'::text))::numeric > (0)::numeric)));


--
-- Name: ins_broker_fee_tax_rows(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_broker_fee_tax_rows(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS SETOF public.ins_broker_fee_tax_report
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 perform ins_policy_cash_require_finance();
 if p_date_from is not null and p_date_to is not null and p_date_from>p_date_to then raise exception 'INS_REPORT_PERIOD: invalid period'; end if;
 return query select r.* from ins_broker_fee_tax_report r where r.tenant_id=get_my_tenant_id()
  and(p_date_from is null or r.invoice_date>=p_date_from) and(p_date_to is null or r.invoice_date<=p_date_to) order by r.invoice_date,r.policy_no,r.charge_id;
end $$;


--
-- Name: ins_cancellation_cash_bank_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_bank_history_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if(new.name,new.kind,new.currency,new.gl_account_id) is distinct from(old.name,old.kind,old.currency,old.gl_account_id) and
 (exists(select 1 from ins_cancellation_cash_requests where old.id in(bank_account_id,to_bank_account_id)) or
 exists(select 1 from ins_policy_cancellations c join ins_policy_cash_items k on k.source_id=c.policy_id join fin_allocations a on a.open_item_id=k.id join fin_settlements s on s.id=a.settlement_id where c.status='posted' and s.bank_account_id=old.id) or
 exists(select 1 from ins_cancellation_insurer_adjustments a join ins_commission_transfers t on t.id=(a.original_commission_state->>'transfer_id')::uuid where old.id in(t.from_bank_account_id,t.to_bank_account_id))) then
 raise exception 'INS_CXL_CASH_BANK_HISTORY: cancellation bank identity, currency, kind and GL are immutable; use a separately reviewed bank migration'; end if;
 return new;
end $$;


--
-- Name: ins_cancellation_cash_book_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_book_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare tid uuid;
begin
 tid:=case when tg_op='DELETE' then old.tenant_id else new.tenant_id end;
 if exists(select 1 from ins_policy_cancellations where tenant_id=tid and status='posted') then perform pg_advisory_xact_lock(hashtextextended('ins-cxl-cash-book:'||tid::text,0)); end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: ins_cancellation_cash_complete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_complete_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_cancellation_cash_requests%rowtype; c ins_policy_cancellations%rowtype; s fin_settlements%rowtype;
begin
 select * into q from ins_cancellation_cash_requests where id=new.id; select * into c from ins_policy_cancellations where id=q.cancellation_id;
 if q.status='posting' then raise exception 'INS_CXL_CASH_INCOMPLETE: transaction cannot commit while posting'; end if;
 if q.status in('posted','voided') and q.kind<>'void' then
 if(q.kind in('commission_return','commission_withdrawal'))<>(q.to_settlement_id is not null) then raise exception 'INS_CXL_CASH_INCOMPLETE: internal transfers need both legs'; end if;
 for s in select * from fin_settlements where id in(q.settlement_id,q.to_settlement_id) loop
 if s.amount<>q.amount or s.created_by<>q.checker_id or s.journal_entry_id is null or s.status<>(case q.status when 'voided' then 'void' else 'posted' end) then raise exception 'INS_CXL_CASH_INCOMPLETE: settlement differs from approval'; end if;
 if q.kind in('commission_return','commission_withdrawal') then
 if exists(select 1 from fin_allocations where settlement_id=s.id) then raise exception 'INS_CXL_CASH_INCOMPLETE: internal transfers cannot settle third-party balances'; end if;
 elsif(select coalesce(sum(amount),0) from fin_allocations where settlement_id=s.id)<>q.amount then raise exception 'INS_CXL_CASH_INCOMPLETE: exact allocation required'; end if;
 end loop;
 if(select coalesce(sum(l.debit-l.credit),0) from ins_cancellation_cash_journals j join journal_entry_lines l on l.journal_entry_id=j.journal_entry_id where j.request_id=q.id and l.gl_account_id=c.clearing_gl_account_id)<>0 then raise exception 'INS_CXL_CASH_INCOMPLETE: transfer clearing must net to zero'; end if;
 end if; return null;
end $$;


--
-- Name: ins_cancellation_cash_context(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_context(p_policy_id uuid, p_bank_account_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c ins_policy_cancellations%rowtype; v jsonb; rows jsonb; banks jsonb:='[]';
begin
 if auth.uid() is null or not(can_access_insurance() or is_finance_team_member('finance')) then raise exception 'INS_FORBIDDEN: Insurance or Finance required' using errcode='42501'; end if;
 if p_bank_account_id is not null and(not is_finance_team_member('finance') or effective_user_id() is distinct from auth.uid()) then raise exception 'INS_CXL_CASH_BANK: bank-book views require acting Finance membership' using errcode='42501'; end if;
 if p_offset is null or p_offset<0 then raise exception 'INS_CXL_CASH_INPUT: invalid page'; end if;
 select * into c from ins_policy_cancellations where policy_id=p_policy_id and tenant_id=get_my_tenant_id() and status='posted';
 if not found then return jsonb_build_object('policy_id',p_policy_id,'available',false); end if;
 if p_bank_account_id is not null and not exists(select 1 from fin_bank_accounts where id=p_bank_account_id and tenant_id=c.tenant_id) then raise exception 'INS_CXL_CASH_BANK: bank outside this company'; end if;
 v:=platform_ins_cancellation_cash_position(c.id,p_bank_account_id);
 select coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object('amount',q.amount::text,
 'matched',platform_ins_cancellation_cash_proven(q.settlement_id),'destination_matched',platform_ins_cancellation_cash_proven(q.to_settlement_id),
 'void_requested',exists(select 1 from ins_cancellation_cash_requests vr where vr.voids_request_id=q.id and vr.status in('pending','posting','posted')),'settlement_no',(select settlement_no from fin_settlements where id=q.settlement_id),'destination_settlement_no',(select settlement_no from fin_settlements where id=q.to_settlement_id),
 'journals',coalesce((select jsonb_agg(to_jsonb(j)) from ins_cancellation_cash_journals j where j.request_id=q.id),'[]'::jsonb)) order by q.created_at desc,q.id),'[]'::jsonb) into rows
 from(select * from ins_cancellation_cash_requests where cancellation_id=c.id order by created_at desc,id limit 25 offset p_offset) q;
 if is_finance_team_member('finance') and effective_user_id()=auth.uid() then select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind,'currency',currency) order by name),'[]'::jsonb) into banks from fin_bank_accounts where tenant_id=c.tenant_id and is_active and currency=fin_ledger_currency(c.tenant_id); end if;
 return v||jsonb_build_object('available',true,'selected_bank_id',p_bank_account_id,'actor_id',auth.uid(),'can_finance',is_finance_team_member('finance') and effective_user_id()=auth.uid(),'cancellation_no',c.cancellation_no,'banks',banks,'requests',rows,'offset',p_offset,'has_more',(select count(*)>p_offset+25 from ins_cancellation_cash_requests where cancellation_id=c.id));
end $$;


--
-- Name: ins_cancellation_cash_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare keys text[]:=array['status','checker_id','checked_at','decision_reason','settlement_id','to_settlement_id','operation_txid','voided_by_request_id'];
begin
 if tg_op='DELETE' or tg_table_name<>'ins_cancellation_cash_requests' then raise exception 'INS_CXL_CASH_IMMUTABLE: evidence cannot be rewritten'; end if;
 if(to_jsonb(old)-keys) is distinct from(to_jsonb(new)-keys) then raise exception 'INS_CXL_CASH_IMMUTABLE: request instructions cannot change'; end if;
 perform ins_policy_cash_require_finance();
 if old.status='posted' and new.status='voided' and exists(select 1 from ins_cancellation_cash_requests v where v.id=new.voided_by_request_id and v.voids_request_id=old.id and v.status='posting' and v.operation_txid=txid_current() and v.checker_id=auth.uid()) then return new; end if;
 if old.status='pending' and new.status in('posting','rejected','cancelled') then
 if(new.status='cancelled' and old.maker_id=auth.uid()) or(new.status<>'cancelled' and new.checker_id=auth.uid() and old.maker_id<>auth.uid()) then return new; end if;
 elsif old.status='posting' and new.status in('posting','posted') and old.operation_txid=txid_current() and old.checker_id=auth.uid() then return new;
 end if;
 raise exception 'INS_CXL_CASH_IMMUTABLE: invalid evidence transition';
end $$;


--
-- Name: ins_cancellation_cash_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_history_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if tg_table_name='fin_settlements' then
 if new.status is distinct from old.status and exists(select 1 from ins_cancellation_cash_requests where old.id in(settlement_id,to_settlement_id)) and not platform_ins_cancellation_cash_void_authorized(old.id) then raise exception 'INS_CXL_CASH_VOID_REQUIRED: independent cancellation cash void approval required'; end if;
 elsif new.status is distinct from old.status and exists(select 1 from ins_cancellation_cash_journals where journal_entry_id=old.id) then raise exception 'INS_CXL_CASH_IMMUTABLE: cash journals cannot be independently voided'; end if;
 return new;
end $$;


--
-- Name: ins_cancellation_cash_reconciliation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_cash_reconciliation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sid uuid; q ins_cancellation_cash_requests%rowtype; c ins_policy_cancellations%rowtype; s fin_settlements%rowtype; row_json jsonb; b fin_bank_accounts%rowtype; l bank_statement_lines%rowtype;
begin
 sid:=case when tg_op='DELETE' then old.settlement_id else new.settlement_id end;
 if tg_op='UPDATE' and exists(select 1 from ins_cancellation_cash_requests where old.settlement_id in(settlement_id,to_settlement_id) or new.settlement_id in(settlement_id,to_settlement_id)) then raise exception 'INS_CXL_CASH_MATCH: matches are immutable; unmatch/rematch'; end if;
 select * into q from ins_cancellation_cash_requests where sid in(settlement_id,to_settlement_id) and kind<>'void';
 if found then select * into c from ins_policy_cancellations where id=q.cancellation_id;
 else select cx.* into c from ins_policy_cancellations cx join ins_policy_cash_items k on k.source_id=cx.policy_id join fin_allocations a on a.open_item_id=k.id where a.settlement_id=sid and cx.status='posted' limit 1; end if;
 if c.id is null then if tg_op='DELETE' then return old; else return new; end if; end if;
 perform ins_policy_cash_require_finance(); perform id from ins_policies where id=c.policy_id for update;
 select * into s from fin_settlements where id=sid for update;
 if q.id is not null then
 if auth.uid() in(q.maker_id,q.checker_id,s.created_by) then raise exception 'INS_CXL_CASH_THIRD_PERSON: a third distinct Finance reconciler is required' using errcode='42501'; end if;
 if tg_op<>'DELETE' then
 select * into b from fin_bank_accounts where id=s.bank_account_id; select * into l from bank_statement_lines where id=new.bank_statement_line_id;
 if s.status<>'posted' or q.status<>'posted' or new.matched_by is distinct from auth.uid() or new.tenant_id<>s.tenant_id or new.variance is distinct from 0 or l.tenant_id<>s.tenant_id or l.bank_account<>b.name or l.currency<>s.currency or l.amount<>(case s.direction when 'in' then s.amount else -s.amount end) then raise exception 'INS_CXL_CASH_MATCH: exact bank, currency, amount and acting reconciler required'; end if;
 end if;
 end if;
 if tg_op='DELETE' and(s.direction='in' or q.kind='commission_return') and exists(select 1 from ins_cancellation_cash_requests where cancellation_id=c.id and status='posted' and kind in('refund','remittance','commission_withdrawal')) then raise exception 'INS_CXL_CASH_FUNDS_IN_USE: reverse downstream cancellation payments before removing funding evidence'; end if;
 if q.id is not null then insert into ins_cancellation_cash_events(tenant_id,request_id,event,actor_id,detail) values(c.tenant_id,q.id,case tg_op when 'DELETE' then 'unmatched' else 'matched' end,auth.uid(),case tg_op when 'DELETE' then to_jsonb(old) else to_jsonb(new) end); end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: ins_cancellation_complete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_complete_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c ins_policy_cancellations%rowtype; difference numeric;
begin
 select * into c from ins_policy_cancellations where id=new.id;
 if c.status='posting' then raise exception 'INS_CANCELLATION_INCOMPLETE: interrupted transaction'; end if;
 if c.status='posted' then
  if not exists(select 1 from ins_policies where id=c.policy_id and status='cancelled') or exists(select 1 from ins_cancellation_credit_links l left join fin_credit_notes n on n.id=l.credit_note_id where l.cancellation_id=c.id and (n.id is null or n.journal_entry_id is null or n.status<>'posted' or n.amount<>l.amount)) then
   raise exception 'INS_CANCELLATION_INCOMPLETE: missing policy state or credit document'; end if;
  select coalesce(sum(l.debit-l.credit),0) into difference from ins_cancellation_journals j join journal_entry_lines l on l.journal_entry_id=j.journal_entry_id where j.cancellation_id=c.id and l.gl_account_id=c.clearing_gl_account_id;
  if difference<>0 then raise exception 'INS_CANCELLATION_INCOMPLETE: clearing account does not reconcile'; end if;
  if (select count(*) from ins_cancellation_insurer_adjustments where cancellation_id=c.id)<>jsonb_array_length(c.calculation->'insurers')
   or coalesce((select sum(l.amount) from ins_cancellation_credit_links l join fin_open_items i on i.id=l.open_item_id where l.cancellation_id=c.id and i.source_type='ins_policy_premium'),0)<>(c.calculation->>'receivable_credit')::numeric then
   raise exception 'INS_CANCELLATION_INCOMPLETE: insurer rows or receivable credits missing'; end if;
  if ((c.calculation->>'client_refund_due')::numeric>0 and not exists(select 1 from fin_open_items i where i.id=c.refund_item_id and i.tenant_id=c.tenant_id and i.source_type='ins_cancellation_client_refund' and i.source_id=c.id and i.control_role='ap_control' and i.amount=(c.calculation->>'client_refund_due')::numeric))
    or ((c.calculation->>'client_refund_due')::numeric=0 and c.refund_item_id is not null) then raise exception 'INS_CANCELLATION_INCOMPLETE: refund liability mismatch'; end if;
  if exists(select 1 from ins_cancellation_insurer_adjustments a where a.cancellation_id=c.id and
   (a.payable_credit<>coalesce((select sum(l.amount) from ins_cancellation_credit_links l where l.cancellation_id=c.id and l.open_item_id=a.original_item_id),0)
    or (a.recovery_due>0 and not exists(select 1 from fin_open_items i where i.id=a.recovery_item_id and i.tenant_id=c.tenant_id and i.source_type='ins_cancellation_insurer_recovery' and i.source_id=a.id and i.amount=a.recovery_due)))) then
   raise exception 'INS_CANCELLATION_INCOMPLETE: insurer credits/recovery items missing'; end if;
  if exists(select 1 from ins_cancellation_journals j join journal_entries e on e.id=j.journal_entry_id where j.cancellation_id=c.id and (e.tenant_id<>c.tenant_id or e.status<>'posted' or e.entry_date<>c.posting_date)) then raise exception 'INS_CANCELLATION_INCOMPLETE: journal state/date mismatch'; end if;
 end if;
 return new;
end $$;


--
-- Name: ins_cancellation_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare cid uuid; c ins_policy_cancellations%rowtype;
begin
 if tg_table_name='ins_policy_cancellations' then
  if tg_op='DELETE' then raise exception 'INS_CANCELLATION_IMMUTABLE: retain cancellation audit'; end if;
  if tg_op='INSERT' then return new; end if;
  if old.status in('posted','rejected','withdrawn') then raise exception 'INS_CANCELLATION_IMMUTABLE: terminal cases cannot change'; end if;
  if (to_jsonb(new)-array['status','prepared_by','prepared_at','clearing_gl_account_id','calculation','checked_by','checked_at','review_note','manual_exception_accepted','cancellation_no','posting_date','journal_entry_id','refund_item_id','cash_at_posting','accounting_mappings','operation_txid'])
    is distinct from (to_jsonb(old)-array['status','prepared_by','prepared_at','clearing_gl_account_id','calculation','checked_by','checked_at','review_note','manual_exception_accepted','cancellation_no','posting_date','journal_entry_id','refund_item_id','cash_at_posting','accounting_mappings','operation_txid']) then
   raise exception 'INS_CANCELLATION_IMMUTABLE: proposal inputs cannot be rewritten; withdraw and resubmit'; end if;
  return new;
 end if;
 if tg_table_name='ins_cancellation_events' then
  if tg_op<>'INSERT' then raise exception 'INS_CANCELLATION_IMMUTABLE: append-only audit'; end if;
  return new;
 end if;
 cid:=case when tg_op='DELETE' then old.cancellation_id else new.cancellation_id end;
 select * into c from ins_policy_cancellations where id=cid;
 if tg_op='DELETE' or c.status<>'posting' or c.operation_txid<>txid_current() then raise exception 'INS_CANCELLATION_IMMUTABLE: financial evidence is transaction-bound and immutable'; end if;
 if tg_op='UPDATE' and (tg_table_name<>'ins_cancellation_insurer_adjustments' or (to_jsonb(new)-'recovery_item_id') is distinct from (to_jsonb(old)-'recovery_item_id')) then
  raise exception 'INS_CANCELLATION_IMMUTABLE: adjustment history cannot change'; end if;
 return new;
end $$;


--
-- Name: ins_cancellation_finance_lock_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancellation_finance_lock_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if tg_table_name='fin_allocations' then if platform_ins_cancellation_cash_authorized(new.open_item_id,new.settlement_id,new.amount) then return new; end if;
 elsif tg_table_name='fin_settlements' then if platform_ins_cancellation_cash_void_authorized(old.id) then return new; end if; end if;
 if tg_table_name='fin_credit_notes' then
  if new.status is distinct from old.status and exists(select 1 from ins_cancellation_credit_links where credit_note_id=old.id) then raise exception 'INS_CANCELLATION_LOCKED: linked credit cannot be voided independently'; end if;
 elsif tg_table_name='journal_entries' then
  if new.status is distinct from old.status then
   perform p.id from ins_policies p where exists(select 1 from fin_settlements s join fin_allocations a on a.settlement_id=s.id join ins_policy_cash_items k on k.id=a.open_item_id
    where k.source_id=p.id and old.id in(s.journal_entry_id,s.void_journal_entry_id)) or exists(select 1 from ins_commission_events e join ins_commission_entries ce on ce.id=e.entry_id where ce.policy_id=p.id and e.journal_entry_id=old.id) order by p.id for update;
   if exists(select 1 from ins_cancellation_journals where journal_entry_id=old.id)
    or exists(select 1 from fin_settlements s join fin_allocations a on a.settlement_id=s.id join ins_policy_cash_items k on k.id=a.open_item_id
      join ins_policy_cancellations c on c.policy_id=k.source_id and c.status='posted' where old.id in(s.journal_entry_id,s.void_journal_entry_id))
    or exists(select 1 from ins_cancellation_insurer_adjustments a join ins_commission_events e on e.entry_id=a.original_commission_entry_id where e.journal_entry_id=old.id)
    or exists(select 1 from ins_cancellation_insurer_adjustments a join ins_commission_transfers t on t.id=(a.original_commission_state->>'transfer_id')::uuid where old.id in(t.journal_entry_id,t.void_journal_entry_id)) then
    raise exception 'INS_CANCELLATION_LOCKED: linked or original cash/commission journal cannot be voided independently'; end if;
  end if;
 elsif tg_table_name='fin_settlements' then
  if new.status is distinct from old.status then
   perform p.id from ins_policies p join ins_policy_cash_items k on k.source_id=p.id join fin_allocations a on a.open_item_id=k.id where a.settlement_id=old.id order by p.id for update of p;
   if exists(select 1 from fin_allocations a join ins_policy_cash_items k on k.id=a.open_item_id join ins_policy_cancellations c on c.policy_id=k.source_id and c.status='posted' where a.settlement_id=old.id) then raise exception 'INS_CANCELLATION_LOCKED: historical cash is preserved after cancellation'; end if;
  end if;
 elsif tg_table_name='ins_commission_transfers' then
  if new.status is distinct from old.status and exists(select 1 from ins_cancellation_insurer_adjustments a join ins_policy_cancellations c on c.id=a.cancellation_id and c.status='posted' where (a.original_commission_state->>'transfer_id')::uuid=old.id) then raise exception 'INS_CANCELLATION_LOCKED: historical commission transfer is preserved; recover the clawback separately'; end if;
 elsif tg_table_name='fin_allocations' then
  if exists(select 1 from fin_open_items where id=new.open_item_id and source_type in('ins_cancellation_client_refund','ins_cancellation_insurer_recovery')) then raise exception 'INS_CANCELLATION_CASH_REQUIRED: separately approved, funded cash workflow required'; end if;
 elsif tg_table_name='fin_credit_applications' then
  if exists(select 1 from fin_open_items where id=new.open_item_id and source_type in('ins_cancellation_client_refund','ins_cancellation_insurer_recovery')) then raise exception 'INS_CANCELLATION_LOCKED: cancellation balances cannot be generically credited'; end if;
 end if;
 return new;
end $$;


--
-- Name: ins_cancelled_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_cancelled_policy_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if old.status='cancelled' and new.status is distinct from old.status then raise exception 'INS_CANCELLATION_LOCKED: cancelled policies cannot reactivate'; end if;
 if new.status='cancelled' and old.status<>'cancelled' and not exists(select 1 from ins_policy_cancellations c where c.policy_id=new.id and c.tenant_id=new.tenant_id and c.status='posted' and c.checked_by=auth.uid() and c.posting_date=current_date) then
  raise exception 'INS_CANCELLATION_CONTEXT: use the independently approved cancellation workflow'; end if;
 return new;
end $$;


--
-- Name: ins_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    claim_no text NOT NULL,
    policy_id uuid NOT NULL,
    status text DEFAULT 'notified'::text NOT NULL,
    loss_date date NOT NULL,
    notified_date date DEFAULT CURRENT_DATE NOT NULL,
    loss_description text NOT NULL,
    insurer_claim_ref text,
    reserve_amount numeric(18,2) DEFAULT 0 NOT NULL,
    approved_amount numeric(18,2),
    paid_amount numeric(18,2) DEFAULT 0 NOT NULL,
    settled_at timestamp with time zone,
    assigned_to uuid,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_mode text,
    recognised_at timestamp with time zone,
    recognised_by uuid,
    CONSTRAINT ins_claims_approved_check CHECK (((approved_amount IS NULL) OR (approved_amount >= (0)::numeric))),
    CONSTRAINT ins_claims_notified_check CHECK ((notified_date >= loss_date)),
    CONSTRAINT ins_claims_paid_check CHECK (((paid_amount >= (0)::numeric) AND ((approved_amount IS NULL) OR (paid_amount <= approved_amount)))),
    CONSTRAINT ins_claims_payment_mode_check CHECK (((payment_mode IS NULL) OR (payment_mode = ANY (ARRAY['insurer_direct'::text, 'via_broker'::text])))),
    CONSTRAINT ins_claims_reserve_check CHECK ((reserve_amount >= (0)::numeric)),
    CONSTRAINT ins_claims_status_check CHECK ((status = ANY (ARRAY['notified'::text, 'assessing'::text, 'approved'::text, 'settled'::text, 'repudiated'::text, 'closed'::text])))
);


--
-- Name: ins_claim_apply_payment_totals(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_claim_apply_payment_totals(p_claim_id uuid, p_note text) RETURNS public.ins_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_claim ins_claims%rowtype;
  v_paid  numeric;
  v_from  text;
begin
  select * into v_claim from ins_claims where id = p_claim_id for update;
  if not found then
    raise exception 'INS_NOT_FOUND: claim';
  end if;
  select coalesce(sum(amount), 0) into v_paid
    from ins_claim_payments
   where claim_id = p_claim_id and status = 'posted' and kind in ('insurer_direct', 'client_payout');

  perform set_config('ins.via_rpc', 'on', true);
  v_from := v_claim.status;

  if v_claim.status = 'approved' and v_paid >= coalesce(v_claim.approved_amount, 0) then
    update ins_claims set paid_amount = v_paid, status = 'settled', settled_at = now()
     where id = v_claim.id returning * into v_claim;
    insert into ins_claim_events (tenant_id, claim_id, from_status, to_status, note)
    values (v_claim.tenant_id, v_claim.id, v_from, 'settled', p_note);
  elsif v_claim.status = 'settled' and v_paid < coalesce(v_claim.approved_amount, 0) then
    update ins_claims set paid_amount = v_paid, status = 'approved', settled_at = null
     where id = v_claim.id returning * into v_claim;
    insert into ins_claim_events (tenant_id, claim_id, from_status, to_status, note)
    values (v_claim.tenant_id, v_claim.id, v_from, 'approved', p_note);
  else
    update ins_claims set paid_amount = v_paid
     where id = v_claim.id returning * into v_claim;
  end if;
  return v_claim;
end;
$$;


--
-- Name: ins_claim_reserve_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_claim_reserve_history_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.ins_via_rpc() then
    raise exception 'INS_RPC_ONLY: revise a claim reserve with ins_revise_claim_reserve()' using errcode = '42501';
  end if;
  if tg_op in ('UPDATE', 'DELETE') then
    raise exception 'INS_RESERVE_HISTORY_IMMUTABLE: reserve history is never edited or deleted';
  end if;
  return new;
end $$;


--
-- Name: ins_claim_settlement_void_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_claim_settlement_void_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_pay        ins_claim_payments%rowtype;
  v_held_after numeric;
  v_status     text;
begin
  select * into v_pay from ins_claim_payments where settlement_id = new.id and status = 'posted' for update;
  if not found then
    return new;
  end if;
  select status into v_status from ins_claims where id = v_pay.claim_id;
  if v_status = 'closed' then
    raise exception 'INS_CLAIM_CLOSED: payments on a closed claim cannot be voided';
  end if;
  if v_pay.kind = 'insurer_receipt' then
    select coalesce(sum(amount) filter (where kind = 'insurer_receipt'), 0)
           - coalesce(sum(amount) filter (where kind = 'client_payout'), 0)
      into v_held_after
      from ins_claim_payments
     where claim_id = v_pay.claim_id and status = 'posted' and id <> v_pay.id;
    if v_held_after < 0 then
      raise exception 'INS_CLAIM_FUNDS_PAID_OUT: this receipt has already been paid out to the client; void the payout first';
    end if;
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  update ins_claim_payments
     set status = 'void', voided_at = now(), voided_by = auth.uid(),
         void_reason = coalesce(new.void_reason, 'Settlement voided')
   where id = v_pay.id;
  perform ins_claim_apply_payment_totals(v_pay.claim_id, 'Payment voided: ' || coalesce(new.void_reason, 'settlement voided'));
  return new;
end;
$$;


--
-- Name: ins_claims_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_claims_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    if not public.ins_via_rpc() then
      raise exception 'INS_RPC_ONLY: create claims with ins_create_claim()' using errcode = '42501';
    end if;
    return new;
  end if;

  if new.claim_no is distinct from old.claim_no or new.policy_id is distinct from old.policy_id then
    raise exception 'INS_IMMUTABLE: a claim number and its policy cannot be changed';
  end if;
  if not public.ins_via_rpc() and (
    new.status is distinct from old.status
    or new.approved_amount is distinct from old.approved_amount
    or new.paid_amount is distinct from old.paid_amount
    or new.settled_at is distinct from old.settled_at
    or new.payment_mode is distinct from old.payment_mode
    or new.reserve_amount is distinct from old.reserve_amount
  ) then
    raise exception 'INS_CLAIM_RPC_ONLY: status, amounts, reserve and payment mode change through the claim functions' using errcode = '42501';
  end if;

  if new.loss_date is distinct from old.loss_date and not exists (
    select 1 from ins_policies p
     where p.id = new.policy_id and p.tenant_id = new.tenant_id
       and new.loss_date between p.inception_date and p.expiry_date
  ) then
    raise exception 'INS_LOSS_OUTSIDE_POLICY: loss date % is outside the policy period', new.loss_date;
  end if;
  return new;
end;
$$;


--
-- Name: ins_claims_initial_reserve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_claims_initial_reserve() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_claim_reserve_history (tenant_id, claim_id, kind, previous_amount, new_amount, reason, revised_by)
  values (new.tenant_id, new.id, 'initial', null, new.reserve_amount, 'Initial reserve when the claim was registered', new.created_by);
  return new;
end $$;


--
-- Name: ins_clear_renewal_outcome(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_clear_renewal_outcome(p_policy_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers can clear a renewal outcome' using errcode = '42501';
  end if;
  perform set_config('ins.via_rpc', 'on', true);
  delete from ins_renewal_outcomes where tenant_id = v_tenant and policy_id = p_policy_id;
  if not found then
    raise exception 'INS_NOT_FOUND: no renewal outcome is recorded for this policy';
  end if;
end $$;


--
-- Name: ins_clients_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_clients_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.client_id is distinct from old.client_id then
    raise exception 'INS_IMMUTABLE: the BD client link cannot be changed';
  end if;
  if tg_op = 'UPDATE' and new.party_account_id is distinct from old.party_account_id and not public.ins_via_rpc() then
    raise exception 'INS_PARTY_ACCOUNT_RPC_ONLY: the party account is managed by binding a policy' using errcode = '42501';
  end if;
  if not public.ins_via_rpc() and not public.can_manage_insurance() then
    if tg_op = 'INSERT' and new.kyc_status is distinct from 'pending' then
      raise exception 'INS_KYC_MANAGER_ONLY: new clients start as pending; a manager verifies KYC' using errcode = '42501';
    end if;
    if tg_op = 'UPDATE' and new.kyc_status is distinct from old.kyc_status then
      raise exception 'INS_KYC_MANAGER_ONLY: only insurance admins and managers can change KYC status' using errcode = '42501';
    end if;
  end if;
  if not exists (select 1 from bd_clients c where c.id = new.client_id and c.tenant_id = new.tenant_id) then
    raise exception 'INS_CROSS_TENANT: the BD client belongs to another tenant';
  end if;
  if new.party_account_id is not null and not exists (
    select 1 from accounts a where a.id = new.party_account_id and a.tenant_id = new.tenant_id
  ) then
    raise exception 'INS_CROSS_TENANT: party account belongs to another tenant';
  end if;
  return new;
end;
$$;


--
-- Name: ins_commission_bank_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_commission_bank_accounts() RETURNS TABLE(id uuid, name text, kind text, currency text, bank_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers can list transfer bank accounts' using errcode = '42501';
  end if;
  return query
    select b.id, b.name, b.kind, b.currency, b.bank_name
      from fin_bank_accounts b
     where b.tenant_id = get_my_tenant_id()
       and b.is_active
       and b.gl_account_id is not null
       and b.currency = fin_ledger_currency(b.tenant_id)
     order by b.kind, b.name;
end;
$$;


--
-- Name: ins_commission_on_settlement_posted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_commission_on_settlement_posted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r          record;
  v_unearned uuid;
  v_income   uuid;
  v_ev       uuid;
  v_je       journal_entries;
  v_line     jsonb;
  v_line2    jsonb;
begin
 if exists(select 1 from ins_cancellation_cash_requests where new.id in(settlement_id,to_settlement_id)) then return new; end if;
  if new.direction <> 'out' or new.status <> 'posted' or new.journal_entry_id is null then
    return new;
  end if;

  for r in
    select e.id as entry_id, e.amount, p.policy_no, i.currency as item_currency,
           i.fx_rate as item_rate, i.journal_entry_id as booking_entry
    from fin_allocations al
    join fin_open_items i  on i.id = al.open_item_id and i.source_type in ('ins_policy_insurer','ins_policy_share_insurer','ins_policy_endorsement_insurer')
    join fin_open_item_balances ob on ob.id = i.id
    join ins_commission_entries e on (
          -- An endorsement entry is earned only by its own insurer item.
          (e.source_open_item_id = i.id)
          -- The policy's bind entries earn off the original items, as before;
          -- provenance-tagged entries are excluded so a later endorsement item
          -- cannot earn them early.
       or (e.insurer_share_id = i.source_id and i.source_type = 'ins_policy_share_insurer'
           and e.source_open_item_id is null)
       or (e.policy_id = i.source_id and e.insurer_share_id is null
           and i.source_type = 'ins_policy_insurer' and e.source_open_item_id is null)
        ) and e.tenant_id = i.tenant_id
    join ins_policies p on p.id = e.policy_id
    where al.settlement_id = new.id
      and e.status = 'deferred'
      -- An item is done when its settlements plus its credit notes cover it:
      -- endorsement returns credit the original items, and a returned premium
      -- must not leave its commission deferred forever.
      and ins_item_paid_amount(i.id) + ob.credited_amount >= i.amount
    order by p.policy_no
    for update of e
  loop
    v_unearned := get_posting_account(new.tenant_id, 'unearned_commission');
    v_income   := get_posting_account(new.tenant_id, 'commission_income');
    if v_unearned is null or v_income is null then
      raise exception 'INS_POSTING_RULE_MISSING: paying the insurer for % earns commission, which needs the unearned_commission and commission_income posting rules', r.policy_no;
    end if;

    v_line  := jsonb_build_object('gl_account_id', v_unearned, 'debit',  r.amount, 'description', 'Commission earned on ' || r.policy_no);
    v_line2 := jsonb_build_object('gl_account_id', v_income,   'credit', r.amount, 'description', 'Commission earned on ' || r.policy_no);
    if r.item_currency is distinct from fin_ledger_currency(new.tenant_id) then
      -- The commission was deferred at the rate the policy was bound at; recognising it
      -- at the same rate keeps the unearned account at zero in base when it empties.
      if r.booking_entry is null or r.item_rate is null or r.item_rate <= 0 then
        raise exception 'INS_COMMISSION_RATE: commission on % has no booked rate; the insurer item must name its booking entry', r.policy_no;
      end if;
      v_line  := v_line  || jsonb_build_object('currency', r.item_currency, 'rate_from_entry', r.booking_entry, 'fx_rate', r.item_rate);
      v_line2 := v_line2 || jsonb_build_object('currency', r.item_currency, 'rate_from_entry', r.booking_entry, 'fx_rate', r.item_rate);
    end if;

    v_ev := gen_random_uuid();
    v_je := post_journal_entry(new.tenant_id, 'ins_commission_recognition', v_ev, new.settlement_date,
      'Commission earned on ' || r.policy_no, jsonb_build_array(v_line, v_line2));

    insert into ins_commission_events (id, tenant_id, entry_id, event, amount, journal_entry_id, settlement_id)
    values (v_ev, new.tenant_id, r.entry_id, 'recognised', r.amount, v_je.id, new.id);

    update ins_commission_entries
       set status = 'earned', earned_on = new.settlement_date, updated_at = now()
     where id = r.entry_id;
  end loop;

  return new;
end;
$$;


--
-- Name: ins_commission_on_settlement_voided(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_commission_on_settlement_voided() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r          record;
  v_unearned uuid;
  v_income   uuid;
  v_ev       uuid;
  v_je       journal_entries;
  v_date     date;
  v_rec_je   uuid;
  v_lines    jsonb;
begin
 if exists(select 1 from ins_cancellation_cash_requests where new.id in(settlement_id,to_settlement_id)) then return new; end if;
  if new.direction <> 'out' or old.status <> 'posted' or new.status <> 'void' then
    return new;
  end if;

  select entry_date into v_date from journal_entries where id = new.void_journal_entry_id;
  v_date := coalesce(v_date, current_date);

  for r in
    select e.id as entry_id, e.amount, e.status as entry_status, p.policy_no, i.currency as item_currency
    from fin_allocations al
    join fin_open_items i  on i.id = al.open_item_id and i.source_type in ('ins_policy_insurer','ins_policy_share_insurer')
    join ins_commission_entries e on ((e.insurer_share_id=i.source_id and i.source_type='ins_policy_share_insurer') or (e.policy_id=i.source_id and e.insurer_share_id is null and i.source_type='ins_policy_insurer')) and e.tenant_id=i.tenant_id
    join ins_policies p on p.id = e.policy_id
    where al.settlement_id = new.id
      and e.status in ('earned', 'transferred')
      and ins_item_paid_amount(i.id) < i.amount
    order by p.policy_no
    for update of e
  loop
    if r.entry_status = 'transferred' then
      raise exception 'INS_COMMISSION_TRANSFERRED: commission on % has already been transferred to the operating account; void that commission transfer first', r.policy_no;
    end if;

    v_unearned := get_posting_account(new.tenant_id, 'unearned_commission');
    v_income   := get_posting_account(new.tenant_id, 'commission_income');
    if v_unearned is null or v_income is null then
      raise exception 'INS_POSTING_RULE_MISSING: reversing commission on % needs the unearned_commission and commission_income posting rules', r.policy_no;
    end if;

    v_ev := gen_random_uuid();
    if r.item_currency is distinct from fin_ledger_currency(new.tenant_id) then
      -- Reverse the recognition journal exactly: its lines carry the currency and the
      -- booked rate, and reversal mode keeps them, so the recognition negates to zero.
      select journal_entry_id into v_rec_je
        from ins_commission_events
       where entry_id = r.entry_id and event = 'recognised' and journal_entry_id is not null
       order by created_at desc
       limit 1;
      if v_rec_je is null then
        raise exception 'INS_COMMISSION_RATE: reversing commission on % needs its recognition journal', r.policy_no;
      end if;
      select jsonb_agg(jsonb_build_object(
               'gl_account_id', l.gl_account_id, 'debit', l.credit, 'credit', l.debit,
               'currency', l.currency, 'fx_rate', l.fx_rate, 'is_rounding', l.is_rounding,
               'description', 'Reversal of commission earned on ' || r.policy_no))
        into v_lines
        from journal_entry_lines l
       where l.journal_entry_id = v_rec_je;
      perform set_config('fin.reversal_of', v_rec_je::text, true);
      v_je := post_journal_entry(new.tenant_id, 'ins_commission_recognition_reversal', v_ev, v_date,
        'Commission no longer earned on ' || r.policy_no || ' (settlement voided)', v_lines);
      perform set_config('fin.reversal_of', '', true);
    else
      v_je := post_journal_entry(new.tenant_id, 'ins_commission_recognition_reversal', v_ev, v_date,
        'Commission no longer earned on ' || r.policy_no || ' (settlement voided)',
        jsonb_build_array(
          jsonb_build_object('gl_account_id', v_income,   'debit',  r.amount, 'description', 'Reversal of commission earned on ' || r.policy_no),
          jsonb_build_object('gl_account_id', v_unearned, 'credit', r.amount, 'description', 'Reversal of commission earned on ' || r.policy_no)));
    end if;

    insert into ins_commission_events (id, tenant_id, entry_id, event, amount, journal_entry_id, settlement_id)
    values (v_ev, new.tenant_id, r.entry_id, 'recognition_reversed', r.amount, v_je.id, new.id);

    update ins_commission_entries
       set status = 'deferred', earned_on = null, updated_at = now()
     where id = r.entry_id;
  end loop;

  return new;
end;
$$;


--
-- Name: ins_complex_policy_credit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_complex_policy_credit_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare linked ins_cancellation_credit_links%rowtype; c ins_policy_cancellations%rowtype;
begin
 select * into linked from ins_cancellation_credit_links where credit_note_id=new.credit_note_id and tenant_id=new.tenant_id;
 if found then
  c:=platform_ins_cancellation_context(linked.cancellation_id);
  if linked.open_item_id<>new.open_item_id or linked.amount<>new.amount then raise exception 'INS_CANCELLATION_CONTEXT: credit outside exact authorization'; end if;
  return new;
 end if;
 if exists(select 1 from ins_policy_cash_items m join ins_policy_financial_snapshots sn on sn.policy_id=m.source_id and sn.tenant_id=m.tenant_id and sn.extended
   where m.id=new.open_item_id and m.tenant_id=new.tenant_id and m.source_type in('ins_policy_premium','ins_policy_insurer'))
  or exists(select 1 from ins_policy_cash_items m join ins_policy_cancellations c2 on c2.policy_id=m.source_id and c2.tenant_id=m.tenant_id and c2.status in('posting','posted') where m.id=new.open_item_id) then
  raise exception 'INS_CANCELLATION_REQUIRED: policy credits require the cancellation workflow'; end if;
 return new;
end $$;


--
-- Name: ins_create_claim(uuid, date, date, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_create_claim(p_policy_id uuid, p_loss_date date, p_notified_date date, p_loss_description text, p_insurer_claim_ref text DEFAULT NULL::text, p_reserve_amount numeric DEFAULT 0) RETURNS public.ins_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_pol    ins_policies%rowtype;
  v_row    ins_claims%rowtype;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  select * into v_pol from ins_policies where id = p_policy_id and tenant_id = v_tenant;
  if not found then
    raise exception 'INS_NOT_FOUND: policy';
  end if;
  if v_pol.status = 'draft' then
    raise exception 'INS_CLAIM_STATE: a claim needs a bound policy';
  end if;
  if p_loss_date < v_pol.inception_date or p_loss_date > v_pol.expiry_date then
    raise exception 'INS_LOSS_OUTSIDE_POLICY: loss date % is outside the policy period % to %',
      p_loss_date, v_pol.inception_date, v_pol.expiry_date;
  end if;
  if nullif(btrim(p_loss_description), '') is null then
    raise exception 'INS_REQUIRED: describe the loss';
  end if;
  if coalesce(p_reserve_amount, 0) < 0 then
    raise exception 'INS_AMOUNT: reserve cannot be negative';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_claims (
    tenant_id, claim_no, policy_id, status, loss_date, notified_date,
    loss_description, insurer_claim_ref, reserve_amount
  ) values (
    v_tenant, next_doc_number(v_tenant, 'INS_CLAIM', 'CLM', 5), v_pol.id, 'notified', p_loss_date,
    coalesce(p_notified_date, current_date), btrim(p_loss_description),
    nullif(btrim(p_insurer_claim_ref), ''), coalesce(p_reserve_amount, 0)
  )
  returning * into v_row;

  insert into ins_claim_events (tenant_id, claim_id, from_status, to_status, note)
  values (v_tenant, v_row.id, null, 'notified', 'Claim notified');
  return v_row;
end;
$$;


--
-- Name: ins_create_policy(uuid, uuid, uuid, date, date, numeric, text, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_create_policy(p_client_id uuid, p_insurer_id uuid, p_product_line_id uuid, p_inception_date date, p_expiry_date date, p_sum_insured numeric, p_currency text, p_gross_premium numeric, p_commission_rate_pct numeric, p_risk_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return public.ins_create_policy(
    p_client_id, p_insurer_id, p_product_line_id, p_inception_date, p_expiry_date,
    p_sum_insured, p_currency, p_gross_premium, p_commission_rate_pct,
    null::uuid, null::uuid, p_risk_description, p_notes);
end;
$$;


--
-- Name: ins_create_policy(uuid, uuid, uuid, date, date, numeric, text, numeric, numeric, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_create_policy(p_client_id uuid, p_insurer_id uuid, p_product_line_id uuid, p_inception_date date, p_expiry_date date, p_sum_insured numeric, p_currency text, p_gross_premium numeric, p_commission_rate_pct numeric, p_branch_id uuid, p_agent_id uuid, p_risk_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_row    ins_policies%rowtype;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  if p_expiry_date is null or p_inception_date is null or p_expiry_date <= p_inception_date then
    raise exception 'INS_DATES: expiry must be after inception';
  end if;
  if coalesce(p_sum_insured, -1) < 0 or coalesce(p_gross_premium, -1) < 0 then
    raise exception 'INS_AMOUNT: sum insured and premium cannot be negative';
  end if;
  if p_commission_rate_pct is null or p_commission_rate_pct < 0 or p_commission_rate_pct >= 100 then
    raise exception 'INS_COMMISSION: commission rate must be at least 0 and below 100';
  end if;
  if not exists (select 1 from ins_clients where id = p_client_id and tenant_id = v_tenant) then
    raise exception 'INS_NOT_FOUND: client';
  end if;
  if not exists (select 1 from ins_insurers where id = p_insurer_id and tenant_id = v_tenant and is_active) then
    raise exception 'INS_NOT_FOUND: active insurer';
  end if;
  if not exists (select 1 from ins_product_lines where id = p_product_line_id and tenant_id = v_tenant and is_active) then
    raise exception 'INS_NOT_FOUND: active product line';
  end if;
  -- A new policy is produced by an agent who is active today. A policy keeps an agent who is
  -- suspended later; the guard only requires activity when the reference changes.
  if p_agent_id is not null and not exists (
    select 1 from ins_intermediaries a
    where a.id = p_agent_id and a.tenant_id = v_tenant and a.status = 'active'
  ) then
    raise exception 'INS_NOT_FOUND: active intermediary (agent)';
  end if;
  if p_branch_id is not null and not exists (
    select 1 from organizations o
    where o.id = p_branch_id and o.tenant_id = v_tenant and o.is_active
  ) then
    raise exception 'INS_NOT_FOUND: active organisation (branch)';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_policies (
    tenant_id, policy_no, client_id, insurer_id, product_line_id, status,
    inception_date, expiry_date, sum_insured, currency, gross_premium,
    commission_rate_pct, risk_description, notes, branch_id, agent_id, transaction_type
  ) values (
    v_tenant, next_doc_number(v_tenant, 'INS_POLICY', 'POL', 5), p_client_id, p_insurer_id, p_product_line_id, 'draft',
    p_inception_date, p_expiry_date, coalesce(p_sum_insured, 0), coalesce(nullif(p_currency, ''), 'UGX'), coalesce(p_gross_premium, 0),
    p_commission_rate_pct, nullif(btrim(p_risk_description), ''), nullif(btrim(p_notes), ''),
    p_branch_id, p_agent_id, 'new_business'
  )
  returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: ins_create_renewal_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_create_renewal_draft(p_policy_id uuid) RETURNS public.ins_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  if exists (select 1 from ins_renewal_outcomes where tenant_id = get_my_tenant_id() and policy_id = p_policy_id) then
    raise exception 'INS_RENEWAL_CLOSED: a renewal outcome is recorded for this policy; clear it before starting a renewal';
  end if;
  return platform_ins_create_renewal_pre_outcome_impl(p_policy_id);
end $$;


--
-- Name: ins_create_renewal_drafts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_create_renewal_drafts(p_policy_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_ids    uuid[];
  v_id     uuid;
  v_no     text;
  v_draft  ins_policies%rowtype;
  v_out    jsonb := '[]'::jsonb;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  select coalesce(array_agg(distinct x), '{}'::uuid[]) into v_ids from unnest(p_policy_ids) as x where x is not null;
  if cardinality(v_ids) = 0 then
    raise exception 'INS_BULK_EMPTY: choose at least one policy';
  end if;
  if cardinality(v_ids) > 100 then
    raise exception 'INS_BULK_LIMIT: renew at most 100 policies at a time';
  end if;

  foreach v_id in array v_ids loop
    select policy_no into v_no from ins_policies where id = v_id and tenant_id = v_tenant;
    begin
      v_draft := public.ins_create_renewal_draft(v_id);
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'policy_id', v_id, 'policy_no', v_no, 'ok', true, 'draft_id', v_draft.id));
    exception when others then
      v_out := v_out || jsonb_build_array(jsonb_build_object(
        'policy_id', v_id, 'policy_no', v_no, 'ok', false, 'error', sqlerrm));
    end;
  end loop;
  return v_out;
end $$;


--
-- Name: ins_cancellation_cash_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_cancellation_cash_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    cancellation_id uuid NOT NULL,
    kind text NOT NULL,
    adjustment_id uuid,
    bank_account_id uuid NOT NULL,
    to_bank_account_id uuid,
    amount numeric(18,2) NOT NULL,
    cash_date date NOT NULL,
    reference text NOT NULL,
    notes text NOT NULL,
    request_key uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    maker_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    checker_id uuid,
    checked_at timestamp with time zone,
    decision_reason text,
    settlement_id uuid,
    to_settlement_id uuid,
    operation_txid bigint,
    voids_request_id uuid,
    voided_by_request_id uuid,
    CONSTRAINT ins_cancellation_cash_requests_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT ins_cancellation_cash_requests_check CHECK (((checker_id IS NULL) OR (checker_id <> maker_id))),
    CONSTRAINT ins_cancellation_cash_requests_check1 CHECK (((status = 'posting'::text) = (operation_txid IS NOT NULL))),
    CONSTRAINT ins_cancellation_cash_requests_check2 CHECK (((status <> ALL (ARRAY['posting'::text, 'posted'::text, 'voided'::text])) OR ((checker_id IS NOT NULL) AND (checked_at IS NOT NULL)))),
    CONSTRAINT ins_cancellation_cash_requests_check3 CHECK (((status <> ALL (ARRAY['posted'::text, 'voided'::text])) OR (kind = 'void'::text) OR (settlement_id IS NOT NULL))),
    CONSTRAINT ins_cancellation_cash_requests_check4 CHECK (((kind = 'void'::text) = (voids_request_id IS NOT NULL))),
    CONSTRAINT ins_cancellation_cash_requests_check5 CHECK (((status = 'voided'::text) = (voided_by_request_id IS NOT NULL))),
    CONSTRAINT ins_cancellation_cash_requests_check6 CHECK (((to_bank_account_id IS NULL) OR (to_bank_account_id <> bank_account_id))),
    CONSTRAINT ins_cancellation_cash_requests_kind_check CHECK ((kind = ANY (ARRAY['recovery'::text, 'premium_receipt'::text, 'refund'::text, 'remittance'::text, 'commission_return'::text, 'commission_withdrawal'::text, 'void'::text]))),
    CONSTRAINT ins_cancellation_cash_requests_notes_check CHECK (((length(btrim(notes)) >= 5) AND (length(btrim(notes)) <= 2000))),
    CONSTRAINT ins_cancellation_cash_requests_reference_check CHECK (((length(btrim(reference)) >= 3) AND (length(btrim(reference)) <= 200))),
    CONSTRAINT ins_cancellation_cash_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'posting'::text, 'posted'::text, 'rejected'::text, 'cancelled'::text, 'voided'::text])))
);


--
-- Name: ins_decide_cancellation_cash(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_decide_cancellation_cash(p_request_id uuid, p_decision text, p_reason text) RETURNS public.ins_cancellation_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_cancellation_cash_requests%rowtype; target ins_cancellation_cash_requests%rowtype; c ins_policy_cancellations%rowtype; s fin_settlements%rowtype; item uuid; v jsonb;
begin
 perform ins_policy_cash_require_finance();
 if p_decision is null or p_decision not in('approve','reject','cancel') or p_reason is null or length(btrim(p_reason)) not between 5 and 2000 then raise exception 'INS_CXL_CASH_INPUT: decision and detailed review note required'; end if;
 select cx.* into c from ins_policy_cancellations cx join ins_cancellation_cash_requests r on r.cancellation_id=cx.id where r.id=p_request_id and r.tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: cash request'; end if;
 -- All actors lock policy, banks in UUID order, request, then items/settlements.
 perform id from ins_policies where id=c.policy_id for update;
 perform id from fin_bank_accounts where tenant_id=c.tenant_id order by id for update;
 perform pg_advisory_xact_lock(hashtextextended('ins-cxl-cash-book:'||c.tenant_id::text,0));
 select * into q from ins_cancellation_cash_requests where id=p_request_id for update;
 if(p_decision='cancel' and q.maker_id<>auth.uid()) or(p_decision<>'cancel' and q.maker_id=auth.uid()) then raise exception 'INS_CXL_CASH_SELF_APPROVAL: maker cannot act as checker'; end if;
 if p_decision='approve' and q.status in('posted','voided') and q.checker_id=auth.uid() then return q; end if;
 if q.status<>'pending' then raise exception 'INS_CXL_CASH_STATE: pending request required'; end if;
 if p_decision in('reject','cancel') then
 update ins_cancellation_cash_requests set status=case p_decision when 'reject' then 'rejected' else 'cancelled' end,checker_id=case p_decision when 'reject' then auth.uid() end,checked_at=now(),decision_reason=btrim(p_reason) where id=q.id returning * into q;
 else
 if q.cash_date<>current_date or exists(select 1 from accounting_periods where tenant_id=c.tenant_id and status='closed' and current_date between period_start and period_end) then raise exception 'INS_CXL_CASH_PERIOD: current open posting date required; cancel and recreate stale-date requests'; end if;
 if q.kind<>'void' then item:=platform_ins_cancellation_cash_validate(c.id,q.kind,q.adjustment_id,q.bank_account_id,q.to_bank_account_id,q.amount,q.cash_date); end if;
 update ins_cancellation_cash_requests set status='posting',checker_id=auth.uid(),checked_at=now(),decision_reason=btrim(p_reason),operation_txid=txid_current() where id=q.id returning * into q;
 if q.kind='void' then
 select * into target from ins_cancellation_cash_requests where id=q.voids_request_id and cancellation_id=c.id and status='posted' for update;
 if not found then raise exception 'INS_CXL_CASH_VOID: target is not posted'; end if;
 if exists(select 1 from bank_reconciliations where settlement_id in(target.settlement_id,target.to_settlement_id)) then raise exception 'INS_CXL_CASH_MATCHED: unmatch both legs before requesting a void'; end if;
 if target.kind in('recovery','premium_receipt','commission_return') and exists(select 1 from ins_cancellation_cash_requests where cancellation_id=c.id and status='posted' and kind in('refund','remittance','commission_withdrawal')) then raise exception 'INS_CXL_CASH_FUNDS_IN_USE: reverse downstream cancellation payments first'; end if;
 if target.kind='remittance' and exists(select 1 from ins_cancellation_cash_requests where adjustment_id=target.adjustment_id and kind='commission_withdrawal' and status='posted') then raise exception 'INS_CXL_CASH_FUNDS_IN_USE: return the retained commission withdrawal first'; end if;
 if target.kind in('recovery','premium_receipt','commission_return') then
 v:=platform_ins_cancellation_cash_position(c.id,case target.kind when 'commission_return' then target.to_bank_account_id else target.bank_account_id end);
 if least((v->>'bank_raw_cash')::numeric,(v->>'bank_book_cash')::numeric)<target.amount then raise exception 'INS_CXL_CASH_FUNDS_IN_USE: receipt cash is no longer available at its bank'; end if;
 elsif target.kind='commission_withdrawal' then
 v:=platform_ins_cancellation_cash_position(c.id,target.to_bank_account_id);
 if(v->>'bank_book_cash')::numeric<target.amount then raise exception 'INS_CXL_CASH_FUNDS_IN_USE: operating cash is no longer available'; end if;
 end if;
 s:=platform_fin_void_settlement_impl(c.tenant_id,target.settlement_id,q.notes,current_date);
 insert into ins_cancellation_cash_journals values(c.tenant_id,q.id,s.void_journal_entry_id,'cash_void');
 if target.to_settlement_id is not null then
 s:=platform_fin_void_settlement_impl(c.tenant_id,target.to_settlement_id,q.notes,current_date);
 insert into ins_cancellation_cash_journals values(c.tenant_id,q.id,s.void_journal_entry_id,'destination_void'); end if;
 update ins_cancellation_cash_requests set status='voided',voided_by_request_id=q.id where id=target.id;
 if target.kind='remittance' then perform platform_ins_cancellation_cash_recognize(q.id,target.adjustment_id); end if;
 else
 perform platform_ins_cancellation_cash_emit(q.id,item);
 if q.kind in('commission_return','commission_withdrawal') then perform platform_ins_cancellation_cash_emit(q.id,null,true); end if;
 if q.kind='remittance' then perform platform_ins_cancellation_cash_recognize(q.id,q.adjustment_id); end if;
 end if;
 update ins_cancellation_cash_requests set status='posted',operation_txid=null where id=q.id returning * into q;
 end if;
 insert into ins_cancellation_cash_events(tenant_id,request_id,event,actor_id,detail) values(c.tenant_id,q.id,q.status,auth.uid(),jsonb_build_object('reason',p_reason));
 return q;
end $$;


--
-- Name: ins_decide_policy_cancellation(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_decide_policy_cancellation(p_cancellation_id uuid, p_decision text, p_review_note text, p_accept_manual_exception boolean DEFAULT false) RETURNS public.ins_policy_cancellations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c ins_policy_cancellations%rowtype; p ins_policies%rowtype; pid uuid; fresh jsonb; mappings jsonb; cash jsonb;
 client_item fin_open_items%rowtype; item fin_open_items%rowtype; created_item fin_open_items%rowtype; ce ins_commission_entries%rowtype;
 line jsonb; charge jsonb; outstanding numeric; amount numeric; applied numeric; recovered numeric; remaining numeric; claw numeric;
 target_status text; adjustment_id uuid; insurer uuid; share_id uuid; lines jsonb:='[]'; debit_total numeric:=0; recognition_lines jsonb:='[]'; recognized numeric:=0;
 je journal_entries%rowtype; transfer_due numeric; client_credit numeric; refund numeric;
 v_functional text; v_foreign boolean; v_items jsonb:='[]'::jsonb; v_todo jsonb; v_bound_rate numeric;
begin
 perform ins_policy_cash_require_finance();
 if p_decision not in('approve','reject') or p_decision is null or p_review_note is null or length(btrim(p_review_note)) not between 5 and 2000 then
  raise exception 'INS_CANCELLATION_INPUT: decision and detailed Finance review note required'; end if;
 select policy_id into pid from ins_policy_cancellations where id=p_cancellation_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: cancellation'; end if;
 select * into p from ins_policies where id=pid and tenant_id=get_my_tenant_id() for update;
 select * into c from ins_policy_cancellations where id=p_cancellation_id for update;
 if c.prepared_by=auth.uid() or c.proposed_by=auth.uid() then raise exception 'INS_CANCELLATION_SELF_APPROVAL: an independent Finance checker is required'; end if;
 if c.status='posted' and p_decision='approve' and c.checked_by=auth.uid() then
  if c.review_note is distinct from btrim(p_review_note) or c.manual_exception_accepted is distinct from coalesce(p_accept_manual_exception,false) then raise exception 'INS_CANCELLATION_RETRY_CONFLICT: different approval payload'; end if;
  return c;
 end if;
 if p_decision='reject' then
  if c.status not in('proposed','prepared') then raise exception 'INS_CANCELLATION_STATE: open proposal required'; end if;
  update ins_policy_cancellations set status='rejected',checked_by=auth.uid(),checked_at=now(),review_note=btrim(p_review_note) where id=c.id returning * into c;
  insert into ins_cancellation_events(tenant_id,cancellation_id,event,actor_id,detail) values(c.tenant_id,c.id,'rejected',auth.uid(),jsonb_build_object('note',p_review_note));
  return c;
 end if;
 if c.status<>'prepared' then raise exception 'INS_CANCELLATION_STATE: Finance preparation required before approval'; end if;
 -- Serialize with cash approvals, claims, credits and commission transfers.
 perform m.id from fin_open_items m join ins_policy_cash_items k on k.id=m.id where k.source_id=p.id and k.tenant_id=p.tenant_id order by m.id for update of m;
 perform e.id from ins_commission_entries e where e.policy_id=p.id order by e.id for update;
 fresh:=ins_preview_policy_cancellation(p.id,c.effective_date,c.insurer_terms,c.charge_refunds)||platform_ins_cancellation_review_position(p.id);
 if exists(select 1 from accounting_periods where tenant_id=p.tenant_id and status='closed' and current_date between period_start and period_end) then raise exception 'INS_CANCELLATION_PERIOD: current accounting period closed'; end if;
 if (fresh-'generated_at') is distinct from (c.calculation-'generated_at') then raise exception 'INS_CANCELLATION_STALE: amounts or collection position changed; Finance maker must refresh preparation'; end if;
 if (fresh->>'requires_finance_exception')::boolean and not coalesce(p_accept_manual_exception,false) then raise exception 'INS_CANCELLATION_EXCEPTION: explicit independent Finance acceptance of the documented manual exception required'; end if;
 mappings:=platform_ins_cancellation_mappings(p.id,c.clearing_gl_account_id);
 if mappings is distinct from c.accounting_mappings then raise exception 'INS_CANCELLATION_STALE: accounting mappings changed'; end if;
 cash:=ins_policy_cash_totals(p.id);
 v_functional:=fin_ledger_currency(p.tenant_id);
 v_foreign:=p.currency is distinct from v_functional;
 -- Existing credits to any insurer payable would otherwise double-adjust its
 -- original bound obligations. Treat them as an exception, not as cash paid.
 if exists(select 1 from fin_credit_applications a join fin_credit_notes n on n.id=a.credit_note_id and n.status='posted'
   join ins_policy_cash_items k on k.id=a.open_item_id where k.source_id=p.id and k.source_type='ins_policy_insurer') then
  raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: original insurer credits need separate Finance review'; end if;
 update ins_policy_cancellations set status='posting',checked_by=auth.uid(),checked_at=now(),review_note=btrim(p_review_note),manual_exception_accepted=coalesce(p_accept_manual_exception,false),
  posting_date=current_date,cancellation_no=next_doc_number(c.tenant_id,'ins_policy_cancellation','CXL'),cash_at_posting=cash,operation_txid=txid_current() where id=c.id returning * into c;
 select * into client_item from fin_open_items where tenant_id=p.tenant_id and source_type='ins_policy_premium' and source_id=p.id;
 client_credit:=(fresh->>'receivable_credit')::numeric; refund:=(fresh->>'client_refund_due')::numeric;
 if client_credit>0 then perform platform_ins_cancellation_credit(c.id,client_item.id,client_credit); end if;
 if refund>0 then
  -- The refund item is created after the journal posts, so it can name its booking entry.
  v_items:=v_items||jsonb_build_object('kind','refund','party',client_item.party_account_id,'amount',refund);
  lines:=lines||jsonb_build_array(jsonb_build_object('gl_account_id',c.clearing_gl_account_id,'debit',refund),jsonb_build_object('gl_account_id',(mappings->>'refund_payable')::uuid,'credit',refund));
 end if;
 for line in select value from jsonb_array_elements(fresh->'insurers') loop
  insurer:=(line->>'insurer_id')::uuid; amount:=(line->>'total_insurer_credit')::numeric; claw:=(line->>'commission_clawback')::numeric;
  select id into share_id from ins_policy_insurer_shares where policy_id=p.id and insurer_id=insurer;
  select i.* into item from fin_open_items i join ins_policy_cash_items k on k.id=i.id
   where k.source_id=p.id and k.source_type='ins_policy_insurer' and k.tenant_id=p.tenant_id
    and (k.insurer_share_id=share_id or (k.insurer_share_id is null and insurer=p.insurer_id));
  if not found then raise exception 'INS_CANCELLATION_HISTORY: original insurer item missing'; end if;
  select outstanding_amount into outstanding from fin_open_item_balances where id=item.id;
  applied:=least(outstanding,amount); recovered:=amount-applied;
  select * into ce from ins_commission_entries where policy_id=p.id and insurer_share_id is not distinct from
   (case when exists(select 1 from ins_policy_financial_snapshots where policy_id=p.id and extended) then share_id else null end);
  if (line->>'original_commission')::numeric>0 and (mappings->>'commission_treatment')='deferred' and ce.id is null then raise exception 'INS_CANCELLATION_HISTORY: original commission entry missing'; end if;
  if ce.id is not null and ce.amount<>(line->>'original_commission')::numeric then raise exception 'INS_CANCELLATION_HISTORY: original commission amount differs'; end if;
  remaining:=(line->>'original_commission')::numeric-claw;
  target_status:=case when ce.id is null then 'legacy' when ce.status='transferred' then 'transferred' when ce.status='earned' then 'earned'
   when outstanding-applied=0 and remaining>0 then 'earned' else 'deferred' end;
  transfer_due:=case when ce.status='transferred' then claw else 0 end;
  adjustment_id:=gen_random_uuid();
  insert into ins_cancellation_insurer_adjustments(id,tenant_id,cancellation_id,insurer_id,insurer_share_id,original_item_id,original_commission_entry_id,original_commission_state,
   return_premium,commission_clawback,pass_through_refund,total_insurer_credit,payable_credit,recovery_due,retained_commission,retained_commission_status,transferred_clawback_due)
  values(adjustment_id,c.tenant_id,c.id,insurer,share_id,item.id,ce.id,case when ce.id is not null then to_jsonb(ce) else null end,
   (line->>'return_premium')::numeric,claw,(line->>'pass_through_refund')::numeric,amount,applied,recovered,remaining,target_status,transfer_due);
  if applied>0 then perform platform_ins_cancellation_credit(c.id,item.id,applied); end if;
  if recovered>0 then
   v_items:=v_items||jsonb_build_object('kind','recovery','party',item.party_account_id,'adjustment',adjustment_id,'amount',recovered);
   lines:=lines||jsonb_build_array(jsonb_build_object('gl_account_id',(mappings->>'ar')::uuid,'debit',recovered),jsonb_build_object('gl_account_id',c.clearing_gl_account_id,'credit',recovered));
  end if;
  if claw>0 then
   lines:=lines||jsonb_build_object('gl_account_id',(mappings->>case when ce.id is not null and ce.status='deferred' then 'unearned' else 'income' end)::uuid,'debit',claw);
   debit_total:=debit_total+claw;
  end if;
  if ce.status='deferred' and target_status='earned' and remaining>0 then
   if v_foreign then
    -- Recognition releases the unearned commission at the rate the policy was bound at,
    -- the same convention as the settlement-triggered recognition.
    if v_bound_rate is null then
     if p.journal_entry_id is null then raise exception 'INS_CANCELLATION_RATE: the policy has no bind journal, so its commission rate is unknown'; end if;
     select l.fx_rate into v_bound_rate from journal_entry_lines l
      where l.journal_entry_id=p.journal_entry_id and l.tenant_id=p.tenant_id and l.currency=p.currency
        and l.gl_account_id=(mappings->>'unearned')::uuid
      order by l.id limit 1;
     if v_bound_rate is null then raise exception 'INS_CANCELLATION_RATE: the bind journal has no % line on unearned commission, so the booked rate is unknown', p.currency; end if;
    end if;
    recognition_lines:=recognition_lines||jsonb_build_array(
     jsonb_build_object('gl_account_id',(mappings->>'unearned')::uuid,'debit',remaining)||jsonb_build_object('currency',p.currency,'rate_from_entry',p.journal_entry_id,'fx_rate',v_bound_rate),
     jsonb_build_object('gl_account_id',(mappings->>'income')::uuid,'credit',remaining)||jsonb_build_object('currency',p.currency,'rate_from_entry',p.journal_entry_id,'fx_rate',v_bound_rate));
   else
    recognition_lines:=recognition_lines||jsonb_build_array(jsonb_build_object('gl_account_id',(mappings->>'unearned')::uuid,'debit',remaining),jsonb_build_object('gl_account_id',(mappings->>'income')::uuid,'credit',remaining));
   end if;
   recognized:=recognized+remaining;
  end if;
 end loop;
 for charge in select value from jsonb_array_elements(fresh->'charges') where value->>'kind'='broker_fee' loop
  if (charge->>'refund_base')::numeric>0 then
   lines:=lines||jsonb_build_object('gl_account_id',(charge->>'income_gl_account_id')::uuid,'debit',(charge->>'refund_base')::numeric);
   debit_total:=debit_total+(charge->>'refund_base')::numeric;
  end if;
  if (charge->>'refund_vat')::numeric>0 then
   lines:=lines||jsonb_build_object('gl_account_id',(mappings->>'vat')::uuid,'debit',(charge->>'refund_vat')::numeric);
   debit_total:=debit_total+(charge->>'refund_vat')::numeric;
  end if;
 end loop;
 if debit_total>0 then lines:=lines||jsonb_build_object('gl_account_id',c.clearing_gl_account_id,'credit',debit_total); end if;
 if jsonb_array_length(lines)>0 then
  if v_foreign then
   -- Every adjustment leg posts in the policy's currency at the cancellation-date rate,
   -- so the clearing account nets to zero in the currency and in base.
   lines:=(select jsonb_agg(value || jsonb_build_object('currency',p.currency)) from jsonb_array_elements(lines));
  end if;
  je:=post_journal_entry(c.tenant_id,'ins_policy_cancellation',c.id,current_date,'Cancellation '||c.cancellation_no||': '||c.reason,lines);
  insert into ins_cancellation_journals values(c.tenant_id,c.id,je.id,'cancellation_adjustments');
  for v_todo in select * from jsonb_array_elements(v_items) loop
   if v_todo->>'kind'='refund' then
    created_item:=fin_create_open_item_fx(c.tenant_id,(v_todo->>'party')::uuid,'ap_control','ins_cancellation_client_refund',c.id,c.cancellation_no,current_date,current_date,(v_todo->>'amount')::numeric,'Client refund due: '||p.policy_no,p.currency,je.id);
    update ins_policy_cancellations set refund_item_id=created_item.id where id=c.id;
   else
    created_item:=fin_create_open_item_fx(c.tenant_id,(v_todo->>'party')::uuid,'ar_control','ins_cancellation_insurer_recovery',(v_todo->>'adjustment')::uuid,c.cancellation_no,current_date,current_date,(v_todo->>'amount')::numeric,'Insurer recovery: '||p.policy_no,p.currency,je.id);
    update ins_cancellation_insurer_adjustments set recovery_item_id=created_item.id where id=(v_todo->>'adjustment')::uuid;
   end if;
  end loop;
 end if;
 if recognized>0 then
  declare recognition journal_entries%rowtype; begin
   recognition:=post_journal_entry(c.tenant_id,'ins_policy_cancellation',gen_random_uuid(),current_date,'Retained commission earned: '||c.cancellation_no,recognition_lines);
   insert into ins_cancellation_journals values(c.tenant_id,c.id,recognition.id,'retained_commission_recognition');
  end;
 end if;
 update ins_policy_cancellations set status='posted',journal_entry_id=je.id,operation_txid=null where id=c.id returning * into c;
 perform set_config('ins.via_rpc','on',true);
 update ins_policies set status='cancelled' where id=p.id;
 update ins_policy_cash_requests set status='cancelled',checker_id=null,checked_at=now(),decision_reason='Policy cancellation posted: '||c.cancellation_no
  where policy_id=p.id and status='pending';
 insert into ins_cancellation_events(tenant_id,cancellation_id,event,actor_id,detail) values(c.tenant_id,c.id,'posted',auth.uid(),jsonb_build_object('review_note',p_review_note,'manual_exception_accepted',p_accept_manual_exception,'cash_authorized',false));
 return c;
end $$;


--
-- Name: ins_policy_cash_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_cash_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    kind text NOT NULL,
    bank_account_id uuid NOT NULL,
    amount numeric(18,2) NOT NULL,
    cash_date date NOT NULL,
    reference text,
    notes text,
    request_key uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    maker_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    checker_id uuid,
    checked_at timestamp with time zone,
    decision_reason text,
    settlement_id uuid,
    operation_txid bigint,
    insurer_share_id uuid,
    CONSTRAINT ins_policy_cash_requests_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT ins_policy_cash_requests_check CHECK (((checker_id IS NULL) OR (checker_id <> maker_id))),
    CONSTRAINT ins_policy_cash_requests_check1 CHECK ((((status = 'pending'::text) AND (checker_id IS NULL) AND (checked_at IS NULL) AND (settlement_id IS NULL) AND (operation_txid IS NULL)) OR ((status = 'posting'::text) AND (checker_id IS NOT NULL) AND (checked_at IS NOT NULL) AND (operation_txid IS NOT NULL)) OR ((status = 'posted'::text) AND (checker_id IS NOT NULL) AND (checked_at IS NOT NULL) AND (settlement_id IS NOT NULL) AND (operation_txid IS NULL)) OR ((status = 'rejected'::text) AND (checker_id IS NOT NULL) AND (checked_at IS NOT NULL) AND (settlement_id IS NULL) AND (operation_txid IS NULL) AND (length(btrim(decision_reason)) >= 5)) OR ((status = 'cancelled'::text) AND (checker_id IS NULL) AND (checked_at IS NOT NULL) AND (settlement_id IS NULL) AND (operation_txid IS NULL) AND (length(btrim(decision_reason)) >= 5)))),
    CONSTRAINT ins_policy_cash_requests_kind_check CHECK ((kind = ANY (ARRAY['receipt'::text, 'remittance'::text]))),
    CONSTRAINT ins_policy_cash_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'posting'::text, 'posted'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: ins_decide_policy_cash_request(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_decide_policy_cash_request(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS public.ins_policy_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_policy_cash_requests%rowtype; i fin_open_items%rowtype; s fin_settlements%rowtype; pid uuid;
begin
  perform ins_policy_cash_require_finance();
  if p_decision is null or p_decision not in ('approve','reject','cancel') then raise exception 'INS_CASH_INPUT: invalid decision'; end if;
  select policy_id into pid from ins_policy_cash_requests where id=p_request_id and tenant_id=get_my_tenant_id();
  if not found then raise exception 'INS_NOT_FOUND: cash request'; end if;
  perform id from ins_policies where id=pid and tenant_id=get_my_tenant_id() for update;
  select * into q from ins_policy_cash_requests where id=p_request_id and tenant_id=get_my_tenant_id() for update;
  if p_decision='cancel' then
    if q.maker_id<>auth.uid() then raise exception 'INS_CASH_MAKER: only the maker can cancel a pending request'; end if;
  elsif q.maker_id=auth.uid() then raise exception 'INS_CASH_SELF_APPROVAL: another Finance user must check the request';
  end if;
  -- A lost response may be retried by the same checker, without reposting.
  if q.status='posted' and p_decision='approve' and q.checker_id=auth.uid() then return q; end if;
  if q.status<>'pending' then raise exception 'INS_CASH_DECIDED: request is no longer pending'; end if;
  if p_decision in ('reject','cancel') then
    if p_reason is null or length(btrim(p_reason))<5 then raise exception 'INS_CASH_REASON: at least five characters are required'; end if;
    update ins_policy_cash_requests set status=case p_decision when 'reject' then 'rejected' else 'cancelled' end,
      checker_id=case when p_decision='reject' then auth.uid() else null end,checked_at=now(),decision_reason=btrim(p_reason)
      where id=q.id returning * into q;
    return q;
  end if;
  i := ins_policy_cash_validate(q.policy_id,q.kind,q.bank_account_id,q.amount,q.cash_date,q.insurer_share_id);
  update ins_policy_cash_requests set status='posting',checker_id=auth.uid(),checked_at=now(),operation_txid=txid_current()
    where id=q.id;
  s := platform_fin_record_settlement_impl(q.tenant_id,q.bank_account_id,
    case q.kind when 'receipt' then 'in' else 'out' end,i.party_account_id,q.amount,q.cash_date,
    jsonb_build_array(jsonb_build_object('open_item_id',i.id,'amount',q.amount)),q.reference,q.notes);
  -- Allocation trigger binds the exact settlement to this approval context.
  update ins_policy_cash_requests set status='posted',operation_txid=null
    where id=q.id and settlement_id=s.id returning * into q;
  if not found then raise exception 'INS_CASH_CONTEXT: approved allocation was not recorded'; end if;
  return q;
end $$;


--
-- Name: ins_policy_endorsements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_endorsements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    request_key uuid NOT NULL,
    reason text NOT NULL,
    effective_date date NOT NULL,
    insurer_terms jsonb NOT NULL,
    changes jsonb DEFAULT '{}'::jsonb NOT NULL,
    proposed_by uuid NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'proposed'::text NOT NULL,
    prepared_by uuid,
    prepared_at timestamp with time zone,
    calculation jsonb NOT NULL,
    checked_by uuid,
    checked_at timestamp with time zone,
    review_note text,
    manual_exception_accepted boolean DEFAULT false NOT NULL,
    endorsement_no text,
    posting_date date,
    journal_entry_id uuid,
    premium_item_id uuid,
    credit_note_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    commission_entry_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    accounting_mappings jsonb,
    operation_txid bigint,
    CONSTRAINT ins_policy_endorsements_changes_check CHECK ((jsonb_typeof(changes) = 'object'::text)),
    CONSTRAINT ins_policy_endorsements_insurer_terms_check CHECK ((jsonb_typeof(insurer_terms) = 'array'::text)),
    CONSTRAINT ins_policy_endorsements_reason_check CHECK (((length(btrim(reason)) >= 5) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT ins_policy_endorsements_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'prepared'::text, 'posting'::text, 'posted'::text, 'rejected'::text, 'withdrawn'::text])))
);


--
-- Name: ins_decide_policy_endorsement(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_decide_policy_endorsement(p_endorsement_id uuid, p_decision text, p_review_note text, p_accept_manual_exception boolean DEFAULT false) RETURNS public.ins_policy_endorsements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c ins_policy_endorsements%rowtype;
  p ins_policies%rowtype;
  fresh jsonb; mappings jsonb; share jsonb;
  insurer uuid; v_share_id uuid;
  delta numeric; v_claw numeric; net numeric;
  v_ar uuid; v_payable uuid; v_unearned uuid; v_income uuid; v_clearing uuid;
  v_client_acc uuid; v_ins_acc uuid;
  item fin_open_items%rowtype; created_item fin_open_items%rowtype; note fin_credit_notes%rowtype;
  ce record;
  v_claw_left numeric; v_take numeric; v_claw_lines jsonb := '[]'::jsonb; v_debit_total numeric := 0;
  v_add_lines jsonb := '[]'::jsonb; v_add_items jsonb := '[]'::jsonb;
  v_recos jsonb := '[]'::jsonb; v_todo jsonb;
  v_credit_notes jsonb := '[]'::jsonb; v_new_entries jsonb := '[]'::jsonb;
  v_outstanding numeric; v_applied numeric; v_recovered numeric;
  note_id uuid;
  je journal_entries%rowtype; je_adj uuid := null; je_add uuid := null;
  v_first_premium_item uuid := null;
  v_desc text;
begin
  perform ins_policy_cash_require_finance();
  if p_decision not in ('approve','reject') or p_decision is null
     or p_review_note is null or length(btrim(p_review_note)) not between 5 and 2000 then
    raise exception 'INS_ENDORSEMENT_INPUT: decision and detailed Finance review note required';
  end if;
  select policy_id into p.id from ins_policy_endorsements
   where id = p_endorsement_id and tenant_id = get_my_tenant_id();
  if not found then raise exception 'INS_NOT_FOUND: endorsement'; end if;
  select * into p from ins_policies where id = p.id and tenant_id = get_my_tenant_id() for update;
  select * into c from ins_policy_endorsements where id = p_endorsement_id for update;
  if p.status not in ('active','renewed') then
    raise exception 'INS_ENDORSEMENT_STATE: the policy is %; only a bound policy endorses', p.status;
  end if;
  if c.prepared_by = auth.uid() or c.proposed_by = auth.uid() then
    raise exception 'INS_ENDORSEMENT_SELF_APPROVAL: an independent Finance checker is required';
  end if;
  -- An approve retry on a posted case is idempotent only with the same payload.
  if c.status = 'posted' and p_decision = 'approve' and c.checked_by = auth.uid() then
    if c.review_note is distinct from btrim(p_review_note)
       or c.manual_exception_accepted is distinct from coalesce(p_accept_manual_exception, false) then
      raise exception 'INS_ENDORSEMENT_RETRY_CONFLICT: different approval payload';
    end if;
    return c;
  end if;
  if p_decision = 'reject' then
    if c.status not in ('proposed','prepared') then
      raise exception 'INS_ENDORSEMENT_STATE: open proposal required';
    end if;
    update ins_policy_endorsements
       set status = 'rejected', checked_by = auth.uid(), checked_at = now(),
           review_note = btrim(p_review_note)
     where id = c.id
     returning * into c;
    insert into ins_policy_endorsement_events(tenant_id, endorsement_id, event, actor_id, detail)
    values (c.tenant_id, c.id, 'rejected', auth.uid(), jsonb_build_object('note', p_review_note));
    return c;
  end if;
  if c.status <> 'prepared' then
    raise exception 'INS_ENDORSEMENT_STATE: Finance preparation required before approval';
  end if;
  -- Serialize with cash approvals, claims, credits and commission transfers.
  perform m.id from fin_open_items m join ins_policy_cash_items k on k.id = m.id
   where k.source_id = p.id and k.tenant_id = p.tenant_id order by m.id for update of m;
  perform e.id from ins_commission_entries e where e.policy_id = p.id order by e.id for update;
  fresh := ins_preview_policy_endorsement(p.id, c.effective_date, c.insurer_terms, c.changes)
           || ins_endorsement_review_position(p.id);
  if exists(select 1 from accounting_periods
             where tenant_id = p.tenant_id and status = 'closed'
               and current_date between period_start and period_end) then
    raise exception 'INS_ENDORSEMENT_PERIOD: current accounting period closed';
  end if;
  -- live_endorsements carries the case's own lifecycle state (proposed ->
  -- prepared between maker and checker), not amounts; the one-live rule means
  -- it cannot hide a competitor. Everything else in the recompute must match.
  if (fresh - 'generated_at' - 'live_endorsements') is distinct from (c.calculation - 'generated_at' - 'live_endorsements') then
    raise exception 'INS_ENDORSEMENT_STALE: amounts or collection position changed; Finance maker must refresh preparation';
  end if;
  -- requires_review lives per share (a share delta bigger than that share's
  -- whole premium); any share flagging demands the checker's explicit nod.
  if exists (select 1 from jsonb_array_elements(fresh -> 'shares') sh
              where (sh ->> 'requires_review')::boolean)
     and not coalesce(p_accept_manual_exception, false) then
    raise exception 'INS_ENDORSEMENT_EXCEPTION: explicit independent Finance acceptance of the reviewed calculation required';
  end if;
  mappings := ins_endorsement_mappings(p.id, (c.accounting_mappings ->> 'clearing')::uuid);
  if mappings is distinct from c.accounting_mappings then
    raise exception 'INS_ENDORSEMENT_STALE: accounting mappings changed';
  end if;
  update ins_policy_endorsements
     set status = 'posting', checked_by = auth.uid(), checked_at = now(),
         review_note = btrim(p_review_note),
         manual_exception_accepted = coalesce(p_accept_manual_exception, false),
         posting_date = current_date,
         endorsement_no = next_doc_number(c.tenant_id, 'ins_policy_endorsement', 'END'),
         operation_txid = txid_current()
   where id = c.id
   returning * into c;

  v_ar       := (mappings ->> 'ar')::uuid;
  v_payable  := (mappings ->> 'payable')::uuid;
  v_unearned := (mappings ->> 'unearned')::uuid;
  v_income   := (mappings ->> 'income')::uuid;
  v_clearing := (mappings ->> 'clearing')::uuid;
  v_client_acc := ins_ensure_client_account(p.client_id);
  v_desc := 'Endorsement ' || c.endorsement_no || ' on ' || p.policy_no;

  for share in select value from jsonb_array_elements(fresh -> 'shares') loop
    insurer := (share ->> 'insurer_id')::uuid;
    delta   := (share ->> 'premium_delta')::numeric;
    continue when delta = 0;
    v_claw  := (share ->> 'commission_delta')::numeric;
    select id into v_share_id from ins_policy_insurer_shares
     where policy_id = p.id and tenant_id = p.tenant_id and insurer_id = insurer
     order by id limit 1;
    v_ins_acc := ins_ensure_insurer_account(insurer);

    if delta > 0 then
      ---------------------------------------------------------------
      -- Additional premium: AR item + insurer-share item + a new
      -- deferred commission entry tied to the endorsement's own item.
      ---------------------------------------------------------------
      net := delta - v_claw;
      if net <= 0 then
        raise exception 'INS_ENDORSEMENT_COMMISSION: commission would leave nothing to remit to the insurer';
      end if;
      v_add_lines := v_add_lines || jsonb_build_array(
        jsonb_build_object('gl_account_id', v_ar, 'debit', delta, 'currency', p.currency, 'description', v_desc),
        jsonb_build_object('gl_account_id', v_payable, 'credit', net, 'currency', p.currency, 'description', v_desc)
      );
      if v_claw > 0 then
        v_add_lines := v_add_lines || jsonb_build_object(
          'gl_account_id', v_unearned, 'credit', v_claw, 'currency', p.currency,
          'description', v_desc || ' - unearned commission');
      end if;
      v_add_items := v_add_items || jsonb_build_object(
        'insurer_id', insurer, 'share_id', v_share_id, 'premium', delta,
        'net', net, 'commission', v_claw);
    else
      ---------------------------------------------------------------
      -- Return premium: credit notes at the booked rates, capped at
      -- each original item's outstanding; honest clawback of the
      -- commission (deferred pool first, then what is earned).
      ---------------------------------------------------------------
      v_claw := -v_claw;  -- the claw is a positive amount on a return
      -- Client side: the original premium item is policy-level.
      select * into item from fin_open_items
       where tenant_id = p.tenant_id and source_type = 'ins_policy_premium' and source_id = p.id;
      if not found then raise exception 'INS_ENDORSEMENT_HISTORY: original premium item missing'; end if;
      select outstanding_amount into v_outstanding from fin_open_item_balances where id = item.id;
      v_applied := least(v_outstanding, -delta);
      if v_applied > 0 then
        -- The 3d-1 note machinery: the note takes the item's currency; in a
        -- foreign currency the control line rides the item's booked rate, the
        -- clearing offset prices at the credit-date rate, and the difference
        -- books as realised result. A functional note is unchanged (rate 1).
        note := platform_fin_raise_credit_note_impl(c.tenant_id, item.control_role, item.party_account_id,
          v_applied, current_date, v_clearing,
          jsonb_build_array(jsonb_build_object('open_item_id', item.id, 'amount', v_applied)),
          c.reason, c.endorsement_no);
        note_id := note.id;
        v_credit_notes := v_credit_notes || jsonb_build_object(
          'note_id', note_id, 'open_item_id', item.id, 'amount', v_applied, 'side', item.side);
      end if;
      v_recovered := (-delta) - v_applied;
      if v_recovered > 0 then
        -- The return exceeds the billed premium still outstanding: the client
        -- owes the difference back (the cancellation engine's recovery item).
        v_recos := v_recos || jsonb_build_object(
          'party', item.party_account_id, 'role', 'ar_control', 'source_type',
          'ins_policy_endorsement_recovery', 'source_id', c.id, 'amount', v_recovered);
      end if;
      -- Insurer side: mirror the share's net reduction against its item.
      net := (-delta) - v_claw;
      -- The ORIGINAL bind items: pinned by their booking journal (the policy's
      -- bind entry), so a prior additional endorsement's items never match.
      if v_share_id is not null then
        select i.* into item from fin_open_items i join ins_policy_cash_items k on k.id = i.id
         where k.source_id = p.id and k.source_type = 'ins_policy_insurer'
           and k.insurer_share_id = v_share_id and k.tenant_id = p.tenant_id
           and i.journal_entry_id = p.journal_entry_id;
      else
        select i.* into item from fin_open_items i join ins_policy_cash_items k on k.id = i.id
         where k.source_id = p.id and k.source_type = 'ins_policy_insurer'
           and k.insurer_share_id is null and i.party_account_id = v_ins_acc
           and i.journal_entry_id = p.journal_entry_id and k.tenant_id = p.tenant_id;
      end if;
      if not found then raise exception 'INS_ENDORSEMENT_HISTORY: original insurer item missing'; end if;
      select outstanding_amount into v_outstanding from fin_open_item_balances where id = item.id;
      v_applied := least(v_outstanding, net);
      if v_applied > 0 then
        note := platform_fin_raise_credit_note_impl(c.tenant_id, item.control_role, item.party_account_id,
          v_applied, current_date, v_clearing,
          jsonb_build_array(jsonb_build_object('open_item_id', item.id, 'amount', v_applied)),
          c.reason, c.endorsement_no);
        note_id := note.id;
        v_credit_notes := v_credit_notes || jsonb_build_object(
          'note_id', note_id, 'open_item_id', item.id, 'amount', v_applied, 'side', item.side);
      end if;
      v_recovered := net - v_applied;
      if v_recovered > 0 then
        v_recos := v_recos || jsonb_build_object(
          'party', item.party_account_id, 'role', 'ar_control', 'source_type',
          'ins_policy_endorsement_recovery_insurer', 'source_id', c.id, 'amount', v_recovered);
      end if;
      -- Commission clawback: the deferred pool first, then earned, then
      -- transferred; the rows are never mutated, the ledger records the take.
      v_claw_left := v_claw;
      for ce in
        select e.id, e.amount, e.status,
               (e.amount - coalesce((select sum(x.amount) from ins_endorsement_clawbacks x
                                      where x.commission_entry_id = e.id and x.tenant_id = e.tenant_id), 0)) as available
          from ins_commission_entries e
         where e.policy_id = p.id and e.tenant_id = p.tenant_id
           and case when v_share_id is not null
                    then e.insurer_share_id = v_share_id
                    else e.insurer_share_id is null end
         order by case e.status when 'deferred' then 0 when 'earned' then 1 else 2 end,
                  e.created_at, e.id
      loop
        exit when v_claw_left <= 0;
        v_take := least(v_claw_left, greatest(ce.available, 0));
        continue when v_take <= 0;
        v_claw_lines := v_claw_lines || jsonb_build_object(
          'gl_account_id', case when ce.status = 'deferred' then v_unearned else v_income end,
          'debit', v_take, 'currency', p.currency,
          'description', v_desc || ' - commission clawback');
        insert into ins_endorsement_clawbacks(id, tenant_id, endorsement_id, commission_entry_id, amount)
        values (gen_random_uuid(), c.tenant_id, c.id, ce.id, v_take);
        v_claw_left := v_claw_left - v_take;
      end loop;
      if v_claw_left > 0 then
        raise exception 'INS_ENDORSEMENT_HISTORY: the policy''s commission cannot cover this clawback';
      end if;
    end if;
  end loop;

  -- The return-side adjustments journal: clawback debits, clearing balance.
  if jsonb_array_length(v_claw_lines) > 0 then
    v_debit_total := (select coalesce(sum((l ->> 'debit')::numeric), 0) from jsonb_array_elements(v_claw_lines) l);
    -- The balancing clearing line joins the array FIRST so the E3 mapping
    -- below stamps it too.
    v_claw_lines := v_claw_lines || jsonb_build_object('gl_account_id', v_clearing, 'credit', v_debit_total);
    if p.currency is distinct from fin_ledger_currency(c.tenant_id) then
      -- E3/3d-3 convention: every adjustment leg rides the policy's currency at
      -- the posting-date rate, so the clearing account nets to zero in the
      -- currency and in base (the balancing line must not fall back to the
      -- ledger currency).
      v_claw_lines := (select jsonb_agg(value || jsonb_build_object('currency', p.currency))
                         from jsonb_array_elements(v_claw_lines) value);
    end if;
    je := post_journal_entry(c.tenant_id, 'ins_policy_endorsement', c.id, current_date,
      v_desc || ': commission clawback', v_claw_lines);
    je_adj := je.id;
  end if;
  -- Recovery items name the adjustments journal (created after posting, the
  -- cancellation pattern).
  for v_todo in select * from jsonb_array_elements(v_recos) loop
    created_item := fin_create_open_item_fx(c.tenant_id, (v_todo ->> 'party')::uuid,
      (v_todo ->> 'role'), (v_todo ->> 'source_type'), (v_todo ->> 'source_id')::uuid,
      c.endorsement_no, current_date, current_date, (v_todo ->> 'amount')::numeric,
      'Endorsement recovery: ' || p.policy_no, p.currency, je_adj);
  end loop;
  -- The additional-side journal, then one client item for the whole
  -- endorsement, and per-insurer payable items. Each insurer item is keyed by
  -- its deferred commission entry (created first, naming the item once it
  -- exists): when that item is fully paid, the recognition trigger earns
  -- exactly that entry.
  if jsonb_array_length(v_add_lines) > 0 then
    je := post_journal_entry(c.tenant_id, 'ins_policy_endorsement', c.id, current_date, v_desc, v_add_lines);
    je_add := je.id;
    created_item := fin_create_open_item_fx(c.tenant_id, v_client_acc, 'ar_control',
      'ins_policy_endorsement', c.id, c.endorsement_no, current_date, current_date,
      (select sum((v ->> 'premium')::numeric) from jsonb_array_elements(v_add_items) v),
      'Endorsement premium due: ' || p.policy_no, p.currency, je_add);
    v_first_premium_item := created_item.id;
  end if;
  for v_todo in select * from jsonb_array_elements(v_add_items) loop
    -- The commission entry is born first (open items are immutable, so the
    -- item must carry its final source at birth); the item then carries the
    -- entry's id as its source, and the entry names the item whose full
    -- payment earns it.
    if (v_todo ->> 'commission')::numeric > 0 then
      insert into ins_commission_entries(id, tenant_id, policy_id, amount, status, insurer_share_id)
      values (gen_random_uuid(), c.tenant_id, p.id, (v_todo ->> 'commission')::numeric, 'deferred',
              (v_todo ->> 'share_id')::uuid)
      returning id into note_id;
      v_new_entries := v_new_entries || to_jsonb(note_id);
    else
      note_id := null;
    end if;
    created_item := fin_create_open_item_fx(c.tenant_id,
      ins_ensure_insurer_account((v_todo ->> 'insurer_id')::uuid), 'insurer_payable',
      'ins_policy_endorsement_insurer', note_id, c.endorsement_no, current_date, current_date,
      (v_todo ->> 'net')::numeric, 'Net premium payable to insurer: ' || p.policy_no, p.currency, je_add);
    if note_id is not null then
      update ins_commission_entries set source_open_item_id = created_item.id where id = note_id;
    end if;
  end loop;

  update ins_policy_endorsements
     set status = 'posted',
         journal_entry_id = coalesce(je_adj, je_add),
         premium_item_id = v_first_premium_item,
         credit_note_ids = v_credit_notes,
         commission_entry_ids = v_new_entries,
         operation_txid = null
   where id = c.id
   returning * into c;
  insert into ins_policy_endorsement_events(tenant_id, endorsement_id, event, actor_id, detail)
  values (c.tenant_id, c.id, 'posted', auth.uid(), jsonb_build_object(
    'review_note', p_review_note,
    'manual_exception_accepted', coalesce(p_accept_manual_exception, false),
    'adjustment_journal', je_adj, 'additional_journal', je_add,
    'credit_notes', v_credit_notes));
  return c;
end $$;


--
-- Name: ins_end_insurer_product_rate(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_end_insurer_product_rate(p_id uuid, p_effective_to date) RETURNS public.ins_insurer_product_rates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row ins_insurer_product_rates%rowtype;
begin
  select * into v_row from ins_insurer_product_rates
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'INS_RATE_NOT_FOUND: rate not found';
  end if;
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers end a commission rate' using errcode = '42501';
  end if;
  if v_row.status <> 'approved' then
    raise exception 'INS_RATE_NOT_APPROVED: only an approved rate can be end-dated (this one is %)', v_row.status;
  end if;
  if p_effective_to is null or p_effective_to < v_row.effective_from then
    raise exception 'INS_RATE_WINDOW: the new end date cannot be empty or before the rate starts (%)', v_row.effective_from;
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  update ins_insurer_product_rates
     set effective_to = p_effective_to
   where id = p_id
   returning * into v_row;
  perform set_config('ins.via_rpc', 'off', true);
  return v_row;
end;
$$;


--
-- Name: ins_endorsement_cross_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_endorsement_cross_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_table_name = 'ins_policy_cancellations' then
    if new.status in ('proposed','prepared','posting') and exists (
      select 1 from ins_policy_endorsements
       where policy_id = new.policy_id and status in ('proposed','prepared','posting')
    ) then
      raise exception 'INS_ENDORSEMENT_LIVE: finish or withdraw the live endorsement before cancelling this policy';
    end if;
    if new.status in ('proposed','prepared','posting') and exists (
      select 1 from ins_policy_endorsements
       where policy_id = new.policy_id and status = 'posted'
    ) then
      raise exception 'INS_ENDORSEMENT_POSTED: this policy has posted endorsements; cancelling it needs the endorsement-items extension (E4)';
    end if;
  else
    if new.status in ('proposed','prepared','posting') and exists (
      select 1 from ins_policy_cancellations
       where policy_id = new.policy_id and status in ('proposed','prepared','posting','posted')
    ) then
      raise exception 'INS_CANCELLATION_LIVE: this policy has a cancellation in flight; endorse it another day';
    end if;
  end if;
  return new;
end $$;


--
-- Name: ins_endorsement_mappings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_endorsement_mappings(p_policy_id uuid, p_clearing_gl_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid;
  v_ar uuid; v_payable uuid; v_unearned uuid; v_income uuid;
begin
  select tenant_id into v_tenant from ins_policies where id = p_policy_id;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  v_ar       := get_posting_account(v_tenant, 'ar_control');
  v_payable  := get_posting_account(v_tenant, 'insurer_payable');
  v_unearned := get_posting_account(v_tenant, 'unearned_commission');
  v_income   := get_posting_account(v_tenant, 'commission_income');
  if v_ar is null or v_payable is null or v_unearned is null or v_income is null then
    raise exception 'INS_ENDORSEMENT_POSTING_RULE_MISSING: the chart of accounts needs ar_control, insurer_payable, unearned_commission and commission_income';
  end if;
  if p_clearing_gl_account_id is null or not exists (
    select 1 from gl_accounts
     where id = p_clearing_gl_account_id and tenant_id = v_tenant
  ) then
    raise exception 'INS_ENDORSEMENT_CLEARING: choose a clearing account from this tenant''s chart of accounts';
  end if;
  return jsonb_build_object(
    'ar', v_ar, 'payable', v_payable, 'unearned', v_unearned,
    'income', v_income, 'clearing', p_clearing_gl_account_id);
end $$;


--
-- Name: ins_endorsement_review_position(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_endorsement_review_position(p_policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p ins_policies%rowtype;
  v_gross numeric;
  v_commission numeric;
  v_sum_insured numeric;
  v_live jsonb;
  v_posted integer;
  v_cxl_live boolean;
  r record;
  c record;
begin
  if auth.uid() is null or not (can_access_insurance() or is_finance_team_member('finance')) then
    raise exception 'INS_FORBIDDEN' using errcode = '42501';
  end if;
  select * into p from ins_policies where id = p_policy_id and tenant_id = get_my_tenant_id();
  if not found then
    raise exception 'INS_NOT_FOUND: policy';
  end if;
  v_gross := p.gross_premium;
  v_commission := p.commission_amount;
  v_sum_insured := p.sum_insured;
  v_posted := 0;
  for r in
    select calculation
      from ins_policy_endorsements
     where policy_id = p.id and tenant_id = p.tenant_id and status = 'posted'
     order by posting_date nulls last, proposed_at
  loop
    v_posted := v_posted + 1;
    v_gross := v_gross + coalesce((r.calculation ->> 'premium_delta')::numeric, 0);
    v_commission := v_commission + coalesce((r.calculation ->> 'commission_delta')::numeric, 0);
    -- The latest posted change to sum_insured wins.
    if r.calculation -> 'changes' <> '[]'::jsonb then
      for c in select * from jsonb_array_elements(r.calculation -> 'changes') where value ->> 'field' = 'sum_insured' loop
        v_sum_insured := (c.value ->> 'after')::numeric;
      end loop;
    end if;
  end loop;
  select jsonb_agg(to_jsonb(x)) into v_live
    from ins_policy_endorsements x
   where x.policy_id = p.id and x.tenant_id = p.tenant_id and x.status in ('proposed','prepared');
  select exists (
    select 1 from ins_policy_cancellations
     where policy_id = p.id and tenant_id = p.tenant_id and status in ('proposed','prepared','posting','posted')
  ) into v_cxl_live;
  return jsonb_build_object(
    'policy_id', p.id, 'policy_no', p.policy_no, 'currency', p.currency,
    'bound_gross_premium', p.gross_premium,
    'bound_commission_amount', p.commission_amount,
    'current_gross_premium', v_gross,
    'current_commission_amount', v_commission,
    'current_sum_insured', v_sum_insured,
    'posted_endorsements', v_posted,
    'live_endorsements', coalesce(v_live, '[]'::jsonb),
    'cancellation_in_flight', v_cxl_live);
end $$;


--
-- Name: ins_ensure_client_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_ensure_client_account(p_ins_client_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_client ins_clients%rowtype;
  v_name   text;
  v_acc    uuid;
begin
  select * into v_client from ins_clients where id = p_ins_client_id for update;
  if v_client.party_account_id is not null then
    return v_client.party_account_id;
  end if;
  select name into v_name from bd_clients where id = v_client.client_id;
  insert into accounts (tenant_id, account_code, name, account_type, is_active)
  values (
    v_client.tenant_id,
    next_doc_number(v_client.tenant_id, 'INS_CLIENT_ACCOUNT', 'CLI', 5),
    v_name, 'client', true
  )
  returning id into v_acc;
  perform set_config('ins.via_rpc', 'on', true);
  update ins_clients set party_account_id = v_acc where id = v_client.id;
  return v_acc;
end;
$$;


--
-- Name: ins_ensure_insurer_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_ensure_insurer_account(p_insurer_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_ins ins_insurers%rowtype;
  v_acc uuid;
begin
  select * into v_ins from ins_insurers where id = p_insurer_id for update;
  if v_ins.party_account_id is not null then
    return v_ins.party_account_id;
  end if;
  insert into accounts (tenant_id, account_code, name, account_type, is_active)
  values (
    v_ins.tenant_id,
    next_doc_number(v_ins.tenant_id, 'INS_INSURER_ACCOUNT', 'INSA', 4),
    v_ins.name, 'vendor', true
  )
  returning id into v_acc;
  perform set_config('ins.via_rpc', 'on', true);
  update ins_insurers set party_account_id = v_acc where id = v_ins.id;
  return v_acc;
end;
$$;


--
-- Name: ins_finance_pending_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_finance_pending_approvals() RETURNS TABLE(item_type text, item_id uuid, policy_id uuid, policy_no text, client_name text, insurer_name text, currency text, kind text, amount numeric, submitted_at timestamp with time zone, submitted_by_name text, is_mine boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform ins_policy_cash_require_finance();
  return query
  with pending as (
    select 'premium_cash'::text as p_type, r.id as p_id, r.policy_id as p_policy, r.kind as p_kind, r.amount as p_amount,
           r.created_at as p_at, r.maker_id as p_by, (r.maker_id = auth.uid()) as p_mine
      from ins_policy_cash_requests r
     where r.tenant_id = get_my_tenant_id() and r.status = 'pending'
    union all
    select 'cancellation_cash'::text, c.id, pc.policy_id, c.kind, c.amount,
           c.created_at, c.maker_id, (c.maker_id = auth.uid())
      from ins_cancellation_cash_requests c
      join ins_policy_cancellations pc on pc.id = c.cancellation_id and pc.tenant_id = c.tenant_id
     where c.tenant_id = get_my_tenant_id() and c.status = 'pending'
    union all
    select 'cancellation'::text, x.id, x.policy_id, x.status, null::numeric,
           x.proposed_at, x.proposed_by, (x.proposed_by = auth.uid() or coalesce(x.prepared_by = auth.uid(), false))
      from ins_policy_cancellations x
     where x.tenant_id = get_my_tenant_id() and x.status in ('proposed', 'prepared')
  )
  select pe.p_type, pe.p_id, pe.p_policy, po.policy_no, bc.name, ii.name, po.currency,
         pe.p_kind, pe.p_amount, pe.p_at, coalesce(au.name, 'Unknown'), pe.p_mine
    from pending pe
    join ins_policies po on po.id = pe.p_policy and po.tenant_id = get_my_tenant_id()
    join ins_clients ic on ic.id = po.client_id and ic.tenant_id = po.tenant_id
    join bd_clients bc on bc.id = ic.client_id and bc.tenant_id = ic.tenant_id
    join ins_insurers ii on ii.id = po.insurer_id and ii.tenant_id = po.tenant_id
    left join app_users au on au.id = pe.p_by and au.tenant_id = get_my_tenant_id()
   order by pe.p_at, pe.p_id
   limit 200;
end $$;


--
-- Name: ins_financial_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_financial_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare pid uuid;
begin
 if tg_table_name='ins_policy_financial_snapshots' then
   if tg_op<>'INSERT' then raise exception 'INS_FINANCIAL_IMMUTABLE: bind snapshot cannot be changed or deleted'; end if;
   return new;
 end if;
 pid:=case when tg_op='DELETE' then old.policy_id else new.policy_id end;
 perform id from ins_policies where id=pid for update;
 if exists(select 1 from ins_policies where id=pid and status<>'draft') then
   raise exception 'INS_FINANCIAL_IMMUTABLE: insurer shares and charge lines are locked after bind';
 end if;
 if tg_op='UPDATE' and (new.policy_id is distinct from old.policy_id or new.tenant_id is distinct from old.tenant_id) then
   raise exception 'INS_FINANCIAL_IMMUTABLE: configuration cannot move between policies';
 end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: ins_insurer_commission_statement_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_insurer_commission_statement_data(p_insurer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare policies jsonb; ledger jsonb;
begin
 if not can_access_insurance() then raise exception 'INS_FORBIDDEN: Insurance access required' using errcode='42501'; end if;
 if not exists(select 1 from ins_insurers where id=p_insurer_id and tenant_id=get_my_tenant_id()) then raise exception 'INS_NOT_FOUND: insurer'; end if;
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('gross_premium',coalesce(s.premium_amount,p.gross_premium)-coalesce(adj.return_premium,0),
  'commission_rate_pct',coalesce(s.commission_rate_pct,p.commission_rate_pct),'commission_amount',coalesce(s.commission_amount,p.commission_amount)-coalesce(adj.commission_clawback,0),
  'net_premium_to_insurer',coalesce(s.payable_amount,p.net_premium_to_insurer)-coalesce(adj.total_insurer_credit,0),'insurer_id',p_insurer_id,
  'ins_clients',jsonb_build_object('bd_clients',jsonb_build_object('name',b.name)))),'[]'::jsonb) into policies
 from ins_policies p left join ins_policy_insurer_shares s on s.policy_id=p.id and s.insurer_id=p_insurer_id
  and exists(select 1 from ins_policy_financial_snapshots sn where sn.policy_id=p.id and sn.extended)
 left join ins_cancellation_insurer_adjustments adj on adj.insurer_id=p_insurer_id and adj.cancellation_id in(select cx.id from ins_policy_cancellations cx where cx.policy_id=p.id and cx.status='posted')
 join ins_clients c on c.id=p.client_id join bd_clients b on b.id=c.client_id
 where p.tenant_id=get_my_tenant_id() and p.status<>'draft' and (s.id is not null or
  (p.insurer_id=p_insurer_id and not exists(select 1 from ins_policy_financial_snapshots sn where sn.policy_id=p.id and sn.extended)));
 select coalesce(jsonb_agg(to_jsonb(l)),'[]'::jsonb) into ledger from ins_commission_ledger l where tenant_id=get_my_tenant_id() and insurer_id=p_insurer_id;
 return jsonb_build_object('policies',policies,'ledger',ledger);
end $$;


--
-- Name: ins_insurer_product_rates_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_insurer_product_rates_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.ins_via_rpc() then
    raise exception 'INS_RPC_ONLY: manage commission rates with ins_set_insurer_product_rate()' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'INS_RATE_STATUS: a new rate starts as a draft; approval is a separate step by a different person';
    end if;
    if new.approved_by is not null or new.approved_at is not null or new.withdrawn_reason is not null then
      raise exception 'INS_RATE_STATUS: approval and withdrawal fields cannot be set on a new draft';
    end if;
  else
    if new.tenant_id is distinct from old.tenant_id
       or new.insurer_id is distinct from old.insurer_id
       or new.product_line_id is distinct from old.product_line_id then
      raise exception 'INS_RATE_KEY_IMMUTABLE: a rate cannot move to another company, insurer or product line';
    end if;
    -- Immutable: company, insurer, product line, rate, window start, source and
    -- entrant. What RPCs may change on top: status and its stamps (approve,
    -- withdraw) and, for an approved rate, the window end (end-date).
    if (to_jsonb(new) - array['status', 'approved_by', 'approved_at', 'withdrawn_reason', 'effective_to', 'updated_at'])
       is distinct from (to_jsonb(old) - array['status', 'approved_by', 'approved_at', 'withdrawn_reason', 'effective_to', 'updated_at']) then
      raise exception 'INS_RATE_IMMUTABLE: a rate''s insurer, product line, rate, start date, source and entrant cannot be changed; enter a correcting rate';
    end if;
    if new.status is distinct from old.status and not public.ins_via_rpc() then
      raise exception 'INS_RATE_STATUS_VIA_RPC: change status with ins_approve_insurer_product_rate or ins_withdraw_insurer_product_rate';
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: ins_insurers_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_insurers_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.party_account_id is distinct from old.party_account_id and not public.ins_via_rpc() then
    raise exception 'INS_PARTY_ACCOUNT_RPC_ONLY: the party account is managed by binding a policy' using errcode = '42501';
  end if;
  if new.party_account_id is not null and not exists (
    select 1 from accounts a where a.id = new.party_account_id and a.tenant_id = new.tenant_id
  ) then
    raise exception 'INS_CROSS_TENANT: party account belongs to another tenant';
  end if;
  return new;
end;
$$;


--
-- Name: ins_intermediary_chain_has(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_intermediary_chain_has(p_tenant uuid, p_start uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recursive chain(id, parent_id, depth) as (
    select i.id, i.parent_id, 0 from ins_intermediaries i where i.tenant_id = p_tenant and i.id = p_start
    union all
    select p.id, p.parent_id, c.depth + 1
      from chain c join ins_intermediaries p on p.tenant_id = p_tenant and p.id = c.parent_id
     where c.depth < 100
  )
  select exists (select 1 from chain where id = p_target);
$$;


--
-- Name: ins_issue_certificate(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_issue_certificate(p_serial_no text, p_risk_id uuid, p_issued_to text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); c ins_certificate_stock%rowtype;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  select * into c from ins_certificate_stock where tenant_id = t and serial_no = btrim(p_serial_no) for update;
  if not found then raise exception 'INS_NOT_FOUND: certificate'; end if;
  if c.status <> 'in_stock' then raise exception 'INS_CERTIFICATE_STATE: certificate % is %, not in stock', c.serial_no, c.status; end if;
  if not exists (select 1 from ins_risks where id = p_risk_id and tenant_id = t and status = 'active' and risk_type = 'vehicle') then
    raise exception 'INS_CERTIFICATE_RISK: certificates are issued to an active vehicle risk';
  end if;
  update ins_certificate_stock
     set status = 'issued', risk_id = p_risk_id, issued_to = nullif(btrim(coalesce(p_issued_to, '')), ''), issued_at = now()
   where id = c.id;
  return c.id;
end $$;


--
-- Name: ins_item_paid_amount(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_item_paid_amount(p_open_item_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(al.amount), 0)
  from fin_allocations al
  join fin_settlements s on s.id = al.settlement_id
  where al.open_item_id = p_open_item_id and s.status = 'posted';
$$;


--
-- Name: ins_link_policy_risk(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_link_policy_risk(p_policy_id uuid, p_risk_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); p ins_policies%rowtype;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  select * into p from ins_policies where id = p_policy_id and tenant_id = t for update;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  if p.status <> 'draft' then raise exception 'INS_NOT_DRAFT: risks can only be linked to a draft policy'; end if;
  if not exists (select 1 from ins_risks r where r.id = p_risk_id and r.tenant_id = t and r.client_id = p.client_id and r.status = 'active') then
    raise exception 'INS_RISK_CLIENT: an active risk of this policy''s client is required';
  end if;
  insert into ins_policy_risks (tenant_id, policy_id, risk_id) values (t, p_policy_id, p_risk_id)
  on conflict (policy_id, risk_id) do nothing;
end $$;


--
-- Name: ins_load_certificate_range(text, bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_load_certificate_range(p_prefix text, p_from bigint, p_to bigint, p_width integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); n integer;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  if p_from is null or p_to is null or p_from < 0 or p_to < p_from then raise exception 'INS_INPUT: the range must start at 0 or more and end at or after its start'; end if;
  if p_to - p_from >= 5000 then raise exception 'INS_INPUT: load at most 5000 certificates at a time'; end if;
  if p_width is null or p_width < 1 or p_width > 20 then raise exception 'INS_INPUT: serial width must be 1 to 20'; end if;
  begin
    with gen as (
      select coalesce(btrim(p_prefix), '') || lpad(g::text, p_width, '0') as serial
      from generate_series(p_from, p_to) g
    )
    insert into ins_certificate_stock (tenant_id, serial_no)
    select t, serial from gen;
  exception when unique_violation then
    raise exception 'INS_DUPLICATE: some serials in this range are already in stock';
  end;
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: ins_notify(uuid, uuid[], uuid[], text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify(p_tenant uuid, p_recipients uuid[], p_exclude uuid[], p_type text, p_title text, p_body text, p_link text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into notifications (tenant_id, recipient_id, type, title, body, link_path)
  select p_tenant, u.id, p_type, p_title, p_body, p_link
  from app_users u
  where u.tenant_id = p_tenant
    and u.id = any (array_remove(coalesce(p_recipients, '{}'::uuid[]), null))
    and u.id <> all (array_remove(coalesce(p_exclude, '{}'::uuid[]), null));
exception when others then
  raise warning 'ins_notify % failed: % (%)', p_type, sqlerrm, sqlstate;
end;
$$;


--
-- Name: ins_notify_approval_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify_approval_case() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor     uuid := auth.uid();
  v_row       jsonb := to_jsonb(NEW);
  v_what      text;
  v_slug      text;
  v_no        text;
  v_policy_no text;
  v_link      text;
  v_people    uuid[];
begin
  if TG_TABLE_NAME = 'ins_policy_endorsements' then
    v_what := 'Endorsement'; v_slug := 'ins_endorsement';
    v_no := v_row ->> 'endorsement_no';
  else
    v_what := 'Cancellation'; v_slug := 'ins_cancellation';
    v_no := v_row ->> 'cancellation_no';
  end if;

  select p.policy_no into v_policy_no
  from ins_policies p
  where p.id = NEW.policy_id and p.tenant_id = NEW.tenant_id;
  v_policy_no := coalesce(v_policy_no, 'policy');
  v_link := '/insurance/policies/' || NEW.policy_id::text;
  v_people := array[NEW.proposed_by, NEW.prepared_by];

  if TG_OP = 'INSERT' then
    if NEW.status = 'proposed' then
      perform ins_notify(
        NEW.tenant_id, ins_notify_finance_users(NEW.tenant_id), array[v_actor, NEW.proposed_by],
        v_slug || '_proposed',
        v_what || ' proposed: ' || v_policy_no,
        format('A %s on policy %s, effective %s, is waiting for a Finance maker to prepare it.',
               lower(v_what), v_policy_no, NEW.effective_date),
        v_link);
    end if;
    return NEW;
  end if;

  if NEW.status is not distinct from OLD.status then
    return NEW;
  end if;

  if NEW.status = 'prepared' then
    perform ins_notify(
      NEW.tenant_id, ins_notify_finance_users(NEW.tenant_id),
      array[v_actor, NEW.proposed_by, NEW.prepared_by],
      v_slug || '_prepared',
      v_what || ' awaiting your check: ' || v_policy_no,
      format('A %s on policy %s was prepared and needs an independent Finance checker.',
             lower(v_what), v_policy_no),
      v_link);
  elsif NEW.status = 'posted' then
    perform ins_notify(
      NEW.tenant_id, v_people, array[v_actor],
      v_slug || '_posted',
      v_what || ' posted: ' || coalesce(v_no, v_policy_no),
      format('The %s on policy %s was approved and posted.', lower(v_what), v_policy_no),
      v_link);
  elsif NEW.status = 'rejected' then
    perform ins_notify(
      NEW.tenant_id, v_people, array[v_actor],
      v_slug || '_rejected',
      v_what || ' rejected: ' || v_policy_no,
      format('The %s on policy %s was rejected.%s', lower(v_what), v_policy_no,
             case when nullif(btrim(coalesce(NEW.review_note, '')), '') is not null
                  then ' Reviewer note: ' || left(btrim(NEW.review_note), 200) else '' end),
      v_link);
  end if;
  return NEW;
exception when others then
  raise warning 'ins_notify_approval_case failed: % (%)', sqlerrm, sqlstate;
  return NEW;
end;
$$;


--
-- Name: ins_notify_cancellation_cash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify_cancellation_cash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor     uuid := auth.uid();
  v_policy_id uuid;
  v_policy_no text;
  v_currency  text;
  v_link      text;
  v_summary   text;
begin
  select p.id, p.policy_no, p.currency into v_policy_id, v_policy_no, v_currency
  from ins_policy_cancellations c
  join ins_policies p on p.id = c.policy_id and p.tenant_id = c.tenant_id
  where c.id = NEW.cancellation_id and c.tenant_id = NEW.tenant_id;

  v_policy_no := coalesce(v_policy_no, 'policy');
  v_link := case when v_policy_id is null then null else '/insurance/policies/' || v_policy_id::text end;
  v_summary := format('%s of %s %s on policy %s',
                      replace(NEW.kind, '_', ' '), coalesce(v_currency, ''),
                      to_char(NEW.amount, 'FM999,999,999,990.00'), v_policy_no);

  if TG_OP = 'INSERT' then
    if NEW.status = 'pending' then
      perform ins_notify(
        NEW.tenant_id, ins_notify_finance_users(NEW.tenant_id), array[v_actor, NEW.maker_id],
        'ins_cancellation_cash_pending',
        'Cash request awaiting your check: ' || v_policy_no,
        'A cancellation cash request needs an independent Finance checker: ' || v_summary || '.',
        v_link);
    end if;
    return NEW;
  end if;

  if NEW.status is not distinct from OLD.status then
    return NEW;
  end if;

  if NEW.status in ('posted', 'rejected') then
    perform ins_notify(
      NEW.tenant_id, array[NEW.maker_id], array[v_actor],
      'ins_cancellation_cash_' || NEW.status,
      'Cash request ' || NEW.status || ': ' || v_policy_no,
      format('Your cancellation cash request (%s) was %s.', v_summary, NEW.status),
      v_link);
  end if;
  return NEW;
exception when others then
  raise warning 'ins_notify_cancellation_cash failed: % (%)', sqlerrm, sqlstate;
  return NEW;
end;
$$;


--
-- Name: ins_notify_claim_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify_claim_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor     uuid := auth.uid();
  v_policy_no text;
  v_link      text := '/insurance/claims/' || NEW.id::text;
begin
  select p.policy_no into v_policy_no
  from ins_policies p
  where p.id = NEW.policy_id and p.tenant_id = NEW.tenant_id;
  v_policy_no := coalesce(v_policy_no, 'policy');

  if TG_OP = 'INSERT' then
    perform ins_notify(
      NEW.tenant_id, ins_notify_insurance_users(NEW.tenant_id, array['admin', 'manager']),
      array[v_actor, NEW.assigned_to],
      'ins_claim_registered',
      'New claim ' || NEW.claim_no,
      format('Claim %s on policy %s (loss date %s) was registered.', NEW.claim_no, v_policy_no, NEW.loss_date),
      v_link);
    if NEW.assigned_to is not null then
      perform ins_notify(
        NEW.tenant_id, array[NEW.assigned_to], array[v_actor],
        'ins_claim_assigned',
        'Claim assigned to you: ' || NEW.claim_no,
        format('Claim %s on policy %s was assigned to you.', NEW.claim_no, v_policy_no),
        v_link);
    end if;
    return NEW;
  end if;

  if NEW.assigned_to is not null and NEW.assigned_to is distinct from OLD.assigned_to then
    perform ins_notify(
      NEW.tenant_id, array[NEW.assigned_to], array[v_actor],
      'ins_claim_assigned',
      'Claim assigned to you: ' || NEW.claim_no,
      format('Claim %s on policy %s was assigned to you.', NEW.claim_no, v_policy_no),
      v_link);
  end if;

  if NEW.status is distinct from OLD.status and NEW.status in ('approved', 'repudiated', 'settled') then
    perform ins_notify(
      NEW.tenant_id, array[NEW.assigned_to, NEW.created_by], array[v_actor],
      'ins_claim_' || NEW.status,
      'Claim ' || NEW.status || ': ' || NEW.claim_no,
      format('Claim %s on policy %s is now %s.', NEW.claim_no, v_policy_no, NEW.status),
      v_link);
  end if;
  return NEW;
exception when others then
  raise warning 'ins_notify_claim_change failed: % (%)', sqlerrm, sqlstate;
  return NEW;
end;
$$;


--
-- Name: ins_notify_finance_users(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify_finance_users(p_tenant uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct f.user_id), '{}'::uuid[])
  from finance_team_members f
  where f.tenant_id = p_tenant
    and f.role = 'finance';
$$;


--
-- Name: ins_notify_insurance_users(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_notify_insurance_users(p_tenant uuid, p_roles text[]) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct sr.user_id), '{}'::uuid[])
  from staff_roles sr
  where sr.tenant_id = p_tenant
    and sr.module = 'insurance'
    and sr.role = any (p_roles);
$$;


--
-- Name: ins_policies_active_refs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policies_active_refs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if new.insurer_id is distinct from old.insurer_id
     and not exists (select 1 from ins_insurers i
                     where i.id = new.insurer_id and i.tenant_id = new.tenant_id and i.is_active) then
    raise exception 'INS_NOT_FOUND: active insurer' using errcode = '23514';
  end if;
  if new.product_line_id is distinct from old.product_line_id
     and not exists (select 1 from ins_product_lines p
                     where p.id = new.product_line_id and p.tenant_id = new.tenant_id and p.is_active) then
    raise exception 'INS_NOT_FOUND: active product line' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: ins_policies_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policies_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    if not public.ins_via_rpc() then
      raise exception 'INS_RPC_ONLY: create policies with ins_create_policy()' using errcode = '42501';
    end if;
  else
    if new.status is distinct from old.status and not public.ins_via_rpc() then
      raise exception 'INS_STATUS_RPC_ONLY: policy status changes go through ins_bind_policy()' using errcode = '42501';
    end if;
    if old.status <> 'draft' and (
      to_jsonb(old) - array['status', 'notes', 'updated_at']
    ) is distinct from (
      to_jsonb(new) - array['status', 'notes', 'updated_at']
    ) then
      raise exception 'INS_POLICY_LOCKED: a % policy cannot be edited', old.status;
    end if;
    if old.status <> 'draft' and new.status = 'draft' then
      raise exception 'INS_STATUS_INVALID: a bound policy cannot return to draft';
    end if;

    -- Draft-only rules (a non-draft policy was handled by the lock above).
    if not public.ins_via_rpc() then
      if new.renewal_of_id is distinct from old.renewal_of_id then
        raise exception 'INS_RENEWAL_LINK_RPC_ONLY: the renewal link is set by ins_create_renewal_draft()' using errcode = '42501';
      end if;
      if new.commission_amount      is distinct from old.commission_amount
         or new.net_premium_to_insurer is distinct from old.net_premium_to_insurer
         or new.bound_at            is distinct from old.bound_at
         or new.bound_by            is distinct from old.bound_by
         or new.journal_entry_id    is distinct from old.journal_entry_id then
        raise exception 'INS_BIND_FIELDS_RPC_ONLY: commission, net premium and the bind stamps are set by ins_bind_policy()' using errcode = '42501';
      end if;
    end if;
  end if;

  if not exists (select 1 from ins_clients c where c.id = new.client_id and c.tenant_id = new.tenant_id) then
    raise exception 'INS_CROSS_TENANT: client belongs to another tenant';
  end if;
  if not exists (select 1 from ins_insurers i where i.id = new.insurer_id and i.tenant_id = new.tenant_id) then
    raise exception 'INS_CROSS_TENANT: insurer belongs to another tenant';
  end if;
  if not exists (select 1 from ins_product_lines p where p.id = new.product_line_id and p.tenant_id = new.tenant_id) then
    raise exception 'INS_CROSS_TENANT: product line belongs to another tenant';
  end if;
  if new.agent_id is not null and not exists (
    select 1 from ins_intermediaries a where a.id = new.agent_id and a.tenant_id = new.tenant_id
  ) then
    raise exception 'INS_CROSS_TENANT: agent belongs to another tenant';
  end if;
  if new.branch_id is not null and not exists (
    select 1 from organizations o where o.id = new.branch_id and o.tenant_id = new.tenant_id
  ) then
    raise exception 'INS_CROSS_TENANT: branch belongs to another tenant';
  end if;
  -- Activity only matters when the reference is being moved: a draft keeps an agent or branch
  -- that was suspended after it was chosen, the same rule as the insurer and product line.
  if tg_op = 'UPDATE' then
    if new.agent_id is distinct from old.agent_id and new.agent_id is not null and not exists (
      select 1 from ins_intermediaries a
      where a.id = new.agent_id and a.tenant_id = new.tenant_id and a.status = 'active'
    ) then
      raise exception 'INS_NOT_ACTIVE: agent must be an active intermediary';
    end if;
    if new.branch_id is distinct from old.branch_id and new.branch_id is not null and not exists (
      select 1 from organizations o
      where o.id = new.branch_id and o.tenant_id = new.tenant_id and o.is_active
    ) then
      raise exception 'INS_NOT_ACTIVE: branch must be an active organisation';
    end if;
  end if;
  return new;
end $$;


--
-- Name: ins_policies_link_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policies_link_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ins_policy_risks r where r.tenant_id = new.tenant_id and r.policy_id = new.id) then
    return new;
  end if;
  if new.client_id is distinct from old.client_id then
    raise exception 'INS_POLICY_LINKED: risks are linked to this policy, so its client cannot change. Unlink the risks first.'
      using errcode = '23514';
  end if;
  if new.product_line_id is distinct from old.product_line_id then
    raise exception 'INS_POLICY_LINKED: risks are linked to this policy, so its product line cannot change. Unlink the risks first.'
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: ins_policy_cancellation_context(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cancellation_context(p_policy_id uuid, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; sn ins_policy_financial_snapshots%rowtype; shares jsonb; charge jsonb; charges jsonb:='[]'; parts jsonb; cases jsonb; accounts jsonb:='[]';
begin
 if auth.uid() is null or not(can_access_insurance() or is_finance_team_member('finance')) then raise exception 'INS_FORBIDDEN: Insurance or Finance required' using errcode='42501'; end if;
 if p_offset is null or p_offset<0 then raise exception 'INS_REPORT_PAGE: invalid offset'; end if;
 select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 select * into sn from ins_policy_financial_snapshots where policy_id=p.id;
 shares:=sn.snapshot->'shares';
 if shares is null or shares='[]'::jsonb then shares:=jsonb_build_array(jsonb_build_object('insurer_id',p.insurer_id,'premium_amount',p.gross_premium,'commission_amount',p.commission_amount,'commission_rate_pct',p.commission_rate_pct,'share_pct',100)); end if;
 select jsonb_agg(x||jsonb_build_object('premium_amount',x->>'premium_amount','commission_amount',x->>'commission_amount','commission_rate_pct',x->>'commission_rate_pct','insurer_name',i.name)) into shares
 from jsonb_array_elements(shares) x join ins_insurers i on i.id=(x->>'insurer_id')::uuid and i.tenant_id=p.tenant_id;
 for charge in select value from jsonb_array_elements(coalesce(sn.snapshot->'charges','[]')) loop
  parts:='[]';
  if charge->>'kind'='insurer_pass_through' then
   if charge->>'recipient_mode'='one_insurer' then parts:=jsonb_build_array(jsonb_build_object('insurer_id',charge->>'recipient_insurer_id','amount',charge->>'amount'));
   else
    with bases as(select x->>'insurer_id' as insurer_id,trunc((charge->>'amount')::numeric*(x->>'share_pct')::numeric/100,2) as base,
     (charge->>'amount')::numeric*(x->>'share_pct')::numeric/100-trunc((charge->>'amount')::numeric*(x->>'share_pct')::numeric/100,2) as fraction from jsonb_array_elements(shares) x),
    ranked as(select *,row_number() over(order by fraction desc,insurer_id collate "C") as rank,round(((charge->>'amount')::numeric-sum(base) over())*100) as cents from bases)
    select jsonb_agg(jsonb_build_object('insurer_id',insurer_id,'amount',(base+case when rank<=cents then .01 else 0 end)::text)) into parts from ranked;
   end if;
   select jsonb_agg(x||jsonb_build_object('insurer_name',i.name)) into parts from jsonb_array_elements(parts) x join ins_insurers i on i.id=(x->>'insurer_id')::uuid and i.tenant_id=p.tenant_id;
  end if;
  charges:=charges||jsonb_build_array(charge||jsonb_build_object('amount',charge->>'amount','vat_amount',coalesce(charge->>'vat_amount','0'),'original_allocations',parts));
 end loop;
 select coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object(
  'insurer_adjustments',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('insurer_name',i.name,'payable_credit',a.payable_credit::text,'recovery_due',a.recovery_due::text,'retained_commission',a.retained_commission::text,'transferred_clawback_due',a.transferred_clawback_due::text)) from ins_cancellation_insurer_adjustments a join ins_insurers i on i.id=a.insurer_id where a.cancellation_id=q.id),'[]'::jsonb),
  'credits',coalesce((select jsonb_agg(to_jsonb(l)||jsonb_build_object('credit_note_no',n.credit_note_no,'amount',l.amount::text,'journal_entry_id',n.journal_entry_id)) from ins_cancellation_credit_links l join fin_credit_notes n on n.id=l.credit_note_id where l.cancellation_id=q.id),'[]'::jsonb),
  'journals',coalesce((select jsonb_agg(to_jsonb(j)) from ins_cancellation_journals j where j.cancellation_id=q.id),'[]'::jsonb)) order by q.proposed_at desc,q.id),'[]'::jsonb) into cases
 from(select * from ins_policy_cancellations where policy_id=p.id order by proposed_at desc,id limit 20 offset p_offset) q;
 if is_finance_team_member('finance') and effective_user_id()=auth.uid() then
  select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'account_code',g.account_code) order by g.account_code),'[]'::jsonb) into accounts from gl_accounts g
   where g.tenant_id=p.tenant_id and g.is_active and g.account_type='asset' and not g.is_control_account
    and not exists(select 1 from gl_posting_rules r where r.tenant_id=p.tenant_id and r.gl_account_id=g.id)
    and not exists(select 1 from fin_bank_accounts b where b.tenant_id=p.tenant_id and b.gl_account_id=g.id);
 end if;
 return jsonb_build_object('policy_id',p.id,'policy_no',p.policy_no,'policy_status',p.status,'currency',p.currency,'inception_date',p.inception_date,'expiry_date',p.expiry_date,
  'actor_id',auth.uid(),'can_propose',effective_user_id()=auth.uid() and (can_manage_insurance() or is_finance_team_member('finance')),
  'can_finance',effective_user_id()=auth.uid() and is_finance_team_member('finance'),'has_live_case',exists(select 1 from ins_policy_cancellations where policy_id=p.id and status in('proposed','prepared','posted')),'has_claims',exists(select 1 from ins_claims where policy_id=p.id),
  'insurers',shares,'charges',charges,'cases',cases,'offset',p_offset,'has_more',(select count(*)>p_offset+20 from ins_policy_cancellations where policy_id=p.id),'clearing_accounts',accounts);
end $$;


--
-- Name: ins_policy_cash_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare m record; s fin_settlements%rowtype; q ins_policy_cash_requests%rowtype;
begin
 if platform_ins_cancellation_cash_authorized(new.open_item_id,new.settlement_id,new.amount) then return new; end if;
 select * into m from ins_policy_cash_items where id=new.open_item_id and tenant_id=new.tenant_id;
 if m.source_type not in('ins_policy_premium','ins_policy_insurer') then return new; end if;
 perform ins_policy_cash_require_finance();
 select * into s from fin_settlements where id=new.settlement_id and tenant_id=new.tenant_id;
 select * into q from ins_policy_cash_requests where tenant_id=new.tenant_id and policy_id=m.source_id
  and insurer_share_id is not distinct from m.insurer_share_id
  and status='posting' and operation_txid=txid_current() and checker_id=auth.uid() and maker_id<>auth.uid()
  and bank_account_id=s.bank_account_id and amount=new.amount and amount=s.amount and cash_date=s.settlement_date
  and kind=case m.source_type when 'ins_policy_premium' then 'receipt' else 'remittance' end
  and(settlement_id is null or settlement_id=s.id) for update;
 if q.id is null or s.direction<>(case q.kind when 'receipt' then 'in' else 'out' end)
  or s.party_account_id<>m.party_account_id or exists(select 1 from fin_allocations where settlement_id=s.id) then
   raise exception 'INS_CASH_APPROVAL_REQUIRED: independent Finance approval required for this insurer payable';
 end if;
 perform ins_policy_cash_validate(q.policy_id,q.kind,q.bank_account_id,q.amount,q.cash_date,q.insurer_share_id);
 update ins_policy_cash_requests set settlement_id=s.id where id=q.id;
 return new;
end $$;


--
-- Name: fin_bank_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fin_bank_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    kind text DEFAULT 'operating'::text NOT NULL,
    currency text NOT NULL,
    gl_account_id uuid,
    bank_name text,
    account_number text,
    is_active boolean DEFAULT true NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fin_bank_accounts_client_money_gl_check CHECK (((kind = 'operating'::text) OR (gl_account_id IS NOT NULL))),
    CONSTRAINT fin_bank_accounts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT fin_bank_accounts_kind_check CHECK ((kind = ANY (ARRAY['operating'::text, 'client_money'::text]))),
    CONSTRAINT fin_bank_accounts_name_check CHECK (((name <> ''::text) AND (name = btrim(name))))
);


--
-- Name: ins_policy_cash_bank_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_bank_accounts() RETURNS SETOF public.fin_bank_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform ins_policy_cash_require_finance();
  return query select b.* from fin_bank_accounts b where b.tenant_id=get_my_tenant_id()
    and b.kind='client_money' and b.is_active and b.gl_account_id is not null
    and b.currency=fin_ledger_currency(b.tenant_id) order by b.name;
end $$;


--
-- Name: ins_policy_cash_commission_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_commission_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
 if new.status='transferred' and old.status<>'transferred' then
  perform id from ins_policies where id=new.policy_id and tenant_id=new.tenant_id for update;
  v:=case when new.insurer_share_id is null then ins_policy_cash_totals(new.policy_id) else ins_share_cash_totals(new.insurer_share_id) end;
  if (v->>'available_allocated_funds')::numeric<new.amount then raise exception 'INS_CASH_COMMISSION_UNFUNDED: this insurer share has insufficient collected commission funds'; end if;
 end if;
 return new;
end $$;


--
-- Name: ins_policy_cash_policies(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_policies(p_search text DEFAULT ''::text, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, policy_no text, status text, currency text, client_name text, insurer_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform ins_policy_cash_require_finance();
  if p_offset is null or p_offset<0 then raise exception 'INS_CASH_INPUT: invalid page'; end if;
  return query select p.id,p.policy_no,p.status,p.currency,c.name,i.name
    from ins_policies p join ins_clients ic on ic.id=p.client_id and ic.tenant_id=p.tenant_id
    join bd_clients c on c.id=ic.client_id and c.tenant_id=ic.tenant_id
    join ins_insurers i on i.id=p.insurer_id and i.tenant_id=p.tenant_id
    where p.tenant_id=get_my_tenant_id() and p.status<>'draft'
      and (p.policy_no ilike '%'||coalesce(p_search,'')||'%' or c.name ilike '%'||coalesce(p_search,'')||'%'
           or i.name ilike '%'||coalesce(p_search,'')||'%'
           or exists(select 1 from ins_policy_insurer_shares sh join ins_insurers co on co.id=sh.insurer_id and co.tenant_id=sh.tenant_id
              where sh.policy_id=p.id and co.name ilike '%'||coalesce(p_search,'')||'%'))
    order by p.created_at desc,p.id limit 50 offset p_offset;
end $$;


--
-- Name: ins_policy_cash_position(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_position(p_policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
 v:=platform_ins_cash_position_before_cancellation(p_policy_id);
 if v->>'policy_status'='cancelled' then
  if jsonb_typeof(v->'shares')='array' then v:=jsonb_set(v,'{shares}',coalesce((select jsonb_agg(x||jsonb_build_object('maximum_remittance',0)) from jsonb_array_elements(v->'shares') x),'[]'::jsonb)); end if;
  v:=v||jsonb_build_object('can_prepare',false,'maximum_remittance',0,'cash_notice','Policy cancelled. Use the cancellation-specific recovery/refund workflow; cancellation approval did not authorize cash.'); end if;
 return v;
end $$;


--
-- Name: ins_policy_cash_reconciliation_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_reconciliation_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sid uuid; snapshot jsonb;
begin
  sid := case when tg_op='DELETE' then old.settlement_id else new.settlement_id end;
  if sid is null then return null; end if;
  snapshot := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  insert into ins_policy_cash_reconciliation_events(tenant_id,policy_id,settlement_id,event,actor_id,reconciliation_snapshot)
    select distinct i.tenant_id,i.source_id,sid,case tg_op when 'DELETE' then 'unmatched' else 'matched' end,auth.uid(),snapshot
    from fin_allocations a join ins_policy_cash_items i on i.id=a.open_item_id and i.tenant_id=a.tenant_id
    where a.settlement_id=sid and i.source_type in ('ins_policy_premium','ins_policy_insurer');
  return null;
end $$;


--
-- Name: ins_policy_cash_reconciliation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_reconciliation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sid uuid; s fin_settlements%rowtype; q ins_policy_cash_requests%rowtype;
begin
  if tg_op='UPDATE' and exists(select 1 from fin_allocations a join ins_policy_cash_items i on i.id=a.open_item_id
    where a.settlement_id in (old.settlement_id,new.settlement_id)
      and i.source_type in ('ins_policy_premium','ins_policy_insurer')) then
    raise exception 'INS_CASH_RECONCILIATION: policy matches are immutable; unmatch and rematch';
  end if;
  sid := case when tg_op='DELETE' then old.settlement_id else new.settlement_id end;
  if sid is null or not exists(select 1 from fin_allocations a join ins_policy_cash_items i on i.id=a.open_item_id
    where a.settlement_id=sid and i.source_type in ('ins_policy_premium','ins_policy_insurer')) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  perform ins_policy_cash_require_finance();
  select * into s from fin_settlements where id=sid and tenant_id=get_my_tenant_id() for update;
  if not found or s.status<>'posted' then raise exception 'INS_CASH_RECONCILIATION: posted settlement in this company required'; end if;
  select * into q from ins_policy_cash_requests where settlement_id=s.id and tenant_id=s.tenant_id;
  if auth.uid()=s.created_by or auth.uid()=q.maker_id or auth.uid()=q.checker_id then
    raise exception 'INS_CASH_THIRD_PERSON: reconciliation requires a third Finance user, not the maker, checker or poster' using errcode='42501';
  end if;
  if tg_op<>'DELETE' then
    if new.tenant_id<>s.tenant_id or new.matched_by is distinct from auth.uid() then
      raise exception 'INS_CASH_RECONCILIATION: the reconciler must be the acting Finance user';
    end if;
    return new;
  end if;
  return old;
end $$;


--
-- Name: ins_policy_cash_require_finance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_require_finance() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or effective_user_id() is distinct from auth.uid()
     or not is_finance_team_member('finance') then
    raise exception 'INS_CASH_FORBIDDEN: an authorized Finance user, acting as themselves, is required' using errcode='42501';
  end if;
end $$;


--
-- Name: ins_policy_cash_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_totals(p_policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare sn ins_policy_financial_snapshots%rowtype; v jsonb; sh jsonb; shares jsonb:='[]'; c numeric; due numeric;
 remitted numeric:=0; withdrawn numeric:=0; available numeric:=0; liability numeric:=0; cap numeric:=0;
 endo_c numeric:=0; endo_client numeric:=0; endo_insurer numeric:=0;
begin
 -- Endorsement money rides endorsement-scoped items, not the policy's: the
 -- client's payments against an endorsement item fund remittances all the
 -- same, and an endorsement's receivables and payables are the policy's
 -- outstanding on both sides. (Endorsement payables are settled by generic
 -- settlements, so they display here but are not remittance-capped.)
 select coalesce(sum(a.amount),0) into endo_c
  from ins_policy_endorsements x
  join fin_open_items i on i.source_id=x.id and i.tenant_id=x.tenant_id and i.source_type='ins_policy_endorsement'
  join fin_allocations a on a.open_item_id=i.id and a.tenant_id=i.tenant_id
  join fin_settlements f on f.id=a.settlement_id and f.status='posted' and f.direction='in'
  where x.policy_id=p_policy_id;
 select coalesce(sum(b.outstanding_amount) filter (where b.side='receivable'),0),
        coalesce(sum(b.outstanding_amount) filter (where b.side='payable'),0)
  into endo_client, endo_insurer
  from ins_policy_endorsements x
  join fin_open_item_balances b on b.source_id=x.id and b.tenant_id=x.tenant_id
   and b.source_type in ('ins_policy_endorsement','ins_policy_endorsement_insurer')
  where x.policy_id=p_policy_id;
 select * into sn from ins_policy_financial_snapshots where policy_id=p_policy_id;
 if sn.policy_id is null or not sn.extended then
  v := platform_ins_policy_cash_legacy_totals(p_policy_id);
  v := jsonb_set(v, '{collected}', to_jsonb((v->>'collected')::numeric + endo_c));
  v := jsonb_set(v, '{available_allocated_funds}', to_jsonb(greatest((v->>'available_allocated_funds')::numeric + endo_c, 0)));
  v := jsonb_set(v, '{client_outstanding}', to_jsonb(greatest((v->>'client_outstanding')::numeric + endo_client, 0)));
  v := jsonb_set(v, '{insurer_outstanding}', to_jsonb(greatest((v->>'insurer_outstanding')::numeric + endo_insurer, 0)));
  return v;
 end if;
 select coalesce(sum(a.amount),0) into c from fin_open_items i join fin_allocations a on a.open_item_id=i.id
  join fin_settlements f on f.id=a.settlement_id and f.status='posted' and f.direction='in'
  where i.source_id=p_policy_id and i.source_type='ins_policy_premium';
 select outstanding_amount into due from fin_open_item_balances where source_id=p_policy_id and source_type='ins_policy_premium';
 for sh in select ins_share_cash_totals(s.id)||jsonb_build_object('insurer_name',i.name,'is_lead',s.is_lead) from ins_policy_insurer_shares s
  join ins_insurers i on i.id=s.insurer_id where s.policy_id=p_policy_id order by s.insurer_id
 loop
  shares:=shares||jsonb_build_array(sh); remitted:=remitted+(sh->>'remitted')::numeric;
  withdrawn:=withdrawn+(sh->>'commission_transferred')::numeric; available:=available+(sh->>'available_allocated_funds')::numeric;
  liability:=liability+(sh->>'outstanding')::numeric; cap:=cap+(sh->>'maximum_remittance')::numeric;
 end loop;
 return jsonb_build_object('collected',c+endo_c,'remitted',remitted,'commission_transferred',withdrawn,
  'available_allocated_funds',available+endo_c,
  'insurer_outstanding',liability+endo_insurer,'client_outstanding',coalesce(due,0)+endo_client,
  'maximum_remittance',cap,'shares',shares,
  'invoice_total',sn.invoice_total,'broker_fee_collected',trunc(sn.broker_fee_total*least((c+endo_c)/sn.invoice_total,1),2),
  'vat_collected',trunc(sn.vat_total*least((c+endo_c)/sn.invoice_total,1),2));
end $$;


--
-- Name: ins_policy_cash_validate(uuid, text, uuid, numeric, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_validate(p_policy_id uuid, p_kind text, p_bank_id uuid, p_amount numeric, p_date date, p_share_id uuid DEFAULT NULL::uuid) RETURNS public.fin_open_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; b fin_bank_accounts%rowtype; i fin_open_items%rowtype; v jsonb;
begin
 perform ins_policy_cash_require_finance();
 if p_kind is distinct from 'remittance' or not exists(select 1 from ins_policy_financial_snapshots where policy_id=p_policy_id and extended) then
   if p_share_id is not null then raise exception 'INS_SHARE_INPUT: share selection applies only to co-insurance/charge remittances'; end if;
   return platform_ins_policy_cash_legacy_validate(p_policy_id,p_kind,p_bank_id,p_amount,p_date);
 end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or p_amount>9999999999999999.99 then raise exception 'INS_CASH_INPUT: invalid amount'; end if;
 if p_date is null or p_date>current_date then raise exception 'INS_CASH_DATE: invalid cash date'; end if;
 select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 if p.status not in('active','renewed') then raise exception 'INS_CASH_STATE: bound, non-reversed policy required'; end if;
 perform f.id from fin_open_items f join ins_policy_cash_items m on m.id=f.id where m.source_id=p.id and f.tenant_id=p.tenant_id
  and m.source_type in('ins_policy_premium','ins_policy_insurer') order by f.id for update of f;
 select * into b from fin_bank_accounts where id=p_bank_id and tenant_id=p.tenant_id for share;
 if not found or b.kind<>'client_money' or not b.is_active or b.gl_account_id is null or b.currency<>p.currency then raise exception 'INS_CASH_BANK: active mapped client-money bank required'; end if;
 if not exists(select 1 from ins_policy_insurer_shares where id=p_share_id and policy_id=p.id and tenant_id=p.tenant_id) then raise exception 'INS_SHARE_INPUT: select a participating insurer'; end if;
 select * into i from fin_open_items where source_id=p_share_id and source_type='ins_policy_share_insurer' and tenant_id=p.tenant_id;
 if not found then raise exception 'INS_CASH_ITEM: insurer payable missing'; end if;
 v:=ins_share_cash_totals(p_share_id);
 if p_amount>(v->>'maximum_remittance')::numeric then raise exception 'INS_CASH_CAP: remittance exceeds this insurer share pro-rata funding or outstanding payable'; end if;
 return i;
end $$;


--
-- Name: ins_policy_cash_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_cash_void_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare x record; v jsonb;
begin
 if platform_ins_cancellation_cash_void_authorized(old.id) then return new; end if;
  if old.status<>'posted' or new.status<>'void' then return new; end if;
  for x in select i.source_id as policy_id,sum(a.amount) as removed
    from fin_allocations a join ins_policy_cash_items i on i.id=a.open_item_id and i.tenant_id=a.tenant_id
    where a.settlement_id=old.id and i.source_type='ins_policy_premium'
    group by i.source_id order by i.source_id
  loop
    perform id from ins_policies where id=x.policy_id and tenant_id=old.tenant_id for update;
    v := ins_policy_cash_totals(x.policy_id);
    if (v->>'collected')::numeric-x.removed < (v->>'remitted')::numeric+(v->>'commission_transferred')::numeric then
      raise exception 'INS_CASH_FUNDS_IN_USE: reverse the funded remittances/commission transfers before voiding this receipt';
    end if;
    if exists(select 1 from ins_policy_insurer_shares sh join ins_policy_financial_snapshots sn on sn.policy_id=sh.policy_id and sn.extended
      where sh.policy_id=x.policy_id and trunc((sh.premium_amount+sh.pass_through_amount)*least(greatest((v->>'collected')::numeric-x.removed,0)/sn.invoice_total,1),2)
        < (ins_share_cash_totals(sh.id)->>'remitted')::numeric+(ins_share_cash_totals(sh.id)->>'commission_transferred')::numeric) then
      raise exception 'INS_CASH_FUNDS_IN_USE: receipt reduction would underfund an individual insurer share';
    end if;

  end loop;
  -- Outgoing voids also serialize with concurrent approvals and receipt voids.
  perform p.id from ins_policies p join ins_policy_cash_items i on i.source_id=p.id and i.tenant_id=p.tenant_id
    join fin_allocations a on a.open_item_id=i.id and a.tenant_id=i.tenant_id
    where a.settlement_id=old.id and i.source_type='ins_policy_insurer' order by p.id for update of p;
  return new;
end $$;


--
-- Name: ins_policy_charge_income_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_charge_income_accounts() RETURNS TABLE(id uuid, account_code text, name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode='42501'; end if;
 return query select g.id,g.account_code,g.name from gl_accounts g where tenant_id=get_my_tenant_id() and account_type='revenue' and is_active order by g.account_code;
end $$;


--
-- Name: ins_policy_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_child_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; target uuid;
begin
  target:=case when tg_table_name='ins_claims' then (to_jsonb(new)->>'policy_id')::uuid
               else (to_jsonb(new)->>'renewal_of_id')::uuid end;
  if target is null then return new; end if;
  select * into p from ins_policies where id=target and tenant_id=new.tenant_id for update;
  if not found or p.status not in ('active','renewed') then
    raise exception 'INS_POLICY_UNAVAILABLE: claims and renewals require an unreversed bound policy';
  end if;
  return new;
end $$;


--
-- Name: ins_policy_financial_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_financial_details(p_policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; v jsonb;
begin
 if not(can_access_insurance() or is_finance_team_member('finance')) or auth.uid() is null then raise exception 'INS_FORBIDDEN: Insurance or Finance access required' using errcode='42501'; end if;
 select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 select jsonb_build_object('policy_id',p.id,'policy_no',p.policy_no,'status',p.status,'currency',p.currency,'gross_premium',p.gross_premium,
  'shares',coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('insurer_name',i.name) order by s.insurer_id) from ins_policy_insurer_shares s join ins_insurers i on i.id=s.insurer_id where s.policy_id=p.id),'[]'::jsonb),
  'charges',coalesce((select jsonb_agg(to_jsonb(c) order by c.id) from ins_policy_charges c where c.policy_id=p.id),'[]'::jsonb),
  'snapshot',(select to_jsonb(sn) from ins_policy_financial_snapshots sn where sn.policy_id=p.id),
  'can_configure',can_manage_insurance() and effective_user_id()=auth.uid(),
  'client_name',(select b.name from ins_clients c join bd_clients b on b.id=c.client_id where c.id=p.client_id)) into v;
 return v;
end $$;


--
-- Name: ins_policy_reversal_context(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_reversal_context(p_policy_id uuid, p_in_progress boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if not can_manage_insurance() or not exists(select 1 from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id()) then
   raise exception 'INS_FORBIDDEN: policy access required' using errcode='42501';
 end if;
 perform id from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
 if (select count(*) from ins_policy_insurer_shares where policy_id=p_policy_id)>1 or exists(select 1 from ins_policy_charges where policy_id=p_policy_id) then
   raise exception 'INS_REVERSAL_COMPLEX: co-insurance or ANY charge line (including zero) requires the future cancellation workflow';
 end if;
 return platform_ins_policy_reversal_legacy_context(p_policy_id,p_in_progress);
end $$;


--
-- Name: ins_policy_reversal_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_policy_reversal_eligibility(p_policy_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform ins_policy_reversal_context(p_policy_id);
  return jsonb_build_object('eligible',true,'reason',null);
exception when others then
  if sqlerrm like 'INS_REVERSAL_%' then return jsonb_build_object('eligible',false,'reason',sqlerrm); end if;
  raise;
end $$;


--
-- Name: ins_prepare_policy_cancellation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_prepare_policy_cancellation(p_cancellation_id uuid, p_clearing_gl_account_id uuid) RETURNS public.ins_policy_cancellations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c ins_policy_cancellations%rowtype; pid uuid; quote jsonb; mappings jsonb;
begin
 perform ins_policy_cash_require_finance();
 select policy_id into pid from ins_policy_cancellations where id=p_cancellation_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: cancellation'; end if;
 perform id from ins_policies where id=pid for update;
 select * into c from ins_policy_cancellations where id=p_cancellation_id for update;
 if c.status not in('proposed','prepared') or (c.status='prepared' and c.prepared_by<>auth.uid()) then raise exception 'INS_CANCELLATION_STATE: proposal or own prepared case required'; end if;
 quote:=ins_preview_policy_cancellation(c.policy_id,c.effective_date,c.insurer_terms,c.charge_refunds)||platform_ins_cancellation_review_position(c.policy_id);
 mappings:=platform_ins_cancellation_mappings(c.policy_id,p_clearing_gl_account_id);
 update ins_policy_cancellations set status='prepared',prepared_by=auth.uid(),prepared_at=now(),calculation=quote,clearing_gl_account_id=p_clearing_gl_account_id,accounting_mappings=mappings
 where id=c.id returning * into c;
 insert into ins_cancellation_events(tenant_id,cancellation_id,event,actor_id,detail) values(c.tenant_id,c.id,'finance_prepared',auth.uid(),jsonb_build_object('calculation',quote,'mappings',mappings));
 return c;
end $$;


--
-- Name: ins_prepare_policy_endorsement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_prepare_policy_endorsement(p_endorsement_id uuid, p_clearing_gl_account_id uuid) RETURNS public.ins_policy_endorsements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c ins_policy_endorsements%rowtype;
  pid uuid;
  quote jsonb;
  mappings jsonb;
begin
  perform ins_policy_cash_require_finance();
  select policy_id into pid from ins_policy_endorsements
   where id = p_endorsement_id and tenant_id = get_my_tenant_id();
  if not found then raise exception 'INS_NOT_FOUND: endorsement'; end if;
  perform id from ins_policies where id = pid for update;
  select * into c from ins_policy_endorsements where id = p_endorsement_id for update;
  if c.status not in ('proposed','prepared')
     or (c.status = 'prepared' and c.prepared_by <> auth.uid()) then
    raise exception 'INS_ENDORSEMENT_STATE: proposal or own prepared case required';
  end if;
  quote := ins_preview_policy_endorsement(c.policy_id, c.effective_date, c.insurer_terms, c.changes)
           || ins_endorsement_review_position(c.policy_id);
  mappings := ins_endorsement_mappings(c.policy_id, p_clearing_gl_account_id);
  update ins_policy_endorsements
     set status = 'prepared', prepared_by = auth.uid(), prepared_at = now(),
         calculation = quote, accounting_mappings = mappings
   where id = c.id
   returning * into c;
  insert into ins_policy_endorsement_events(tenant_id, endorsement_id, event, actor_id, detail)
  values (c.tenant_id, c.id, 'prepared', auth.uid(),
          jsonb_build_object('calculation', quote, 'mappings', mappings));
  return c;
end $$;


--
-- Name: ins_preview_policy_cancellation(uuid, date, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_preview_policy_cancellation(p_policy_id uuid, p_effective_date date, p_insurer_terms jsonb, p_charge_refunds jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; snap ins_policy_financial_snapshots%rowtype; shares jsonb; charges jsonb;
 allocation jsonb; term jsonb; charge jsonb; rule jsonb; calc jsonb; insurers jsonb:='[]'; charge_results jsonb:='[]'; pass_rows jsonb:='[]';
 original_parts jsonb; parts jsonb; part jsonb; decision jsonb; recipient_refund numeric; recipient_total numeric; final_insurers jsonb:='[]';
 refund numeric; original_amount numeric; original_vat numeric; vat_refund numeric; premium_return numeric:=0; total_credit numeric:=0;
 invoice numeric; unpaid numeric; pass_refund numeric; requires_exception boolean:=false; item_count integer;
begin
 if auth.uid() is null or effective_user_id() is distinct from auth.uid()
  or not (can_manage_insurance() or is_finance_team_member('finance')) then
  raise exception 'INS_FORBIDDEN: Insurance manager or Finance acting as themselves required' using errcode='42501'; end if;
 select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 if p.status not in('active','renewed') then raise exception 'INS_CANCELLATION_STATE: bound policy required'; end if;
 if exists(select 1 from ins_claims where policy_id=p.id and tenant_id=p.tenant_id) then
  raise exception 'INS_CANCELLATION_CLAIM: policies with existing claims are not supported in v1'; end if;
 if p_effective_date is null or p_effective_date>current_date then raise exception 'INS_CANCELLATION_INPUT: a non-future effective cancellation date is required'; end if;
 if jsonb_typeof(p_insurer_terms) is distinct from 'array' or jsonb_typeof(p_charge_refunds) is distinct from 'array' then
  raise exception 'INS_CANCELLATION_INPUT: insurer terms and charge decisions must be arrays'; end if;
 if jsonb_array_length(p_insurer_terms)>30 or jsonb_array_length(p_charge_refunds)>100 then raise exception 'INS_CANCELLATION_INPUT: too many input lines'; end if;
 select * into snap from ins_policy_financial_snapshots where policy_id=p.id and tenant_id=p.tenant_id;
 -- Financial data comes only from immutable bind-time records, never from
 -- client-supplied premiums, shares, commission rates, recipients or VAT rates.
 shares:=snap.snapshot->'shares'; charges:=coalesce(snap.snapshot->'charges','[]'::jsonb);
 if shares is null or shares='[]'::jsonb then
  shares:=jsonb_build_array(jsonb_build_object('insurer_id',p.insurer_id,'premium_amount',p.gross_premium,
   'commission_amount',p.commission_amount,'commission_rate_pct',p.commission_rate_pct,'share_pct',100));
 end if;
 invoice:=coalesce(snap.invoice_total,p.gross_premium);
 if jsonb_array_length(p_insurer_terms)<>jsonb_array_length(shares)
  or (select count(*)<>count(distinct x->>'insurer_id') from jsonb_array_elements(p_insurer_terms) x) then
  raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: provide one set of terms for every original insurer'; end if;
 for allocation in select value from jsonb_array_elements(shares) loop
  select x->'terms' into term from jsonb_array_elements(p_insurer_terms) x where x->>'insurer_id'=allocation->>'insurer_id';
  if term is null then raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: missing original insurer terms'; end if;
  calc:=platform_ins_calculate_insurer_cancellation(allocation,term,p.inception_date,p.expiry_date,p_effective_date);
  insurers:=insurers||jsonb_build_array(calc);
  premium_return:=premium_return+(calc->>'return_premium')::numeric;
  requires_exception:=requires_exception or (calc->>'requires_finance_exception')::boolean;
 end loop;
 if jsonb_array_length(p_charge_refunds)<>jsonb_array_length(charges)
  or (select count(*)<>count(distinct x->>'charge_id') from jsonb_array_elements(p_charge_refunds) x) then
  raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: decide every original charge, including zero-valued lines'; end if;
 total_credit:=premium_return;
 for charge in select value from jsonb_array_elements(charges) loop
  select x into rule from jsonb_array_elements(p_charge_refunds) x where x->>'charge_id'=charge->>'id';
  if rule is null or rule->'legal_basis_confirmed' is distinct from 'true'::jsonb or length(btrim(coalesce(rule->>'basis','')))<5 then
   raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: confirm the contractual/legal basis for every refundable or retained charge'; end if;
  original_amount:=platform_ins_cancellation_money(charge->>'amount');
  refund:=platform_ins_cancellation_money(rule->>'refund_amount');
  if refund>original_amount then raise exception 'INS_CANCELLATION_INPUT: charge refund exceeds its original amount'; end if;
  original_vat:=coalesce((charge->>'vat_amount')::numeric,0); vat_refund:=0;
  if charge->>'kind'='broker_fee' then
   if original_amount=0 and original_vat<>0 then raise exception 'INS_CANCELLATION_HISTORY: VAT without broker-fee base'; end if;
   vat_refund:=case when original_amount=0 then 0 when refund=original_amount then original_vat else platform_ins_cancellation_round_ratio(original_vat*refund,original_amount) end;
  else
   if charge->>'recipient_mode'='one_insurer' then
    original_parts:=jsonb_build_array(jsonb_build_object('insurer_id',charge->>'recipient_insurer_id','amount',original_amount::text));
   else
    -- Reconstruct the exact original Hamilton allocation from immutable shares.
    with bases as(select x->>'insurer_id' as insurer_id,trunc(original_amount*(x->>'share_pct')::numeric/100,2) as base,
      original_amount*(x->>'share_pct')::numeric/100-trunc(original_amount*(x->>'share_pct')::numeric/100,2) as fraction from jsonb_array_elements(shares) x),
    ranked as(select *,row_number() over(order by fraction desc,insurer_id collate "C") as rank,round((original_amount-sum(base) over())*100) as cents from bases)
    select jsonb_agg(jsonb_build_object('insurer_id',insurer_id,'amount',(base+case when rank<=cents then .01 else 0 end)::text)) into original_parts from ranked;
   end if;
   if jsonb_typeof(rule->'insurer_refunds') is distinct from 'array' then
    raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: each pass-through recipient needs its own explicit refund decision'; end if;
   if jsonb_array_length(rule->'insurer_refunds')<>jsonb_array_length(original_parts)
     or (select count(*)<>count(distinct x->>'insurer_id') from jsonb_array_elements(rule->'insurer_refunds') x) then
    raise exception 'INS_CANCELLATION_INPUT: exactly one charge decision per original recipient required'; end if;
   recipient_total:=0;
   for part in select value from jsonb_array_elements(original_parts) loop
    select x into decision from jsonb_array_elements(rule->'insurer_refunds') x where x->>'insurer_id'=part->>'insurer_id';
    if decision is null or length(btrim(coalesce(decision->>'basis','')))<5 then
     raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: recipient-specific charge refund/retention basis required'; end if;
    recipient_refund:=platform_ins_cancellation_money(decision->>'refund_amount');
    if recipient_refund>(part->>'amount')::numeric then raise exception 'INS_CANCELLATION_INPUT: refund exceeds recipient original charge allocation'; end if;
    recipient_total:=recipient_total+recipient_refund;
    pass_rows:=pass_rows||jsonb_build_array(jsonb_build_object('insurer_id',part->>'insurer_id','charge_id',charge->>'id',
     'amount',recipient_refund::text,'original_amount',part->>'amount','retained_amount',((part->>'amount')::numeric-recipient_refund)::text,'basis',decision->>'basis'));
   end loop;
   if recipient_total<>refund then raise exception 'INS_CANCELLATION_INPUT: recipient refunds must equal the charge refund'; end if;
  end if;
  total_credit:=total_credit+refund+vat_refund;
  charge_results:=charge_results||jsonb_build_array(jsonb_build_object('charge_id',charge->>'id','kind',charge->>'kind',
   'refund_base',refund::text,'retained_base',(original_amount-refund)::text,'refund_vat',vat_refund::text,'retained_vat',(original_vat-vat_refund)::text,
   'basis',btrim(rule->>'basis'),'recipient_mode',charge->>'recipient_mode','recipient_insurer_id',charge->>'recipient_insurer_id',
   'vat_mode',charge->>'vat_mode','income_gl_account_id',charge->>'income_gl_account_id'));
 end loop;
 for calc in select value from jsonb_array_elements(insurers) loop
  select coalesce(sum((x->>'amount')::numeric),0) into pass_refund from jsonb_array_elements(pass_rows) x where x->>'insurer_id'=calc->>'insurer_id';
  final_insurers:=final_insurers||jsonb_build_array(calc||jsonb_build_object('pass_through_refund',pass_refund::text,
   'total_insurer_credit',((calc->>'net_insurer_credit')::numeric+pass_refund)::text));
 end loop;
 select count(*),sum(outstanding_amount) into item_count,unpaid from fin_open_item_balances where tenant_id=p.tenant_id and source_id=p.id and source_type='ins_policy_premium';
 if item_count<>1 or unpaid<0 or unpaid>invoice or total_credit>invoice then raise exception 'INS_CANCELLATION_HISTORY: policy receivable does not reconcile'; end if;
 if exists(select 1 from fin_credit_applications a join fin_credit_notes n on n.id=a.credit_note_id
   join fin_open_items i on i.id=a.open_item_id where i.tenant_id=p.tenant_id and i.source_type='ins_policy_premium' and i.source_id=p.id and n.status='posted') then
  raise exception 'INS_CANCELLATION_REVIEW_REQUIRED: existing policy credits require Finance review'; end if;
 return jsonb_build_object('stage','calculation_only','approval_status','not_approved','payment_authorized',false,
  'policy_id',p.id,'currency',p.currency,'effective_date',p_effective_date,'generated_at',now(),
  'cover_day_convention','inclusive cover dates; cancellation day is not earned cover',
  'insurers',final_insurers,'charges',charge_results,'pass_through_allocations',pass_rows,
  'invoice_credit',total_credit::text,'receivable_credit',least(total_credit,unpaid)::text,'client_refund_due',greatest(total_credit-unpaid,0)::text,
  'requires_finance_review',true,'requires_finance_exception',requires_exception,
  'funding_status','not_checked','notice','Calculation only. Cancellation approval and separately approved, funded cash payment are still required.');
end $$;


--
-- Name: ins_preview_policy_endorsement(uuid, date, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_preview_policy_endorsement(p_policy_id uuid, p_effective_date date, p_insurer_terms jsonb, p_changes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p ins_policies%rowtype;
  snap ins_policy_financial_snapshots%rowtype;
  shares jsonb;
  term jsonb;
  allocation jsonb;
  matched text := '';
  calc jsonb := '{}'::jsonb;
  rows_out jsonb := '[]'::jsonb;
  changes_out jsonb := '[]'::jsonb;
  field text;
  before_val jsonb;
  after_val jsonb;
  delta numeric;
  total_days integer;
  remaining_days integer;
  premium_delta numeric := 0;
  commission_delta numeric := 0;
  premium_zero boolean := true;
begin
  if auth.uid() is null or effective_user_id() is distinct from auth.uid()
     or not (can_manage_insurance() or is_finance_team_member('finance')) then
    raise exception 'INS_FORBIDDEN: Insurance manager or Finance acting as themselves required' using errcode = '42501';
  end if;
  select * into p from ins_policies where id = p_policy_id and tenant_id = get_my_tenant_id() for update;
  if not found then
    raise exception 'INS_NOT_FOUND: policy';
  end if;
  if p.status not in ('active','renewed') then
    raise exception 'INS_ENDORSEMENT_STATE: a bound policy is required (this one is %)', p.status;
  end if;
  if p_effective_date is null or p_effective_date > current_date then
    raise exception 'INS_ENDORSEMENT_INPUT: a non-future effective date is required';
  end if;
  if jsonb_typeof(p_insurer_terms) is distinct from 'array'
     or jsonb_array_length(p_insurer_terms) > 30 then
    raise exception 'INS_ENDORSEMENT_INPUT: insurer terms must be an array of at most 30 lines';
  end if;
  if p_changes is null or jsonb_typeof(p_changes) is distinct from 'object' then
    raise exception 'INS_ENDORSEMENT_INPUT: changes must be a JSON object';
  end if;

  -- The immutable bind-time shares, with the single-insurer fallback the
  -- cancellation preview uses.
  select * into snap from ins_policy_financial_snapshots where policy_id = p.id and tenant_id = p.tenant_id;
  shares := coalesce(snap.snapshot -> 'shares', '[]'::jsonb);
  if shares is null or shares = '[]'::jsonb then
    shares := jsonb_build_array(jsonb_build_object(
      'insurer_id', p.insurer_id, 'premium_amount', p.gross_premium,
      'commission_amount', p.commission_amount, 'commission_rate_pct', p.commission_rate_pct, 'share_pct', 100));
  end if;

  total_days := (p.expiry_date - p.inception_date);
  remaining_days := (p.expiry_date - p_effective_date);
  if remaining_days < 0 then
    raise exception 'INS_ENDORSEMENT_INPUT: the effective date is after the policy expires';
  end if;

  -- Per-insurer premium deltas. The insurer's agreed delta wins; pro-rata by
  -- the remaining days of the policy is the fallback. An insurer without a
  -- term simply takes no delta -- unlike a cancellation, an endorsement may
  -- concern one co-insurer only.
  for term in select value from jsonb_array_elements(p_insurer_terms) loop
    if term ->> 'insurer_id' is null then
      raise exception 'INS_ENDORSEMENT_INPUT: each term names its insurer';
    end if;
    for allocation in select value from jsonb_array_elements(shares) loop
      continue when allocation ->> 'insurer_id' is distinct from term ->> 'insurer_id';
      if matched like '%|' || (term ->> 'insurer_id') || '|%' then
        raise exception 'INS_ENDORSEMENT_INPUT: insurer % appears twice in the terms', term ->> 'insurer_id';
      end if;
      matched := matched || '|' || (term ->> 'insurer_id') || '|';

      if term ? 'agreed_delta' then
        delta := platform_ins_endorsement_money(term ->> 'agreed_delta');
      elsif term ->> 'method' = 'pro_rata' then
        delta := round(
          platform_ins_endorsement_money(term ->> 'annual_delta')
          * remaining_days / greatest(total_days, 1), 2);
      else
        raise exception 'INS_ENDORSEMENT_INPUT: a term is either an agreed_delta or pro_rata with annual_delta';
      end if;

      calc := jsonb_build_object(
        'insurer_id', term ->> 'insurer_id',
        'share_pct', allocation ->> 'share_pct',
        'share_premium', allocation ->> 'premium_amount',
        'basis', case when term ? 'agreed_delta' then 'agreed' else 'pro_rata' end,
        'input', case when term ? 'agreed_delta' then term ->> 'agreed_delta' else term ->> 'annual_delta' end,
        'premium_delta', delta,
        'commission_delta', round(delta * (p.commission_rate_pct / 100.0), 2),
        'rate_pct', p.commission_rate_pct,
        'requires_review', abs(delta) > (allocation ->> 'premium_amount')::numeric);
      rows_out := rows_out || calc;
      premium_delta := premium_delta + delta;
      commission_delta := commission_delta + (calc ->> 'commission_delta')::numeric;
    end loop;
    if not matched like '%|' || (term ->> 'insurer_id') || '|%' then
      raise exception 'INS_ENDORSEMENT_INPUT: insurer % is not on this policy', term ->> 'insurer_id';
    end if;
  end loop;

  premium_zero := premium_delta = 0;

  -- Descriptive changes ride along; only known fields, with before/after
  -- recorded (the policy row itself is never mutated).
  for field in select jsonb_object_keys(p_changes) loop
    if field not in ('sum_insured','risk_description','notes') then
      raise exception 'INS_ENDORSEMENT_INPUT: % is not an endorsable field', field;
    end if;
    after_val := p_changes -> field;
    if field = 'sum_insured' then
      if jsonb_typeof(after_val) is distinct from 'number'
         or (after_val)::numeric is null or (after_val)::numeric <= 0 then
        raise exception 'INS_ENDORSEMENT_INPUT: sum_insured must be a positive number';
      end if;
      before_val := to_jsonb(p.sum_insured);
    else
      if jsonb_typeof(after_val) is distinct from 'string'
         or length(btrim(after_val #>> '{}')) > 2000 then
        raise exception 'INS_ENDORSEMENT_INPUT: % must be text of at most 2000 characters', field;
      end if;
      before_val := to_jsonb(case when field = 'notes' then p.notes else p.risk_description end);
    end if;
    changes_out := changes_out || jsonb_build_object('field', field, 'before', before_val, 'after', after_val);
  end loop;

  if premium_zero and jsonb_array_length(changes_out) = 0 then
    raise exception 'INS_ENDORSEMENT_INPUT: an endorsement changes the premium or the policy record -- this one changes neither';
  end if;

  return jsonb_build_object(
    'policy_id', p.id, 'policy_no', p.policy_no, 'currency', p.currency,
    'inception_date', p.inception_date, 'expiry_date', p.expiry_date,
    'effective_date', p_effective_date,
    'total_days', total_days, 'remaining_days', remaining_days,
    'commission_rate_pct', p.commission_rate_pct,
    'shares', rows_out,
    'premium_delta', premium_delta,
    'commission_delta', commission_delta,
    'premium_zero', premium_zero,
    'changes', changes_out);
end $$;


--
-- Name: ins_propose_policy_endorsement(uuid, date, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_propose_policy_endorsement(p_policy_id uuid, p_effective_date date, p_insurer_terms jsonb, p_changes jsonb, p_reason text, p_request_key uuid) RETURNS public.ins_policy_endorsements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  e ins_policy_endorsements%rowtype;
  quote jsonb;
begin
  if auth.uid() is null or effective_user_id() is distinct from auth.uid()
     or not (can_manage_insurance() or is_finance_team_member('finance')) then
    raise exception 'INS_FORBIDDEN: Insurance manager or Finance acting as themselves required' using errcode = '42501';
  end if;
  if p_request_key is null or p_reason is null or length(btrim(p_reason)) not between 5 and 2000 then
    raise exception 'INS_ENDORSEMENT_INPUT: request key and reason required';
  end if;

  -- Idempotent retry by key, with a payload-conflict refusal.
  select * into e from ins_policy_endorsements
   where tenant_id = get_my_tenant_id() and request_key = p_request_key;
  if found then
    if e.proposed_by <> auth.uid()
       or e.policy_id is distinct from p_policy_id
       or e.effective_date is distinct from p_effective_date
       or e.insurer_terms is distinct from p_insurer_terms
       or e.changes is distinct from coalesce(p_changes, '{}'::jsonb)
       or e.reason is distinct from btrim(p_reason) then
      raise exception 'INS_ENDORSEMENT_RETRY_CONFLICT: different payload';
    end if;
    return e;
  end if;

  perform id from ins_policies where id = p_policy_id and tenant_id = get_my_tenant_id() for update;
  if not found then
    raise exception 'INS_NOT_FOUND: policy';
  end if;
  if exists (select 1 from ins_policy_endorsements
              where policy_id = p_policy_id and status in ('proposed','prepared','posting')) then
    raise exception 'INS_ENDORSEMENT_EXISTS: a live endorsement already exists on this policy';
  end if;
  if exists (select 1 from ins_policy_cancellations
              where policy_id = p_policy_id and status in ('proposed','prepared','posting','posted')) then
    raise exception 'INS_ENDORSEMENT_CXL_LIVE: this policy has a cancellation in flight; endorse it another day';
  end if;

  quote := ins_preview_policy_endorsement(p_policy_id, p_effective_date, p_insurer_terms, p_changes);
  insert into ins_policy_endorsements
    (tenant_id, policy_id, request_key, reason, effective_date, insurer_terms, changes, proposed_by, calculation)
  values
    (get_my_tenant_id(), p_policy_id, p_request_key, btrim(p_reason), p_effective_date,
     p_insurer_terms, coalesce(p_changes, '{}'::jsonb), auth.uid(), quote)
  returning * into e;
  insert into ins_policy_endorsement_events(tenant_id, endorsement_id, event, actor_id)
    values (e.tenant_id, e.id, 'proposed', auth.uid());
  return e;
end $$;


--
-- Name: ins_recognise_claim_receivable(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_recognise_claim_receivable(p_claim_id uuid, p_insurer_confirmation text) RETURNS public.ins_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_claim  ins_claims%rowtype;
  v_insurer uuid;
  v_client  uuid;
  v_ccy     text;
  v_recv_gl uuid;
  v_pay_gl  uuid;
  v_ins_acc uuid;
  v_cli_acc uuid;
  v_desc    text;
  v_je      journal_entries%rowtype;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers recognise claim receivables' using errcode = '42501';
  end if;
  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: claim';
  end if;
  if v_claim.status <> 'approved' then
    raise exception 'INS_CLAIM_STATE: only an approved claim can be recognised (this one is %)', v_claim.status;
  end if;
  if v_claim.payment_mode <> 'via_broker' then
    raise exception 'INS_CLAIM_MODE: only a claim paid through the brokerage is recognised here';
  end if;
  if v_claim.recognised_at is not null then
    raise exception 'INS_CLAIM_RECOGNISED: this claim is already recognised';
  end if;
  if nullif(btrim(p_insurer_confirmation), '') is null then
    raise exception 'INS_NOTE_REQUIRED: give the insurer''s written confirmation reference before recognising the receivable';
  end if;

  select p.insurer_id, p.client_id, p.currency into v_insurer, v_client, v_ccy from ins_policies p where p.id = v_claim.policy_id;
  v_recv_gl := get_posting_account(v_tenant, 'insurer_claim_receivable');
  v_pay_gl  := get_posting_account(v_tenant, 'client_claim_payable');
  if v_recv_gl is null or v_pay_gl is null then
    raise exception 'INS_POSTING_RULE_MISSING: this insurer pays claims through the brokerage, so the chart of accounts needs insurer_claim_receivable and client_claim_payable';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  v_ins_acc := ins_ensure_insurer_account(v_insurer);
  v_cli_acc := ins_ensure_client_account(v_client);
  v_desc := 'Claim ' || v_claim.claim_no || ' recognised: insurer confirmed payment through the brokerage';
  v_je := post_journal_entry(v_tenant, 'ins_claim_accrual', v_claim.id, current_date, v_desc, jsonb_build_array(
    jsonb_build_object('gl_account_id', v_recv_gl, 'debit',  v_claim.approved_amount, 'currency', v_ccy, 'description', v_desc),
    jsonb_build_object('gl_account_id', v_pay_gl,  'credit', v_claim.approved_amount, 'currency', v_ccy, 'description', v_desc)));
  -- The claim items hold the rate the accrual was booked at.
  perform fin_create_open_item_fx(v_tenant, v_ins_acc, 'insurer_claim_receivable', 'ins_claim_insurer', v_claim.id,
    v_claim.claim_no, current_date, current_date, v_claim.approved_amount, 'Claim funds due from the insurer', v_ccy, v_je.id);
  perform fin_create_open_item_fx(v_tenant, v_cli_acc, 'client_claim_payable', 'ins_claim_client', v_claim.id,
    v_claim.claim_no, current_date, current_date, v_claim.approved_amount, 'Claim proceeds due to the client', v_ccy, v_je.id);

  update ins_claims set recognised_at = now(), recognised_by = auth.uid()
   where id = v_claim.id returning * into v_claim;
  insert into ins_claim_events (tenant_id, claim_id, from_status, to_status, note)
  values (v_tenant, v_claim.id, 'approved', 'approved', 'Receivable recognised. Insurer confirmation: ' || btrim(p_insurer_confirmation));
  return v_claim;
end;
$$;


--
-- Name: ins_claim_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_claim_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    claim_id uuid NOT NULL,
    kind text NOT NULL,
    amount numeric(18,2) NOT NULL,
    payment_date date NOT NULL,
    reference text,
    notes text,
    settlement_id uuid,
    status text DEFAULT 'posted'::text NOT NULL,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ins_claim_payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT ins_claim_payments_kind_check CHECK ((kind = ANY (ARRAY['insurer_direct'::text, 'insurer_receipt'::text, 'client_payout'::text]))),
    CONSTRAINT ins_claim_payments_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT ins_claim_payments_settlement_kind_check CHECK (((kind = 'insurer_direct'::text) = (settlement_id IS NULL))),
    CONSTRAINT ins_claim_payments_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'void'::text]))),
    CONSTRAINT ins_claim_payments_void_check CHECK ((((status = 'posted'::text) AND (voided_at IS NULL) AND (void_reason IS NULL)) OR ((status = 'void'::text) AND (voided_at IS NOT NULL) AND (void_reason IS NOT NULL))))
);


--
-- Name: ins_record_claim_payment(uuid, numeric, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_record_claim_payment(p_claim_id uuid, p_amount numeric, p_payment_date date, p_reference text, p_notes text DEFAULT NULL::text) RETURNS public.ins_claim_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_claim  ins_claims%rowtype;
  v_pay    ins_claim_payments%rowtype;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers record claim payments' using errcode = '42501';
  end if;
  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then raise exception 'INS_NOT_FOUND: claim'; end if;
  if v_claim.status <> 'approved' then
    raise exception 'INS_CLAIM_STATE: payments are recorded on an approved claim (this one is %)', v_claim.status;
  end if;
  if v_claim.payment_mode <> 'insurer_direct' then
    raise exception 'INS_CLAIM_MODE: this claim is paid through the brokerage; record the insurer receipt and the client payout instead';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'INS_AMOUNT: the payment amount must be greater than zero';
  end if;
  if p_amount > v_claim.approved_amount - v_claim.paid_amount then
    raise exception 'INS_AMOUNT: only % is still unpaid on this claim', v_claim.approved_amount - v_claim.paid_amount;
  end if;
  if p_payment_date is null or p_payment_date > current_date or p_payment_date < v_claim.notified_date then
    raise exception 'INS_DATE: the payment date must be between the notified date and today';
  end if;
  if nullif(btrim(p_reference), '') is null then
    raise exception 'INS_REFERENCE_REQUIRED: give the insurer payment reference, because nothing else in the system evidences this payment';
  end if;

  insert into ins_claim_payments (tenant_id, claim_id, kind, amount, payment_date, reference, notes)
  values (v_tenant, v_claim.id, 'insurer_direct', p_amount, p_payment_date, btrim(p_reference), nullif(btrim(p_notes), ''))
  returning * into v_pay;

  perform ins_claim_apply_payment_totals(v_claim.id, 'Paid in full by the insurer');
  return v_pay;
end;
$$;


--
-- Name: ins_record_claim_payout(uuid, uuid, numeric, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_record_claim_payout(p_claim_id uuid, p_bank_account_id uuid, p_amount numeric, p_payment_date date, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_claim_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant   uuid := get_my_tenant_id();
  v_claim    ins_claims%rowtype;
  v_kind     text;
  v_item     record;
  v_held     numeric;
  v_set      fin_settlements%rowtype;
  v_pay      ins_claim_payments%rowtype;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers pay out claims' using errcode = '42501';
  end if;
  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then raise exception 'INS_NOT_FOUND: claim'; end if;
  if v_claim.status <> 'approved' then
    raise exception 'INS_CLAIM_STATE: payouts are made on an approved claim (this one is %)', v_claim.status;
  end if;
  if v_claim.payment_mode <> 'via_broker' then
    raise exception 'INS_CLAIM_MODE: this insurer pays the client directly; there is nothing for the brokerage to pay out';
  end if;
  if v_claim.recognised_at is null then
    raise exception 'INS_CLAIM_NOT_RECOGNISED: record the insurer''s confirmation first, so the payable is recognised';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'INS_AMOUNT: the payout amount must be greater than zero';
  end if;
  select kind into v_kind from fin_bank_accounts where id = p_bank_account_id and tenant_id = v_tenant;
  if v_kind is distinct from 'client_money' then
    raise exception 'INS_BANK_KIND: claim money is paid out of a client-money bank account';
  end if;

  -- Held funds are counted per currency: only money that arrived in this
  -- account's currency satisfies a payout from it. The settlement engine
  -- refuses a cross-currency payout outright (SETTLEMENT_CURRENCY); this
  -- keeps the anti-fronting arithmetic honest when a claim ever carries
  -- payments in more than one currency.
  select coalesce(sum(p.amount) filter (where p.kind = 'insurer_receipt'), 0)
         - coalesce(sum(p.amount) filter (where p.kind = 'client_payout'), 0)
    into v_held
    from ins_claim_payments p
   where p.claim_id = v_claim.id
     and p.status = 'posted'
     and (select s.currency from fin_settlements s where s.id = p.settlement_id)
       = (select b.currency from fin_bank_accounts b where b.id = p_bank_account_id);
  if p_amount > v_held then
    raise exception 'INS_CLAIM_FUNDS_NOT_RECEIVED: only % has been received from the insurer in this account''s currency and not yet paid out; the brokerage does not pay a client ahead of the insurer', v_held;
  end if;

  select b.id, b.party_account_id, b.outstanding_amount into v_item
    from fin_open_item_balances b
   where b.tenant_id = v_tenant and b.source_type = 'ins_claim_client' and b.source_id = v_claim.id;
  if not found then raise exception 'INS_NOT_FOUND: the client item for this claim'; end if;
  if p_amount > v_item.outstanding_amount then
    raise exception 'INS_AMOUNT: only % is still owed to the client on this claim', v_item.outstanding_amount;
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  v_set := platform_fin_record_settlement_impl(
    v_tenant, p_bank_account_id, 'out', v_item.party_account_id, p_amount, p_payment_date,
    jsonb_build_array(jsonb_build_object('open_item_id', v_item.id, 'amount', p_amount)),
    coalesce(nullif(btrim(p_reference), ''), v_claim.claim_no), nullif(btrim(p_notes), ''));

  insert into ins_claim_payments (tenant_id, claim_id, kind, amount, payment_date, reference, notes, settlement_id)
  values (v_tenant, v_claim.id, 'client_payout', p_amount, p_payment_date, nullif(btrim(p_reference), ''), nullif(btrim(p_notes), ''), v_set.id)
  returning * into v_pay;

  perform ins_claim_apply_payment_totals(v_claim.id, 'Paid in full to the client by the brokerage');
  return v_pay;
end;
$$;


--
-- Name: ins_record_claim_receipt(uuid, uuid, numeric, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_record_claim_receipt(p_claim_id uuid, p_bank_account_id uuid, p_amount numeric, p_receipt_date date, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_claim_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_claim  ins_claims%rowtype;
  v_kind   text;
  v_item   record;
  v_set    fin_settlements%rowtype;
  v_pay    ins_claim_payments%rowtype;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers record claim receipts' using errcode = '42501';
  end if;
  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then raise exception 'INS_NOT_FOUND: claim'; end if;
  if v_claim.status <> 'approved' then
    raise exception 'INS_CLAIM_STATE: receipts are recorded on an approved claim (this one is %)', v_claim.status;
  end if;
  if v_claim.payment_mode <> 'via_broker' then
    raise exception 'INS_CLAIM_MODE: this insurer pays the client directly; record the insurer payment instead';
  end if;
  if v_claim.recognised_at is null then
    raise exception 'INS_CLAIM_NOT_RECOGNISED: record the insurer''s confirmation first, so the receivable is recognised';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'INS_AMOUNT: the receipt amount must be greater than zero';
  end if;
  select kind into v_kind from fin_bank_accounts where id = p_bank_account_id and tenant_id = v_tenant;
  if v_kind is distinct from 'client_money' then
    raise exception 'INS_BANK_KIND: claim money is received into a client-money bank account';
  end if;

  select b.id, b.party_account_id, b.outstanding_amount into v_item
    from fin_open_item_balances b
   where b.tenant_id = v_tenant and b.source_type = 'ins_claim_insurer' and b.source_id = v_claim.id;
  if not found then raise exception 'INS_NOT_FOUND: the insurer item for this claim'; end if;
  if p_amount > v_item.outstanding_amount then
    raise exception 'INS_AMOUNT: the insurer still owes only % on this claim', v_item.outstanding_amount;
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  v_set := platform_fin_record_settlement_impl(
    v_tenant, p_bank_account_id, 'in', v_item.party_account_id, p_amount, p_receipt_date,
    jsonb_build_array(jsonb_build_object('open_item_id', v_item.id, 'amount', p_amount)),
    coalesce(nullif(btrim(p_reference), ''), v_claim.claim_no), nullif(btrim(p_notes), ''));

  insert into ins_claim_payments (tenant_id, claim_id, kind, amount, payment_date, reference, notes, settlement_id)
  values (v_tenant, v_claim.id, 'insurer_receipt', p_amount, p_receipt_date, nullif(btrim(p_reference), ''), nullif(btrim(p_notes), ''), v_set.id)
  returning * into v_pay;
  return v_pay;
end;
$$;


--
-- Name: ins_renewal_outcomes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_renewal_outcomes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    outcome text NOT NULL,
    reason text NOT NULL,
    recorded_by uuid DEFAULT auth.uid(),
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ins_renewal_outcomes_outcome_check CHECK ((outcome = ANY (ARRAY['lost'::text, 'declined'::text, 'lapsed'::text]))),
    CONSTRAINT ins_renewal_outcomes_reason_check CHECK ((char_length(btrim(reason)) >= 5))
);


--
-- Name: ins_record_renewal_outcome(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_record_renewal_outcome(p_policy_id uuid, p_outcome text, p_reason text) RETURNS public.ins_renewal_outcomes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_pol    ins_policies%rowtype;
  v_row    ins_renewal_outcomes%rowtype;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  if p_outcome is null or p_outcome not in ('lost', 'declined', 'lapsed') then
    raise exception 'INS_OUTCOME_INVALID: choose lost, declined or lapsed';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 5 then
    raise exception 'INS_OUTCOME_REASON: give a reason of at least 5 characters';
  end if;

  select * into v_pol from ins_policies where id = p_policy_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: policy';
  end if;
  if v_pol.status <> 'active' then
    raise exception 'INS_RENEWAL_STATE: only an active policy can have a renewal outcome (this one is %)', v_pol.status;
  end if;
  if exists (select 1 from ins_policies where renewal_of_id = v_pol.id and status = 'draft') then
    raise exception 'INS_RENEWAL_EXISTS: a renewal draft is already open for %; finish or discard it first', v_pol.policy_no;
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  delete from ins_renewal_outcomes where tenant_id = v_tenant and policy_id = v_pol.id;
  insert into ins_renewal_outcomes (tenant_id, policy_id, outcome, reason)
  values (v_tenant, v_pol.id, p_outcome, btrim(p_reason))
  returning * into v_row;
  return v_row;
end $$;


--
-- Name: ins_clients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    client_type text DEFAULT 'corporate'::text NOT NULL,
    tax_id text,
    risk_rating text DEFAULT 'medium'::text NOT NULL,
    kyc_status text DEFAULT 'pending'::text NOT NULL,
    relationship_owner_id uuid,
    party_account_id uuid,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ins_clients_kyc_check CHECK ((kyc_status = ANY (ARRAY['pending'::text, 'verified'::text, 'expired'::text]))),
    CONSTRAINT ins_clients_risk_check CHECK ((risk_rating = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT ins_clients_type_check CHECK ((client_type = ANY (ARRAY['individual'::text, 'corporate'::text])))
);


--
-- Name: ins_register_client(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_register_client(p_name text, p_client_type text DEFAULT 'corporate'::text, p_tax_id text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_risk_rating text DEFAULT 'medium'::text) RETURNS public.ins_clients
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_bd_id  uuid;
  v_row    ins_clients%rowtype;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  if nullif(btrim(p_name), '') is null then
    raise exception 'INS_REQUIRED: client name is required';
  end if;

  insert into bd_clients (tenant_id, name, email, phone, created_by)
  values (v_tenant, btrim(p_name), nullif(btrim(p_email), ''), nullif(btrim(p_phone), ''), auth.uid())
  returning id into v_bd_id;

  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_clients (tenant_id, client_id, client_type, tax_id, risk_rating, relationship_owner_id)
  values (v_tenant, v_bd_id, p_client_type, nullif(btrim(p_tax_id), ''), p_risk_rating, auth.uid())
  returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: ins_register_risk(uuid, uuid, text, text, text, text, text, text, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_register_risk(p_client_id uuid, p_product_line_id uuid, p_risk_type text, p_description text, p_reg_no text DEFAULT NULL::text, p_chassis_no text DEFAULT NULL::text, p_engine_no text DEFAULT NULL::text, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_year_made integer DEFAULT NULL::integer, p_sum_insured numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); needs_cert boolean; new_id uuid;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  if not exists (select 1 from ins_clients where id = p_client_id and tenant_id = t) then raise exception 'INS_NOT_FOUND: client'; end if;
  perform 1 from ins_product_lines where id = p_product_line_id and tenant_id = t and is_active;
  if not found then raise exception 'INS_NOT_FOUND: active product line'; end if;
  needs_cert := public.platform_ins_line_needs_certificate(t, p_product_line_id);
  if needs_cert and p_risk_type <> 'vehicle' then
    raise exception 'INS_RISK_TYPE: a motor product line needs a vehicle risk';
  end if;
  if needs_cert and nullif(btrim(coalesce(p_chassis_no, '')), '') is null then
    raise exception 'INS_RISK_INPUT: a vehicle needs a chassis number';
  end if;
  begin
    insert into ins_risks (tenant_id, client_id, product_line_id, risk_type, description, reg_no, chassis_no, engine_no,
      make, model, year_made, sum_insured)
    values (t, p_client_id, p_product_line_id, p_risk_type, btrim(p_description),
      nullif(btrim(coalesce(p_reg_no, '')), ''), nullif(btrim(coalesce(p_chassis_no, '')), ''),
      nullif(btrim(coalesce(p_engine_no, '')), ''), nullif(btrim(coalesce(p_make, '')), ''),
      nullif(btrim(coalesce(p_model, '')), ''), p_year_made, coalesce(p_sum_insured, 0))
    returning id into new_id;
  exception when unique_violation then
    raise exception 'INS_DUPLICATE: a risk with this chassis number already exists';
  end;
  return new_id;
end $$;


--
-- Name: ins_remittance_due_date(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_remittance_due_date(p_tenant_id uuid, p_receipt_date date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_days numeric;
  v_due  date;
begin
  if p_receipt_date is null then
    return null;
  end if;
  begin
    v_days := platform_reg_number(p_tenant_id, 'remittance.deadline_working_days', p_receipt_date);
  exception when others then
    if sqlerrm like 'REG_PARAM_MISSING%' then
      return null;   -- no approved value: no deadline, and no default is assumed
    end if;
    raise;
  end;
  if v_days is null or v_days < 0 or v_days <> trunc(v_days) then
    raise exception 'REG_VALUE_INVALID: remittance deadline must be a whole number of working days';
  end if;
  if v_days = 0 then
    return p_receipt_date;
  end if;
  select (p_receipt_date + g.n) into v_due
    from generate_series(1, 120) as g(n)
   where extract(isodow from p_receipt_date + g.n) < 6
   order by g.n
   offset (v_days::int - 1)
   limit 1;
  return v_due;
end;
$$;


--
-- Name: ins_renewal_notification_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_renewal_notification_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant  uuid := get_my_tenant_id();
  v_recips  uuid[];
  v_kinds   text[] := '{}';
  v_nos     text[] := '{}';
  v_ins     integer;
  v_total   integer := 0;
  r         record;
  k         text;
  v_list    text[];
  v_count   integer;
  v_shown   text;
begin
  if auth.uid() is null or v_tenant is null
     or not has_module_role('insurance', array['admin', 'manager', 'member']) then
    return 0;
  end if;

  -- Nobody to tell: leave the markers alone so the policies are picked up
  -- once a manager exists, rather than marking them as sent.
  v_recips := ins_notify_insurance_users(v_tenant, array['admin', 'manager']);
  if coalesce(array_length(v_recips, 1), 0) = 0 then
    return 0;
  end if;

  for r in
    select p.id, p.policy_no,
      case
        when p.expiry_date < current_date              then 'lapsed'
        when p.expiry_date - current_date <= 7         then 'renewal_7'
        when p.expiry_date - current_date <= 30        then 'renewal_30'
        else 'renewal_60'
      end as kind
    from ins_policies p
    where p.tenant_id = v_tenant
      and p.status = 'active'
      and p.expiry_date >= current_date - 30
      and p.expiry_date <= current_date + 60
      and not exists (select 1 from ins_policies d
                      where d.tenant_id = p.tenant_id and d.renewal_of_id = p.id and d.status = 'draft')
      and not exists (select 1 from ins_renewal_outcomes o
                      where o.tenant_id = p.tenant_id and o.policy_id = p.id)
      and not exists (select 1 from ins_policy_cancellations c
                      where c.tenant_id = p.tenant_id and c.policy_id = p.id
                        and c.status in ('proposed', 'prepared', 'posting', 'posted'))
    order by p.expiry_date, p.policy_no
  loop
    -- A policy first seen inside a tighter window skips the looser notices.
    if r.kind = 'renewal_7' then
      insert into ins_notification_marks (tenant_id, policy_id, kind)
      values (v_tenant, r.id, 'renewal_30'), (v_tenant, r.id, 'renewal_60')
      on conflict do nothing;
    elsif r.kind = 'renewal_30' then
      insert into ins_notification_marks (tenant_id, policy_id, kind)
      values (v_tenant, r.id, 'renewal_60')
      on conflict do nothing;
    end if;

    insert into ins_notification_marks (tenant_id, policy_id, kind)
    values (v_tenant, r.id, r.kind)
    on conflict do nothing;
    get diagnostics v_ins = row_count;

    if v_ins = 1 then
      v_kinds := v_kinds || r.kind;
      v_nos   := v_nos || r.policy_no;
    end if;
  end loop;

  foreach k in array array['renewal_7', 'renewal_30', 'renewal_60', 'lapsed'] loop
    select coalesce(array_agg(t.n order by t.ord), '{}') into v_list
    from unnest(v_kinds, v_nos) with ordinality as t(kind, n, ord)
    where t.kind = k;

    v_count := coalesce(array_length(v_list, 1), 0);
    continue when v_count = 0;

    v_total := v_total + v_count;
    v_shown := array_to_string(v_list[1:5], ', ')
               || case when v_count > 5 then format(' and %s more', v_count - 5) else '' end;

    perform ins_notify(
      v_tenant, v_recips, '{}'::uuid[],
      case when k = 'lapsed' then 'ins_policy_lapsed' else 'ins_renewal_due' end,
      case k
        when 'renewal_7'  then 'Renewals due within 7 days'
        when 'renewal_30' then 'Renewals due within 30 days'
        when 'renewal_60' then 'Renewals due within 60 days'
        else 'Policies lapsed without renewal'
      end,
      case when k = 'lapsed'
           then format('%s %s expired in the last 30 days with no renewal, outcome or cancellation: %s.',
                       v_count, case when v_count = 1 then 'policy' else 'policies' end, v_shown)
           else format('%s %s expire%s %s: %s.',
                       v_count, case when v_count = 1 then 'policy' else 'policies' end,
                       case when v_count = 1 then 's' else '' end,
                       case k when 'renewal_7' then 'within 7 days'
                              when 'renewal_30' then 'within 30 days'
                              else 'within 60 days' end,
                       v_shown)
      end,
      '/insurance/renewals');
  end loop;

  return v_total;
end;
$$;


--
-- Name: ins_renewal_outcomes_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_renewal_outcomes_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.ins_via_rpc() then
    raise exception 'INS_RPC_ONLY: record renewal outcomes with ins_record_renewal_outcome()' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' then
    raise exception 'INS_OUTCOME_IMMUTABLE: a renewal outcome is not edited; record a new one or clear it';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end $$;


--
-- Name: ins_reversal_complete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reversal_complete_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r ins_policy_reversals%rowtype;
begin
  select * into r from ins_policy_reversals where id=new.id;
  if r.outcome<>'posted' or r.premium_credit_note_id is null or r.insurer_credit_note_id is null
    or r.premium_journal_entry_id is null or r.insurer_journal_entry_id is null
    or r.reissue_requested is distinct from (r.replacement_policy_id is not null)
    or not exists(select 1 from ins_policies where id=r.original_policy_id and status='reversed') then
    raise exception 'INS_REVERSAL_INCOMPLETE: reversal must be complete at commit';
  end if;
  return null;
end $$;


--
-- Name: ins_reversal_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reversal_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.outcome='posted' then raise exception 'INS_REVERSAL_IMMUTABLE: reversal audit cannot be changed'; end if;
  return new;
end $$;


--
-- Name: ins_reversal_journal_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reversal_journal_void_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status and (
    old.source_type='ins_policy_bind' or exists(select 1 from ins_policy_reversals
      where old.id in (premium_journal_entry_id,insurer_journal_entry_id))) then
    raise exception 'INS_REVERSAL_JOURNAL_LOCKED: use the policy workflow, not independent journal voids';
  end if;
  return new;
end $$;


--
-- Name: ins_reversal_note_void_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reversal_note_void_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status and exists(select 1 from ins_policy_reversals
    where old.id in (premium_credit_note_id,insurer_credit_note_id)) then
    raise exception 'INS_REVERSAL_NOTE_LOCKED: reversal credit notes cannot be voided independently';
  end if;
  return new;
end $$;


--
-- Name: ins_policy_reversals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_policy_reversals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    original_policy_id uuid NOT NULL,
    replacement_policy_id uuid,
    request_key uuid NOT NULL,
    reason text NOT NULL,
    reissue_requested boolean NOT NULL,
    accounting_treatment text NOT NULL,
    original_journal_entry_id uuid NOT NULL,
    premium_credit_note_id uuid,
    insurer_credit_note_id uuid,
    premium_journal_entry_id uuid,
    insurer_journal_entry_id uuid,
    reversed_by uuid DEFAULT auth.uid() NOT NULL,
    reversed_at timestamp with time zone DEFAULT now() NOT NULL,
    reversal_date date DEFAULT CURRENT_DATE NOT NULL,
    outcome text DEFAULT 'building'::text NOT NULL,
    operation_txid bigint DEFAULT txid_current() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ins_policy_reversals_accounting_treatment_check CHECK ((accounting_treatment = ANY (ARRAY['deferred'::text, 'legacy'::text, 'none'::text]))),
    CONSTRAINT ins_policy_reversals_outcome_check CHECK ((outcome = ANY (ARRAY['building'::text, 'posted'::text]))),
    CONSTRAINT ins_policy_reversals_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT ins_policy_reversals_reason_check CHECK ((length(btrim(reason)) >= 5))
);


--
-- Name: ins_reverse_policy(uuid, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reverse_policy(p_policy_id uuid, p_reason text, p_reissue boolean, p_request_key uuid) RETURNS public.ins_policy_reversals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p ins_policies%rowtype; r ins_policy_reversals%rowtype; c jsonb;
  cn fin_credit_notes%rowtype; draft ins_policies%rowtype;
  old_flag text := coalesce(current_setting('ins.via_rpc',true),'');
begin
  if not can_manage_insurance() or effective_user_id() is distinct from auth.uid() then
    raise exception 'INS_FORBIDDEN: insurance manager required; user-level impersonation cannot reverse policies' using errcode='42501';
  end if;
  if p_request_key is null or p_reissue is null or p_reason is null or length(btrim(p_reason))<5 then
    raise exception 'INS_REVERSAL_INPUT: request key, reissue choice and a reason of at least 5 characters are required';
  end if;
  select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  select * into r from ins_policy_reversals where original_policy_id=p.id;
  if found then
    if r.request_key=p_request_key and r.reason=btrim(p_reason) and r.reissue_requested=p_reissue and r.outcome='posted' then
      return r;
    end if;
    raise exception 'INS_REVERSAL_DUPLICATE: policy already reversed with a different request';
  end if;
  if exists(select 1 from ins_policy_reversals where tenant_id=p.tenant_id and request_key=p_request_key) then
    raise exception 'INS_REVERSAL_DUPLICATE: request key already used for another policy';
  end if;
  c:=ins_policy_reversal_context(p.id);
  insert into ins_policy_reversals(tenant_id,original_policy_id,request_key,reason,reissue_requested,
    accounting_treatment,original_journal_entry_id)
  values(p.tenant_id,p.id,p_request_key,btrim(p_reason),p_reissue,c->>'treatment',p.journal_entry_id)
  returning * into r;

  cn:=platform_fin_raise_policy_credit_note_impl(p.tenant_id,'ar_control',(c->>'client_party_id')::uuid,
    p.gross_premium,current_date,(c->>'offset_id')::uuid,
    jsonb_build_array(jsonb_build_object('open_item_id',c->>'premium_item_id','amount',p.gross_premium)),
    btrim(p_reason),p.policy_no,p.id);
  update ins_policy_reversals set premium_credit_note_id=cn.id,premium_journal_entry_id=cn.journal_entry_id where id=r.id;
  cn:=platform_fin_raise_policy_credit_note_impl(p.tenant_id,'insurer_payable',(c->>'insurer_party_id')::uuid,
    p.net_premium_to_insurer,current_date,(c->>'offset_id')::uuid,
    jsonb_build_array(jsonb_build_object('open_item_id',c->>'insurer_item_id','amount',p.net_premium_to_insurer)),
    btrim(p_reason),p.policy_no,p.id);
  update ins_policy_reversals set insurer_credit_note_id=cn.id,insurer_journal_entry_id=cn.journal_entry_id where id=r.id;

  -- Compare the aggregate inverse by actual account, not just total balance.
  if exists(
    select gl_account_id from journal_entry_lines
    where journal_entry_id in (p.journal_entry_id,
      (select premium_journal_entry_id from ins_policy_reversals where id=r.id),cn.journal_entry_id)
    group by gl_account_id having sum(debit-credit)<>0
  ) then raise exception 'INS_REVERSAL_BALANCE: reversal does not negate the original bind'; end if;
  if p_reissue then
    draft:=ins_create_policy(p.client_id,p.insurer_id,p.product_line_id,p.inception_date,p.expiry_date,
      p.sum_insured,p.currency,p.gross_premium,p.commission_rate_pct,p.risk_description,p.notes);
    update ins_policy_reversals set replacement_policy_id=draft.id where id=r.id;
  end if;
  update ins_policy_reversals set outcome='posted' where id=r.id returning * into r;
  perform set_config('ins.via_rpc','on',true);
  update ins_policies set status='reversed' where id=p.id;
  perform set_config('ins.via_rpc',old_flag,true);
  perform log_platform_event('insurance.policy.reverse',p.tenant_id,'ins_policy',p.id::text,btrim(p_reason),
    jsonb_build_object('status','active','journal',p.journal_entry_id),to_jsonb(r));
  return r;
end $$;


--
-- Name: ins_reversed_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_reversed_policy_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.status='reversed' and new.status is distinct from old.status then
    raise exception 'INS_REVERSAL_LOCKED: a reversed policy cannot be reactivated';
  end if;
  if new.status='reversed' and old.status<>'reversed' and not exists(
    select 1 from ins_policy_reversals where original_policy_id=new.id and tenant_id=new.tenant_id and outcome='posted'
  ) then raise exception 'INS_REVERSAL_RPC_ONLY: use ins_reverse_policy'; end if;
  return new;
end $$;


--
-- Name: ins_revise_claim_reserve(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_revise_claim_reserve(p_claim_id uuid, p_new_amount numeric, p_reason text) RETURNS public.ins_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_claim  ins_claims%rowtype;
  v_sum    numeric;
  v_new    numeric(18,2);
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  if p_new_amount is null or p_new_amount < 0 then
    raise exception 'INS_AMOUNT: the reserve cannot be negative';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 5 then
    raise exception 'INS_RESERVE_REASON: give a reason of at least 5 characters';
  end if;
  v_new := round(p_new_amount, 2);

  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: claim';
  end if;
  if v_claim.status not in ('notified', 'assessing', 'approved') then
    raise exception 'INS_CLAIM_STATE: the reserve of a % claim cannot be revised', v_claim.status;
  end if;
  if v_new = v_claim.reserve_amount then
    raise exception 'INS_RESERVE_UNCHANGED: the reserve is already %', v_claim.reserve_amount;
  end if;
  select sum_insured into v_sum from ins_policies where id = v_claim.policy_id and tenant_id = v_tenant;
  if coalesce(v_sum, 0) > 0 and v_new > v_sum then
    raise exception 'INS_AMOUNT: the reserve cannot exceed the policy sum insured';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_claim_reserve_history (tenant_id, claim_id, kind, previous_amount, new_amount, reason)
  values (v_tenant, v_claim.id, 'revision', v_claim.reserve_amount, v_new, btrim(p_reason));
  update ins_claims set reserve_amount = v_new where id = v_claim.id returning * into v_claim;
  return v_claim;
end $$;


--
-- Name: ins_intermediaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_intermediaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    code text NOT NULL,
    kind text DEFAULT 'business'::text NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    contact_email text,
    contact_phone text,
    parent_id uuid,
    licence_ref text,
    licence_authority text,
    licence_valid_from date,
    licence_valid_to date,
    appointment_ref text,
    authorisation_basis text,
    authorisation_reference text,
    status text DEFAULT 'pending_verification'::text NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    last_changed_by uuid DEFAULT auth.uid(),
    last_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    verified_by uuid,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ins_intermediaries_category_check CHECK ((category = ANY (ARRAY['insurer_appointed_agent'::text, 'independent_broker'::text, 'sub_agent'::text, 'referral_partner'::text]))),
    CONSTRAINT ins_intermediaries_kind_check CHECK ((kind = ANY (ARRAY['individual'::text, 'business'::text]))),
    CONSTRAINT ins_intermediaries_licence_dates_check CHECK (((licence_valid_to IS NULL) OR (licence_valid_from IS NULL) OR (licence_valid_to >= licence_valid_from))),
    CONSTRAINT ins_intermediaries_not_self_check CHECK (((parent_id IS NULL) OR (parent_id <> id))),
    CONSTRAINT ins_intermediaries_status_check CHECK ((status = ANY (ARRAY['pending_verification'::text, 'active'::text, 'suspended'::text, 'expired'::text, 'terminated'::text]))),
    CONSTRAINT ins_intermediaries_sub_parent_check CHECK (((category <> 'sub_agent'::text) OR (parent_id IS NOT NULL)))
);


--
-- Name: ins_save_intermediary(uuid, text, text, text, text, text, text, uuid, text, text, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_save_intermediary(p_id uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_kind text DEFAULT 'business'::text, p_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text, p_parent_id uuid DEFAULT NULL::uuid, p_licence_ref text DEFAULT NULL::text, p_licence_authority text DEFAULT NULL::text, p_licence_valid_from date DEFAULT NULL::date, p_licence_valid_to date DEFAULT NULL::date, p_appointment_ref text DEFAULT NULL::text, p_authorisation_basis text DEFAULT NULL::text, p_authorisation_reference text DEFAULT NULL::text) RETURNS public.ins_intermediaries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant  uuid := get_my_tenant_id();
  v_row     ins_intermediaries%rowtype;
  v_old     ins_intermediaries%rowtype;
  v_parent  ins_intermediaries%rowtype;
  v_code    text := nullif(btrim(p_code), '');
  v_name    text := nullif(btrim(p_name), '');
  v_ref     text := nullif(btrim(p_licence_ref), '');
  v_auth    text := nullif(btrim(p_licence_authority), '');
  v_appt    text := nullif(btrim(p_appointment_ref), '');
  v_basis   text := nullif(btrim(p_authorisation_basis), '');
  v_aref    text := nullif(btrim(p_authorisation_reference), '');
  v_email   text := nullif(btrim(p_contact_email), '');
  v_phone   text := nullif(btrim(p_contact_phone), '');
  v_changed boolean := false;
  v_status_before text;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers maintain intermediaries' using errcode = '42501';
  end if;

  if p_id is not null then
    select * into v_old from ins_intermediaries where id = p_id and tenant_id = v_tenant for update;
    if not found then
      raise exception 'INS_NOT_FOUND: intermediary';
    end if;
    if v_old.status = 'terminated' then
      raise exception 'INS_TERMINATED: a terminated intermediary cannot be changed';
    end if;
  end if;

  if v_code is null then raise exception 'INS_REQUIRED: give the intermediary a reference code'; end if;
  if v_name is null then raise exception 'INS_REQUIRED: give the intermediary a name'; end if;
  if p_kind not in ('individual', 'business') then raise exception 'INS_INVALID: kind must be individual or business'; end if;
  if p_category not in ('insurer_appointed_agent', 'independent_broker', 'sub_agent', 'referral_partner') then
    raise exception 'INS_INVALID: unknown category %', p_category;
  end if;

  -- Credentials. A referral partner needs none. Every other category needs a licence.
  if p_category <> 'referral_partner' then
    if v_ref is null or v_auth is null or p_licence_valid_to is null then
      raise exception 'INS_REQUIRED: a licence needs its reference, issuing authority and expiry date';
    end if;
    if p_licence_valid_to < current_date then
      raise exception 'INS_LICENCE_EXPIRED: the licence has already expired';
    end if;
    if p_licence_valid_from is not null and p_licence_valid_to < p_licence_valid_from then
      raise exception 'INS_INVALID: the licence expiry is before its start date';
    end if;
  end if;

  if p_category = 'insurer_appointed_agent' and v_appt is null then
    raise exception 'INS_REQUIRED: an insurer-appointed agent needs the insurer''s appointment reference';
  end if;

  -- Parent link.
  if p_category = 'sub_agent' then
    if p_parent_id is null then
      raise exception 'INS_PARENT_REQUIRED: a sub-agent must be placed under a parent intermediary';
    end if;
    if v_basis is null or v_aref is null then
      raise exception 'INS_AUTHORISATION_REQUIRED: record the basis on which the parent may appoint this sub-agent, and its reference';
    end if;
  end if;

  if p_parent_id is not null then
    select * into v_parent from ins_intermediaries where id = p_parent_id and tenant_id = v_tenant;
    if not found then
      raise exception 'INS_NOT_FOUND: parent intermediary';
    end if;
    if v_parent.status <> 'active' then
      raise exception 'INS_PARENT_NOT_ACTIVE: the parent must be verified and active before it can be linked (it is %)', v_parent.status;
    end if;
    if v_parent.category = 'referral_partner' then
      raise exception 'INS_PARENT_CATEGORY: a referral partner cannot appoint or be a parent';
    end if;
    if p_id is not null and ins_intermediary_chain_has(v_tenant, p_parent_id, p_id) then
      raise exception 'INS_CYCLE: that parent sits below this intermediary in the chain';
    end if;
  end if;

  if p_id is null then
    insert into ins_intermediaries (
      tenant_id, code, kind, name, category, contact_email, contact_phone, parent_id,
      licence_ref, licence_authority, licence_valid_from, licence_valid_to, appointment_ref,
      authorisation_basis, authorisation_reference, status, last_changed_by, last_changed_at)
    values (
      v_tenant, v_code, p_kind, v_name, p_category, v_email, v_phone, p_parent_id,
      v_ref, v_auth, p_licence_valid_from, p_licence_valid_to, v_appt,
      v_basis, v_aref, 'pending_verification', auth.uid(), now())
    returning * into v_row;

    insert into ins_intermediary_events (tenant_id, intermediary_id, action, to_status, note)
    values (v_tenant, v_row.id, 'created', 'pending_verification', null);
    return v_row;
  end if;

  -- Update. Any change to a credential, category or parent means it must be verified again.
  v_changed := (v_old.category, v_old.parent_id, v_old.licence_ref, v_old.licence_authority,
                v_old.licence_valid_from, v_old.licence_valid_to, v_old.appointment_ref,
                v_old.authorisation_basis, v_old.authorisation_reference)
               is distinct from
               (p_category, p_parent_id, v_ref, v_auth, p_licence_valid_from, p_licence_valid_to, v_appt,
                v_basis, v_aref);
  v_status_before := v_old.status;

  update ins_intermediaries set
    code = v_code, kind = p_kind, name = v_name, category = p_category,
    contact_email = v_email, contact_phone = v_phone, parent_id = p_parent_id,
    licence_ref = v_ref, licence_authority = v_auth,
    licence_valid_from = p_licence_valid_from, licence_valid_to = p_licence_valid_to,
    appointment_ref = v_appt, authorisation_basis = v_basis, authorisation_reference = v_aref,
    status = case when v_changed then 'pending_verification' else status end,
    verified_by = case when v_changed then null else verified_by end,
    verified_at = case when v_changed then null else verified_at end,
    last_changed_by = auth.uid(), last_changed_at = now(), updated_at = now()
  where id = p_id and tenant_id = v_tenant
  returning * into v_row;

  if v_changed then
    insert into ins_intermediary_events (tenant_id, intermediary_id, action, from_status, to_status, note)
    values (v_tenant, v_row.id, 'changed', v_status_before, 'pending_verification',
            'Credentials, category or parent changed: verification required again');
  else
    insert into ins_intermediary_events (tenant_id, intermediary_id, action, from_status, to_status, note)
    values (v_tenant, v_row.id, 'edited', v_status_before, v_status_before, 'Details edited');
  end if;
  return v_row;
end;
$$;


--
-- Name: ins_set_insurer_product_rate(uuid, uuid, numeric, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_set_insurer_product_rate(p_insurer_id uuid, p_product_line_id uuid, p_rate numeric, p_effective_from date, p_effective_to date DEFAULT NULL::date, p_source_ref text DEFAULT NULL::text) RETURNS public.ins_insurer_product_rates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_row    ins_insurer_product_rates%rowtype;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers maintain commission rates' using errcode = '42501';
  end if;
  if not exists (select 1 from ins_insurers where id = p_insurer_id and tenant_id = v_tenant and is_active) then
    raise exception 'INS_NOT_FOUND: active insurer';
  end if;
  if not exists (select 1 from ins_product_lines where id = p_product_line_id and tenant_id = v_tenant and is_active) then
    raise exception 'INS_NOT_FOUND: active product line';
  end if;
  if p_rate is null or p_rate < 0 or p_rate >= 100 then
    raise exception 'INS_RATE_VALUE: commission rate must be at least 0 and below 100';
  end if;
  if p_effective_from is null then
    raise exception 'INS_RATE_WINDOW: give the date the rate takes effect';
  end if;
  if p_effective_to is not null and p_effective_to < p_effective_from then
    raise exception 'INS_RATE_WINDOW: the end date cannot be before the start date';
  end if;
  if p_source_ref is null or btrim(p_source_ref) = '' then
    raise exception 'INS_RATE_SOURCE: record the agreement the rate comes from';
  end if;

  perform set_config('ins.via_rpc', 'on', true);
  insert into ins_insurer_product_rates (
    tenant_id, insurer_id, product_line_id, rate, effective_from, effective_to, source_ref
  ) values (
    v_tenant, p_insurer_id, p_product_line_id, p_rate, p_effective_from, p_effective_to, btrim(p_source_ref)
  )
  returning * into v_row;
  perform set_config('ins.via_rpc', 'off', true);
  return v_row;
end;
$$;


--
-- Name: ins_set_intermediary_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_set_intermediary_status(p_id uuid, p_to text, p_note text DEFAULT NULL::text) RETURNS public.ins_intermediaries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_row    ins_intermediaries%rowtype;
  v_from   text;
  v_note   text := nullif(btrim(p_note), '');
  v_active_children integer;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers change intermediary status' using errcode = '42501';
  end if;
  select * into v_row from ins_intermediaries where id = p_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: intermediary';
  end if;
  v_from := v_row.status;

  -- Moves allowed here. Pending to active is verification; expired to active needs re-verification.
  if not (
       (v_from = 'active' and p_to in ('suspended', 'expired', 'terminated'))
    or (v_from = 'suspended' and p_to in ('active', 'terminated'))
    or (v_from = 'expired' and p_to = 'terminated')
    or (v_from = 'pending_verification' and p_to = 'terminated')
  ) then
    raise exception 'INS_STATE: an intermediary cannot move from % to %', v_from, p_to;
  end if;

  if p_to in ('suspended', 'terminated') and v_note is null then
    raise exception 'INS_NOTE_REQUIRED: give the reason for suspending or terminating';
  end if;
  if p_to = 'suspended' and v_from = 'suspended' then
    raise exception 'INS_STATE: already suspended';
  end if;

  if p_to = 'expired' and (v_row.licence_valid_to is null or v_row.licence_valid_to >= current_date) then
    raise exception 'INS_NOT_EXPIRED: the licence has not passed its expiry date';
  end if;

  if p_to = 'active' and v_from = 'suspended' and v_row.licence_valid_to is not null and v_row.licence_valid_to < current_date then
    raise exception 'INS_LICENCE_EXPIRED: the licence has expired; renew it before reinstating';
  end if;

  if p_to = 'terminated' then
    select count(*) into v_active_children from ins_intermediaries
     where tenant_id = v_tenant and parent_id = v_row.id and status in ('active', 'suspended', 'pending_verification');
    if v_active_children > 0 then
      raise exception 'INS_HAS_SUBAGENTS: % sub-agent(s) still sit under this intermediary; end or move them first', v_active_children;
    end if;
  end if;

  update ins_intermediaries set status = p_to, updated_at = now() where id = v_row.id returning * into v_row;
  insert into ins_intermediary_events (tenant_id, intermediary_id, action, from_status, to_status, note)
  values (v_tenant, v_row.id, 'status', v_from, p_to, v_note);
  return v_row;
end;
$$;


--
-- Name: ins_set_policy_financial_configuration(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_set_policy_financial_configuration(p_policy_id uuid, p_shares jsonb, p_charges jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p ins_policies%rowtype; x jsonb; lead_id uuid; n integer; total numeric;
begin
 if not can_manage_insurance() or effective_user_id() is distinct from auth.uid() then
   raise exception 'INS_FORBIDDEN: an Insurance manager acting as themselves is required' using errcode='42501';
 end if;
 select * into p from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 if p.status<>'draft' then raise exception 'INS_FINANCIAL_IMMUTABLE: only drafts can be configured'; end if;
 if jsonb_typeof(p_shares) is distinct from 'array' or jsonb_typeof(p_charges) is distinct from 'array'
    or jsonb_array_length(p_shares)>30 or jsonb_array_length(p_charges)>100 then raise exception 'INS_CONFIG_INPUT: invalid configuration arrays'; end if;
 -- Existing IDs are draft-only; bound IDs never change and are used by allocations.
 delete from ins_policy_charges where policy_id=p.id;
 delete from ins_policy_insurer_shares where policy_id=p.id;
 for x in select * from jsonb_array_elements(p_shares) loop
   if (x->>'share_pct')::numeric is null or (x->>'share_pct')::numeric<>round((x->>'share_pct')::numeric,4)
      or (x->>'commission_rate_pct')::numeric is null or (x->>'commission_rate_pct')::numeric<>round((x->>'commission_rate_pct')::numeric,4)
      or not exists(select 1 from ins_insurers where id=(x->>'insurer_id')::uuid and tenant_id=p.tenant_id and is_active) then
     raise exception 'INS_CONFIG_INPUT: active insurer, share and commission rate are required (maximum four decimals)';
   end if;
   insert into ins_policy_insurer_shares(tenant_id,policy_id,insurer_id,is_lead,share_pct,commission_rate_pct,insurer_policy_no,reviewed)
   values(p.tenant_id,p.id,(x->>'insurer_id')::uuid,coalesce((x->>'is_lead')::boolean,false),
    (x->>'share_pct')::numeric,(x->>'commission_rate_pct')::numeric,nullif(btrim(x->>'insurer_policy_no'),''),coalesce((x->>'reviewed')::boolean,false));
 end loop;
 select count(*) filter(where is_lead),sum(share_pct) into n,total from ins_policy_insurer_shares where policy_id=p.id;
 if jsonb_array_length(p_shares)>0 and (n<>1 or total<>100) then raise exception 'INS_SHARE_TOTAL: shares must total exactly 100%% with exactly one lead insurer'; end if;
 if jsonb_array_length(p_shares)=0 and jsonb_array_length(p_charges)>0 then raise exception 'INS_SHARE_REQUIRED: charges require explicit insurer allocation'; end if;
 for x in select * from jsonb_array_elements(p_charges) loop
   if (x->>'amount')::numeric is not null and ((x->>'amount')::numeric<>round((x->>'amount')::numeric,2) or (x->>'amount')::numeric>9999999999999999.99) then
     raise exception 'INS_CONFIG_INPUT: charge amounts need at most two decimals';
   end if;
   if (x->>'vat_rate_pct')::numeric is not null and (x->>'vat_rate_pct')::numeric<>round((x->>'vat_rate_pct')::numeric,4) then
     raise exception 'INS_CONFIG_INPUT: VAT rate accepts at most four decimals';
   end if;
   if x->>'recipient_mode'='one_insurer' and not exists(select 1 from ins_policy_insurer_shares where policy_id=p.id and insurer_id=(x->>'recipient_insurer_id')::uuid) then
     raise exception 'INS_CHARGE_RECIPIENT: intended insurer must participate in this policy';
   end if;
   insert into ins_policy_charges(tenant_id,policy_id,kind,description,amount,recipient_mode,recipient_insurer_id,vat_mode,vat_rate_pct,income_gl_account_id,reviewed)
   values(p.tenant_id,p.id,x->>'kind',x->>'description',(x->>'amount')::numeric,x->>'recipient_mode',(x->>'recipient_insurer_id')::uuid,
    coalesce(x->>'vat_mode','not_calculated'),(x->>'vat_rate_pct')::numeric,(x->>'income_gl_account_id')::uuid,coalesce((x->>'reviewed')::boolean,false));
 end loop;
 select insurer_id into lead_id from ins_policy_insurer_shares where policy_id=p.id and is_lead;
 if lead_id is not null then
   perform set_config('ins.via_rpc','on',true);
   update ins_policies set insurer_id=lead_id,
    commission_rate_pct=case when jsonb_array_length(p_shares)=1 then (select commission_rate_pct from ins_policy_insurer_shares where policy_id=p.id) else commission_rate_pct end
    where id=p.id;
 end if;
end $$;


--
-- Name: ins_set_risk_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_set_risk_status(p_risk_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  if p_status not in ('active', 'inactive') then raise exception 'INS_INPUT: status must be active or inactive'; end if;
  update ins_risks set status = p_status where id = p_risk_id and tenant_id = get_my_tenant_id();
  if not found then raise exception 'INS_NOT_FOUND: risk'; end if;
end $$;


--
-- Name: ins_share_cash_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_share_cash_totals(p_share_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 with s as(select * from ins_policy_insurer_shares where id=p_share_id),
 cash as(select coalesce(sum(a.amount),0) as collected from s join fin_open_items i on i.source_id=s.policy_id and i.source_type='ins_policy_premium' and i.tenant_id=s.tenant_id
   join fin_allocations a on a.open_item_id=i.id join fin_settlements f on f.id=a.settlement_id and f.status='posted' and f.direction='in'),
 item as(select i.id,i.amount from s join fin_open_items i on i.source_id=s.id and i.source_type='ins_policy_share_insurer' and i.tenant_id=s.tenant_id),
 paid as(select coalesce(sum(a.amount),0) as amount from item i join fin_allocations a on a.open_item_id=i.id join fin_settlements f on f.id=a.settlement_id and f.status='posted' and f.direction='out'),
 withdrawn as(select coalesce(sum(e.amount),0) as amount from s join ins_commission_entries e on e.insurer_share_id=s.id and e.status='transferred'
   join ins_commission_transfers t on t.id=e.transfer_id and t.status='posted'),
 calc as(select s.*,c.collected,p.amount as remitted,w.amount as withdrawn,
   trunc((s.premium_amount+s.pass_through_amount)*least(c.collected/nullif(sn.invoice_total,0),1),2) as funded,
   coalesce((select outstanding_amount from fin_open_item_balances where id=(select id from item)),0) as outstanding
   from s cross join cash c cross join paid p cross join withdrawn w join ins_policy_financial_snapshots sn on sn.policy_id=s.policy_id)
 select jsonb_build_object('share_id',id,'insurer_id',insurer_id,'share_pct',share_pct,'premium_amount',premium_amount,
  'pass_through_amount',pass_through_amount,'commission_amount',commission_amount,'funded',funded,'remitted',remitted,
  'commission_transferred',withdrawn,'available_allocated_funds',greatest(funded-remitted-withdrawn,0),
  'outstanding',outstanding,'maximum_remittance',least(greatest(funded-remitted-withdrawn,0),greatest(outstanding,0))) from calc;
$$;


--
-- Name: ins_submit_cancellation_cash(uuid, text, uuid, uuid, uuid, numeric, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_submit_cancellation_cash(p_cancellation_id uuid, p_kind text, p_adjustment_id uuid, p_bank_account_id uuid, p_to_bank_account_id uuid, p_amount numeric, p_cash_date date, p_reference text, p_notes text, p_request_key uuid) RETURNS public.ins_cancellation_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_cancellation_cash_requests%rowtype; c ins_policy_cancellations%rowtype;
begin
 perform ins_policy_cash_require_finance();
 select * into c from ins_policy_cancellations where id=p_cancellation_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: cancellation'; end if;
 perform id from ins_policies where id=c.policy_id for update;
 select * into q from ins_cancellation_cash_requests where tenant_id=c.tenant_id and request_key=p_request_key;
 if found then
 if q.maker_id<>auth.uid() or (q.cancellation_id,q.kind,q.adjustment_id,q.bank_account_id,q.to_bank_account_id,q.amount,q.cash_date,q.reference,q.notes) is distinct from
 (p_cancellation_id,p_kind,p_adjustment_id,p_bank_account_id,p_to_bank_account_id,p_amount,p_cash_date,btrim(p_reference),btrim(p_notes)) then raise exception 'INS_CXL_CASH_RETRY: request key belongs to different inputs'; end if;
 return q; end if;
 if p_request_key is null or p_reference is null or length(btrim(p_reference)) not between 3 and 200 or p_notes is null or length(btrim(p_notes)) not between 5 and 2000 then raise exception 'INS_CXL_CASH_INPUT: request key, reference and detailed purpose required'; end if;
 perform platform_ins_cancellation_cash_validate(c.id,p_kind,p_adjustment_id,p_bank_account_id,p_to_bank_account_id,p_amount,p_cash_date);
 insert into ins_cancellation_cash_requests(tenant_id,cancellation_id,kind,adjustment_id,bank_account_id,to_bank_account_id,amount,cash_date,reference,notes,request_key,maker_id)
 values(c.tenant_id,c.id,p_kind,p_adjustment_id,p_bank_account_id,p_to_bank_account_id,p_amount,p_cash_date,btrim(p_reference),btrim(p_notes),p_request_key,auth.uid()) returning * into q;
 insert into ins_cancellation_cash_events(tenant_id,request_id,event,actor_id) values(c.tenant_id,q.id,'submitted',auth.uid());
 return q;
end $$;


--
-- Name: ins_submit_cancellation_cash_void(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_submit_cancellation_cash_void(p_request_id uuid, p_reason text, p_request_key uuid) RETURNS public.ins_cancellation_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare target ins_cancellation_cash_requests%rowtype; q ins_cancellation_cash_requests%rowtype;
begin
 perform ins_policy_cash_require_finance();
 select * into target from ins_cancellation_cash_requests where id=p_request_id and tenant_id=get_my_tenant_id();
 if not found then raise exception 'INS_NOT_FOUND: cash request'; end if;
 perform p.id from ins_policies p join ins_policy_cancellations c on c.policy_id=p.id where c.id=target.cancellation_id for update of p;
 select * into q from ins_cancellation_cash_requests where tenant_id=target.tenant_id and request_key=p_request_key;
 if found then if q.maker_id<>auth.uid() or q.voids_request_id is distinct from target.id or q.notes is distinct from btrim(p_reason) then raise exception 'INS_CXL_CASH_RETRY: different void inputs'; end if; return q; end if;
 if target.kind='void' or target.status<>'posted' or p_request_key is null or p_reason is null or length(btrim(p_reason)) not between 5 and 2000 then raise exception 'INS_CXL_CASH_VOID: posted cash and detailed reason required'; end if;
 insert into ins_cancellation_cash_requests(tenant_id,cancellation_id,kind,adjustment_id,bank_account_id,to_bank_account_id,amount,cash_date,reference,notes,request_key,maker_id,voids_request_id)
 values(target.tenant_id,target.cancellation_id,'void',target.adjustment_id,target.bank_account_id,target.to_bank_account_id,target.amount,current_date,'Void '||target.id,btrim(p_reason),p_request_key,auth.uid(),target.id) returning * into q;
 insert into ins_cancellation_cash_events(tenant_id,request_id,event,actor_id) values(q.tenant_id,q.id,'void_requested',auth.uid()); return q;
end $$;


--
-- Name: ins_submit_policy_cancellation(uuid, date, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_submit_policy_cancellation(p_policy_id uuid, p_effective_date date, p_insurer_terms jsonb, p_charge_refunds jsonb, p_reason text, p_request_key uuid) RETURNS public.ins_policy_cancellations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare c ins_policy_cancellations%rowtype; quote jsonb;
begin
 if auth.uid() is null or effective_user_id() is distinct from auth.uid() or not(can_manage_insurance() or is_finance_team_member('finance')) then
  raise exception 'INS_FORBIDDEN: Insurance manager or Finance acting as themselves required' using errcode='42501'; end if;
 if p_request_key is null or p_reason is null or length(btrim(p_reason)) not between 5 and 2000 then raise exception 'INS_CANCELLATION_INPUT: request key and reason required'; end if;
 perform id from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 select * into c from ins_policy_cancellations where tenant_id=get_my_tenant_id() and request_key=p_request_key;
 if found then
  if c.proposed_by<>auth.uid() or c.policy_id is distinct from p_policy_id or c.effective_date is distinct from p_effective_date or c.insurer_terms is distinct from p_insurer_terms
   or c.charge_refunds is distinct from p_charge_refunds or c.reason is distinct from btrim(p_reason) then raise exception 'INS_CANCELLATION_RETRY_CONFLICT: different payload'; end if;
  return c;
 end if;
 quote:=ins_preview_policy_cancellation(p_policy_id,p_effective_date,p_insurer_terms,p_charge_refunds);
 if exists(select 1 from ins_policy_cancellations where policy_id=p_policy_id and status in('proposed','prepared','posting','posted')) then raise exception 'INS_CANCELLATION_EXISTS: a live proposal or posted cancellation already exists'; end if;
 insert into ins_policy_cancellations(tenant_id,policy_id,request_key,reason,effective_date,insurer_terms,charge_refunds,proposed_by,calculation)
 values(get_my_tenant_id(),p_policy_id,p_request_key,btrim(p_reason),p_effective_date,p_insurer_terms,p_charge_refunds,auth.uid(),quote) returning * into c;
 insert into ins_cancellation_events(tenant_id,cancellation_id,event,actor_id) values(c.tenant_id,c.id,'proposed',auth.uid());
 return c;
end $$;


--
-- Name: ins_submit_policy_cash_request(uuid, text, uuid, numeric, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_submit_policy_cash_request(p_policy_id uuid, p_kind text, p_bank_account_id uuid, p_amount numeric, p_cash_date date, p_request_key uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_policy_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_policy_cash_requests%rowtype;
begin
  perform ins_policy_cash_require_finance();
  if p_request_key is null then raise exception 'INS_CASH_INPUT: request key required'; end if;
  -- The policy lock also serializes equal retry keys for this policy.
  perform id from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  select * into q from ins_policy_cash_requests where tenant_id=get_my_tenant_id() and request_key=p_request_key;
  if found then
    if q.maker_id<>auth.uid() or q.policy_id<>p_policy_id or q.kind is distinct from p_kind
       or q.bank_account_id is distinct from p_bank_account_id or q.amount is distinct from p_amount
       or q.cash_date is distinct from p_cash_date or q.reference is distinct from nullif(btrim(p_reference),'')
       or q.notes is distinct from nullif(btrim(p_notes),'') then
      raise exception 'INS_CASH_RETRY_CONFLICT: request key already used with a different payload';
    end if;
    return q;
  end if;
  perform ins_policy_cash_validate(p_policy_id,p_kind,p_bank_account_id,p_amount,p_cash_date);
  insert into ins_policy_cash_requests(tenant_id,policy_id,kind,bank_account_id,amount,cash_date,request_key,reference,notes,maker_id)
  values(get_my_tenant_id(),p_policy_id,p_kind,p_bank_account_id,p_amount,p_cash_date,p_request_key,
    nullif(btrim(p_reference),''),nullif(btrim(p_notes),''),auth.uid()) returning * into q;
  return q;
end $$;


--
-- Name: ins_submit_policy_share_cash_request(uuid, uuid, uuid, numeric, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_submit_policy_share_cash_request(p_policy_id uuid, p_insurer_share_id uuid, p_bank_account_id uuid, p_amount numeric, p_cash_date date, p_request_key uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.ins_policy_cash_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare q ins_policy_cash_requests%rowtype;
begin
 perform ins_policy_cash_require_finance();
 if p_request_key is null then raise exception 'INS_CASH_INPUT: request key required'; end if;
 perform id from ins_policies where id=p_policy_id and tenant_id=get_my_tenant_id() for update;
 if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
 select * into q from ins_policy_cash_requests where tenant_id=get_my_tenant_id() and request_key=p_request_key;
 if found then
  if q.maker_id<>auth.uid() or q.policy_id<>p_policy_id or q.kind<>'remittance' or q.insurer_share_id is distinct from p_insurer_share_id
   or q.bank_account_id is distinct from p_bank_account_id or q.amount is distinct from p_amount or q.cash_date is distinct from p_cash_date
   or q.reference is distinct from nullif(btrim(p_reference),'') or q.notes is distinct from nullif(btrim(p_notes),'') then raise exception 'INS_CASH_RETRY_CONFLICT: request key already used'; end if;
  return q;
 end if;
 perform ins_policy_cash_validate(p_policy_id,'remittance',p_bank_account_id,p_amount,p_cash_date,p_insurer_share_id);
 insert into ins_policy_cash_requests(tenant_id,policy_id,kind,insurer_share_id,bank_account_id,amount,cash_date,request_key,reference,notes,maker_id)
 values(get_my_tenant_id(),p_policy_id,'remittance',p_insurer_share_id,p_bank_account_id,p_amount,p_cash_date,p_request_key,nullif(btrim(p_reference),''),nullif(btrim(p_notes),''),auth.uid()) returning * into q;
 return q;
end $$;


--
-- Name: ins_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: ins_commission_transfers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ins_commission_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    transfer_no text NOT NULL,
    from_bank_account_id uuid NOT NULL,
    to_bank_account_id uuid NOT NULL,
    transfer_date date NOT NULL,
    amount numeric(18,2) NOT NULL,
    currency text NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    notes text,
    journal_entry_id uuid,
    void_journal_entry_id uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT ins_commission_transfers_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT ins_commission_transfers_banks_differ CHECK ((from_bank_account_id <> to_bank_account_id)),
    CONSTRAINT ins_commission_transfers_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT ins_commission_transfers_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'void'::text]))),
    CONSTRAINT ins_commission_transfers_void_check CHECK ((((status = 'posted'::text) AND (void_journal_entry_id IS NULL) AND (voided_at IS NULL)) OR ((status = 'void'::text) AND (void_journal_entry_id IS NOT NULL) AND (voided_at IS NOT NULL))))
);


--
-- Name: ins_transfer_earned_commission(uuid, uuid, date, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_transfer_earned_commission(p_from_bank_account_id uuid, p_to_bank_account_id uuid, p_transfer_date date, p_entry_ids uuid[] DEFAULT NULL::uuid[], p_notes text DEFAULT NULL::text) RETURNS public.ins_commission_transfers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
 if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: insurance manager required' using errcode='42501'; end if;
 perform p.id from ins_policies p where p.tenant_id=get_my_tenant_id() and exists(select 1 from ins_commission_entries e where e.policy_id=p.id and e.status='earned' and (p_entry_ids is null or e.id=any(p_entry_ids))) order by p.id for update;
 return platform_ins_transfer_before_cancellation_impl(p_from_bank_account_id,p_to_bank_account_id,p_transfer_date,p_entry_ids,p_notes);
end $$;


--
-- Name: ins_transition_claim(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_transition_claim(p_claim_id uuid, p_to text, p_note text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric) RETURNS public.ins_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant     uuid := get_my_tenant_id();
  v_claim      ins_claims%rowtype;
  v_from       text;
  v_sum        numeric;
  v_insurer    uuid;
  v_client     uuid;
  v_mode       text;
  v_legal      boolean;
  v_live_pays  integer;
begin
  if not can_access_insurance() then
    raise exception 'INS_FORBIDDEN: insurance access required' using errcode = '42501';
  end if;
  select * into v_claim from ins_claims where id = p_claim_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: claim';
  end if;
  v_from := v_claim.status;

  if p_to in ('approved', 'settled', 'repudiated', 'closed') and not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers decide claims' using errcode = '42501';
  end if;

  v_legal := (v_from, p_to) in (
    ('notified', 'assessing'), ('notified', 'repudiated'),
    ('assessing', 'approved'), ('assessing', 'repudiated'),
    ('approved', 'settled'), ('approved', 'assessing'),
    ('settled', 'closed'), ('repudiated', 'closed')
  );
  if not v_legal then
    raise exception 'INS_CLAIM_TRANSITION: a claim cannot move from % to %', v_from, p_to;
  end if;

  if p_to = 'repudiated' and nullif(btrim(p_note), '') is null then
    raise exception 'INS_NOTE_REQUIRED: give the reason for repudiating the claim';
  end if;

  -- Un-approval: manager only, reason required, and only before anything was recognised or paid.
  if v_from = 'approved' and p_to = 'assessing' then
    if not can_manage_insurance() then
      raise exception 'INS_FORBIDDEN: only insurance admins and managers un-approve claims' using errcode = '42501';
    end if;
    if nullif(btrim(p_note), '') is null then
      raise exception 'INS_NOTE_REQUIRED: give the reason for un-approving the claim';
    end if;
    if v_claim.recognised_at is not null then
      raise exception 'INS_CLAIM_RECOGNISED: this claim''s receivable is recognised, so it cannot be un-approved';
    end if;
    select count(*) into v_live_pays from ins_claim_payments
     where claim_id = v_claim.id and tenant_id = v_tenant and voided_at is null;
    if v_claim.paid_amount <> 0 or v_live_pays > 0 then
      raise exception 'INS_CLAIM_PAID: this claim has payments recorded, so it cannot be un-approved';
    end if;
  end if;

  -- Segregation of duties: the registrant cannot approve their own claim.
  if p_to = 'approved' and v_claim.created_by is not null and v_claim.created_by = auth.uid() then
    raise exception 'INS_SEGREGATION: the person who registered this claim cannot approve it; another manager must';
  end if;

  perform set_config('ins.via_rpc', 'on', true);

  if p_to = 'approved' then
    if p_amount is null or p_amount <= 0 then
      raise exception 'INS_AMOUNT: approved amount must be greater than zero';
    end if;
    select p.sum_insured, p.insurer_id, p.client_id into v_sum, v_insurer, v_client
      from ins_policies p where p.id = v_claim.policy_id;
    if v_sum > 0 and p_amount > v_sum then
      raise exception 'INS_AMOUNT: approved amount exceeds the policy sum insured';
    end if;
    select i.claim_payment_mode into v_mode from ins_insurers i where i.id = v_insurer and i.tenant_id = v_tenant;
    v_mode := coalesce(v_mode, 'insurer_direct');

    -- Approval does not create a receivable or payable. For a brokerage-managed claim
    -- the claim is 'approved, pending settlement' until ins_recognise_claim_receivable.
    update ins_claims set status = 'approved', approved_amount = p_amount, payment_mode = v_mode
     where id = v_claim.id returning * into v_claim;
  elsif p_to = 'assessing' and v_from = 'approved' then
    -- Un-approval clears the decision. Nothing was posted, so nothing needs reversing.
    update ins_claims set status = 'assessing', approved_amount = null, payment_mode = null
     where id = v_claim.id returning * into v_claim;
  elsif p_to = 'settled' then
    if v_claim.paid_amount < coalesce(v_claim.approved_amount, 0) then
      raise exception 'INS_CLAIM_PAYMENT_REQUIRED: a claim settles when its payments cover the approved amount; record the payments instead';
    end if;
    update ins_claims set status = 'settled', settled_at = coalesce(settled_at, now())
     where id = v_claim.id returning * into v_claim;
  else
    update ins_claims set status = p_to
     where id = v_claim.id returning * into v_claim;
  end if;

  insert into ins_claim_events (tenant_id, claim_id, from_status, to_status, note)
  values (v_tenant, v_claim.id, v_from, p_to, nullif(btrim(p_note), ''));
  return v_claim;
end;
$$;


--
-- Name: ins_unlink_policy_risk(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_unlink_policy_risk(p_policy_id uuid, p_risk_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare t uuid := get_my_tenant_id(); st text;
begin
  if not can_manage_insurance() then raise exception 'INS_FORBIDDEN: Insurance manager required' using errcode = '42501'; end if;
  select status into st from ins_policies where id = p_policy_id and tenant_id = t for update;
  if not found then raise exception 'INS_NOT_FOUND: policy'; end if;
  if st <> 'draft' then raise exception 'INS_NOT_DRAFT: risks can only be unlinked from a draft policy'; end if;
  update ins_certificate_stock set policy_id = null
   where tenant_id = t and policy_id = p_policy_id and risk_id = p_risk_id and status = 'issued';
  delete from ins_policy_risks where tenant_id = t and policy_id = p_policy_id and risk_id = p_risk_id;
end $$;


--
-- Name: ins_unremitted_premium_report(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_unremitted_premium_report(p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(policy_id uuid, policy_no text, insurer_id uuid, unremitted_amount numeric, receipt_date date, deadline_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant  uuid := get_my_tenant_id();
  p         record;
  v_avail   numeric;
  v_receipt date;
  v_due     date;
  v_status  text;
begin
  if not has_module_role('insurance', array['admin', 'manager', 'member']) then
    raise exception 'INS_FORBIDDEN: insurance access is required' using errcode = '42501';
  end if;

  for p in
    select ip.id, ip.policy_no, ip.insurer_id
      from public.ins_policies ip
     where ip.tenant_id = v_tenant
       and ip.status in ('active', 'renewed')
  loop
    v_avail := coalesce((public.ins_policy_cash_totals(p.id) ->> 'available_allocated_funds')::numeric, 0);
    continue when v_avail <= 0;

    select min(s.settlement_date) into v_receipt
      from public.fin_open_items i
      join public.fin_allocations a on a.open_item_id = i.id
      join public.fin_settlements s on s.id = a.settlement_id
       and s.status = 'posted' and s.direction = 'in'
     where i.tenant_id = v_tenant
       and i.source_type = 'ins_policy_premium'
       and i.source_id = p.id;

    v_due := public.ins_remittance_due_date(v_tenant, v_receipt);

    v_status := case
      when v_receipt is null then 'receipt_date_missing'
      when v_due is null then 'deadline_not_set'
      when v_due < p_as_of then 'overdue'
      when v_due = p_as_of then 'due_today'
      else 'within_deadline'
    end;

    policy_id := p.id;
    policy_no := p.policy_no;
    insurer_id := p.insurer_id;
    unremitted_amount := v_avail;
    receipt_date := v_receipt;
    deadline_date := v_due;
    status := v_status;
    return next;
  end loop;
end;
$$;


--
-- Name: ins_verify_intermediary(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ins_verify_intermediary(p_id uuid, p_note text DEFAULT NULL::text) RETURNS public.ins_intermediaries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
  v_row    ins_intermediaries%rowtype;
  v_parent_status text;
begin
  if not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: only insurance admins and managers verify intermediaries' using errcode = '42501';
  end if;
  select * into v_row from ins_intermediaries where id = p_id and tenant_id = v_tenant for update;
  if not found then
    raise exception 'INS_NOT_FOUND: intermediary';
  end if;
  if v_row.status <> 'pending_verification' then
    raise exception 'INS_STATE: only a pending intermediary can be verified (this one is %)', v_row.status;
  end if;
  if v_row.last_changed_by is not null and v_row.last_changed_by = auth.uid() then
    raise exception 'INS_SEGREGATION: the person who last changed this record cannot verify it; another manager must';
  end if;
  if v_row.licence_valid_to is not null and v_row.licence_valid_to < current_date then
    raise exception 'INS_LICENCE_EXPIRED: the licence has expired, so the intermediary cannot be verified';
  end if;
  if v_row.parent_id is not null then
    select status into v_parent_status from ins_intermediaries where id = v_row.parent_id and tenant_id = v_tenant;
    if v_parent_status is distinct from 'active' then
      raise exception 'INS_PARENT_NOT_ACTIVE: the parent must be active before this sub-agent can be verified';
    end if;
  end if;

  update ins_intermediaries set status = 'active', verified_by = auth.uid(), verified_at = now(), updated_at = now()
   where id = v_row.id returning * into v_row;
  insert into ins_intermediary_events (tenant_id, intermediary_id, action, from_status, to_status, note)
  values (v_tenant, v_row.id, 'verified', 'pending_verification', 'active', nullif(btrim(p_note), ''));
  return v_row;
end;
$$;


