--
-- Name: link_ticket_to_problem(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_ticket_to_problem(p_problem_id uuid, p_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant uuid := get_my_tenant_id();
begin
  if not is_it_support() then
    raise exception 'not authorized to link tickets to problems';
  end if;
  if not exists (select 1 from problems where id = p_problem_id and tenant_id = v_tenant) then
    raise exception 'problem not found';
  end if;
  if not exists (select 1 from it_tickets where id = p_ticket_id and tenant_id = v_tenant) then
    raise exception 'ticket not found';
  end if;

  insert into problem_tickets (problem_id, ticket_id, tenant_id)
  values (p_problem_id, p_ticket_id, v_tenant)
  on conflict do nothing;
end;
$$;


--
-- Name: link_vendor_account_on_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_vendor_account_on_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid;
begin
  if NEW.vendor_account_id is null then
    select tenant_id into v_tenant_id from requests where id = NEW.request_id;
    NEW.vendor_account_id := resolve_or_create_vendor_account(v_tenant_id, NEW.vendor_name);
  end if;
  return NEW;
end;
$$;


--
-- Name: list_feature_flags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_feature_flags() RETURNS TABLE(key text, description text, default_enabled boolean, updated_at timestamp with time zone, tenants_on bigint, tenants_off bigint, overrides jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select f.key, f.description, f.default_enabled, f.updated_at,
    (select count(*) from tenant_feature_flags tf where tf.flag_key = f.key and tf.enabled),
    (select count(*) from tenant_feature_flags tf where tf.flag_key = f.key and not tf.enabled),
    (select coalesce(jsonb_agg(jsonb_build_object('tenant_id', tf.tenant_id, 'tenant_name', t.name, 'enabled', tf.enabled, 'note', tf.note, 'updated_at', tf.updated_at) order by t.name), '[]'::jsonb)
       from tenant_feature_flags tf join tenants t on t.id = tf.tenant_id where tf.flag_key = f.key)
  from platform_feature_flags f
  where public.platform_admin_mfa_gate('list feature flags')
  order by f.key;
$$;


--
-- Name: list_impersonation_history(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_impersonation_history(p_tenant_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, platform_admin_id uuid, platform_admin_email text, tenant_id uuid, tenant_name text, reason text, started_at timestamp with time zone, ended_at timestamp with time zone, expires_at timestamp with time zone, is_active boolean, impersonated_user_id uuid, impersonated_user_email text, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    s.id,
    s.platform_admin_id,
    u.email,
    s.tenant_id,
    t.name,
    s.reason,
    s.started_at,
    s.ended_at,
    s.expires_at,
    (s.ended_at is null and s.expires_at > now()) as is_active,
    s.impersonated_user_id,
    iu.email,
    count(*) over () as total_count
  from impersonation_sessions s
  join tenants t on t.id = s.tenant_id
  left join auth.users u on u.id = s.platform_admin_id
  left join app_users iu on iu.id = s.impersonated_user_id
  where public.platform_admin_mfa_gate('list impersonation history')
    and (p_tenant_id is null or s.tenant_id = p_tenant_id)
  order by s.started_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 500))
  offset greatest(0, coalesce(p_offset, 0));
$$;


--
-- Name: list_industry_templates(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_industry_templates(p_include_inactive boolean DEFAULT false) RETURNS TABLE(key text, name text, description text, is_active boolean, is_default boolean, sort_order integer, updated_at timestamp with time zone, department_count integer, module_count integer, stage_count integer, tenants_using bigint, items jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    t.key, t.name, t.description, t.is_active, t.is_default, t.sort_order, t.updated_at,
    (select count(*) from industry_template_items i where i.template_key = t.key and i.kind = 'department')::integer,
    (select count(*) from industry_template_items i where i.template_key = t.key and i.kind = 'module')::integer,
    (select count(*) from industry_template_items i where i.template_key = t.key and i.kind = 'workflow_stage')::integer,
    (select count(*) from tenants x where x.industry_template = t.key),
    (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'sort_order', i.sort_order, 'name', i.name, 'payload', i.payload)
                                order by i.kind, i.sort_order), '[]'::jsonb)
       from industry_template_items i where i.template_key = t.key)
  from industry_templates t
  where public.platform_admin_mfa_gate('list industry templates')
    and (p_include_inactive or t.is_active)
  order by t.sort_order, t.name;
$$;


--
-- Name: list_my_approval_surfaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_approval_surfaces() RETURNS TABLE(surface_key text, label text, route text, pending_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH my_assignment AS (
    -- Same "am I on the hook for something in the generic workflow
    -- engine" signal get_my_approval_queue()/get_my_invoice_approval_queue()
    -- rely on: a direct approval_assignments row, or an active delegation
    -- from someone who has one. Backs both the Request/Offer queue and
    -- the Invoice queue, since both draw candidate items via the same
    -- workflow_stage_id -> approval_assignments join, just against
    -- different base tables (requests vs invoice_requests).
    SELECT EXISTS (
      SELECT 1 FROM approval_assignments WHERE user_id = auth.uid()
      UNION ALL
      SELECT 1 FROM approval_delegations d
      JOIN approval_assignments aa ON aa.user_id = d.delegator_user_id
      WHERE d.delegate_user_id = auth.uid()
        AND d.status = 'active'
        AND now() BETWEEN d.starts_at AND d.ends_at
        AND (d.workflow_stage_id IS NULL OR d.workflow_stage_id = aa.workflow_stage_id)
    ) AS is_assigned
  )
  SELECT 'request_approvals', 'Approval Queue', '/approvals',
         (SELECT count(*)::int FROM get_my_approval_queue())
  WHERE (SELECT is_assigned FROM my_assignment)
  UNION ALL
  SELECT 'invoice_approvals', 'Invoice Approval Queue', '/multiplexing/approvals',
         (SELECT count(*)::int FROM get_my_invoice_approval_queue())
  WHERE (SELECT is_assigned FROM my_assignment)
  UNION ALL
  SELECT 'material_request_approvals', 'Material Request Approvals', '/approvals/material-requests',
         (SELECT coalesce(sum(pending_item_count), 0)::int FROM get_pending_material_request_batches())
  WHERE public.am_i_finance()
  UNION ALL
  SELECT 'sap_payment_recording', 'SAP Payment Recording', '/sap/payment-approvals', NULL
  WHERE public.can_access_finance()
  UNION ALL
  SELECT 'ticket_approvals', 'IT Ticket Approvals', '/it-support/approvals',
         (SELECT count(*)::int FROM it_tickets
          WHERE tenant_id = get_my_tenant_id() AND approval_status = 'pending')
  WHERE public.has_module_role('it', ARRAY['admin','manager'])
  UNION ALL
  SELECT 'proposal_approvals', 'Proposal Approvals', '/business-development/proposals/approvals',
         (SELECT count(*)::int FROM bd_proposals
          WHERE tenant_id = get_my_tenant_id() AND status IN ('pending_approval','in_review'))
  WHERE public.has_module_role('bd', ARRAY['admin','manager'])
  UNION ALL
  SELECT 'contract_approvals', 'Contract Approvals', '/law-compliance/contracts/approvals',
         (SELECT count(*)::int FROM law_contracts
          WHERE tenant_id = get_my_tenant_id() AND status IN ('pending_approval','draft'))
  WHERE public.has_module_role('legal', ARRAY['admin','manager','member'])
  UNION ALL
  SELECT 'leave_approvals', 'Leave Approvals', '/hr/leaves/approvals',
         (SELECT count(*)::int FROM hr_leave_requests
          WHERE tenant_id = get_my_tenant_id() AND status = 'pending')
  WHERE public.has_module_role('hr', ARRAY['admin','manager','member'])
  UNION ALL
  SELECT 'payroll_approvals', 'Payroll Approvals', '/hr/payroll/approvals',
         (SELECT count(*)::int FROM hr_payroll_runs
          WHERE tenant_id = get_my_tenant_id() AND status = 'pending_approval')
  WHERE public.can_view_payroll_approvals();
$$;


--
-- Name: list_platform_admins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_admins() RETURNS TABLE(user_id uuid, name text, email text, tenant_id uuid, tenant_name text, mfa_enrolled boolean, last_sign_in_at timestamp with time zone, created_at timestamp with time zone, granted_at timestamp with time zone, granted_by_email text, is_self boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform require_platform_admin('The platform team list');

  return query
  select
    u.id,
    u.name,
    u.email,
    u.tenant_id,
    t.name,
    exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified'),
    au.last_sign_in_at,
    u.created_at,
    g.created_at,
    g.actor_email,
    (u.id = auth.uid())
  from app_users u
  join tenants t on t.id = u.tenant_id
  left join auth.users au on au.id = u.id
  left join lateral (
    select e.created_at, e.actor_email
    from platform_audit_events e
    where e.action = 'platform_admin.grant' and e.target_id = u.id::text
    order by e.created_at desc
    limit 1
  ) g on true
  where u.is_platform_admin
  order by u.created_at, u.email;
end;
$$;


--
-- Name: list_platform_announcements(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_announcements(p_include_past boolean DEFAULT false) RETURNS TABLE(id uuid, title text, body text, severity text, tenant_id uuid, tenant_name text, starts_at timestamp with time zone, ends_at timestamp with time zone, dismissible boolean, link_url text, link_label text, is_active boolean, state text, dismissals bigint, created_at timestamp with time zone, created_by_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select a.id, a.title, a.body, a.severity, a.tenant_id, t.name, a.starts_at, a.ends_at, a.dismissible,
         a.link_url, a.link_label, a.is_active,
         case
           when not a.is_active then 'disabled'
           when a.ends_at is not null and a.ends_at <= now() then 'ended'
           when a.starts_at > now() then 'scheduled'
           else 'live'
         end as state,
         (select count(*) from platform_announcement_dismissals d where d.announcement_id = a.id),
         a.created_at,
         (select email from auth.users u where u.id = a.created_by)
  from platform_announcements a
  left join tenants t on t.id = a.tenant_id
  where public.platform_admin_mfa_gate('list platform announcements')
    and (p_include_past or a.is_active and (a.ends_at is null or a.ends_at > now() - interval '7 days'))
  order by a.is_active desc, a.starts_at desc;
$$;


--
-- Name: list_platform_audit_events(uuid, uuid, text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_audit_events(p_tenant_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, created_at timestamp with time zone, actor_id uuid, actor_email text, tenant_id uuid, tenant_name text, action text, target_type text, target_id text, reason text, before jsonb, after jsonb, mfa_verified boolean, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with filtered as (
    select e.*
    from platform_audit_events e
    where public.platform_admin_mfa_gate('list platform audit events')
      and (p_tenant_id is null or e.tenant_id = p_tenant_id)
      and (p_actor_id  is null or e.actor_id  = p_actor_id)
      and (p_action    is null or e.action like p_action)
      and (p_from      is null or e.created_at >= p_from)
      and (p_to        is null or e.created_at <  p_to)
  )
  select
    f.id, f.created_at, f.actor_id, f.actor_email, f.tenant_id, t.name,
    f.action, f.target_type, f.target_id, f.reason, f.before, f.after, f.mfa_verified,
    count(*) over () as total_count
  from filtered f
  left join tenants t on t.id = f.tenant_id
  order by f.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 500))
  offset greatest(0, coalesce(p_offset, 0));
$$;


--
-- Name: platform_digests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_digests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    trigger text DEFAULT 'scheduled'::text NOT NULL,
    generated_by uuid,
    attention_count integer DEFAULT 0 NOT NULL,
    payload jsonb NOT NULL,
    recipients text[] DEFAULT '{}'::text[] NOT NULL,
    delivery_status text DEFAULT 'pending'::text NOT NULL,
    delivered_at timestamp with time zone,
    delivery_error text,
    CONSTRAINT platform_digests_delivery_check CHECK ((delivery_status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT platform_digests_trigger_check CHECK ((trigger = ANY (ARRAY['scheduled'::text, 'manual'::text])))
);


--
-- Name: list_platform_digests(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_platform_digests(p_limit integer DEFAULT 14) RETURNS SETOF public.platform_digests
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select d.* from platform_digests d
  where public.platform_admin_mfa_gate('list platform digests')
  order by d.generated_at desc
  limit greatest(1, least(coalesce(p_limit, 14), 90));
$$;


--
-- Name: list_receipt_assignees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_receipt_assignees() RETURNS TABLE(id uuid, user_id uuid, user_name text, assigned_by_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT mra.id, mra.user_id, u.name, ab.name, mra.created_at
  FROM material_receipt_assignments mra
  JOIN app_users u ON u.id = mra.user_id
  JOIN app_users ab ON ab.id = mra.assigned_by
  WHERE mra.tenant_id = get_my_tenant_id()
  ORDER BY mra.created_at DESC;
$$;


--
-- Name: lock_number_sequence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_number_sequence(p_tenant_id uuid, p_kind text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform pg_advisory_xact_lock(
    hashtextextended('number_sequence:' || p_kind || ':' || p_tenant_id::text, 0)
  );
end;
$$;


--
-- Name: log_platform_event(text, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_platform_event(p_action text, p_tenant_id uuid DEFAULT NULL::uuid, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  insert into platform_audit_events (
    actor_id, actor_email, tenant_id, action, target_type, target_id,
    reason, before, after, mfa_verified
  )
  values (
    auth.uid(),
    (select email from auth.users where id = auth.uid()),
    p_tenant_id, p_action, p_target_type, p_target_id,
    nullif(btrim(p_reason), ''), p_before, p_after,
    platform_session_is_mfa()
  )
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: machine_maintenance_overdue_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.machine_maintenance_overdue_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_req record;
  v_count int := 0;
  v_tenant uuid;
begin
  if not has_module_role('machine_operation', array['admin', 'manager', 'member']) then
    return 0; -- outsiders just get nothing
  end if;
  v_tenant := get_my_tenant_id();

  for v_req in
    select r.*, m.machine_no, m.name as machine_name
    from maintenance_requests r
    join machines m on m.id = r.machine_id
    where r.tenant_id = v_tenant
      and r.status in ('scheduled', 'in_progress')
      and r.scheduled_date is not null
      and r.scheduled_date < current_date
      and r.overdue_notified_at is null
  loop
    insert into notifications (tenant_id, recipient_id, type, title, body)
    select distinct on (recipient) v_req.tenant_id, recipient,
      'maintenance_overdue',
      'Maintenance overdue: ' || v_req.machine_no,
      format('"%s" on machine %s - %s was scheduled for %s and is %s day(s) overdue.',
        left(v_req.description, 80), v_req.machine_no, v_req.machine_name,
        v_req.scheduled_date::text, (current_date - v_req.scheduled_date)::text)
    from (values (v_req.requested_by), (v_req.assigned_to)) as rec(recipient)
    where recipient is not null;

    update maintenance_requests
    set overdue_notified_at = now()
    where id = v_req.id;

    v_count := v_count + 1;
  end loop;

  perform platform_record_job_run('machine_maintenance_overdue_sweep', v_tenant, 'ok', v_count);
  return v_count;
end;
$$;


--
-- Name: mark_platform_digest_delivered(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_platform_digest_delivered(p_id uuid, p_status text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', current_user) <> 'service_role'
     and current_user not in ('postgres', 'supabase_admin') then
    raise exception 'PLATFORM_ADMIN_REQUIRED: digest delivery is recorded by the service role only'
      using errcode = '42501';
  end if;
  if p_status not in ('sent', 'failed', 'skipped') then
    raise exception 'status must be sent, failed or skipped';
  end if;
  update platform_digests
     set delivery_status = p_status,
         delivered_at    = case when p_status = 'sent' then now() else delivered_at end,
         delivery_error  = nullif(btrim(p_error), '')
   where id = p_id;
end;
$$;


--
-- Name: bank_reconciliations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_reconciliations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    bank_statement_line_id uuid NOT NULL,
    cash_bank_transaction_id uuid,
    match_type text DEFAULT 'manual'::text NOT NULL,
    variance numeric DEFAULT 0 NOT NULL,
    matched_by uuid,
    matched_at timestamp with time zone DEFAULT now() NOT NULL,
    settlement_id uuid,
    commission_transfer_id uuid,
    transfer_side text,
    CONSTRAINT bank_reconciliations_match_type_check CHECK ((match_type = ANY (ARRAY['manual'::text, 'auto'::text]))),
    CONSTRAINT bank_reconciliations_one_source_check CHECK ((num_nonnulls(cash_bank_transaction_id, settlement_id, commission_transfer_id) = 1)),
    CONSTRAINT bank_reconciliations_transfer_side_check CHECK ((((commission_transfer_id IS NULL) AND (transfer_side IS NULL)) OR ((commission_transfer_id IS NOT NULL) AND (transfer_side IS NOT NULL) AND (transfer_side = ANY (ARRAY['from'::text, 'to'::text])))))
);


--
-- Name: match_bank_statement_line(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_bank_statement_line(p_statement_line_id uuid, p_cash_bank_transaction_id uuid) RETURNS public.bank_reconciliations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_line bank_statement_lines%rowtype;
  v_txn cash_bank_transactions%rowtype;
  v_txn_signed numeric;
  v_row bank_reconciliations%rowtype;
begin
  if not is_finance_team_member('finance') then
    raise exception 'not authorized to reconcile bank transactions';
  end if;

  select * into v_line from bank_statement_lines where id = p_statement_line_id and tenant_id = v_tenant_id;
  if not found then
    raise exception 'statement line not found';
  end if;

  select * into v_txn from cash_bank_transactions where id = p_cash_bank_transaction_id and tenant_id = v_tenant_id;
  if not found then
    raise exception 'cash/bank transaction not found';
  end if;

  if v_txn.payment_method != 'bank' then
    raise exception 'only bank-method transactions can be reconciled against a statement';
  end if;

  if v_txn.bank_account is distinct from v_line.bank_account then
    raise exception 'statement line and transaction are on different bank accounts (% vs %)', v_line.bank_account, v_txn.bank_account;
  end if;

  if v_txn.currency is distinct from v_line.currency then
    raise exception 'statement line and transaction are in different currencies (% vs %)', v_line.currency, v_txn.currency;
  end if;

  v_txn_signed := case when v_txn.transaction_type = 'receipt' then v_txn.amount else -v_txn.amount end;

  insert into bank_reconciliations (
    tenant_id, bank_statement_line_id, cash_bank_transaction_id, match_type, variance, matched_by
  ) values (
    v_tenant_id, p_statement_line_id, p_cash_bank_transaction_id, 'manual', v_line.amount - v_txn_signed, auth.uid()
  )
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: match_bank_statement_line_to_commission_transfer(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_bank_statement_line_to_commission_transfer(p_statement_line_id uuid, p_transfer_id uuid) RETURNS public.bank_reconciliations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_line   bank_statement_lines%rowtype;
  v_tr     ins_commission_transfers%rowtype;
  v_from   text;
  v_to     text;
  v_side   text;
  v_signed numeric;
  v_row    bank_reconciliations%rowtype;
begin
  if not is_finance_team_member('finance') then
    raise exception 'not authorized to reconcile bank transactions';
  end if;

  select * into v_line from bank_statement_lines
   where id = p_statement_line_id and tenant_id = v_tenant_id;
  if not found then
    raise exception 'statement line not found';
  end if;

  -- Lock the transfer so a concurrent void cannot slip past the reconciled check.
  select * into v_tr from ins_commission_transfers
   where id = p_transfer_id and tenant_id = v_tenant_id
   for update;
  if not found then
    raise exception 'commission transfer not found';
  end if;
  if v_tr.status <> 'posted' then
    raise exception 'only posted commission transfers can be reconciled (% is %)', v_tr.transfer_no, v_tr.status;
  end if;

  select name into v_from from fin_bank_accounts where id = v_tr.from_bank_account_id and tenant_id = v_tenant_id;
  select name into v_to   from fin_bank_accounts where id = v_tr.to_bank_account_id   and tenant_id = v_tenant_id;

  v_side := case
    when v_line.bank_account = v_from then 'from'
    when v_line.bank_account = v_to   then 'to'
    else null end;
  if v_side is null then
    raise exception 'statement line is on % but transfer % moves money between % and %',
      v_line.bank_account, v_tr.transfer_no, v_from, v_to;
  end if;

  if v_tr.currency is distinct from v_line.currency then
    raise exception 'statement line and commission transfer are in different currencies (% vs %)',
      v_line.currency, v_tr.currency;
  end if;

  v_signed := case when v_side = 'to' then v_tr.amount else -v_tr.amount end;

  begin
    insert into bank_reconciliations (
      tenant_id, bank_statement_line_id, commission_transfer_id, transfer_side, match_type, variance, matched_by
    ) values (
      v_tenant_id, p_statement_line_id, p_transfer_id, v_side, 'manual', v_line.amount - v_signed, auth.uid()
    )
    returning * into v_row;
  exception when unique_violation then
    raise exception 'statement line or that side of the transfer is already reconciled';
  end;

  return v_row;
end;
$$;


--
-- Name: match_bank_statement_line_to_settlement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_bank_statement_line_to_settlement(p_statement_line_id uuid, p_settlement_id uuid) RETURNS public.bank_reconciliations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare pid uuid;
begin
 select c.policy_id into pid from ins_policy_cancellations c where c.tenant_id=get_my_tenant_id() and
 (exists(select 1 from ins_cancellation_cash_requests q where q.cancellation_id=c.id and p_settlement_id in(q.settlement_id,q.to_settlement_id)) or exists(select 1 from ins_policy_cash_items k join fin_allocations a on a.open_item_id=k.id where k.source_id=c.policy_id and a.settlement_id=p_settlement_id));
 if pid is not null then perform ins_policy_cash_require_finance(); perform id from ins_policies where id=pid for update; end if;
 return platform_ins_cxl_before_match_settlement(p_statement_line_id,p_settlement_id);
end $$;


--
-- Name: next_asset_tag(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_asset_tag(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_next_num int;
begin
  perform public.assert_tenant_access(p_tenant_id);
  perform public.lock_number_sequence(p_tenant_id, 'asset_tag');

  select coalesce(max(nullif(regexp_replace(asset_tag, '^AST-', ''), asset_tag)::int), 0) + 1
  into v_next_num
  from assets
  where tenant_id = p_tenant_id and asset_tag like 'AST-%';

  return 'AST-' || lpad(v_next_num::text, 5, '0');
end;
$$;


--
-- Name: next_doc_number(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_doc_number(p_tenant_id uuid, p_doc_type text, p_prefix text, p_pad integer DEFAULT 4) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  yr text := to_char(now(), 'YYYY');
  n int;
begin
  perform public.assert_tenant_access(p_tenant_id);

  insert into public.doc_sequences (tenant_id, doc_type, year, last_number)
  values (p_tenant_id, p_doc_type, yr, 1)
  on conflict (tenant_id, doc_type, year)
  do update set last_number = public.doc_sequences.last_number + 1
  returning last_number into n;

  return p_prefix || '-' || yr || '-' || lpad(n::text, p_pad, '0');
end;
$$;


--
-- Name: next_material_catalog_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_material_catalog_code(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_next_num int;
begin
  perform public.assert_tenant_access(p_tenant_id);
  perform public.lock_number_sequence(p_tenant_id, 'material_catalog_code');

  select coalesce(max(nullif(regexp_replace(code, '^MAT-', ''), code)::int), 0) + 1
  into v_next_num
  from material_catalog
  where tenant_id = p_tenant_id and code like 'MAT-%';

  return 'MAT-' || lpad(v_next_num::text, 5, '0');
end;
$$;


--
-- Name: next_mr_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_mr_number(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_next_num int;
begin
  perform public.assert_tenant_access(p_tenant_id);
  perform public.lock_number_sequence(p_tenant_id, 'mr_number');

  select coalesce(max(nullif(regexp_replace(mr_number, '^MR-', ''), mr_number)::int), 0) + 1
  into v_next_num
  from requests
  where tenant_id = p_tenant_id and mr_number like 'MR-%';

  return 'MR-' || lpad(v_next_num::text, 5, '0');
end;
$$;


