--
-- Name: notify_contract_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_contract_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reason text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('active', 'terminated', 'rejected')
     AND NEW.created_by IS NOT NULL THEN
    IF NEW.status = 'rejected' THEN
      -- attach the rejection notes, if a decision row was just written
      select d.notes into v_reason
      from law_contract_decisions d
      where d.contract_id = NEW.id and d.decision = 'rejected'
      order by d.created_at desc
      limit 1;
    END IF;
    INSERT INTO notifications (tenant_id, recipient_id, type, title, body)
    VALUES (
      NEW.tenant_id,
      NEW.created_by,
      'contract_' || NEW.status,
      (CASE NEW.status
         WHEN 'active'  THEN 'Contract approved: '
         WHEN 'rejected' THEN 'Contract rejected: '
         ELSE 'Contract terminated: ' END) || NEW.contract_no,
      CASE NEW.status
        WHEN 'active'  THEN format('Contract "%s" (%s) has been approved and is now active.', NEW.title, NEW.contract_no)
        WHEN 'rejected' THEN format('Contract "%s" (%s) was rejected.%s', NEW.title, NEW.contract_no,
                                coalesce(' Reason: ' || v_reason, ''))
        ELSE format('Contract "%s" (%s) is now terminated.', NEW.title, NEW.contract_no)
      END
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: notify_leave_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_leave_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_recipient_id uuid;
begin
  if NEW.status = OLD.status then
    return NEW;
  end if;

  if NEW.status not in ('approved', 'rejected') then
    return NEW;
  end if;

  select user_id into v_recipient_id from hr_employees where id = NEW.employee_id;

  -- Employee may not have a linked portal account (user_id is nullable) --
  -- nothing to notify in that case.
  if v_recipient_id is null then
    return NEW;
  end if;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    NEW.tenant_id,
    v_recipient_id,
    'leave_' || NEW.status,
    case
      when NEW.status = 'approved' then 'Your leave request has been approved'
      else 'Your leave request has been rejected'
    end,
    format(
      'Leave request %s (%s to %s, %s day%s) was %s.',
      coalesce(NEW.leave_no, NEW.id::text),
      NEW.start_date,
      NEW.end_date,
      NEW.days,
      case when NEW.days = 1 then '' else 's' end,
      NEW.status
    )
  );

  return NEW;
end;
$$;


--
-- Name: notify_proposal_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_proposal_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IN ('approved', 'rejected')
     AND NEW.created_by IS NOT NULL THEN
    INSERT INTO notifications (tenant_id, recipient_id, type, title, body)
    VALUES (
      NEW.tenant_id,
      NEW.created_by,
      'proposal_' || NEW.status,
      'Proposal ' || NEW.status || ': ' || COALESCE(NEW.proposal_no, NEW.title),
      format('Your proposal "%s" has been %s.', NEW.title, NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: platform_accounting_policy_version(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_accounting_policy_version(p_tenant_id uuid, p_on date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select max(version)
       from accounting_policies
      where tenant_id = p_tenant_id
        and status = 'approved'
        and effective_from <= p_on),
    1);
$$;


