-- Name: platform_admin_bypass(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_bypass() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select is_platform_admin() and impersonated_user_id() is null;
$$;


--
-- Name: platform_admin_has_mfa_factor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_has_mfa_factor() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from auth.mfa_factors f
    where f.user_id = auth.uid()
      and f.status = 'verified'
  );
$$;


--
-- Name: platform_admin_mfa_gate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_mfa_gate(p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not is_platform_admin() then
    return false;
  end if;
  perform require_platform_admin(p_action);
  return true;
end;
$$;


--
-- Name: platform_apply_template_items(uuid, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_apply_template_items(p_tenant_id uuid, p_template_key text, p_kinds text[], p_write boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_item      record;
  v_mods      text[] := '{}';
  v_depts     text[] := '{}';
  v_flags     jsonb  := '[]'::jsonb;
  v_accts     jsonb  := '[]'::jsonb;
  v_rules     jsonb  := '[]'::jsonb;
  v_conf      jsonb  := '[]'::jsonb;
  v_new_codes text[] := '{}';
  v_code      text;
  v_acct_id   uuid;
  v_cur_code  text;
  v_cur_type  text;
  v_cur_on    boolean;
  v_want_on   boolean;
begin
  if not is_platform_admin() then
    raise exception 'Only platform admins can apply template content';
  end if;

  -- Modules: entitle the ones the tenant lacks. set_tenant_modules() also gives the
  -- tenant's company admins an admin role on each newly entitled module.
  if 'module' = any (p_kinds) then
    for v_item in
      select i.name from industry_template_items i
      where i.template_key = p_template_key and i.kind = 'module' order by i.sort_order
    loop
      if exists (select 1 from tenant_modules where tenant_id = p_tenant_id and module = v_item.name) then
        continue;
      end if;
      if not exists (select 1 from platform_modules m where m.key = v_item.name and m.is_active and m.tenant_entitled) then
        v_conf := v_conf || jsonb_build_object('kind', 'module', 'name', v_item.name,
                    'reason', 'module is no longer active or entitleable in the registry');
        continue;
      end if;
      v_mods := v_mods || v_item.name;
    end loop;
    if p_write and cardinality(v_mods) > 0 then
      perform set_tenant_modules(
        p_tenant_id,
        coalesce((select array_agg(module) from tenant_modules where tenant_id = p_tenant_id), '{}') || v_mods
      );
    end if;
  end if;

  -- Departments: matched by name, case-insensitive; existing ones are left as they are.
  if 'department' = any (p_kinds) then
    for v_item in
      select i.name from industry_template_items i
      where i.template_key = p_template_key and i.kind = 'department' order by i.sort_order
    loop
      if exists (select 1 from departments d
                  where d.tenant_id = p_tenant_id and lower(btrim(d.name)) = lower(btrim(v_item.name))) then
        continue;
      end if;
      v_depts := v_depts || v_item.name;
      if p_write then
        insert into departments (tenant_id, name) values (p_tenant_id, v_item.name);
      end if;
    end loop;
  end if;

  -- Feature flags: insert missing overrides; a differing existing override is a conflict.
  if 'feature_flag' = any (p_kinds) then
    for v_item in
      select i.name, i.payload from industry_template_items i
      where i.template_key = p_template_key and i.kind = 'feature_flag' order by i.sort_order
    loop
      v_want_on := coalesce((v_item.payload ->> 'enabled')::boolean, true);
      if not exists (select 1 from platform_feature_flags f where f.key = v_item.name) then
        v_conf := v_conf || jsonb_build_object('kind', 'feature_flag', 'name', v_item.name,
                    'reason', 'flag no longer exists');
        continue;
      end if;
      select tf.enabled into v_cur_on from tenant_feature_flags tf
       where tf.tenant_id = p_tenant_id and tf.flag_key = v_item.name;
      if found then
        if v_cur_on is distinct from v_want_on then
          v_conf := v_conf || jsonb_build_object('kind', 'feature_flag', 'name', v_item.name,
                      'reason', 'tenant already overrides this flag',
                      'existing', v_cur_on, 'template', v_want_on);
        end if;
        continue;
      end if;
      v_flags := v_flags || jsonb_build_object('flag_key', v_item.name, 'enabled', v_want_on);
      if p_write then
        insert into tenant_feature_flags (tenant_id, flag_key, enabled, note, updated_by)
        values (p_tenant_id, v_item.name, v_want_on, 'Applied from template ' || p_template_key, auth.uid());
      end if;
    end loop;
  end if;

  -- GL accounts: matched by code. Never renamed or retyped.
  if 'gl_account' = any (p_kinds) then
    for v_item in
      select i.name, i.payload from industry_template_items i
      where i.template_key = p_template_key and i.kind = 'gl_account' order by i.sort_order
    loop
      select a.account_type into v_cur_type from gl_accounts a
       where a.tenant_id = p_tenant_id and a.account_code = v_item.name;
      if found then
        if v_cur_type is distinct from (v_item.payload ->> 'account_type') then
          v_conf := v_conf || jsonb_build_object('kind', 'gl_account', 'name', v_item.name,
                      'reason', 'account code exists with a different type',
                      'existing', v_cur_type, 'template', v_item.payload ->> 'account_type');
        end if;
        continue;
      end if;
      v_accts := v_accts || jsonb_build_object('account_code', v_item.name,
                   'name', v_item.payload ->> 'name', 'account_type', v_item.payload ->> 'account_type');
      v_new_codes := v_new_codes || v_item.name;
      if p_write then
        insert into gl_accounts (tenant_id, account_code, name, account_type, is_control_account)
        values (p_tenant_id, v_item.name, v_item.payload ->> 'name', v_item.payload ->> 'account_type',
                coalesce((v_item.payload ->> 'is_control_account')::boolean, false));
      end if;
    end loop;
  end if;

  -- Posting rules: one per role. An existing rule is never repointed.
  if 'posting_rule' = any (p_kinds) then
    for v_item in
      select i.name, i.payload from industry_template_items i
      where i.template_key = p_template_key and i.kind = 'posting_rule' order by i.sort_order
    loop
      v_code := v_item.payload ->> 'account_code';
      select a.account_code into v_cur_code
        from gl_posting_rules r join gl_accounts a on a.id = r.gl_account_id
       where r.tenant_id = p_tenant_id and r.account_role = v_item.name;
      if found then
        if v_cur_code is distinct from v_code then
          v_conf := v_conf || jsonb_build_object('kind', 'posting_rule', 'name', v_item.name,
                      'reason', 'role already points at a different account',
                      'existing', v_cur_code, 'template', v_code);
        end if;
        continue;
      end if;
      select a.id into v_acct_id from gl_accounts a
       where a.tenant_id = p_tenant_id and a.account_code = v_code;
      if v_acct_id is null and not (not p_write and v_code = any (v_new_codes)) then
        v_conf := v_conf || jsonb_build_object('kind', 'posting_rule', 'name', v_item.name,
                    'reason', 'target account ' || coalesce(v_code, '(none)') || ' is not available on this tenant');
        continue;
      end if;
      v_rules := v_rules || jsonb_build_object('account_role', v_item.name, 'account_code', v_code);
      if p_write then
        insert into gl_posting_rules (tenant_id, account_role, gl_account_id)
        values (p_tenant_id, v_item.name, v_acct_id);
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'modules',       to_jsonb(v_mods),
    'departments',   to_jsonb(v_depts),
    'feature_flags', v_flags,
    'gl_accounts',   v_accts,
    'posting_rules', v_rules,
    'conflicts',     v_conf
  );
end;
$$;


--
-- Name: platform_digest_summary(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_digest_summary(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case when coalesce((p_payload ->> 'attention_count')::integer, 0) = 0
    then 'All clear - nothing needs attention'
    else concat_ws(' · ',
      nullif(jsonb_array_length(p_payload -> 'stalled'), 0) || ' stalled in setup',
      nullif(jsonb_array_length(p_payload -> 'trials_ending'), 0) || ' trial(s) ending',
      nullif(jsonb_array_length(p_payload -> 'quiet'), 0) || ' gone quiet',
      nullif(jsonb_array_length(p_payload -> 'pending_over_threshold'), 0) || ' pending too long',
      nullif(jsonb_array_length(p_payload -> 'admins_without_mfa'), 0) || ' admin(s) without MFA')
  end;
$$;


--
-- Name: platform_fin_backfill_bank_accounts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_backfill_bank_accounts(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_count integer;
begin
  with seen as (
    select t.tenant_id,
           btrim(t.bank_account) as name,
           case when upper(btrim(t.currency)) ~ '^[A-Z]{3}$' then upper(btrim(t.currency)) else 'UGX' end as currency
    from cash_bank_transactions t
    where t.bank_account is not null and btrim(t.bank_account) <> ''
      and (p_tenant_id is null or t.tenant_id = p_tenant_id)
    union all
    select l.tenant_id,
           btrim(l.bank_account),
           case when upper(btrim(l.currency)) ~ '^[A-Z]{3}$' then upper(btrim(l.currency)) else 'UGX' end
    from bank_statement_lines l
    where l.bank_account is not null and btrim(l.bank_account) <> ''
      and (p_tenant_id is null or l.tenant_id = p_tenant_id)
  ), agg as (
    select tenant_id, name, mode() within group (order by currency) as currency
    from seen
    group by tenant_id, name
  ), ins as (
    insert into fin_bank_accounts (tenant_id, name, kind, currency, gl_account_id, created_by)
    select a.tenant_id, a.name, 'operating', a.currency, g.id, null
    from agg a
    left join gl_posting_rules r
      on r.tenant_id = a.tenant_id and r.account_role = 'bank'
    left join gl_accounts g
      on g.id = r.gl_account_id and g.account_type = 'asset' and g.is_active
    on conflict (tenant_id, name) do nothing
    returning 1
  )
  select count(*) into v_count from ins;

  return v_count;
end;
$_$;


--
-- Name: platform_fin_raise_credit_note_impl(uuid, text, uuid, numeric, date, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_raise_credit_note_impl(p_tenant_id uuid, p_control_role text, p_party_account_id uuid, p_amount numeric, p_credit_date date, p_offset_gl_account_id uuid, p_applications jsonb, p_reason text, p_reference text DEFAULT NULL::text) RETURNS public.fin_credit_notes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_side       text;
  v_ids        uuid[] := '{}';
  v_sum        numeric := 0;
  v_elem       jsonb;
  v_item       fin_open_items%rowtype;
  v_role       record;
  v_ctl_gl     uuid;
  v_ctl_row    gl_accounts%rowtype;
  v_off_row    gl_accounts%rowtype;
  v_no         text;
  v_desc       text;
  v_lines      jsonb;
  v_note       fin_credit_notes%rowtype;
  v_je         journal_entries%rowtype;
  v_functional text;
  v_ccy        text := null;
  v_foreign    boolean;
  v_nr         numeric := 1;
  v_base_note  numeric;
  v_total_orig numeric := 0;
  v_result     numeric := 0;
  v_fx_line    jsonb;
begin
  if p_tenant_id is null then raise exception 'tenant id is required'; end if;
  if p_control_role is null or p_control_role not in ('ar_control', 'commission_receivable', 'ap_control', 'insurer_payable') then
    raise exception 'CREDIT_NOTE_INPUT: control role must be ar_control, commission_receivable, ap_control or insurer_payable';
  end if;
  v_side := case when p_control_role in ('ar_control', 'commission_receivable') then 'receivable' else 'payable' end;
  if p_amount is null or p_amount <= 0 then
    raise exception 'CREDIT_NOTE_INPUT: amount must be positive';
  end if;
  if p_credit_date is null or p_credit_date > current_date + 1 then
    raise exception 'CREDIT_NOTE_INPUT: credit date is required and cannot be in the future';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'CREDIT_NOTE_INPUT: a reason of at least 5 characters is required';
  end if;
  if p_applications is null or jsonb_typeof(p_applications) <> 'array' or jsonb_array_length(p_applications) = 0 then
    raise exception 'CREDIT_NOTE_INPUT: applications must be a non-empty array of {open_item_id, amount}';
  end if;

  for v_elem in select * from jsonb_array_elements(p_applications) loop
    if jsonb_typeof(v_elem) <> 'object'
       or jsonb_typeof(v_elem -> 'open_item_id') <> 'string'
       or jsonb_typeof(v_elem -> 'amount') <> 'number' then
      raise exception 'CREDIT_NOTE_INPUT: each application needs an open_item_id (string) and an amount (number)';
    end if;
    if (v_elem ->> 'amount')::numeric <= 0 then
      raise exception 'CREDIT_NOTE_INPUT: application amounts must be positive';
    end if;
    if (v_elem ->> 'open_item_id')::uuid = any (v_ids) then
      raise exception 'CREDIT_NOTE_INPUT: an open item appears twice in the applications';
    end if;
    v_ids := v_ids || (v_elem ->> 'open_item_id')::uuid;
    v_sum := v_sum + (v_elem ->> 'amount')::numeric;
  end loop;
  if v_sum <> p_amount then
    raise exception 'CREDIT_NOTE_NOT_FULLY_APPLIED: applications total % but the credit note is %', v_sum, p_amount;
  end if;

  -- Lock the items in a fixed order, then check each one. The note's currency is the
  -- items' currency: they must all agree.
  for v_item in
    select * from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids) order by id for update
  loop
    if v_item.control_role <> p_control_role then
      raise exception 'CREDIT_NOTE_ROLE: a % credit note cannot be applied to % items (%)',
        p_control_role, v_item.control_role, v_item.document_no;
    end if;
    if v_ccy is null then
      v_ccy := v_item.currency;
    elsif v_item.currency is distinct from v_ccy then
      raise exception 'CREDIT_NOTE_CURRENCY: a credit note is in one currency; item % is in %, not %',
        v_item.document_no, v_item.currency, v_ccy;
    end if;
  end loop;
  if (select count(*) from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'CREDIT_APPLICATION_ITEM: an open item was not found in this company';
  end if;

  v_functional := fin_ledger_currency(p_tenant_id);
  v_foreign    := v_ccy is not null and v_ccy <> v_functional;
  if v_foreign then
    if exists (
      select 1 from fin_open_items
       where tenant_id = p_tenant_id and id = any (v_ids)
         and (journal_entry_id is null or fx_rate is null or fx_rate <= 0)
    ) then
      raise exception 'CREDIT_NOTE_ITEM_RATE: a % credit note needs items that name the entry that booked them, at a positive rate', v_ccy;
    end if;
    v_nr := round((platform_fx_rate(p_tenant_id, v_ccy, p_credit_date)).rate, 8);
  end if;

  -- Control account for the role.
  v_ctl_gl := get_posting_account(p_tenant_id, p_control_role);
  if v_ctl_gl is null then
    raise exception 'CREDIT_NOTE_UNMAPPED_ROLE: the posting role % is not mapped to a GL account', p_control_role;
  end if;
  select * into v_ctl_row from gl_accounts where id = v_ctl_gl and tenant_id = p_tenant_id;
  if not found or not v_ctl_row.is_active then
    raise exception 'CREDIT_NOTE_UNMAPPED_ROLE: the GL account for posting role % is missing or inactive', p_control_role;
  end if;

  -- Offset account: same company, active, and not a bank, client-money or control account.
  select * into v_off_row from gl_accounts where id = p_offset_gl_account_id and tenant_id = p_tenant_id;
  if not found then
    raise exception 'CREDIT_NOTE_OFFSET: the offset account was not found in this company';
  end if;
  if not v_off_row.is_active then
    raise exception 'CREDIT_NOTE_OFFSET: the offset account % is inactive', v_off_row.account_code;
  end if;
  if v_off_row.id = v_ctl_gl or v_off_row.is_control_account
     or exists (
       select 1 from gl_posting_rules r
        where r.tenant_id = p_tenant_id and r.gl_account_id = v_off_row.id
          and r.account_role in ('ar_control', 'ap_control', 'commission_receivable', 'insurer_payable',
                                 'bank', 'cash', 'client_money_bank')
     )
     or exists (
       select 1 from fin_bank_accounts b where b.tenant_id = p_tenant_id and b.gl_account_id = v_off_row.id
     ) then
    raise exception 'CREDIT_NOTE_OFFSET: account % is a control, bank or client-money account and cannot be the offset', v_off_row.account_code;
  end if;

  v_no   := next_doc_number(p_tenant_id, 'fin_credit_note', 'CRN');
  v_desc := 'Credit note ' || v_no;

  if not v_foreign then
    v_lines := case v_side
      when 'receivable' then jsonb_build_array(
        jsonb_build_object('gl_account_id', v_off_row.id, 'debit', p_amount, 'description', v_desc),
        jsonb_build_object('gl_account_id', v_ctl_gl, 'credit', p_amount, 'description', v_desc))
      else jsonb_build_array(
        jsonb_build_object('gl_account_id', v_ctl_gl, 'debit', p_amount, 'description', v_desc),
        jsonb_build_object('gl_account_id', v_off_row.id, 'credit', p_amount, 'description', v_desc))
    end;
  else
    -- Foreign currency: one control line per booking entry, at the rate that entry used,
    -- naming the entry as the rate source; the offset line at the credit-date rate.
    v_lines := '[]'::jsonb;
    for v_role in
      select i.journal_entry_id, i.fx_rate, sum((e ->> 'amount')::numeric) as amt
      from jsonb_array_elements(p_applications) e
      join fin_open_items i on i.id = (e ->> 'open_item_id')::uuid and i.tenant_id = p_tenant_id
      group by i.journal_entry_id, i.fx_rate
      order by i.journal_entry_id
    loop
      v_lines := v_lines || jsonb_build_object(
        'gl_account_id', v_ctl_gl,
        case v_side when 'receivable' then 'credit' else 'debit' end, v_role.amt,
        'currency', v_ccy,
        'rate_from_entry', v_role.journal_entry_id,
        'fx_rate', v_role.fx_rate,
        'description', v_desc);
      v_total_orig := v_total_orig + round(v_role.amt * v_role.fx_rate, 2);
    end loop;
    v_lines := v_lines || jsonb_build_object(
      'gl_account_id', v_off_row.id,
      case v_side when 'receivable' then 'debit' else 'credit' end, p_amount,
      'currency', v_ccy,
      'description', v_desc);
    v_base_note := round(p_amount * v_nr, 2);
    -- Cancelling a receivable booked at the original rate with a note at today's rate:
    -- what the offset takes minus what was booked is a gain when positive (the same sign
    -- as a receipt against the item). A payable note is the mirror of a payment.
    v_result  := case v_side when 'receivable' then v_base_note - v_total_orig
                             else v_total_orig - v_base_note end;
    v_fx_line := platform_fx_realised_line(p_tenant_id, v_result, 'Realised exchange result on ' || v_no);
    if v_fx_line is not null then
      v_lines := v_lines || v_fx_line;
    end if;
  end if;

  insert into fin_credit_notes (
    tenant_id, credit_note_no, side, control_role, party_account_id, offset_gl_account_id,
    amount, currency, fx_rate, realised_result, credit_date, reason, reference
  ) values (
    p_tenant_id, v_no, v_side, p_control_role, p_party_account_id, v_off_row.id,
    p_amount, v_ccy, v_nr, v_result, p_credit_date, btrim(p_reason), nullif(btrim(p_reference), '')
  )
  returning * into v_note;

  for v_elem in select * from jsonb_array_elements(p_applications) loop
    insert into fin_credit_applications (tenant_id, credit_note_id, open_item_id, amount)
    values (p_tenant_id, v_note.id, (v_elem ->> 'open_item_id')::uuid, (v_elem ->> 'amount')::numeric);
  end loop;

  v_je := post_journal_entry(p_tenant_id, 'fin_credit_note', v_note.id, p_credit_date, v_desc || ': ' || btrim(p_reason), v_lines);

  update fin_credit_notes set journal_entry_id = v_je.id where id = v_note.id returning * into v_note;
  return v_note;
end;
$$;


--
-- Name: platform_fin_raise_policy_credit_note_impl(uuid, text, uuid, numeric, date, uuid, jsonb, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_raise_policy_credit_note_impl(p_tenant_id uuid, p_control_role text, p_party_account_id uuid, p_amount numeric, p_credit_date date, p_offset_gl_account_id uuid, p_applications jsonb, p_reason text, p_reference text, p_policy_id uuid) RETURNS public.fin_credit_notes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_context    jsonb;
  v_side       text;
  v_ids        uuid[] := '{}';
  v_sum        numeric := 0;
  v_elem       jsonb;
  v_item       fin_open_items%rowtype;
  v_role       record;
  v_ctl_gl     uuid;
  v_ctl_row    gl_accounts%rowtype;
  v_off_row    gl_accounts%rowtype;
  v_no         text;
  v_desc       text;
  v_lines      jsonb;
  v_note       fin_credit_notes%rowtype;
  v_je         journal_entries%rowtype;
  v_functional text;
  v_ccy        text := null;
  v_foreign    boolean;
  v_nr         numeric := 1;
  v_base_note  numeric;
  v_total_orig numeric := 0;
  v_result     numeric := 0;
  v_fx_line    jsonb;
begin
  if p_tenant_id is distinct from get_my_tenant_id() or not can_manage_insurance() then
    raise exception 'INS_FORBIDDEN: insurance manager access required' using errcode = '42501';
  end if;
  v_context := ins_policy_reversal_context(p_policy_id, true);
  if (v_context->>'offset_id')::uuid is distinct from p_offset_gl_account_id
     or p_control_role not in ('ar_control','insurer_payable')
     or p_applications is distinct from jsonb_build_array(jsonb_build_object(
       'open_item_id', case when p_control_role = 'ar_control' then v_context->>'premium_item_id' else v_context->>'insurer_item_id' end,
       'amount', p_amount)) then
    raise exception 'INS_REVERSAL_OFFSET: exemption is limited to this policy and its complete open items';
  end if;
  if p_amount <> (v_context->>(case when p_control_role = 'ar_control' then 'gross' else 'net' end))::numeric then
    raise exception 'INS_REVERSAL_OFFSET: only full policy amounts are allowed';
  end if;
  if p_control_role is null or p_control_role not in ('ar_control', 'commission_receivable', 'ap_control', 'insurer_payable') then
    raise exception 'CREDIT_NOTE_INPUT: control role must be ar_control, commission_receivable, ap_control or insurer_payable';
  end if;
  v_side := case when p_control_role in ('ar_control', 'commission_receivable') then 'receivable' else 'payable' end;
  if p_amount is null or p_amount <= 0 then
    raise exception 'CREDIT_NOTE_INPUT: amount must be positive';
  end if;
  if p_credit_date is null or p_credit_date > current_date + 1 then
    raise exception 'CREDIT_NOTE_INPUT: credit date is required and cannot be in the future';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'CREDIT_NOTE_INPUT: a reason of at least 5 characters is required';
  end if;
  if p_applications is null or jsonb_typeof(p_applications) <> 'array' or jsonb_array_length(p_applications) = 0 then
    raise exception 'CREDIT_NOTE_INPUT: applications must be a non-empty array of {open_item_id, amount}';
  end if;

  v_ids := '{}';
  v_sum := 0;
  for v_elem in select * from jsonb_array_elements(p_applications) loop
    if jsonb_typeof(v_elem) <> 'object'
       or jsonb_typeof(v_elem -> 'open_item_id') <> 'string'
       or jsonb_typeof(v_elem -> 'amount') <> 'number' then
      raise exception 'CREDIT_NOTE_INPUT: each application needs an open_item_id (string) and an amount (number)';
    end if;
    if (v_elem ->> 'amount')::numeric <= 0 then
      raise exception 'CREDIT_NOTE_INPUT: application amounts must be positive';
    end if;
    if (v_elem ->> 'open_item_id')::uuid = any (v_ids) then
      raise exception 'CREDIT_NOTE_INPUT: an open item appears twice in the applications';
    end if;
    v_ids := v_ids || (v_elem ->> 'open_item_id')::uuid;
    v_sum := v_sum + (v_elem ->> 'amount')::numeric;
  end loop;
  if v_sum <> p_amount then
    raise exception 'CREDIT_NOTE_NOT_FULLY_APPLIED: applications total % but the credit note is %', v_sum, p_amount;
  end if;

  -- Lock the items in a fixed order, then check each one. The note's currency is the
  -- items' currency: they must all agree.
  for v_item in
    select * from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids) order by id for update
  loop
    if v_item.control_role <> p_control_role then
      raise exception 'CREDIT_NOTE_ROLE: a % credit note cannot be applied to % items (%)',
        p_control_role, v_item.control_role, v_item.document_no;
    end if;
    if v_ccy is null then
      v_ccy := v_item.currency;
    elsif v_item.currency is distinct from v_ccy then
      raise exception 'CREDIT_NOTE_CURRENCY: a credit note is in one currency; item % is in %, not %',
        v_item.document_no, v_item.currency, v_ccy;
    end if;
  end loop;
  if (select count(*) from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'CREDIT_APPLICATION_ITEM: an open item was not found in this company';
  end if;

  v_functional := fin_ledger_currency(p_tenant_id);
  v_foreign    := v_ccy is not null and v_ccy <> v_functional;
  if v_foreign then
    if exists (
      select 1 from fin_open_items
       where tenant_id = p_tenant_id and id = any (v_ids)
         and (journal_entry_id is null or fx_rate is null or fx_rate <= 0)
    ) then
      raise exception 'CREDIT_NOTE_ITEM_RATE: a % credit note needs items that name the entry that booked them, at a positive rate', v_ccy;
    end if;
    v_nr := round((platform_fx_rate(p_tenant_id, v_ccy, p_credit_date)).rate, 8);
  end if;

  -- Control account for the role.
  v_ctl_gl := get_posting_account(p_tenant_id, p_control_role);
  if v_ctl_gl is null then
    raise exception 'CREDIT_NOTE_UNMAPPED_ROLE: the posting role % is not mapped to a GL account', p_control_role;
  end if;
  select * into v_ctl_row from gl_accounts where id = v_ctl_gl and tenant_id = p_tenant_id;
  if not found or not v_ctl_row.is_active then
    raise exception 'CREDIT_NOTE_UNMAPPED_ROLE: the GL account for posting role % is missing or inactive', p_control_role;
  end if;

  -- Offset account: same company, active, and not a bank, client-money or control account.
  select * into v_off_row from gl_accounts where id = p_offset_gl_account_id and tenant_id = p_tenant_id;
  if not found then
    raise exception 'CREDIT_NOTE_OFFSET: the offset account was not found in this company';
  end if;
  if not v_off_row.is_active then
    raise exception 'CREDIT_NOTE_OFFSET: the offset account % is inactive', v_off_row.account_code;
  end if;
  if v_off_row.id = v_ctl_gl or (v_off_row.is_control_account and (v_context->>'offset_id')::uuid is distinct from v_off_row.id)
     or exists (
       select 1 from gl_posting_rules r
        where r.tenant_id = p_tenant_id and r.gl_account_id = v_off_row.id
          and r.account_role in ('ar_control', 'ap_control', 'commission_receivable', 'insurer_payable',
                                 'bank', 'cash', 'client_money_bank')
     )
     or exists (
       select 1 from fin_bank_accounts b where b.tenant_id = p_tenant_id and b.gl_account_id = v_off_row.id
     ) then
    raise exception 'CREDIT_NOTE_OFFSET: account % is a control, bank or client-money account and cannot be the offset', v_off_row.account_code;
  end if;

  v_no   := next_doc_number(p_tenant_id, 'fin_credit_note', 'CRN');
  v_desc := 'Credit note ' || v_no;

  if not v_foreign then
    v_lines := case v_side
      when 'receivable' then jsonb_build_array(
        jsonb_build_object('gl_account_id', v_off_row.id, 'debit', p_amount, 'description', v_desc),
        jsonb_build_object('gl_account_id', v_ctl_gl, 'credit', p_amount, 'description', v_desc))
      else jsonb_build_array(
        jsonb_build_object('gl_account_id', v_ctl_gl, 'debit', p_amount, 'description', v_desc),
        jsonb_build_object('gl_account_id', v_off_row.id, 'credit', p_amount, 'description', v_desc))
    end;
  else
    -- Foreign currency: one control line per booking entry, at the rate that entry used,
    -- naming the entry as the rate source; the offset line at the credit-date rate.
    v_lines := '[]'::jsonb;
    for v_role in
      select i.journal_entry_id, i.fx_rate, sum((e ->> 'amount')::numeric) as amt
      from jsonb_array_elements(p_applications) e
      join fin_open_items i on i.id = (e ->> 'open_item_id')::uuid and i.tenant_id = p_tenant_id
      group by i.journal_entry_id, i.fx_rate
      order by i.journal_entry_id
    loop
      v_lines := v_lines || jsonb_build_object(
        'gl_account_id', v_ctl_gl,
        case v_side when 'receivable' then 'credit' else 'debit' end, v_role.amt,
        'currency', v_ccy,
        'rate_from_entry', v_role.journal_entry_id,
        'fx_rate', v_role.fx_rate,
        'description', v_desc);
      v_total_orig := v_total_orig + round(v_role.amt * v_role.fx_rate, 2);
    end loop;
    v_lines := v_lines || jsonb_build_object(
      'gl_account_id', v_off_row.id,
      case v_side when 'receivable' then 'debit' else 'credit' end, p_amount,
      'currency', v_ccy,
      'description', v_desc);
    v_base_note := round(p_amount * v_nr, 2);
    v_result    := case v_side when 'receivable' then v_base_note - v_total_orig
                               else v_total_orig - v_base_note end;
    v_fx_line   := platform_fx_realised_line(p_tenant_id, v_result, 'Realised exchange result on ' || v_no);
    if v_fx_line is not null then
      v_lines := v_lines || v_fx_line;
    end if;
  end if;

  insert into fin_credit_notes (
    tenant_id, credit_note_no, side, control_role, party_account_id, offset_gl_account_id,
    amount, currency, fx_rate, realised_result, credit_date, reason, reference
  ) values (
    p_tenant_id, v_no, v_side, p_control_role, p_party_account_id, v_off_row.id,
    p_amount, v_ccy, v_nr, v_result, p_credit_date, btrim(p_reason), nullif(btrim(p_reference), '')
  )
  returning * into v_note;

  for v_elem in select * from jsonb_array_elements(p_applications) loop
    insert into fin_credit_applications (tenant_id, credit_note_id, open_item_id, amount)
    values (p_tenant_id, v_note.id, (v_elem ->> 'open_item_id')::uuid, (v_elem ->> 'amount')::numeric);
  end loop;

  v_je := post_journal_entry(p_tenant_id, 'fin_credit_note', v_note.id, p_credit_date, v_desc || ': ' || btrim(p_reason), v_lines);

  update fin_credit_notes set journal_entry_id = v_je.id where id = v_note.id returning * into v_note;
  return v_note;
end;
$$;


--
-- Name: platform_fin_record_settlement_impl(uuid, uuid, text, uuid, numeric, date, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_record_settlement_impl(p_tenant_id uuid, p_bank_account_id uuid, p_direction text, p_party_account_id uuid, p_amount numeric, p_settlement_date date, p_allocations jsonb, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.fin_settlements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_bank     fin_bank_accounts%rowtype;
  v_gl       gl_accounts%rowtype;
  v_allowed  text[];
  v_ids      uuid[];
  v_sum      numeric;
  v_item     fin_open_items%rowtype;
  v_role     record;
  v_ctl_gl   uuid;
  v_ctl_row  gl_accounts%rowtype;
  v_lines    jsonb := '[]'::jsonb;
  v_no       text;
  v_set      fin_settlements%rowtype;
  v_je       journal_entries%rowtype;
  v_elem     jsonb;
  v_desc     text;
  v_functional text;
  v_ccy        text;
  v_foreign    boolean;
  v_sr         numeric := 1;
  v_bank_base  numeric;
  v_total_orig numeric := 0;
  v_result     numeric := 0;
  v_fx_line    jsonb;
begin
  if p_tenant_id is null then raise exception 'tenant id is required'; end if;
  if p_direction not in ('in', 'out') then
    raise exception 'SETTLEMENT_INPUT: direction must be in or out';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'SETTLEMENT_INPUT: amount must be positive';
  end if;
  if p_settlement_date is null or p_settlement_date > current_date + 1 then
    raise exception 'SETTLEMENT_INPUT: settlement date is required and cannot be in the future';
  end if;
  if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' or jsonb_array_length(p_allocations) = 0 then
    raise exception 'SETTLEMENT_INPUT: allocations must be a non-empty array of {open_item_id, amount}';
  end if;

  v_ids := '{}';
  v_sum := 0;
  for v_elem in select * from jsonb_array_elements(p_allocations) loop
    if jsonb_typeof(v_elem) <> 'object'
       or jsonb_typeof(v_elem -> 'open_item_id') <> 'string'
       or jsonb_typeof(v_elem -> 'amount') <> 'number' then
      raise exception 'SETTLEMENT_INPUT: each allocation needs an open_item_id (string) and an amount (number)';
    end if;
    if (v_elem ->> 'amount')::numeric <= 0 then
      raise exception 'SETTLEMENT_INPUT: allocation amounts must be positive';
    end if;
    if (v_elem ->> 'open_item_id')::uuid = any (v_ids) then
      raise exception 'SETTLEMENT_INPUT: an open item appears twice in the allocations';
    end if;
    v_ids := v_ids || (v_elem ->> 'open_item_id')::uuid;
    v_sum := v_sum + (v_elem ->> 'amount')::numeric;
  end loop;
  if v_sum <> p_amount then
    raise exception 'SETTLEMENT_NOT_FULLY_ALLOCATED: allocations total % but the settlement is %', v_sum, p_amount;
  end if;

  select * into v_bank from fin_bank_accounts where id = p_bank_account_id and tenant_id = p_tenant_id for share;
  if not found then raise exception 'SETTLEMENT_BANK: bank account not found in this company'; end if;
  if not v_bank.is_active then raise exception 'SETTLEMENT_BANK: bank account % is inactive', v_bank.name; end if;
  if v_bank.gl_account_id is null then
    raise exception 'SETTLEMENT_BANK: bank account % has no GL account mapped', v_bank.name;
  end if;

  v_functional := fin_ledger_currency(p_tenant_id);
  v_ccy := v_bank.currency;
  v_foreign := v_ccy <> v_functional;

  select * into v_gl from gl_accounts where id = v_bank.gl_account_id and tenant_id = p_tenant_id;
  if not found or v_gl.account_type <> 'asset' or not v_gl.is_active then
    raise exception 'SETTLEMENT_BANK: the GL account of bank account % is missing, inactive or not an asset account', v_bank.name;
  end if;

  if exists (
    select 1 from fin_bank_accounts b
    where b.tenant_id = p_tenant_id and b.gl_account_id = v_bank.gl_account_id and b.kind <> v_bank.kind
  ) then
    raise exception 'SETTLEMENT_SEGREGATION: GL account % is shared between client money and operating bank accounts', v_gl.account_code;
  end if;
  if v_bank.kind = 'client_money' and exists (
    select 1 from gl_posting_rules r
    where r.tenant_id = p_tenant_id and r.gl_account_id = v_bank.gl_account_id and r.account_role in ('bank', 'cash')
  ) then
    raise exception 'SETTLEMENT_SEGREGATION: GL account % is now the operating bank/cash posting account and cannot hold client money', v_gl.account_code;
  end if;
  if v_bank.kind = 'operating' and exists (
    select 1 from gl_posting_rules r
    where r.tenant_id = p_tenant_id and r.gl_account_id = v_bank.gl_account_id and r.account_role = 'client_money_bank'
  ) then
    raise exception 'SETTLEMENT_SEGREGATION: GL account % is now the client-money posting account and cannot be used by an operating bank account', v_gl.account_code;
  end if;

  v_allowed := case
    when v_bank.kind = 'client_money' and p_direction = 'in'  then array['ar_control', 'insurer_claim_receivable']
    when v_bank.kind = 'client_money'                         then array['insurer_payable', 'client_claim_payable']
    when p_direction = 'in'                                   then array['ar_control', 'commission_receivable']
    else array['ap_control'] end;

  for v_item in
    select * from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids) order by id for update
  loop
    if v_item.control_role <> all (v_allowed) then
      raise exception 'SETTLEMENT_ROLE_NOT_ALLOWED: a % bank account taking money % cannot settle % items (%)',
        replace(v_bank.kind, '_', ' '), p_direction, v_item.control_role, v_item.document_no;
    end if;
    if v_item.control_role in ('insurer_claim_receivable', 'client_claim_payable') and not public.ins_via_rpc() then
      raise exception 'SETTLEMENT_ROLE_NOT_ALLOWED: claim item % is settled from the claim in the Insurance module', v_item.document_no;
    end if;
    if v_item.currency <> v_ccy then
      raise exception 'SETTLEMENT_CURRENCY: item % is in %, but bank account % is in %',
        v_item.document_no, v_item.currency, v_bank.name, v_ccy;
    end if;
    if v_foreign and v_item.journal_entry_id is null then
      raise exception 'SETTLEMENT_ITEM_RATE: item % has no booking entry, so its rate is unknown', v_item.document_no;
    end if;
  end loop;
  if (select count(*) from fin_open_items where tenant_id = p_tenant_id and id = any (v_ids)) <> cardinality(v_ids) then
    raise exception 'ALLOCATION_ITEM: an open item was not found in this company';
  end if;

  v_no := next_doc_number(p_tenant_id, 'fin_settlement', 'STL');
  v_desc := case p_direction when 'in' then 'Receipt ' else 'Payment ' end || v_no;

  if p_direction = 'in' then
    v_lines := v_lines || (jsonb_build_object('gl_account_id', v_bank.gl_account_id, 'debit', p_amount, 'description', v_desc)
                       || case when v_foreign then jsonb_build_object('currency', v_ccy) else '{}'::jsonb end);
  end if;

  if not v_foreign then
    -- Functional currency: control lines grouped by role, exactly as before.
    for v_role in
      select i.control_role, sum((e ->> 'amount')::numeric) as amt
      from jsonb_array_elements(p_allocations) e
      join fin_open_items i on i.id = (e ->> 'open_item_id')::uuid and i.tenant_id = p_tenant_id
      group by i.control_role
      order by i.control_role
    loop
      v_ctl_gl := get_posting_account(p_tenant_id, v_role.control_role);
      if v_ctl_gl is null then
        raise exception 'SETTLEMENT_UNMAPPED_ROLE: the posting role % is not mapped to a GL account', v_role.control_role;
      end if;
      select * into v_ctl_row from gl_accounts where id = v_ctl_gl and tenant_id = p_tenant_id;
      if not found or not v_ctl_row.is_active then
        raise exception 'SETTLEMENT_UNMAPPED_ROLE: the GL account for posting role % is missing or inactive', v_role.control_role;
      end if;
      v_lines := v_lines || jsonb_build_object(
        'gl_account_id', v_ctl_gl,
        case p_direction when 'in' then 'credit' else 'debit' end, v_role.amt,
        'description', v_desc);
    end loop;
  else
    -- Foreign currency: one control line per booking entry, at the rate that entry used,
    -- naming the entry as the rate source.
    for v_role in
      select i.control_role, i.journal_entry_id, i.fx_rate, sum((e ->> 'amount')::numeric) as amt
      from jsonb_array_elements(p_allocations) e
      join fin_open_items i on i.id = (e ->> 'open_item_id')::uuid and i.tenant_id = p_tenant_id
      group by i.control_role, i.journal_entry_id, i.fx_rate
      order by i.control_role, i.journal_entry_id
    loop
      v_ctl_gl := get_posting_account(p_tenant_id, v_role.control_role);
      if v_ctl_gl is null then
        raise exception 'SETTLEMENT_UNMAPPED_ROLE: the posting role % is not mapped to a GL account', v_role.control_role;
      end if;
      select * into v_ctl_row from gl_accounts where id = v_ctl_gl and tenant_id = p_tenant_id;
      if not found or not v_ctl_row.is_active then
        raise exception 'SETTLEMENT_UNMAPPED_ROLE: the GL account for posting role % is missing or inactive', v_role.control_role;
      end if;
      v_lines := v_lines || jsonb_build_object(
        'gl_account_id', v_ctl_gl,
        case p_direction when 'in' then 'credit' else 'debit' end, v_role.amt,
        'currency', v_ccy,
        'rate_from_entry', v_role.journal_entry_id,
        'fx_rate', v_role.fx_rate,
        'description', v_desc);
      v_total_orig := v_total_orig + round(v_role.amt * v_role.fx_rate, 2);
    end loop;
  end if;

  if p_direction = 'out' then
    v_lines := v_lines || (jsonb_build_object('gl_account_id', v_bank.gl_account_id, 'credit', p_amount, 'description', v_desc)
                       || case when v_foreign then jsonb_build_object('currency', v_ccy) else '{}'::jsonb end);
  end if;

  if v_foreign then
    -- Bank line at the settlement-date rate; the difference to what the items were booked
    -- at is the realised result (a gain when more functional currency comes in than was
    -- booked, or less goes out; a loss the other way round).
    v_sr := round((platform_fx_rate(p_tenant_id, v_ccy, p_settlement_date)).rate, 8);
    v_bank_base := round(p_amount * v_sr, 2);
    v_result := case p_direction when 'out' then v_total_orig - v_bank_base else v_bank_base - v_total_orig end;
    v_fx_line := platform_fx_realised_line(p_tenant_id, v_result, 'Realised exchange result on ' || v_no);
    if v_fx_line is not null then
      v_lines := v_lines || v_fx_line;
    end if;
  end if;

  insert into fin_settlements (
    tenant_id, settlement_no, direction, bank_account_id, party_account_id,
    amount, currency, settlement_date, reference, notes, fx_rate, realised_result
  ) values (
    p_tenant_id, v_no, p_direction, p_bank_account_id, p_party_account_id,
    p_amount, v_bank.currency, p_settlement_date, nullif(btrim(p_reference), ''), nullif(btrim(p_notes), ''),
    v_sr, v_result
  )
  returning * into v_set;

  for v_elem in select * from jsonb_array_elements(p_allocations) loop
    insert into fin_allocations (tenant_id, settlement_id, open_item_id, amount)
    values (p_tenant_id, v_set.id, (v_elem ->> 'open_item_id')::uuid, (v_elem ->> 'amount')::numeric);
  end loop;

  v_je := post_journal_entry(p_tenant_id, 'fin_settlement', v_set.id, p_settlement_date, v_desc, v_lines);

  update fin_settlements set journal_entry_id = v_je.id where id = v_set.id returning * into v_set;
  return v_set;
end;
$$;


--
-- Name: platform_fin_void_credit_note_impl(uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_void_credit_note_impl(p_tenant_id uuid, p_credit_note_id uuid, p_reason text, p_void_date date DEFAULT CURRENT_DATE) RETURNS public.fin_credit_notes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_note  fin_credit_notes%rowtype;
  v_lines jsonb;
  v_je    journal_entries%rowtype;
begin
  if p_tenant_id is null then raise exception 'tenant id is required'; end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'CREDIT_NOTE_VOID: a reason of at least 5 characters is required';
  end if;

  select * into v_note from fin_credit_notes where id = p_credit_note_id and tenant_id = p_tenant_id for update;
  if not found then raise exception 'CREDIT_NOTE_VOID: credit note not found in this company'; end if;
  if v_note.status <> 'posted' then raise exception 'CREDIT_NOTE_VOID: credit note % is already void', v_note.credit_note_no; end if;
  if v_note.journal_entry_id is null then raise exception 'CREDIT_NOTE_VOID: credit note % has no posted journal', v_note.credit_note_no; end if;
  if p_void_date is null or p_void_date < v_note.credit_date or p_void_date > current_date + 1 then
    raise exception 'CREDIT_NOTE_VOID: the void date must be between the credit date and today';
  end if;

  -- Swap debit and credit, keeping each line's currency, original rate and rounding flag.
  select jsonb_agg(jsonb_build_object(
           'gl_account_id', l.gl_account_id,
           'debit', l.credit,
           'credit', l.debit,
           'currency', l.currency,
           'fx_rate', l.fx_rate,
           'is_rounding', l.is_rounding,
           'description', 'Reversal of ' || v_note.credit_note_no))
    into v_lines
    from journal_entry_lines l
   where l.journal_entry_id = v_note.journal_entry_id;

  -- Reversal mode: the line guard keeps the original rates, but only rates that the entry
  -- being reversed already used.
  perform set_config('fin.reversal_of', v_note.journal_entry_id::text, true);
  v_je := post_journal_entry(p_tenant_id, 'fin_credit_note_void', v_note.id, p_void_date,
                             'Void of credit note ' || v_note.credit_note_no || ': ' || btrim(p_reason), v_lines);
  perform set_config('fin.reversal_of', '', true);

  update fin_credit_notes
     set status = 'void', void_journal_entry_id = v_je.id, voided_at = now(),
         voided_by = auth.uid(), void_reason = btrim(p_reason)
   where id = v_note.id
  returning * into v_note;

  return v_note;
end;
$$;


--
-- Name: platform_fin_void_settlement_impl(uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fin_void_settlement_impl(p_tenant_id uuid, p_settlement_id uuid, p_reason text, p_void_date date DEFAULT CURRENT_DATE) RETURNS public.fin_settlements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_set   fin_settlements%rowtype;
  v_lines jsonb;
  v_je    journal_entries%rowtype;
begin
  if p_tenant_id is null then raise exception 'tenant id is required'; end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'SETTLEMENT_VOID: a reason of at least 5 characters is required';
  end if;

  select * into v_set from fin_settlements where id = p_settlement_id and tenant_id = p_tenant_id for update;
  if not found then raise exception 'SETTLEMENT_VOID: settlement not found in this company'; end if;

  if exists (
    select 1 from bank_reconciliations r
     where r.settlement_id = v_set.id and r.tenant_id = p_tenant_id
  ) then
    raise exception 'SETTLEMENT_VOID: settlement % is reconciled to a bank statement line; unmatch it first', v_set.settlement_no;
  end if;

  if v_set.status <> 'posted' then raise exception 'SETTLEMENT_VOID: settlement % is already void', v_set.settlement_no; end if;
  if v_set.journal_entry_id is null then raise exception 'SETTLEMENT_VOID: settlement % has no posted journal', v_set.settlement_no; end if;
  if p_void_date is null or p_void_date < v_set.settlement_date or p_void_date > current_date + 1 then
    raise exception 'SETTLEMENT_VOID: the void date must be between the settlement date and today';
  end if;

  -- Swap debit and credit, keeping each line's currency, original rate and rounding flag.
  select jsonb_agg(jsonb_build_object(
           'gl_account_id', l.gl_account_id,
           'debit', l.credit,
           'credit', l.debit,
           'currency', l.currency,
           'fx_rate', l.fx_rate,
           'is_rounding', l.is_rounding,
           'description', 'Reversal of ' || v_set.settlement_no))
    into v_lines
    from journal_entry_lines l
   where l.journal_entry_id = v_set.journal_entry_id;

  -- Reversal mode: the line guard keeps the original rates, but only rates that the entry
  -- being reversed already used.
  perform set_config('fin.reversal_of', v_set.journal_entry_id::text, true);
  v_je := post_journal_entry(p_tenant_id, 'fin_settlement_void', v_set.id, p_void_date,
                             'Void of settlement ' || v_set.settlement_no || ': ' || btrim(p_reason), v_lines);
  perform set_config('fin.reversal_of', '', true);

  update fin_settlements
     set status = 'void', void_journal_entry_id = v_je.id, voided_at = now(),
         voided_by = auth.uid(), void_reason = btrim(p_reason)
   where id = v_set.id
   returning * into v_set;

  return v_set;
end;
$$;


--
-- Name: platform_fx_rate(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fx_rate(p_tenant_id uuid, p_currency text, p_on date) RETURNS public.fx_rates
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v       fx_rates%rowtype;
  v_max   numeric;
begin
  if p_tenant_id is null or p_currency is null or p_on is null then
    raise exception 'FX_ARGUMENT: company, currency and date are required';
  end if;

  if p_currency = fin_ledger_currency(p_tenant_id) then
    v.tenant_id := p_tenant_id;
    v.currency  := p_currency;
    v.rate_date := p_on;
    v.rate      := 1;
    v.source    := 'functional currency';
    v.status    := 'approved';
    return v;
  end if;

  select * into v
  from fx_rates
  where tenant_id = p_tenant_id
    and currency = p_currency
    and status = 'approved'
    and rate_date <= p_on
  order by rate_date desc
  limit 1;

  if not found then
    raise exception 'FX_RATE_MISSING: no approved % rate on or before %', p_currency, p_on;
  end if;

  v_max := platform_reg_number(p_tenant_id, 'fx.rate_max_age_days', p_on);
  if (p_on - v.rate_date) > v_max then
    raise exception 'FX_RATE_STALE: the latest approved % rate is dated %, more than % days before %', p_currency, v.rate_date, v_max, p_on;
  end if;
  return v;
end;
$$;


--
-- Name: platform_fx_realised_line(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fx_realised_line(p_tenant_id uuid, p_result numeric, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_account uuid;
  v_role    text;
begin
  if p_result is null or p_result = 0 then
    return null;
  end if;
  v_role := case when p_result > 0 then 'fx_gain_realised' else 'fx_loss_realised' end;
  select gl_account_id into v_account
    from gl_posting_rules
   where tenant_id = p_tenant_id and account_role = v_role;
  if v_account is null then
    raise exception 'FX_REALISED_ACCOUNT_MISSING: this company has no % account under posting rules', v_role;
  end if;
  return jsonb_build_object(
    'gl_account_id', v_account,
    'debit',  case when p_result < 0 then -p_result else 0 end,
    'credit', case when p_result > 0 then  p_result else 0 end,
    'currency', fin_ledger_currency(p_tenant_id),
    'description', coalesce(p_description,
                            case when p_result > 0 then 'Realised exchange gain' else 'Realised exchange loss' end)
  );
end;
$$;


--
-- Name: platform_fx_revalue_impl(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fx_revalue_impl(p_tenant_id uuid, p_as_of date) RETURNS public.fx_revaluation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_functional text;
  v_run        fx_revaluation_runs%rowtype;
  v_prior      fx_revaluation_runs%rowtype;
  v_je         journal_entries%rowtype;
  v_gain       uuid := null;
  v_loss       uuid := null;
  v_rate       numeric;
  v_target     numeric;
  v_unrealised numeric;
  v_lines      jsonb := '[]'::jsonb;
  v_detail     jsonb := '[]'::jsonb;
  r            record;
begin
  if p_tenant_id is null then
    raise exception 'tenant id is required';
  end if;
  if p_as_of is null or p_as_of > current_date then
    raise exception 'FX_REVAL_INPUT: a revaluation needs a run date that is not in the future';
  end if;
  if exists (
    select 1 from fx_revaluation_runs
     where tenant_id = p_tenant_id and as_of = p_as_of and status = 'posted'
  ) then
    raise exception 'FX_REVAL_EXISTS: a revaluation for % is already live; void it first', p_as_of;
  end if;

  v_functional := fin_ledger_currency(p_tenant_id);

  -- The previous live run's journal is reversed first, so exactly one revaluation
  -- journal is ever live.
  select * into v_prior
    from fx_revaluation_runs
   where tenant_id = p_tenant_id and status = 'posted' and journal_entry_id is not null
   order by posted_at desc
   limit 1
   for update;

  drop table if exists pg_temp.reval_rows;
  drop table if exists pg_temp.reval_final;
  create temp table reval_rows on commit drop as
    -- Control accounts with outstanding foreign open items (at their booked base).
    select get_posting_account(p_tenant_id, i.control_role) as gl_account_id,
           i.currency, true as from_items,
           sum(case when i.control_role in ('ap_control', 'insurer_payable', 'client_claim_payable')
                    then -b.outstanding_amount else b.outstanding_amount end) as ccy_balance,
           sum(case when i.control_role in ('ap_control', 'insurer_payable', 'client_claim_payable')
                    then -b.base_outstanding_amount else b.base_outstanding_amount end) as base_balance
      from fin_open_items i
      join fin_open_item_balances b on b.id = i.id
     where i.tenant_id = p_tenant_id
       and i.currency is distinct from v_functional
       and b.outstanding_amount > 0
       and i.control_role in ('ar_control', 'ap_control', 'insurer_payable', 'commission_receivable',
                              'insurer_claim_receivable', 'client_claim_payable')
     group by 1, 2
    union all
    -- Foreign bank account GLs.
    select l.gl_account_id, l.currency, false as from_items,
           sum(l.debit - l.credit),
           sum(l.base_debit - l.base_credit)
      from journal_entry_lines l
     where l.tenant_id = p_tenant_id
       and l.currency is distinct from v_functional
       and l.gl_account_id in (
         select b.gl_account_id from fin_bank_accounts b
          where b.tenant_id = p_tenant_id and b.gl_account_id is not null
            and b.currency is distinct from v_functional)
     group by 1, 2
    union all
    -- The unearned-commission account (per currency): the base residues that 3d left
    -- behind are what this run clears.
    select l.gl_account_id, l.currency, false as from_items,
           sum(l.debit - l.credit),
           sum(l.base_debit - l.base_credit)
      from journal_entry_lines l
     where l.tenant_id = p_tenant_id
       and l.currency is distinct from v_functional
       and l.gl_account_id = get_posting_account(p_tenant_id, 'unearned_commission')
     group by 1, 2;

  delete from reval_rows where gl_account_id is null;
  -- A bank GL can also appear through the control set in theory; merge duplicates.
  create temp table reval_final on commit drop as
    select gl_account_id, currency, bool_or(from_items) as from_items,
           sum(ccy_balance) as ccy_balance, sum(base_balance) as base_balance
      from reval_rows
     group by 1, 2;

  -- All-or-nothing: every involved currency must have an approved rate for the run
  -- date before anything is written.
  for r in select distinct currency from reval_final loop
    perform platform_fx_rate(p_tenant_id, r.currency, p_as_of);
  end loop;

  -- The previous live run's journal is reversed BEFORE the movements are measured:
  -- its lines are undone first, so the new journal books exactly what still differs
  -- from the closing rate instead of moving the same balance twice.
  if v_prior.id is not null then
    declare
      v_rev_lines jsonb;
    begin
      select jsonb_agg(jsonb_build_object(
               'gl_account_id', l.gl_account_id, 'debit', l.credit, 'credit', l.debit,
               'currency', l.currency, 'fx_rate', l.fx_rate, 'is_rounding', l.is_rounding,
               'description', 'Reversal of the revaluation at ' || v_prior.as_of))
        into v_rev_lines
        from journal_entry_lines l
       where l.journal_entry_id = v_prior.journal_entry_id;
      perform set_config('fin.reversal_of', v_prior.journal_entry_id::text, true);
      v_je := post_journal_entry(p_tenant_id, 'fx_revaluation_void', v_prior.id, p_as_of,
                                 'Reversal of the FX revaluation at ' || v_prior.as_of, v_rev_lines);
      perform set_config('fin.reversal_of', '', true);
      update fx_revaluation_runs
         set status = 'void', void_journal_entry_id = v_je.id,
             void_reason = 'superseded by the revaluation at ' || p_as_of, voided_at = now()
       where id = v_prior.id;
    end;
  end if;

  -- Measure again on the post-reversal balances.
  drop table if exists pg_temp.reval_rows;
  drop table if exists pg_temp.reval_final;
  create temp table reval_rows on commit drop as
    -- Control accounts with outstanding foreign open items (at their booked base).
    select get_posting_account(p_tenant_id, i.control_role) as gl_account_id,
           i.currency, true as from_items,
           sum(case when i.control_role in ('ap_control', 'insurer_payable', 'client_claim_payable')
                    then -b.outstanding_amount else b.outstanding_amount end) as ccy_balance,
           sum(case when i.control_role in ('ap_control', 'insurer_payable', 'client_claim_payable')
                    then -b.base_outstanding_amount else b.base_outstanding_amount end) as base_balance
      from fin_open_items i
      join fin_open_item_balances b on b.id = i.id
     where i.tenant_id = p_tenant_id
       and i.currency is distinct from v_functional
       and b.outstanding_amount > 0
       and i.control_role in ('ar_control', 'ap_control', 'insurer_payable', 'commission_receivable',
                              'insurer_claim_receivable', 'client_claim_payable')
     group by 1, 2
    union all
    -- Foreign bank account GLs.
    select l.gl_account_id, l.currency, false as from_items,
           sum(l.debit - l.credit),
           sum(l.base_debit - l.base_credit)
      from journal_entry_lines l
     where l.tenant_id = p_tenant_id
       and l.currency is distinct from v_functional
       and l.gl_account_id in (
         select b.gl_account_id from fin_bank_accounts b
          where b.tenant_id = p_tenant_id and b.gl_account_id is not null
            and b.currency is distinct from v_functional)
     group by 1, 2
    union all
    -- The unearned-commission account (per currency): the base residues that 3d left
    -- behind are what this run clears.
    select l.gl_account_id, l.currency, false as from_items,
           sum(l.debit - l.credit),
           sum(l.base_debit - l.base_credit)
      from journal_entry_lines l
     where l.tenant_id = p_tenant_id
       and l.currency is distinct from v_functional
       and l.gl_account_id = get_posting_account(p_tenant_id, 'unearned_commission')
     group by 1, 2;

  delete from reval_rows where gl_account_id is null;
  -- A bank GL can also appear through the control set in theory; merge duplicates.
  create temp table reval_final on commit drop as
    select gl_account_id, currency, bool_or(from_items) as from_items,
           sum(ccy_balance) as ccy_balance, sum(base_balance) as base_balance
      from reval_rows
     group by 1, 2;

  for r in
    select * from reval_final
     where round(ccy_balance * round((platform_fx_rate(p_tenant_id, currency, p_as_of)).rate, 8), 2)
           <> round(base_balance, 2)
     order by gl_account_id, currency
  loop
    v_rate := round((platform_fx_rate(p_tenant_id, r.currency, p_as_of)).rate, 8);
    v_target := round(r.ccy_balance * v_rate, 2);
    v_unrealised := v_target - round(r.base_balance, 2);
    if v_gain is null or v_loss is null then
      v_gain := get_posting_account(p_tenant_id, 'fx_gain_unrealised');
      v_loss := get_posting_account(p_tenant_id, 'fx_loss_unrealised');
      if v_gain is null or v_loss is null then
        raise exception 'FX_UNREALISED_ACCOUNT_MISSING: this company has no fx_gain_unrealised/fx_loss_unrealised accounts under posting rules';
      end if;
    end if;
    v_detail := v_detail || jsonb_build_object(
      'gl_account_id', r.gl_account_id, 'currency', r.currency,
      'currency_balance', r.ccy_balance, 'base_balance', round(r.base_balance, 2),
      'closing_rate', v_rate, 'unrealised_result', v_unrealised);
    -- The account moves towards its closing-rate value; the P&L side books the move.
    v_lines := v_lines || jsonb_build_object(
      'gl_account_id', r.gl_account_id,
      'debit',  greatest(v_unrealised, 0), 'credit', greatest(-v_unrealised, 0),
      'description', format('FX revaluation %s: %s at %s', r.currency, to_char(v_unrealised, 'FM9999999999999990.00'), v_rate));
    v_lines := v_lines || (case when v_unrealised > 0
      then jsonb_build_object('gl_account_id', v_gain, 'credit', v_unrealised,
                              'description', 'Unrealised exchange gain at ' || p_as_of)
      else jsonb_build_object('gl_account_id', v_loss, 'debit', -v_unrealised,
                              'description', 'Unrealised exchange loss at ' || p_as_of) end);
  end loop;

  insert into fx_revaluation_runs (tenant_id, as_of, status, detail, posted_by)
  values (p_tenant_id, p_as_of, 'posted', v_detail, auth.uid())
  returning * into v_run;

  if jsonb_array_length(v_lines) > 0 then
    v_je := post_journal_entry(p_tenant_id, 'fx_revaluation', v_run.id, p_as_of,
                               'FX revaluation at ' || p_as_of, v_lines);
    update fx_revaluation_runs set journal_entry_id = v_je.id where id = v_run.id returning * into v_run;
  end if;

  return v_run;
end;
$$;


--
-- Name: platform_fx_settlement(uuid, text, numeric, numeric, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_fx_settlement(p_tenant_id uuid, p_currency text, p_amount numeric, p_original_rate numeric, p_on date, p_settles_debit boolean) RETURNS TABLE(settlement_rate numeric, base_original numeric, base_settlement numeric, result numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_rate numeric;
  v_orig numeric;
  v_sett numeric;
begin
  if p_amount is null or p_amount < 0 or p_original_rate is null or p_original_rate <= 0 then
    raise exception 'FX_ARGUMENT: a settlement needs a non-negative amount and a positive original rate';
  end if;
  -- A line stores its rate to 8 decimals, so the settlement is computed at that precision.
  v_rate := round((platform_fx_rate(p_tenant_id, p_currency, p_on)).rate, 8);
  v_orig := round(p_amount * p_original_rate, 2);
  v_sett := round(p_amount * v_rate, 2);
  return query select v_rate, v_orig, v_sett,
                      case when p_settles_debit then v_orig - v_sett else v_sett - v_orig end;
end;
$$;


--
-- Name: platform_gl_posting_roles(); Type: FUNCTION; Schema: public; Owner: -
