--
-- Name: platform_users_directory(text, uuid, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_users_directory(p_search text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, p_module text DEFAULT NULL::text, p_quiet_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, name text, email text, role_title text, tenant_id uuid, tenant_name text, tenant_status text, is_platform_admin boolean, is_company_admin boolean, modules jsonb, finance_role text, mfa_enrolled boolean, last_sign_in_at timestamp with time zone, created_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_search text := nullif(btrim(p_search), '');
begin
  perform require_platform_admin('The user directory');

  return query
  with base as (
    select
      u.id                as b_user_id,
      u.name              as b_name,
      u.email             as b_email,
      u.role_title        as b_role_title,
      u.tenant_id         as b_tenant_id,
      t.name              as b_tenant_name,
      t.status            as b_tenant_status,
      u.is_platform_admin as b_is_platform_admin,
      u.is_company_admin  as b_is_company_admin,
      coalesce(
        (select jsonb_agg(jsonb_build_object('module', sr.module, 'role', sr.role) order by sr.module)
         from staff_roles sr
         where sr.user_id = u.id and sr.tenant_id = u.tenant_id),
        '[]'::jsonb
      )                   as b_modules,
      (select ftm.role
       from finance_team_members ftm
       where ftm.user_id = u.id and ftm.tenant_id = u.tenant_id
       order by case ftm.role when 'finance' then 0 else 1 end
       limit 1)           as b_finance_role,
      exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified')
                          as b_mfa_enrolled,
      au.last_sign_in_at  as b_last_sign_in_at,
      u.created_at        as b_created_at
    from app_users u
    join tenants t on t.id = u.tenant_id
    left join auth.users au on au.id = u.id
  )
  select
    b.b_user_id, b.b_name, b.b_email, b.b_role_title, b.b_tenant_id, b.b_tenant_name, b.b_tenant_status,
    b.b_is_platform_admin, b.b_is_company_admin, b.b_modules, b.b_finance_role, b.b_mfa_enrolled,
    b.b_last_sign_in_at, b.b_created_at,
    count(*) over () as total_count
  from base b
  where (v_search is null
         or b.b_name ilike '%' || v_search || '%'
         or b.b_email ilike '%' || v_search || '%'
         or b.b_tenant_name ilike '%' || v_search || '%')
    and (p_tenant_id is null or b.b_tenant_id = p_tenant_id)
    and (p_kind is null or case p_kind
           when 'platform_admin' then b.b_is_platform_admin
           when 'company_admin'  then b.b_is_company_admin
           when 'finance'        then b.b_finance_role is not null
           when 'member'         then not b.b_is_platform_admin and not b.b_is_company_admin
           else true end)
    and (p_module is null or b.b_modules @> jsonb_build_array(jsonb_build_object('module', p_module)))
    and (p_quiet_days is null
         or b.b_last_sign_in_at is null
         or b.b_last_sign_in_at < now() - make_interval(days => p_quiet_days))
  order by b.b_tenant_name, b.b_email
  limit greatest(1, least(coalesce(p_limit, 50), 500))
  offset greatest(0, coalesce(p_offset, 0));
end;
$$;


--
-- Name: pmo_check_task_dependency_validity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pmo_check_task_dependency_validity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pred_project uuid;
  v_succ_project uuid;
  v_cycle_found boolean;
BEGIN
  SELECT project_id INTO v_pred_project FROM public.pmo_tasks WHERE id = NEW.predecessor_task_id;
  SELECT project_id INTO v_succ_project FROM public.pmo_tasks WHERE id = NEW.successor_task_id;

  IF v_pred_project IS DISTINCT FROM v_succ_project THEN
    RAISE EXCEPTION 'pmo_task_dependencies: predecessor and successor must belong to the same project';
  END IF;

  -- Would this edge close a loop? True iff the successor can already
  -- reach the predecessor through existing edges (excluding the row
  -- being updated, if this is an UPDATE) -- adding predecessor->successor
  -- on top of that path would complete a cycle.
  WITH RECURSIVE reachable AS (
    SELECT successor_task_id AS task_id
    FROM public.pmo_task_dependencies
    WHERE predecessor_task_id = NEW.successor_task_id
      AND (TG_OP = 'INSERT' OR id <> NEW.id)
    UNION
    SELECT d.successor_task_id
    FROM public.pmo_task_dependencies d
    JOIN reachable r ON d.predecessor_task_id = r.task_id
    WHERE (TG_OP = 'INSERT' OR d.id <> NEW.id)
  )
  SELECT EXISTS (SELECT 1 FROM reachable WHERE task_id = NEW.predecessor_task_id) INTO v_cycle_found;

  IF v_cycle_found THEN
    RAISE EXCEPTION 'pmo_task_dependencies: this dependency would create a cycle';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: pmo_time_entry_apply_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pmo_time_entry_apply_rate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.hourly_rate IS NULL THEN
    SELECT a.hourly_rate INTO NEW.hourly_rate
    FROM hr_employees e
    JOIN pmo_resource_allocations a
      ON a.employee_id = e.id
     AND a.project_id = NEW.project_id
     AND a.status = 'active'
    WHERE e.user_id = NEW.user_id
    ORDER BY a.created_at DESC
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: post_issue_items_to_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_issue_items_to_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_issue goods_issues%ROWTYPE;
BEGIN
  SELECT * INTO v_issue FROM goods_issues WHERE id = NEW.goods_issue_id;

  INSERT INTO stock_movements (tenant_id, warehouse_id, material_catalog_id, material_name, unit, movement_type, quantity, reference_type, reference_id, recorded_by)
  VALUES (v_issue.tenant_id, v_issue.warehouse_id, NEW.material_catalog_id, NEW.material_description, NEW.unit, 'out', NEW.delivered_qty, 'goods_issue', NEW.id, v_issue.warehouse_officer_id);

  RETURN NEW;
END;
$$;


--
-- Name: journal_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entry_date date NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    description text,
    status text DEFAULT 'posted'::text NOT NULL,
    posted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accounting_policy_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT journal_entries_policy_version_check CHECK ((accounting_policy_version >= 1)),
    CONSTRAINT journal_entries_source_type_check CHECK ((source_type = ANY (ARRAY['supplier_invoice'::text, 'receivable_invoice'::text, 'cash_bank_transaction'::text, 'opening_balance'::text, 'manual'::text, 'payroll_run'::text, 'machine_fuel_log'::text, 'machine_maintenance_request'::text, 'fin_settlement'::text, 'fin_settlement_void'::text, 'fin_credit_note'::text, 'fin_credit_note_void'::text, 'ins_policy_bind'::text, 'ins_commission_recognition'::text, 'ins_commission_recognition_reversal'::text, 'ins_commission_transfer'::text, 'ins_commission_transfer_void'::text, 'ins_claim_accrual'::text, 'ins_policy_cancellation'::text, 'ins_cancellation_cash'::text, 'fx_revaluation'::text, 'fx_revaluation_void'::text, 'ins_policy_endorsement'::text]))),
    CONSTRAINT journal_entries_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'void'::text])))
);


--
-- Name: post_journal_entry(uuid, text, uuid, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_journal_entry(p_tenant_id uuid, p_source_type text, p_source_id uuid, p_entry_date date, p_description text, p_lines jsonb) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_entry journal_entries%rowtype;
  v_line jsonb;
  v_bad_accounts int;
  v_reversal boolean := nullif(current_setting('fin.reversal_of', true), '') is not null;
  v_rate numeric;
  v_rounding boolean;
  v_from text;
begin
  if p_tenant_id is null then
    raise exception 'tenant id is required';
  end if;

  -- When called inside a user session (auth.uid() present), the tenant must be the
  -- caller's effective tenant. get_my_tenant_id() already honours active impersonation.
  -- Service-role / cron contexts have no auth.uid() and are skipped.
  if auth.uid() is not null
     and p_tenant_id is distinct from public.get_my_tenant_id() then
    raise exception 'not authorized to post journals for this tenant'
      using errcode = '42501';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'journal must have at least one line';
  end if;

  -- Every referenced GL account must belong to this tenant.
  select count(*) into v_bad_accounts
  from jsonb_array_elements(p_lines) l
  left join gl_accounts ga
    on ga.id = (l ->> 'gl_account_id')::uuid
   and ga.tenant_id = p_tenant_id
  where ga.id is null;

  if v_bad_accounts > 0 then
    raise exception 'one or more GL accounts do not belong to this tenant'
      using errcode = '42501';
  end if;

  if exists (
    select 1 from accounting_periods
    where tenant_id = p_tenant_id
      and status = 'closed'
      and p_entry_date between period_start and period_end
  ) then
    raise exception 'cannot post to %: this date falls in a closed accounting period', p_entry_date;
  end if;

  insert into journal_entries (tenant_id, entry_date, source_type, source_id, description, posted_by)
  values (p_tenant_id, p_entry_date, p_source_type, p_source_id, p_description, auth.uid())
  returning * into v_entry;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    -- The rate is set by the line guard from the approved rate table. Two internal
    -- exceptions, both checked by the guard against an earlier entry: a reversal
    -- (fin.reversal_of, set by void_journal_entry) and a single line that names the
    -- entry it settles ('rate_from_entry' with 'fx_rate').
    v_from     := nullif(v_line ->> 'rate_from_entry', '');
    v_rate     := case when v_reversal or v_from is not null
                       then coalesce((v_line ->> 'fx_rate')::numeric, 1) else 1 end;
    v_rounding := v_reversal and coalesce((v_line ->> 'is_rounding')::boolean, false);

    if v_rounding then
      perform set_config('fin.rounding_line', 'on', true);
    end if;
    if v_from is not null then
      perform set_config('fin.rate_from', v_from, true);
    end if;

    insert into journal_entry_lines
      (journal_entry_id, tenant_id, gl_account_id, debit, credit, description, currency, fx_rate)
    values (
      v_entry.id,
      p_tenant_id,
      (v_line ->> 'gl_account_id')::uuid,
      coalesce((v_line ->> 'debit')::numeric, 0),
      coalesce((v_line ->> 'credit')::numeric, 0),
      v_line ->> 'description',
      -- F3: an omitted line currency is the company's ledger currency, never a
      -- hard-coded default -- a USD company must not see its functional lines
      -- labelled UGX.
      coalesce(nullif(btrim(v_line ->> 'currency'), ''), fin_ledger_currency(p_tenant_id)),
      v_rate
    );

    if v_rounding then
      perform set_config('fin.rounding_line', 'off', true);
    end if;
    if v_from is not null then
      perform set_config('fin.rate_from', '', true);
    end if;
  end loop;

  return v_entry;
end;
$$;


--
-- Name: post_receipt_to_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_receipt_to_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_line request_line_items%ROWTYPE;
  v_tenant_id uuid;
BEGIN
  IF NEW.warehouse_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_line FROM request_line_items WHERE id = NEW.line_item_id;
  SELECT r.tenant_id INTO v_tenant_id FROM requests r WHERE r.id = v_line.request_id;

  INSERT INTO stock_movements (tenant_id, warehouse_id, material_name, unit, movement_type, quantity, reference_type, reference_id, recorded_by)
  VALUES (v_tenant_id, NEW.warehouse_id, v_line.material_service, NULL, 'in', NEW.received_qty, 'goods_receipt', NEW.id, NEW.received_by);

  RETURN NEW;
END;
$$;


--
-- Name: prevent_invoice_organization_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_invoice_organization_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception 'organization cannot be changed on an existing invoice (was %, attempted %) -- void and re-enter under the correct organization instead', old.organization_id, new.organization_id;
  end if;
  return new;
end;
$$;


--
-- Name: prevent_journal_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_journal_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- INSERT goes through post_journal_entry(); UPDATE/DELETE are blocked for
  -- everyone including the table owner. The only exception is the
  -- posted -> void status change on journal_entries, made by void_journal_entry()
  -- which sets app.allow_journal_void = 'true' for its own transaction.
  if tg_op = 'UPDATE' then
    if tg_table_name = 'journal_entries' then
      if old.status = 'posted' and new.status = 'void' then
        if coalesce(current_setting('app.allow_journal_void', true), '') = 'true' then
          return new;
        end if;
      end if;
    end if;
    raise exception 'JOURNAL_IMMUTABLE: journal entries are immutable, create a reversal entry instead (attempted % on %)', tg_op, old.id
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'JOURNAL_IMMUTABLE: journal entries cannot be deleted (attempted delete on %)', old.id
      using errcode = 'restrict_violation';
  end if;
  return null;
end;
$$;


--
-- Name: prevent_law_contract_direct_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_law_contract_direct_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and old.status is distinct from new.status then
    if (old.status = 'draft' and new.status = 'pending_approval')
       or (old.status = 'pending_approval' and new.status in ('active', 'rejected')) then
      if coalesce(current_setting('app.allow_law_status_change', true), '') <> 'true' then
        raise exception 'LAW_STATUS_GUARD: contract status change %->% must go through submit_contract_for_approval() or decide_contract() RPC, not direct table UPDATE', old.status, new.status
          using errcode = 'restrict_violation';
      end if;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: prevent_posted_invoice_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_posted_invoice_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_has_journal boolean;
begin
  if tg_op = 'UPDATE' then
    -- Only care about amount field changes
    if tg_table_name = 'supplier_invoices' then
      if new.amount_incl_vat is distinct from old.amount_incl_vat
         or new.vat_amount is distinct from old.vat_amount
         or new.wht_amount is distinct from old.wht_amount then
        select exists(select 1 from journal_entries where source_type='supplier_invoice' and source_id=old.id)
          into v_has_journal;
        if v_has_journal then
          raise exception 'POSTED_INVOICE_IMMUTABLE: cannot change amount of posted supplier invoice % — create a credit note reversal', old.id
            using errcode = 'restrict_violation';
        end if;
      end if;
    elsif tg_table_name = 'receivable_invoices' then
      if new.amount_incl_vat is distinct from old.amount_incl_vat
         or new.vat_amount is distinct from old.vat_amount then
        select exists(select 1 from journal_entries where source_type='receivable_invoice' and source_id=old.id)
          into v_has_journal;
        if v_has_journal then
          raise exception 'POSTED_INVOICE_IMMUTABLE: cannot change amount of posted receivable invoice %', old.id
            using errcode = 'restrict_violation';
        end if;
      end if;
    elsif tg_table_name = 'cash_bank_transactions' then
      if new.amount is distinct from old.amount then
        select exists(select 1 from journal_entries where source_type='cash_bank_transaction' and source_id=old.id)
          into v_has_journal;
        if v_has_journal then
          raise exception 'POSTED_TRANSACTION_IMMUTABLE: cannot change amount of posted cash/bank transaction %', old.id
            using errcode = 'restrict_violation';
        end if;
      end if;
    elsif tg_table_name = 'fuel_logs' then
      if new.cost is distinct from old.cost then
        select exists(select 1 from journal_entries where source_type='machine_fuel_log' and source_id=old.id)
          into v_has_journal;
        if v_has_journal then
          raise exception 'POSTED_FUEL_LOG_IMMUTABLE: cannot change cost of posted fuel log % — create a correcting entry', old.id
            using errcode = 'restrict_violation';
        end if;
      end if;
    elsif tg_table_name = 'maintenance_requests' then
      if new.actual_cost is distinct from old.actual_cost then
        select exists(select 1 from journal_entries where source_type='machine_maintenance_request' and source_id=old.id)
          into v_has_journal;
        if v_has_journal then
          raise exception 'POSTED_MAINTENANCE_COST_IMMUTABLE: cannot change actual_cost of posted maintenance request %', old.id
            using errcode = 'restrict_violation';
        end if;
      end if;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: protect_delegation_immutable_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_delegation_immutable_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.tenant_id           IS DISTINCT FROM OLD.tenant_id
     OR NEW.delegator_user_id IS DISTINCT FROM OLD.delegator_user_id
     OR NEW.delegate_user_id  IS DISTINCT FROM OLD.delegate_user_id
     OR NEW.workflow_stage_id IS DISTINCT FROM OLD.workflow_stage_id
     OR NEW.starts_at         IS DISTINCT FROM OLD.starts_at
     OR NEW.ends_at           IS DISTINCT FROM OLD.ends_at
  THEN
    RAISE EXCEPTION 'only status can be changed on an existing delegation -- revoke it and create a new one instead';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_po_immutable_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_po_immutable_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('vestateck.allow_po_financial_edit', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF NEW.po_number   IS DISTINCT FROM OLD.po_number
     OR NEW.vendor_name IS DISTINCT FROM OLD.vendor_name
     OR NEW.amount      IS DISTINCT FROM OLD.amount
     OR NEW.request_id  IS DISTINCT FROM OLD.request_id
     OR NEW.generated_by IS DISTINCT FROM OLD.generated_by
  THEN
    RAISE EXCEPTION 'these fields can only be changed via a logged PO edit, not a direct update';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: record_approval_decision(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_approval_decision(p_request_id uuid, p_decision text, p_comment text DEFAULT NULL::text, p_acting_on_behalf_of uuid DEFAULT NULL::uuid, p_selected_offer_id uuid DEFAULT NULL::uuid) RETURNS TABLE(out_request_id uuid, out_status text, out_stage_id uuid, out_purchase_order_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request            requests%rowtype;
  v_stage              workflow_stages%rowtype;
  v_next_stage         workflow_stages%rowtype;
  v_next_stage_id      uuid;
  v_offer              request_offers%rowtype;
  v_po_id              uuid;
  v_po_number          text;
  v_actor              uuid := auth.uid();
  v_effective          uuid := public.effective_user_id();
  v_session_id         uuid;
  v_is_platform_bypass boolean := public.platform_admin_bypass();
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid decision: %', p_decision;
  end if;

  select id into v_session_id
  from impersonation_sessions
  where platform_admin_id = v_actor
    and ended_at is null
    and expires_at > now()
  order by started_at desc
  limit 1;

  select * into v_request from requests where id = p_request_id for update;
  if not found then
    raise exception 'request not found';
  end if;
  if v_request.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this request';
  end if;
  if v_request.status != 'open' then
    raise exception 'request is not open (status: %)', v_request.status;
  end if;
  if v_request.current_stage_id is null then
    raise exception 'request has no current stage';
  end if;
  if not can_act_on_stage(v_request.current_stage_id) then
    raise exception 'not authorized to act on this stage';
  end if;

  select * into v_stage from workflow_stages where id = v_request.current_stage_id;

  -- Anti-collusion: if this stage blocks the offer submitter from approving,
  -- check ALL offers on the request, against the effective identity.
  if v_stage.blocks_offer_submitter_approval then
    if exists (
      select 1 from request_offers
      where request_id = p_request_id and submitted_by = v_effective
    ) then
      raise exception 'you submitted an offer on this request -- a different reviewer must act on it at this stage';
    end if;
  end if;

  insert into approval_actions
    (request_id, workflow_stage_id, approver_id, actor_id, effective_user_id,
     impersonation_session_id, acted_on_behalf_of, decision, comment)
  values
    (p_request_id, v_stage.id,
     case when v_is_platform_bypass then v_actor else v_effective end,
     v_actor, v_effective, v_session_id,
     p_acting_on_behalf_of, p_decision, p_comment);

  if p_decision = 'rejected' then
    update requests set status = 'rejected', updated_at = now() where id = p_request_id;

    insert into notifications (tenant_id, recipient_id, type, title, body, request_id)
    values (
      v_request.tenant_id,
      v_request.requester_id,
      'request_rejected',
      'Request rejected',
      format('Your request "%s" was rejected at the %s stage.', v_request.item_description, v_stage.name),
      p_request_id
    );

    if v_session_id is not null then
      perform log_platform_event(
        'request.reject.during_impersonation', v_request.tenant_id, 'request', p_request_id::text,
        p_comment,
        jsonb_build_object('stage', v_stage.name, 'actor', v_actor, 'effective', v_effective, 'session_id', v_session_id),
        jsonb_build_object('status', 'rejected')
      );
    end if;

    return query select p_request_id, 'rejected'::text, v_stage.id, null::uuid;
    return;
  end if;

  if v_stage.is_finance_terminal_stage then
    update requests
    set status = 'closed', current_stage_id = null, updated_at = now()
    where id = p_request_id;

    select id into v_po_id from purchase_orders where request_id = p_request_id;

    insert into notifications (tenant_id, recipient_id, type, title, body, request_id, purchase_order_id)
    values (
      v_request.tenant_id,
      v_request.requester_id,
      'request_closed',
      'Request closed',
      format('Your request "%s" has been closed. The purchase order is ready for procurement.', v_request.item_description),
      p_request_id,
      v_po_id
    );

    return query select p_request_id, 'closed'::text, null::uuid, v_po_id;
    return;
  end if;

  -- Selection happens exactly once, at the stage flagged requires_offer_selection.
  -- Every other stage just reads whichever offer is currently marked selected.
  if v_stage.requires_offer_selection then
    if p_selected_offer_id is null then
      raise exception 'select a winning offer before approving';
    end if;
    if not exists (
      select 1 from request_offers
      where id = p_selected_offer_id and request_id = p_request_id
    ) then
      raise exception 'selected offer does not belong to this request';
    end if;

    update request_offers
    set is_selected = (id = p_selected_offer_id)
    where request_id = p_request_id;

    select * into v_offer from request_offers where id = p_selected_offer_id;
  else
    select * into v_offer from request_offers
    where request_id = p_request_id and is_selected
    limit 1;
  end if;

  if v_stage.threshold_amount is not null then
    if not found and v_offer.id is null then
      raise exception 'no offer on file to evaluate threshold';
    end if;
    if v_offer.quotation_amount <= v_stage.threshold_amount then
      v_next_stage_id := v_stage.next_stage_low_id;
    else
      v_next_stage_id := v_stage.next_stage_high_id;
    end if;
  else
    v_next_stage_id := v_stage.next_stage_low_id;
  end if;

  if v_next_stage_id is null then
    raise exception 'stage % has no next stage configured', v_stage.name;
  end if;

  select * into v_next_stage from workflow_stages where id = v_next_stage_id;

  if v_next_stage.is_finance_terminal_stage then
    if v_offer.id is null then
      raise exception 'no offer on file to generate a purchase order';
    end if;
    if exists (select 1 from purchase_orders where request_id = p_request_id) then
      raise exception 'a purchase order already exists for this request';
    end if;

    v_po_number := 'PO-' || to_char(now(), 'YYYY') || '-'
                   || lpad(nextval('public.po_number_seq')::text, 5, '0');

    insert into purchase_orders (request_id, po_number, vendor_name, vendor_account_id, amount, generated_by)
    values (p_request_id, v_po_number, v_offer.vendor_name, v_offer.vendor_account_id, v_offer.quotation_amount, v_actor)
    returning id into v_po_id;

    insert into notifications (tenant_id, recipient_id, type, title, body, request_id, purchase_order_id)
    values (
      v_request.tenant_id,
      v_request.requester_id,
      'purchase_order_generated',
      'Purchase order generated',
      format('A purchase order (%s) has been generated for your request "%s".', v_po_number, v_request.item_description),
      p_request_id,
      v_po_id
    );
  end if;

  update requests
  set current_stage_id = v_next_stage_id, updated_at = now()
  where id = p_request_id;

  insert into notifications (tenant_id, recipient_id, type, title, body, request_id)
  select distinct
    v_request.tenant_id,
    recipient_id,
    'approval_needed',
    'Approval needed',
    format('Request "%s" is awaiting your approval at the %s stage.', v_request.item_description, v_next_stage.name),
    p_request_id
  from (
    select aa.user_id as recipient_id
    from approval_assignments aa
    where aa.workflow_stage_id = v_next_stage_id

    union

    select d.delegate_user_id as recipient_id
    from approval_delegations d
    join approval_assignments aa on aa.user_id = d.delegator_user_id
    where d.status = 'active'
      and now() between d.starts_at and d.ends_at
      and aa.workflow_stage_id = v_next_stage_id
      and (d.workflow_stage_id is null or d.workflow_stage_id = v_next_stage_id)
  ) recipients;

  return query select p_request_id, 'open'::text, v_next_stage_id, v_po_id;
end;
$$;


--
-- Name: hr_employee_compensation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_employee_compensation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    basic_salary numeric NOT NULL,
    currency text DEFAULT 'UGX'::text NOT NULL,
    effective_date date NOT NULL,
    contract_reference text,
    note text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_employee_compensation_basic_salary_check CHECK ((basic_salary >= (0)::numeric))
);


--
-- Name: record_employee_compensation(uuid, numeric, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_employee_compensation(p_employee_id uuid, p_basic_salary numeric, p_effective_date date, p_contract_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS public.hr_employee_compensation
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row hr_employee_compensation%rowtype;
  v_tenant_id uuid;
begin
  if not (is_hr_team_member() and has_module_role('hr', array['manager'])) then
    raise exception 'not authorized to record compensation';
  end if;

  select tenant_id into v_tenant_id from hr_employees where id = p_employee_id;
  if v_tenant_id is null or v_tenant_id != get_my_tenant_id() then
    raise exception 'employee not found';
  end if;

  insert into hr_employee_compensation (tenant_id, employee_id, basic_salary, effective_date, contract_reference, note, created_by)
  values (v_tenant_id, p_employee_id, p_basic_salary, p_effective_date, p_contract_reference, p_note, auth.uid())
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: goods_issues; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.goods_issues (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    project_label text,
    voucher_no text,
    issue_date date DEFAULT CURRENT_DATE NOT NULL,
    warehouse_officer_id uuid NOT NULL,
    received_by_name text,
    approved_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: record_goods_issue(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_goods_issue(p_warehouse_id uuid, p_project_label text, p_voucher_no text, p_received_by_name text, p_approved_by_name text, p_items jsonb) RETURNS public.goods_issues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_issue goods_issues%ROWTYPE;
  v_item jsonb;
  v_item_no int := 1;
BEGIN
  IF NOT has_receipt_access() THEN
    RAISE EXCEPTION 'not authorized to record goods issues';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM warehouses WHERE id = p_warehouse_id AND tenant_id = get_my_tenant_id()) THEN
    RAISE EXCEPTION 'warehouse not found';
  END IF;

  IF jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'a goods issue needs at least one line item';
  END IF;

  INSERT INTO goods_issues (tenant_id, warehouse_id, project_label, voucher_no, warehouse_officer_id, received_by_name, approved_by_name)
  VALUES (get_my_tenant_id(), p_warehouse_id, p_project_label, p_voucher_no, auth.uid(), p_received_by_name, p_approved_by_name)
  RETURNING * INTO v_issue;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO goods_issue_items (
      goods_issue_id, item_no, material_catalog_id, material_description,
      cost_center_id, unit, requested_qty, delivered_qty, remarks
    )
    VALUES (
      v_issue.id, v_item_no,
      NULLIF(v_item->>'material_catalog_id', '')::uuid,
      v_item->>'material_description',
      NULLIF(v_item->>'cost_center_id', '')::uuid,
      v_item->>'unit',
      NULLIF(v_item->>'requested_qty', '')::numeric,
      (v_item->>'delivered_qty')::numeric,
      v_item->>'remarks'
    );
    v_item_no := v_item_no + 1;
  END LOOP;

  RETURN v_issue;
END;
$$;


--
-- Name: record_invoice_approval_decision(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_approval_decision(p_invoice_request_id uuid, p_decision text, p_comment text DEFAULT NULL::text, p_acting_on_behalf_of uuid DEFAULT NULL::uuid) RETURNS TABLE(out_invoice_request_id uuid, out_status text, out_stage_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invoice            invoice_requests%rowtype;
  v_stage              workflow_stages%rowtype;
  v_next_stage         workflow_stages%rowtype;
  v_next_stage_id      uuid;
  v_actor              uuid := auth.uid();
  v_effective          uuid := public.effective_user_id();
  v_session_id         uuid;
  v_is_platform_bypass boolean := public.platform_admin_bypass();
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid decision: %', p_decision;
  end if;

  select id into v_session_id
  from impersonation_sessions
  where platform_admin_id = v_actor
    and ended_at is null
    and expires_at > now()
  order by started_at desc
  limit 1;

  select * into v_invoice from invoice_requests where id = p_invoice_request_id for update;
  if not found then
    raise exception 'invoice request not found';
  end if;
  if v_invoice.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this invoice request';
  end if;
  if v_invoice.status != 'open' then
    raise exception 'invoice request is not open (status: %)', v_invoice.status;
  end if;
  if v_invoice.current_stage_id is null then
    raise exception 'invoice request has no current stage';
  end if;
  if not can_act_on_stage(v_invoice.current_stage_id) then
    raise exception 'not authorized to act on this stage';
  end if;

  -- Submitter-block: whoever submitted the invoice may never approve or reject
  -- it, at any stage. Compared against the effective identity.
  if v_invoice.requester_id = v_effective then
    raise exception 'you submitted this invoice -- a different reviewer must act on it';
  end if;

  select * into v_stage from workflow_stages where id = v_invoice.current_stage_id;

  insert into approval_actions
    (invoice_request_id, workflow_stage_id, approver_id, actor_id, effective_user_id,
     impersonation_session_id, acted_on_behalf_of, decision, comment)
  values
    (p_invoice_request_id, v_stage.id,
     case when v_is_platform_bypass then v_actor else v_effective end,
     v_actor, v_effective, v_session_id,
     p_acting_on_behalf_of, p_decision, p_comment);

  if p_decision = 'rejected' then
    update invoice_requests set status = 'rejected', updated_at = now() where id = p_invoice_request_id;

    insert into notifications (tenant_id, recipient_id, type, title, body, invoice_request_id)
    values (
      v_invoice.tenant_id,
      v_invoice.requester_id,
      'invoice_rejected',
      'Invoice rejected',
      format('Your invoice for "%s" (%s) was rejected at the %s stage.', v_invoice.vendor_name, v_invoice.amount, v_stage.name),
      p_invoice_request_id
    );

    return query select p_invoice_request_id, 'rejected'::text, v_stage.id;
    return;
  end if;

  if v_stage.is_finance_terminal_stage then
    update invoice_requests
    set status = 'closed', current_stage_id = null, updated_at = now()
    where id = p_invoice_request_id;

    insert into notifications (tenant_id, recipient_id, type, title, body, invoice_request_id)
    values (
      v_invoice.tenant_id,
      v_invoice.requester_id,
      'invoice_closed',
      'Invoice closed',
      format('Your invoice for "%s" (%s) has been fully approved and closed.', v_invoice.vendor_name, v_invoice.amount),
      p_invoice_request_id
    );

    return query select p_invoice_request_id, 'closed'::text, null::uuid;
    return;
  end if;

  if v_stage.threshold_amount is not null then
    if v_invoice.amount <= v_stage.threshold_amount then
      v_next_stage_id := v_stage.next_stage_low_id;
    else
      v_next_stage_id := v_stage.next_stage_high_id;
    end if;
  else
    v_next_stage_id := v_stage.next_stage_low_id;
  end if;

  if v_next_stage_id is null then
    raise exception 'stage % has no next stage configured', v_stage.name;
  end if;

  select * into v_next_stage from workflow_stages where id = v_next_stage_id;

  if v_next_stage.applies_to != 'invoices' then
    raise exception 'stage % is not configured for the invoice workflow -- check workflow_stages config', v_next_stage.name;
  end if;

  update invoice_requests
  set current_stage_id = v_next_stage_id, updated_at = now()
  where id = p_invoice_request_id;

  insert into notifications (tenant_id, recipient_id, type, title, body, invoice_request_id)
  select distinct
    v_invoice.tenant_id,
    recipient_id,
    'approval_needed',
    'Approval needed',
    format('An invoice for "%s" (%s) is awaiting your approval at the %s stage.', v_invoice.vendor_name, v_invoice.amount, v_next_stage.name),
    p_invoice_request_id
  from (
    select aa.user_id as recipient_id
    from approval_assignments aa
    where aa.workflow_stage_id = v_next_stage_id

    union

    select d.delegate_user_id as recipient_id
    from approval_delegations d
    join approval_assignments aa on aa.user_id = d.delegator_user_id
    where d.status = 'active'
      and now() between d.starts_at and d.ends_at
      and aa.workflow_stage_id = v_next_stage_id
      and (d.workflow_stage_id is null or d.workflow_stage_id = v_next_stage_id)
  ) recipients;

  return query select p_invoice_request_id, 'open'::text, v_next_stage_id;
end;
$$;


--
-- Name: record_line_item_receipt(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_line_item_receipt(p_line_item_id uuid, p_received_qty numeric, p_note text DEFAULT NULL::text) RETURNS public.line_item_receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request requests%ROWTYPE;
  v_line    request_line_items%ROWTYPE;
  v_already numeric;
  v_row     line_item_receipts%ROWTYPE;
BEGIN
  IF p_received_qty IS NULL OR p_received_qty <= 0 THEN
    RAISE EXCEPTION 'received quantity must be greater than zero';
  END IF;

  SELECT * INTO v_line FROM request_line_items WHERE id = p_line_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'line item not found';
  END IF;

  SELECT * INTO v_request FROM requests WHERE id = v_line.request_id;
  IF v_request.tenant_id != get_my_tenant_id() THEN
    RAISE EXCEPTION 'not authorized for this request';
  END IF;
  IF v_request.status != 'closed' THEN
    RAISE EXCEPTION 'goods can only be received against a closed request (PO already generated)';
  END IF;
  IF NOT has_receipt_access() THEN
    RAISE EXCEPTION 'not authorized to record receipts';
  END IF;

  SELECT COALESCE(SUM(received_qty), 0) INTO v_already
  FROM line_item_receipts WHERE line_item_id = p_line_item_id;

  IF v_already + p_received_qty > v_line.quantity * 2 THEN
    RAISE EXCEPTION 'received quantity (%) is more than double what was ordered (%) -- check for a data entry error',
      v_already + p_received_qty, v_line.quantity;
  END IF;

  INSERT INTO line_item_receipts (line_item_id, received_qty, received_by, note)
  VALUES (p_line_item_id, p_received_qty, auth.uid(), p_note)
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: record_line_item_receipt(uuid, numeric, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_line_item_receipt(p_line_item_id uuid, p_received_qty numeric, p_warehouse_id uuid, p_voucher_no text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS public.line_item_receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.line_item_receipts;
BEGIN
  v_row := public.record_line_item_receipt(p_line_item_id, p_received_qty, p_note);

  UPDATE line_item_receipts
  SET warehouse_id = p_warehouse_id, voucher_no = p_voucher_no
  WHERE id = v_row.id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: record_po_pdf(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_po_pdf(p_purchase_order_id uuid, p_storage_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update purchase_orders po
  set pdf_storage_path = p_storage_path,
      pdf_generated_at = now()
  from requests r
  where po.id = p_purchase_order_id
    and po.request_id = r.id
    and r.tenant_id = get_my_tenant_id();

  if not found then
    raise exception 'Purchase order not found or not accessible';
  end if;
end;
$$;


--
-- Name: record_ticket_approval(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_ticket_approval(p_ticket_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS public.it_tickets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ticket public.it_tickets%rowtype;
begin
  if p_decision not in ('approved','rejected') then
    raise exception 'invalid decision: %', p_decision;
  end if;
  if not is_it_support() then
    raise exception 'not authorized to approve tickets';
  end if;

  select * into v_ticket from it_tickets where id = p_ticket_id for update;
  if not found then
    raise exception 'ticket not found';
  end if;
  if v_ticket.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this ticket';
  end if;
  if v_ticket.approval_status != 'pending' then
    raise exception 'ticket is not pending approval';
  end if;

  update it_tickets
  set approval_status = p_decision,
      approved_by = auth.uid(),
      approved_at = now(),
      approval_notes = p_notes,
      status = case when p_decision = 'rejected' then 'closed' else status end,
      resolution_notes = case when p_decision = 'rejected'
        then coalesce(resolution_notes, 'Rejected at approval: ' || coalesce(p_notes, 'no reason given'))
        else resolution_notes end,
      closed_at = case when p_decision = 'rejected' and closed_at is null then now() else closed_at end,
      updated_at = now()
  where id = p_ticket_id
  returning * into v_ticket;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    v_ticket.tenant_id,
    v_ticket.requester_id,
    'ticket_approval_decision',
    'Ticket ' || v_ticket.ticket_number || ' ' || p_decision,
    format('Your ticket "%s" was %s.', v_ticket.subject, p_decision)
  );

  return v_ticket;
end;
$$;


--
-- Name: reg_approve_parameter(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_approve_parameter(p_id uuid) RETURNS public.regulatory_parameters
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row      regulatory_parameters%rowtype;
  v_uid      uuid := auth.uid();
  v_category text;
begin
  select * into v_row from regulatory_parameters
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'REG_NOT_FOUND: parameter not found';
  end if;
  if v_row.status <> 'draft' then
    raise exception 'REG_NOT_DRAFT: only a draft can be approved (this one is %)', v_row.status;
  end if;
  if v_row.created_by is not distinct from v_uid then
    raise exception 'REG_SELF_APPROVAL: the person who proposed a value cannot approve it';
  end if;

  select category into v_category from regulatory_parameter_definitions where key = v_row.parameter_key;
  if not exists (
    select 1 from regulatory_approval_assignments a
     where a.tenant_id = v_row.tenant_id
       and a.user_id = v_uid
       and a.withdrawn_at is null
       and current_date between a.effective_from and coalesce(a.effective_to, date 'infinity')
       and ((a.scope = 'key' and a.scope_value = v_row.parameter_key)
            or (a.scope = 'category' and a.scope_value = v_category))
  ) then
    raise exception 'REG_NOT_APPROVER: you are not assigned to approve % (approval follows the responsibility for the submission, not the role)', v_row.parameter_key
      using errcode = '42501';
  end if;

  perform set_config('reg.via_rpc', 'on', true);
  update regulatory_parameters
     set status = 'approved', approved_by = v_uid, approved_at = now()
   where id = p_id
   returning * into v_row;
  perform set_config('reg.via_rpc', 'off', true);

  insert into regulatory_parameter_events (tenant_id, parameter_id, event, actor, detail)
  values (v_row.tenant_id, v_row.id, 'approved', v_uid, v_row.source_ref);
  return v_row;
end;
$$;


--
-- Name: regulatory_approval_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.regulatory_approval_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    scope text NOT NULL,
    scope_value text NOT NULL,
    responsibility text NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    assigned_by uuid DEFAULT auth.uid() NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    withdrawn_at timestamp with time zone,
    withdrawn_by uuid,
    withdrawn_reason text,
    CONSTRAINT reg_approval_assignment_dates CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT reg_approval_assignment_withdrawn CHECK ((((withdrawn_at IS NULL) AND (withdrawn_by IS NULL) AND (withdrawn_reason IS NULL)) OR ((withdrawn_at IS NOT NULL) AND (withdrawn_by IS NOT NULL) AND (length(btrim(COALESCE(withdrawn_reason, ''::text))) > 0)))),
    CONSTRAINT regulatory_approval_assignments_responsibility_check CHECK ((length(btrim(responsibility)) > 0)),
    CONSTRAINT regulatory_approval_assignments_scope_check CHECK ((scope = ANY (ARRAY['key'::text, 'category'::text])))
);


--
-- Name: reg_assign_approver(uuid, text, text, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_assign_approver(p_user_id uuid, p_scope text, p_scope_value text, p_responsibility text, p_effective_from date DEFAULT CURRENT_DATE, p_effective_to date DEFAULT NULL::date) RETURNS public.regulatory_approval_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row regulatory_approval_assignments%rowtype;
begin
  if not is_tenant_admin() then
    raise exception 'REG_FORBIDDEN: only a company admin can assign an approver' using errcode = '42501';
  end if;
  if p_scope not in ('key', 'category') then
    raise exception 'REG_INPUT: scope must be key or category';
  end if;
  if nullif(btrim(p_responsibility), '') is null then
    raise exception 'REG_INPUT: state the responsibility this approval covers (for example, the submission it supports)';
  end if;
  if not exists (select 1 from app_users where id = p_user_id and tenant_id = get_my_tenant_id()) then
    raise exception 'REG_NOT_FOUND: approver is not a user of this company';
  end if;

  insert into regulatory_approval_assignments
    (tenant_id, user_id, scope, scope_value, responsibility, effective_from, effective_to, assigned_by)
  values
    (get_my_tenant_id(), p_user_id, p_scope, btrim(p_scope_value), btrim(p_responsibility),
     p_effective_from, p_effective_to, auth.uid())
  returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: reg_end_parameter(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_end_parameter(p_id uuid, p_effective_to date) RETURNS public.regulatory_parameters
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row regulatory_parameters%rowtype;
  v_uid uuid := auth.uid();
begin
  select * into v_row from regulatory_parameters
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'REG_NOT_FOUND: parameter not found';
  end if;
  if not is_tenant_admin() then
    raise exception 'REG_FORBIDDEN: only a company admin can end-date a regulatory parameter' using errcode = '42501';
  end if;
  if v_row.status <> 'approved' then
    raise exception 'REG_NOT_APPROVED: only an approved value can be end-dated (this one is %)', v_row.status;
  end if;
  if p_effective_to is null or p_effective_to <= v_row.effective_from then
    raise exception 'REG_END_DATE: the end date must be after the start date (%)', v_row.effective_from;
  end if;
  if v_row.effective_to is not null and p_effective_to >= v_row.effective_to then
    raise exception 'REG_END_DATE: the end date must be earlier than the current end date (%)', v_row.effective_to;
  end if;

  perform set_config('reg.via_rpc', 'on', true);
  update regulatory_parameters set effective_to = p_effective_to where id = p_id returning * into v_row;
  perform set_config('reg.via_rpc', 'off', true);

  insert into regulatory_parameter_events (tenant_id, parameter_id, event, actor, detail)
  values (v_row.tenant_id, v_row.id, 'ended', v_uid, 'effective to ' || p_effective_to::text);
  return v_row;
end;
$$;


--
-- Name: reg_get_parameter(text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_get_parameter(p_key text, p_on date DEFAULT CURRENT_DATE, p_class text DEFAULT NULL::text) RETURNS public.regulatory_parameters
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not (is_tenant_admin() or is_finance_team_member(null::text) or can_access_insurance()) then
    raise exception 'REG_FORBIDDEN: regulatory parameters are visible to company admins, finance and insurance users' using errcode = '42501';
  end if;
  return platform_reg_resolve(get_my_tenant_id(), p_key, p_on, p_class);
end;
$$;


--
-- Name: reg_retire_parameter(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_retire_parameter(p_id uuid, p_reason text) RETURNS public.regulatory_parameters
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row regulatory_parameters%rowtype;
  v_uid uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into v_row from regulatory_parameters
  where id = p_id and tenant_id = get_my_tenant_id()
  for update;
  if not found then
    raise exception 'REG_NOT_FOUND: parameter not found';
  end if;
  if length(v_reason) < 5 then
    raise exception 'REG_REASON: give a reason of at least five characters';
  end if;
  if v_row.status = 'retired' then
    raise exception 'REG_RETIRED_IMMUTABLE: already retired';
  end if;
  if v_row.status = 'approved' and not is_tenant_admin() then
    raise exception 'REG_FORBIDDEN: only a company admin can retire an approved value' using errcode = '42501';
  end if;
  if v_row.status = 'draft'
     and not (is_tenant_admin() or v_row.created_by is not distinct from v_uid) then
    raise exception 'REG_FORBIDDEN: only the proposer or a company admin can withdraw a draft' using errcode = '42501';
  end if;

  perform set_config('reg.via_rpc', 'on', true);
  update regulatory_parameters
     set status = 'retired', retired_reason = v_reason
   where id = p_id
   returning * into v_row;
  perform set_config('reg.via_rpc', 'off', true);

  insert into regulatory_parameter_events (tenant_id, parameter_id, event, actor, detail)
  values (v_row.tenant_id, v_row.id, 'retired', v_uid, v_reason);
  return v_row;
end;
$$;


--
-- Name: reg_withdraw_approver(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reg_withdraw_approver(p_assignment_id uuid, p_reason text) RETURNS public.regulatory_approval_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row regulatory_approval_assignments%rowtype;
begin
  if not is_tenant_admin() then
    raise exception 'REG_FORBIDDEN: only a company admin can withdraw an approver' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then
    raise exception 'REG_INPUT: a reason is required to withdraw an approver';
  end if;
  select * into v_row from regulatory_approval_assignments
   where id = p_assignment_id and tenant_id = get_my_tenant_id()
   for update;
  if not found then
    raise exception 'REG_NOT_FOUND: approval assignment not found';
  end if;
  if v_row.withdrawn_at is not null then
    raise exception 'REG_NOT_FOUND: this approval assignment is already withdrawn';
  end if;

  update regulatory_approval_assignments
     set withdrawn_at = now(), withdrawn_by = auth.uid(), withdrawn_reason = btrim(p_reason)
   where id = p_assignment_id
   returning * into v_row;
  return v_row;
end;
$$;


--
-- Name: regulatory_approval_assignments_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regulatory_approval_assignments_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.tenant_id is distinct from old.tenant_id or new.user_id is distinct from old.user_id
       or new.scope is distinct from old.scope or new.scope_value is distinct from old.scope_value
       or new.responsibility is distinct from old.responsibility
       or new.effective_from is distinct from old.effective_from
       or new.effective_to is distinct from old.effective_to
       or new.assigned_by is distinct from old.assigned_by or new.assigned_at is distinct from old.assigned_at then
      raise exception 'REG_ASSIGNMENT_IMMUTABLE: only a withdrawal can be recorded on an approval assignment';
    end if;
    return new;
  end if;

  if not exists (select 1 from app_users where id = new.user_id and tenant_id = new.tenant_id) then
    raise exception 'REG_NOT_FOUND: approver is not a user of this company';
  end if;

  if new.scope = 'key' then
    if not exists (select 1 from regulatory_parameter_definitions where key = new.scope_value) then
      raise exception 'REG_NOT_FOUND: % is not a known parameter key', new.scope_value;
    end if;
  elsif not exists (select 1 from regulatory_parameter_definitions where category = new.scope_value) then
    raise exception 'REG_NOT_FOUND: % is not a known parameter category', new.scope_value;
  end if;
  return new;
end;
$$;


--
-- Name: regulatory_parameters_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regulatory_parameters_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_def regulatory_parameter_definitions%rowtype;
  v_via boolean := coalesce(current_setting('reg.via_rpc', true), '') = 'on';
begin
  select * into v_def from regulatory_parameter_definitions where key = new.parameter_key;
  if not found then
    raise exception 'REG_UNKNOWN_KEY: % is not a known parameter key', new.parameter_key;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'REG_STATUS: a new parameter starts as a draft; approval is a separate step by a different person';
    end if;
    if new.approved_by is not null or new.approved_at is not null or new.retired_reason is not null then
      raise exception 'REG_STATUS: approval and retirement fields cannot be set on a new draft';
    end if;
  else
    if new.tenant_id is distinct from old.tenant_id then
      raise exception 'REG_TENANT_IMMUTABLE: a parameter cannot move to another company';
    end if;
    if new.parameter_key is distinct from old.parameter_key then
      raise exception 'REG_KEY_IMMUTABLE: the key cannot change; retire this row and add a new one';
    end if;
    if old.status = 'retired' then
      raise exception 'REG_RETIRED_IMMUTABLE: a retired parameter cannot be changed';
    end if;
    if new.status is distinct from old.status and not v_via then
      raise exception 'REG_STATUS_VIA_RPC: change status with reg_approve_parameter or reg_retire_parameter';
    end if;

    if old.status = 'approved' then
      if not v_via then
        raise exception 'REG_APPROVED_IMMUTABLE: an approved value cannot be edited; end-date it with reg_end_parameter and add a new row';
      end if;
      -- Through the RPCs only status, effective_to and retired_reason may move.
      if new.value_num is distinct from old.value_num
         or new.value_text is distinct from old.value_text
         or new.currency is distinct from old.currency
         or new.applies_to is distinct from old.applies_to
         or new.effective_from is distinct from old.effective_from
         or new.source_ref is distinct from old.source_ref
         or new.created_by is distinct from old.created_by
         or new.approved_by is distinct from old.approved_by
         or new.approved_at is distinct from old.approved_at then
        raise exception 'REG_APPROVED_IMMUTABLE: only the end date and status of an approved value can change';
      end if;
      if new.effective_to is distinct from old.effective_to
         and (new.effective_to is null
              or (old.effective_to is not null and new.effective_to >= old.effective_to)) then
        raise exception 'REG_END_DATE: an approved value can only be shortened, never extended';
      end if;
      return new;
    end if;
  end if;

  -- Value rules, for every new draft and every edit of a draft.
  if new.applies_to is not null and not v_def.class_scoped then
    raise exception 'REG_CLASS_NOT_ALLOWED: % does not vary by class', new.parameter_key;
  end if;

  if v_def.value_type = 'text' then
    if new.value_text is null or btrim(new.value_text) = '' or new.value_num is not null or new.currency is not null then
      raise exception 'REG_VALUE_INVALID: % takes a text value only', new.parameter_key;
    end if;
  else
    if new.value_num is null or new.value_text is not null then
      raise exception 'REG_VALUE_INVALID: % takes a number only', new.parameter_key;
    end if;
    if new.value_num < 0 then
      raise exception 'REG_VALUE_INVALID: % cannot be negative', new.parameter_key;
    end if;
    if v_def.value_type = 'amount' then
      if new.currency is null then
        raise exception 'REG_VALUE_INVALID: % is an amount and needs a currency', new.parameter_key;
      end if;
    else
      if new.currency is not null then
        raise exception 'REG_VALUE_INVALID: % is not an amount and cannot carry a currency', new.parameter_key;
      end if;
      if v_def.value_type = 'percent' and new.value_num > 100 then
        raise exception 'REG_VALUE_INVALID: % is a percentage and cannot exceed 100', new.parameter_key;
      end if;
      if v_def.value_type in ('days', 'years') and new.value_num <> trunc(new.value_num) then
        raise exception 'REG_VALUE_INVALID: % must be a whole number of %', new.parameter_key, v_def.value_type;
      end if;
    end if;
  end if;

  -- Approval: no overlap with another approved row for the same key and class.
  if new.status = 'approved' and tg_op = 'UPDATE' and old.status <> 'approved' then
    perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text || ':' || new.parameter_key, 0));
    if exists (
      select 1
      from regulatory_parameters o
      where o.tenant_id = new.tenant_id
        and o.parameter_key = new.parameter_key
        and o.status = 'approved'
        and coalesce(o.applies_to, '') = coalesce(new.applies_to, '')
        and o.id <> new.id
        and new.effective_from < coalesce(o.effective_to, 'infinity'::date)
        and o.effective_from < coalesce(new.effective_to, 'infinity'::date)
    ) then
      raise exception 'REG_OVERLAP: another approved value for % already covers part of this period; end-date it first', new.parameter_key;
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: material_request_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.material_request_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    material_type_id uuid,
    material_group_id uuid,
    external_material_group_id uuid,
    unit text,
    name text NOT NULL,
    description_tr text,
    description_en text,
    description_fr text,
    old_material_code text,
    status text DEFAULT 'pending'::text NOT NULL,
    rejection_message text,
    material_catalog_id uuid,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT material_request_items_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: reject_all_material_request_items(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_all_material_request_items(p_batch_id uuid, p_message text) RETURNS SETOF public.material_request_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item_id uuid;
begin
  for v_item_id in
    select id from material_request_items
    where batch_id = p_batch_id and tenant_id = get_my_tenant_id() and status = 'pending'
  loop
    return next reject_material_request_item(v_item_id, p_message);
  end loop;
end;
$$;


--
-- Name: reject_material_request_item(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_material_request_item(p_item_id uuid, p_message text) RETURNS public.material_request_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item material_request_items%rowtype;
  v_batch material_request_batches%rowtype;
begin
  if not has_po_access() then
    raise exception 'not authorized to reject material requests';
  end if;

  if p_message is null or trim(p_message) = '' then
    raise exception 'a message is required to reject a material request item';
  end if;

  select * into v_item from material_request_items
  where id = p_item_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'material request item not found';
  end if;

  if v_item.status <> 'pending' then
    raise exception 'this item has already been decided';
  end if;

  update material_request_items
  set status = 'rejected', rejection_message = trim(p_message), decided_by = auth.uid(), decided_at = now()
  where id = p_item_id
  returning * into v_item;

  select * into v_batch from material_request_batches where id = v_item.batch_id;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    v_item.tenant_id, v_batch.requester_id, 'material_request_rejected',
    'Material request rejected',
    format('"%s" was rejected: %s', v_item.name, trim(p_message))
  );

  return v_item;
end;
$$;


--
-- Name: reject_payroll_run(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_payroll_run(p_run_id uuid, p_reason text) RETURNS public.hr_payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row       hr_payroll_runs%rowtype;
  v_effective uuid := effective_user_id();
  v_session   uuid;
begin
  if not is_payroll_approver() then
    raise exception 'not authorized to reject payroll';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a rejection reason is required';
  end if;

  select id into v_session from impersonation_sessions
  where platform_admin_id = auth.uid() and ended_at is null and expires_at > now()
  order by started_at desc limit 1;

  update hr_payroll_runs
  set status = 'rejected', rejected_by = auth.uid(), rejected_at = now(), rejection_reason = p_reason,
      effective_user_id = v_effective, impersonation_session_id = v_session
  where id = p_run_id and tenant_id = get_my_tenant_id() and status = 'pending_approval'
  returning * into v_row;

  if v_row.id is null then
    raise exception 'payroll run not found, or not pending approval';
  end if;

  if v_row.prepared_by is not null then
    insert into notifications (tenant_id, recipient_id, type, title, body)
    values (v_row.tenant_id, v_row.prepared_by, 'payroll_run_rejected', 'Payroll run rejected: ' || v_row.period,
            format('The %s payroll run was rejected. Reason: %s', v_row.period, p_reason));
  end if;

  return v_row;
end;
$$;


--
-- Name: remove_finance_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_finance_role(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_tenant_admin() then
    raise exception 'not authorized to manage finance access';
  end if;

  delete from finance_team_members
  where user_id = p_user_id
    and tenant_id = get_my_tenant_id();
end;
$$;


--
-- Name: remove_group_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_group_member(p_group_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to manage group membership';
  end if;
  delete from user_group_members
  where group_id = p_group_id and user_id = p_user_id
    and group_id in (select id from user_groups where tenant_id = get_my_tenant_id());
end;
$$;


--
-- Name: remove_staff_module(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_staff_module(p_user_id uuid, p_module text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_tenant_admin() then
    raise exception 'not authorized to manage team access';
  end if;

  delete from staff_roles
  where user_id = p_user_id
    and tenant_id = get_my_tenant_id()
    and module = p_module;
end;
$$;


--
-- Name: remove_support_team_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_support_team_member(p_team_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to manage team membership';
  end if;
  delete from support_team_members
  where team_id = p_team_id and user_id = p_user_id
    and team_id in (select id from support_teams where tenant_id = get_my_tenant_id());
end;
$$;


--
-- Name: require_platform_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_platform_admin(p_action text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not is_platform_admin() then
    raise exception 'PLATFORM_ADMIN_REQUIRED: % is restricted to platform admins',
      coalesce(p_action, 'this action')
      using errcode = '42501';
  end if;

  if platform_admin_has_mfa_factor() and not platform_session_is_mfa() then
    raise exception 'PLATFORM_MFA_REQUIRED: % requires a session verified with your authenticator (sign out and back in with your code)',
      coalesce(p_action, 'this action')
      using errcode = '42501';
  end if;
end;
$$;


--
-- Name: resolve_or_create_vendor_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_or_create_vendor_account(p_tenant_id uuid, p_vendor_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid;
  v_next_num   int;
  v_code       text;
begin
  if p_vendor_name is null or trim(p_vendor_name) = '' then
    return null;
  end if;

  select id into v_account_id
  from accounts
  where tenant_id = p_tenant_id
    and account_type in ('vendor', 'both')
    and lower(trim(name)) = lower(trim(p_vendor_name))
  limit 1;

  if found then
    return v_account_id;
  end if;

  select coalesce(max(nullif(regexp_replace(account_code, '^VEN-', ''), account_code)::int), 0) + 1
  into v_next_num
  from accounts
  where tenant_id = p_tenant_id
    and account_code like 'VEN-%';

  v_code := 'VEN-' || lpad(v_next_num::text, 4, '0');

  insert into accounts (tenant_id, account_code, name, account_type, is_active)
  values (p_tenant_id, v_code, trim(p_vendor_name), 'vendor', true)
  returning id into v_account_id;

  return v_account_id;
end;
$$;


--
-- Name: return_asset(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_asset(p_assignment_id uuid, p_notes text DEFAULT NULL::text) RETURNS public.asset_assignments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment public.asset_assignments%rowtype;
  v_asset public.assets%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to return assets';
  end if;
  select * into v_assignment from asset_assignments where id = p_assignment_id for update;
  if not found then
    raise exception 'assignment not found';
  end if;
  if v_assignment.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this assignment';
  end if;
  if v_assignment.returned_at is not null then
    raise exception 'assignment already returned';
  end if;

  update asset_assignments
  set returned_at = now(),
      notes = coalesce(p_notes, notes)
  where id = p_assignment_id
  returning * into v_assignment;

  update assets set status = 'in_stock', updated_at = now()
  where id = v_assignment.asset_id
  returning * into v_asset;

  return v_assignment;
end;
$$;


--
-- Name: revise_payroll_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revise_payroll_run(p_run_id uuid) RETURNS public.hr_payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row hr_payroll_runs%rowtype;
begin
  if not is_hr_team_member() then
    raise exception 'not authorized: HR team membership required';
  end if;

  update hr_payroll_runs
  set status = 'draft', rejected_by = null, rejected_at = null, rejection_reason = null,
      effective_user_id = null, impersonation_session_id = null
  where id = p_run_id and tenant_id = get_my_tenant_id() and status = 'rejected'
  returning * into v_row;

  if v_row.id is null then
    raise exception 'payroll run not found, or not in rejected status';
  end if;

  return v_row;
end;
$$;


--
-- Name: revoke_hr_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_hr_team_member(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not has_module_role('hr', array['admin']) then
    raise exception 'not authorized to manage the HR team';
  end if;

  delete from hr_team_members
  where user_id = p_user_id and tenant_id = get_my_tenant_id();
end;
$$;


--
-- Name: revoke_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_invitation(p_invitation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_invitation invitations%rowtype;
  v_caller_is_platform_admin boolean;
  v_caller_tenant_id uuid;
begin
  select * into v_invitation
  from invitations
  where id = p_invitation_id;

  if not found then
    raise exception 'Invitation not found';
  end if;

  v_caller_is_platform_admin := is_platform_admin();
  v_caller_tenant_id := get_my_tenant_id();

  if not (
    v_caller_is_platform_admin
    or (
      v_invitation.role_bundle = 'member'
      and v_invitation.tenant_id = v_caller_tenant_id
      and is_tenant_admin()
    )
  ) then
    raise exception 'Not authorized to revoke this invitation';
  end if;

  if v_invitation.status <> 'pending' then
    raise exception 'Only pending invitations can be revoked (this one is %)', v_invitation.status;
  end if;

  update invitations set status = 'revoked' where id = p_invitation_id;

  -- Only platform-level revokes are platform events; a company admin
  -- revoking their own member invite is tenant business.
  if v_caller_is_platform_admin then
    perform log_platform_event(
      'invitation.revoke', v_invitation.tenant_id, 'invitation', p_invitation_id::text, null,
      jsonb_build_object('email', v_invitation.email, 'role_bundle', v_invitation.role_bundle, 'status', 'pending'),
      jsonb_build_object('status', 'revoked')
    );
  end if;
end;
$$;


--
-- Name: revoke_receipt_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_receipt_access(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_finance_team_member('finance') THEN
    RAISE EXCEPTION 'not authorized to revoke material receipt access';
  END IF;

  DELETE FROM material_receipt_assignments
  WHERE tenant_id = get_my_tenant_id() AND user_id = p_user_id;
END;
$$;


--
-- Name: run_operator_digest_now(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_operator_digest_now() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  perform require_platform_admin('Generating the operator digest');
  v_id := platform_run_operator_digest('manual');
  return (select to_jsonb(d) from platform_digests d where d.id = v_id);
end;
$$;


--
-- Name: save_feature_flag(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_feature_flag(p_key text, p_description text, p_default_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare v_before jsonb;
begin
  perform require_platform_admin('Editing feature flags');
  if p_key !~ '^[a-z][a-z0-9_.]{1,63}$' then
    raise exception 'FLAG_KEY_INVALID: keys are lowercase letters, digits, dots or underscores (2-64 chars)';
  end if;
  select to_jsonb(f) into v_before from platform_feature_flags f where f.key = p_key;
  insert into platform_feature_flags (key, description, default_enabled, updated_by)
  values (p_key, nullif(btrim(p_description), ''), coalesce(p_default_enabled, false), auth.uid())
  on conflict (key) do update
    set description = excluded.description, default_enabled = excluded.default_enabled, updated_at = now(), updated_by = auth.uid();
  perform log_platform_event(
    case when v_before is null then 'feature_flag.create' else 'feature_flag.update' end,
    null, 'feature_flag', p_key, null, v_before, (select to_jsonb(f) from platform_feature_flags f where f.key = p_key));
end;
$_$;


--
-- Name: save_industry_template(text, text, text, jsonb, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_industry_template(p_key text, p_name text, p_description text, p_items jsonb, p_is_active boolean DEFAULT true, p_sort_order integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_before jsonb;
  v_item   jsonb;
  v_kinds  text[] := array['department', 'module', 'workflow_stage', 'gl_account', 'posting_rule', 'feature_flag'];
  v_types  text[] := array['asset', 'liability', 'equity', 'revenue', 'expense'];
  v_orders integer[];
  v_codes  text[];
  v_dup    text;
begin
  perform require_platform_admin('Editing industry templates');

  if p_key !~ '^[a-z][a-z0-9_]{1,39}$' then
    raise exception 'TEMPLATE_KEY_INVALID: key must be 2-40 chars, lowercase letters, digits or underscores, starting with a letter';
  end if;
  if coalesce(btrim(p_name), '') = '' then
    raise exception 'TEMPLATE_NAME_REQUIRED: a template needs a name';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'TEMPLATE_ITEMS_INVALID: items must be an array';
  end if;

  -- Codes of the template's own GL accounts, for posting-rule validation.
  select coalesce(array_agg(btrim(i ->> 'name')), '{}') into v_codes
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i
  where i ->> 'kind' = 'gl_account';

  -- Validate items.
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    if (v_item ->> 'kind') is null or not ((v_item ->> 'kind') = any (v_kinds)) then
      raise exception 'TEMPLATE_ITEMS_INVALID: unknown kind %', coalesce(v_item ->> 'kind', '(missing)');
    end if;
    if coalesce(btrim(v_item ->> 'name'), '') = '' then
      raise exception 'TEMPLATE_ITEMS_INVALID: every item needs a name';
    end if;
    if (v_item ->> 'kind') = 'module' and not exists (
         select 1 from platform_modules m
         where m.key = (v_item ->> 'name') and m.is_active and m.tenant_entitled
       ) then
      raise exception 'TEMPLATE_ITEMS_INVALID: unknown module %', v_item ->> 'name';
    end if;
    if (v_item ->> 'kind') = 'workflow_stage' and coalesce(btrim(v_item -> 'payload' ->> 'approver_role'), '') = '' then
      raise exception 'TEMPLATE_ITEMS_INVALID: stage "%" needs an approver_role', v_item ->> 'name';
    end if;

    if (v_item ->> 'kind') = 'gl_account' then
      if btrim(v_item ->> 'name') !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,19}$' then
        raise exception 'TEMPLATE_ITEMS_INVALID: account code "%" must be 1-20 characters: letters, digits, dot, dash or underscore', v_item ->> 'name';
      end if;
      if coalesce(btrim(v_item -> 'payload' ->> 'name'), '') = '' then
        raise exception 'TEMPLATE_ITEMS_INVALID: account "%" needs a name in its payload', v_item ->> 'name';
      end if;
      if not coalesce((v_item -> 'payload' ->> 'account_type') = any (v_types), false) then
        raise exception 'TEMPLATE_ITEMS_INVALID: account "%" has an invalid account_type (use asset, liability, equity, revenue or expense)', v_item ->> 'name';
      end if;
      if (v_item -> 'payload') ? 'is_control_account'
         and jsonb_typeof(v_item -> 'payload' -> 'is_control_account') <> 'boolean' then
        raise exception 'TEMPLATE_ITEMS_INVALID: account "%" is_control_account must be true or false', v_item ->> 'name';
      end if;
    end if;

    if (v_item ->> 'kind') = 'posting_rule' then
      if not (btrim(v_item ->> 'name') = any (platform_gl_posting_roles())) then
        raise exception 'TEMPLATE_ITEMS_INVALID: unknown posting role "%"', v_item ->> 'name';
      end if;
      if not coalesce(btrim(v_item -> 'payload' ->> 'account_code') = any (v_codes), false) then
        raise exception 'TEMPLATE_ITEMS_INVALID: posting rule "%" points at account "%" which is not a gl_account in this template',
          v_item ->> 'name', coalesce(v_item -> 'payload' ->> 'account_code', '(none)');
      end if;
    end if;

    if (v_item ->> 'kind') = 'feature_flag' then
      if not exists (select 1 from platform_feature_flags f where f.key = btrim(v_item ->> 'name')) then
        raise exception 'TEMPLATE_ITEMS_INVALID: unknown feature flag "%"', v_item ->> 'name';
      end if;
      if (v_item -> 'payload') ? 'enabled' and jsonb_typeof(v_item -> 'payload' -> 'enabled') <> 'boolean' then
        raise exception 'TEMPLATE_ITEMS_INVALID: flag "%" enabled must be true or false', v_item ->> 'name';
      end if;
    end if;
  end loop;

  -- One item per (kind, name): the table is UNIQUE on it, so say so plainly.
  select i ->> 'kind' || ' "' || btrim(i ->> 'name') || '"' into v_dup
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i
  group by i ->> 'kind', btrim(i ->> 'name')
  having count(*) > 1
  limit 1;
  if v_dup is not null then
    raise exception 'TEMPLATE_ITEMS_INVALID: duplicate item %', v_dup;
  end if;

  -- Stage routing must point at stages that exist in this template.
  select array_agg((i ->> 'sort_order')::integer) into v_orders
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i where i ->> 'kind' = 'workflow_stage';
  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i where i ->> 'kind' = 'workflow_stage' loop
    if (v_item -> 'payload' ->> 'next_low') is not null and not ((v_item -> 'payload' ->> 'next_low')::integer = any (v_orders)) then
      raise exception 'TEMPLATE_ITEMS_INVALID: stage "%" routes (low) to a stage that does not exist', v_item ->> 'name';
    end if;
    if (v_item -> 'payload' ->> 'next_high') is not null and not ((v_item -> 'payload' ->> 'next_high')::integer = any (v_orders)) then
      raise exception 'TEMPLATE_ITEMS_INVALID: stage "%" routes (high) to a stage that does not exist', v_item ->> 'name';
    end if;
  end loop;

  select to_jsonb(t) || jsonb_build_object('items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.kind, i.sort_order), '[]'::jsonb) from industry_template_items i where i.template_key = t.key))
    into v_before from industry_templates t where t.key = p_key;

  insert into industry_templates (key, name, description, is_active, sort_order, updated_by)
  values (p_key, btrim(p_name), nullif(btrim(p_description), ''), coalesce(p_is_active, true), coalesce(p_sort_order, 100), auth.uid())
  on conflict (key) do update
    set name = excluded.name, description = excluded.description, is_active = excluded.is_active,
        sort_order = excluded.sort_order, updated_at = now(), updated_by = auth.uid();

  delete from industry_template_items where template_key = p_key;
  insert into industry_template_items (template_key, kind, sort_order, name, payload)
  select p_key, i ->> 'kind', coalesce((i ->> 'sort_order')::integer, rn::integer), btrim(i ->> 'name'), coalesce(i -> 'payload', '{}'::jsonb)
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) with ordinality as x(i, rn);

  perform log_platform_event(
    case when v_before is null then 'industry_template.create' else 'industry_template.update' end,
    null, 'industry_template', p_key, null, v_before,
    (select to_jsonb(t) || jsonb_build_object('items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.kind, i.sort_order), '[]'::jsonb) from industry_template_items i where i.template_key = t.key))
       from industry_templates t where t.key = p_key)
  );

  return (select to_jsonb(r) from list_industry_templates(true) r where r.key = p_key);
end;
$_$;


--
-- Name: save_platform_announcement(uuid, text, text, text, uuid, timestamp with time zone, timestamp with time zone, boolean, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_platform_announcement(p_id uuid, p_title text, p_body text, p_severity text DEFAULT 'info'::text, p_tenant_id uuid DEFAULT NULL::uuid, p_starts_at timestamp with time zone DEFAULT now(), p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_dismissible boolean DEFAULT true, p_link_url text DEFAULT NULL::text, p_link_label text DEFAULT NULL::text, p_is_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_id     uuid := p_id;
  v_before jsonb;
begin
  perform require_platform_admin('Publishing announcements');
  if coalesce(btrim(p_title), '') = '' or coalesce(btrim(p_body), '') = '' then
    raise exception 'ANNOUNCEMENT_INVALID: title and body are required';
  end if;
  if p_tenant_id is not null and not exists (select 1 from tenants where id = p_tenant_id) then
    raise exception 'ANNOUNCEMENT_INVALID: unknown company';
  end if;

  if v_id is not null then
    select to_jsonb(a) into v_before from platform_announcements a where a.id = v_id;
    update platform_announcements
       set title = btrim(p_title), body = btrim(p_body), severity = coalesce(p_severity, 'info'), tenant_id = p_tenant_id,
           starts_at = coalesce(p_starts_at, now()), ends_at = p_ends_at, dismissible = coalesce(p_dismissible, true),
           link_url = nullif(btrim(p_link_url), ''), link_label = nullif(btrim(p_link_label), ''),
           is_active = coalesce(p_is_active, true), updated_at = now()
     where id = v_id;
    if not found then raise exception 'ANNOUNCEMENT_NOT_FOUND'; end if;
  else
    insert into platform_announcements (title, body, severity, tenant_id, starts_at, ends_at, dismissible, link_url, link_label, is_active, created_by)
    values (btrim(p_title), btrim(p_body), coalesce(p_severity, 'info'), p_tenant_id, coalesce(p_starts_at, now()), p_ends_at,
            coalesce(p_dismissible, true), nullif(btrim(p_link_url), ''), nullif(btrim(p_link_label), ''), coalesce(p_is_active, true), auth.uid())
    returning id into v_id;
  end if;

  perform log_platform_event(
    case when v_before is null then 'announcement.create' else 'announcement.update' end,
    p_tenant_id, 'announcement', v_id::text, null, v_before,
    (select to_jsonb(a) from platform_announcements a where a.id = v_id));
  return v_id;
end;
$$;


--
-- Name: seed_default_chart_of_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_default_chart_of_accounts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
  v_bank uuid; v_cash uuid; v_ar uuid; v_vat_in uuid;
  v_ap uuid; v_vat_out uuid; v_wht uuid;
  v_salaries_payable uuid; v_paye_payable uuid; v_nssf_payable uuid;
  v_revenue uuid; v_expense uuid; v_salaries_expense uuid;
begin
  if not is_finance_team_member('finance') then
    raise exception 'not authorized to set up the chart of accounts';
  end if;

  if exists (select 1 from gl_accounts where tenant_id = v_tenant_id) then
    raise exception 'chart of accounts already exists for this tenant';
  end if;

  insert into gl_accounts (tenant_id, account_code, name, account_type, is_control_account) values
    (v_tenant_id, '1000', 'Bank', 'asset', true),
    (v_tenant_id, '1010', 'Cash', 'asset', true),
    (v_tenant_id, '1100', 'Accounts Receivable Control', 'asset', true),
    (v_tenant_id, '1200', 'VAT Input', 'asset', true),
    (v_tenant_id, '2000', 'Accounts Payable Control', 'liability', true),
    (v_tenant_id, '2100', 'VAT Output', 'liability', true),
    (v_tenant_id, '2200', 'WHT Payable', 'liability', true),
    (v_tenant_id, '2300', 'Salaries Payable', 'liability', true),
    (v_tenant_id, '2310', 'PAYE Payable', 'liability', true),
    (v_tenant_id, '2320', 'NSSF Payable', 'liability', true),
    (v_tenant_id, '4000', 'Sales Revenue', 'revenue', false),
    (v_tenant_id, '5000', 'General Expense', 'expense', false),
    (v_tenant_id, '5100', 'Salaries Expense', 'expense', false);

  select id into v_bank from gl_accounts where tenant_id = v_tenant_id and account_code = '1000';
  select id into v_cash from gl_accounts where tenant_id = v_tenant_id and account_code = '1010';
  select id into v_ar from gl_accounts where tenant_id = v_tenant_id and account_code = '1100';
  select id into v_vat_in from gl_accounts where tenant_id = v_tenant_id and account_code = '1200';
  select id into v_ap from gl_accounts where tenant_id = v_tenant_id and account_code = '2000';
  select id into v_vat_out from gl_accounts where tenant_id = v_tenant_id and account_code = '2100';
  select id into v_wht from gl_accounts where tenant_id = v_tenant_id and account_code = '2200';
  select id into v_salaries_payable from gl_accounts where tenant_id = v_tenant_id and account_code = '2300';
  select id into v_paye_payable from gl_accounts where tenant_id = v_tenant_id and account_code = '2310';
  select id into v_nssf_payable from gl_accounts where tenant_id = v_tenant_id and account_code = '2320';
  select id into v_revenue from gl_accounts where tenant_id = v_tenant_id and account_code = '4000';
  select id into v_expense from gl_accounts where tenant_id = v_tenant_id and account_code = '5000';
  select id into v_salaries_expense from gl_accounts where tenant_id = v_tenant_id and account_code = '5100';

  insert into gl_posting_rules (tenant_id, account_role, gl_account_id) values
    (v_tenant_id, 'bank', v_bank),
    (v_tenant_id, 'cash', v_cash),
    (v_tenant_id, 'ar_control', v_ar),
    (v_tenant_id, 'vat_input', v_vat_in),
    (v_tenant_id, 'ap_control', v_ap),
    (v_tenant_id, 'vat_output', v_vat_out),
    (v_tenant_id, 'wht_payable', v_wht),
    (v_tenant_id, 'salaries_payable', v_salaries_payable),
    (v_tenant_id, 'paye_payable', v_paye_payable),
    (v_tenant_id, 'nssf_payable', v_nssf_payable),
    (v_tenant_id, 'default_revenue', v_revenue),
    (v_tenant_id, 'default_expense', v_expense),
    (v_tenant_id, 'salaries_expense', v_salaries_expense);
end;
$$;


--
-- Name: seed_statutory_rate_table(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_statutory_rate_table(p_effective_date date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant_id uuid := get_my_tenant_id();
begin
  if not is_finance_team_member('finance') then
    raise exception 'not authorized to set up statutory rates';
  end if;

  insert into statutory_rate_tables (tenant_id, rate_type, effective_date, band_order, lower_bound, upper_bound, rate, base_tax) values
    (v_tenant_id, 'paye', p_effective_date, 1, 0, 335000, 0, 0),
    (v_tenant_id, 'paye', p_effective_date, 2, 335000, 410000, 10, 0),
    (v_tenant_id, 'paye', p_effective_date, 3, 410000, 10000000, 20, 7500),
    (v_tenant_id, 'paye', p_effective_date, 4, 10000000, null, 30, 1927500),
    (v_tenant_id, 'nssf_employee', p_effective_date, 1, 0, null, 5, 0),
    (v_tenant_id, 'nssf_employer', p_effective_date, 1, 0, null, 10, 0);
end;
$$;


--
-- Name: seed_tenant_defaults(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_tenant_defaults(p_tenant_id uuid, p_industry_template text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_key text := coalesce(nullif(btrim(p_industry_template), ''), (select key from industry_templates where is_default), 'general');
begin
  if not is_platform_admin() then
    raise exception 'Only platform admins can seed tenant defaults';
  end if;

  if not exists (select 1 from industry_templates where key = v_key and is_active) then
    raise exception 'TEMPLATE_NOT_FOUND: no active industry template "%"', v_key;
  end if;

  -- Departments, workflow, modules: first-time seeding only (unchanged behaviour).
  if not (exists (select 1 from departments where tenant_id = p_tenant_id)
          or exists (select 1 from workflow_stages where tenant_id = p_tenant_id)) then
    insert into departments (tenant_id, name)
    select p_tenant_id, i.name
    from industry_template_items i
    where i.template_key = v_key and i.kind = 'department'
    order by i.sort_order;

    perform platform_seed_workflow_from_template(p_tenant_id, v_key, 'requests');

    insert into tenant_modules (tenant_id, module, enabled_by)
    select p_tenant_id, i.name, auth.uid()
    from industry_template_items i
    where i.template_key = v_key and i.kind = 'module'
    order by i.sort_order
    on conflict do nothing;

    update tenants set industry_template = v_key where id = p_tenant_id and industry_template is distinct from v_key;
  end if;

  -- Chart of accounts, posting rules and flag defaults: fill-only, so safe to repeat.
  perform platform_apply_template_items(p_tenant_id, v_key,
    array['feature_flag', 'gl_account', 'posting_rule'], true);
end;
$$;


