CREATE TABLE public.finance_team_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT finance_team_members_role_check CHECK ((role = ANY (ARRAY['finance'::text, 'cost_control'::text])))
);


--
-- Name: set_finance_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_finance_role(p_user_id uuid, p_role text) RETURNS public.finance_team_members
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.finance_team_members%rowtype;
begin
  if not is_tenant_admin() then
    raise exception 'not authorized to manage finance access';
  end if;
  if not exists (select 1 from app_users where id = p_user_id and tenant_id = get_my_tenant_id()) then
    raise exception 'user not found in this tenant';
  end if;

  delete from finance_team_members
  where user_id = p_user_id
    and tenant_id = get_my_tenant_id()
    and role != p_role;

  insert into finance_team_members (tenant_id, user_id, role)
  values (get_my_tenant_id(), p_user_id, p_role)
  on conflict (tenant_id, user_id, role) do nothing
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from finance_team_members
    where user_id = p_user_id and tenant_id = get_my_tenant_id() and role = p_role;
  end if;

  return v_row;
end;
$$;


--
-- Name: set_invoice_request_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_request_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_initial_stage_id uuid;
  v_department_id     uuid;
  v_is_platform_admin boolean;
begin
  NEW.tenant_id := get_my_tenant_id();
  NEW.requester_id := auth.uid();
  NEW.status := 'open';
  NEW.created_at := now();
  NEW.updated_at := now();

  select department_id, coalesce(is_platform_admin, false)
    into v_department_id, v_is_platform_admin
  from app_users
  where id = auth.uid();

  if v_department_id is null and not v_is_platform_admin then
    raise exception 'your account has no department assigned -- ask an admin to set one before submitting an invoice';
  end if;

  NEW.department_id := v_department_id;

  select id into v_initial_stage_id
  from workflow_stages
  where tenant_id = NEW.tenant_id and is_active and applies_to = 'invoices'
  order by sequence_order asc
  limit 1;

  if v_initial_stage_id is null then
    raise exception 'no active invoice workflow stages configured for this tenant';
  end if;

  NEW.current_stage_id := v_initial_stage_id;

  return NEW;
end;
$$;


