--
-- Name: set_tenant_feature_flag(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tenant_feature_flag(p_tenant_id uuid, p_key text, p_enabled boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_before jsonb;
begin
  perform require_platform_admin('Changing a company''s feature flags');
  if not exists (select 1 from platform_feature_flags where key = p_key) then
    raise exception 'FLAG_NOT_FOUND: %', p_key;
  end if;
  select to_jsonb(tf) into v_before from tenant_feature_flags tf where tf.tenant_id = p_tenant_id and tf.flag_key = p_key;
  if p_enabled is null then
    delete from tenant_feature_flags where tenant_id = p_tenant_id and flag_key = p_key;
  else
    insert into tenant_feature_flags (tenant_id, flag_key, enabled, note, updated_by)
    values (p_tenant_id, p_key, p_enabled, nullif(btrim(p_note), ''), auth.uid())
    on conflict (tenant_id, flag_key) do update
      set enabled = excluded.enabled, note = excluded.note, updated_at = now(), updated_by = auth.uid();
  end if;
  perform log_platform_event('tenant.feature_flag.set', p_tenant_id, 'feature_flag', p_key, p_note, v_before,
    (select to_jsonb(tf) from tenant_feature_flags tf where tf.tenant_id = p_tenant_id and tf.flag_key = p_key));
end;
$$;


--
-- Name: set_tenant_modules(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tenant_modules(p_tenant_id uuid, p_modules text[]) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before text[];
  v_after  text[];
  v_new    text[];
begin
  perform require_platform_admin('Changing a company''s modules');

  if not exists (select 1 from tenants where id = p_tenant_id) then
    raise exception 'tenant not found';
  end if;

  select coalesce(array_agg(module order by module), '{}')
    into v_before
  from tenant_modules where tenant_id = p_tenant_id;

  delete from tenant_modules
  where tenant_id = p_tenant_id
    and module != all(coalesce(p_modules, array[]::text[]));

  with ins as (
    insert into tenant_modules (tenant_id, module, enabled_by)
    select p_tenant_id, m, auth.uid()
    from unnest(coalesce(p_modules, array[]::text[])) as m
    on conflict (tenant_id, module) do nothing
    returning module
  )
  select coalesce(array_agg(module order by module), '{}') into v_new from ins;

  -- Company admins get admin on modules newly entitled to their company.
  if coalesce(array_length(v_new, 1), 0) > 0 then
    insert into staff_roles (tenant_id, user_id, module, role)
    select p_tenant_id, u.id, m, 'admin'
    from app_users u
    cross join unnest(v_new) as m
    where u.tenant_id = p_tenant_id and u.is_company_admin
    on conflict (tenant_id, user_id, module) do nothing;
  end if;

  select coalesce(array_agg(module order by module), '{}')
    into v_after
  from tenant_modules where tenant_id = p_tenant_id;

  if v_before is distinct from v_after then
    perform log_platform_event(
      'tenant.modules.set', p_tenant_id, 'tenant', p_tenant_id::text, null,
      jsonb_build_object('modules', to_jsonb(v_before)),
      jsonb_build_object('modules', to_jsonb(v_after))
    );
  end if;

  return query select module from tenant_modules where tenant_id = p_tenant_id order by module;
end;
$$;


--
-- Name: tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    industry_template text DEFAULT 'general'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    contact_name text,
    contact_email text,
    contact_phone text,
    tax_id text,
    address text,
    country text DEFAULT 'UG'::text NOT NULL,
    plan text DEFAULT 'standard'::text NOT NULL,
    subscription_status text DEFAULT 'active'::text NOT NULL,
    seat_limit integer,
    trial_ends_at timestamp with time zone,
    renews_at timestamp with time zone,
    status_changed_at timestamp with time zone,
    read_only boolean DEFAULT false NOT NULL,
    read_only_reason text,
    read_only_since timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenants_plan_check CHECK ((plan = ANY (ARRAY['trial'::text, 'starter'::text, 'standard'::text, 'enterprise'::text, 'internal'::text]))),
    CONSTRAINT tenants_read_only_reason_check CHECK (((NOT read_only) OR (read_only_reason IS NOT NULL))),
    CONSTRAINT tenants_seat_limit_check CHECK (((seat_limit IS NULL) OR (seat_limit > 0))),
    CONSTRAINT tenants_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'suspended'::text]))),
    CONSTRAINT tenants_subscription_status_check CHECK ((subscription_status = ANY (ARRAY['trialing'::text, 'active'::text, 'past_due'::text, 'cancelled'::text])))
);


--
-- Name: set_tenant_read_only(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tenant_read_only(p_tenant_id uuid, p_read_only boolean, p_reason text DEFAULT NULL::text) RETURNS public.tenants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_before public.tenants;
  v_row    public.tenants;
  v_reason text := nullif(btrim(p_reason), '');
begin
  perform require_platform_admin('Changing a company''s read-only mode');

  select * into v_before from tenants where id = p_tenant_id for update;
  if not found then
    raise exception 'tenant not found';
  end if;

  if p_read_only and v_reason is null then
    raise exception 'A reason is required to put a company into read-only mode';
  end if;

  if v_before.read_only = p_read_only then
    return v_before;
  end if;

  update tenants
  set read_only        = p_read_only,
      read_only_reason = case when p_read_only then v_reason else null end,
      read_only_since  = case when p_read_only then now() else null end
  where id = p_tenant_id
  returning * into v_row;

  perform log_platform_event(
    case when p_read_only then 'tenant.read_only.on' else 'tenant.read_only.off' end,
    p_tenant_id, 'tenant', p_tenant_id::text, v_reason,
    jsonb_build_object('read_only', v_before.read_only, 'read_only_reason', v_before.read_only_reason),
    jsonb_build_object('read_only', v_row.read_only, 'read_only_reason', v_row.read_only_reason, 'tenant_name', v_row.name)
  );

  return v_row;
end;
$$;


--
-- Name: set_tenant_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tenant_status(p_tenant_id uuid, p_status text) RETURNS public.tenants
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.set_tenant_status(p_tenant_id, p_status, null);
$$;


--
-- Name: set_tenant_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tenant_status(p_tenant_id uuid, p_status text, p_reason text) RETURNS public.tenants
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_before public.tenants;
  v_row    public.tenants;
  v_reason text := nullif(btrim(p_reason), '');
begin
  perform require_platform_admin('Changing a company''s status');

  if p_status not in ('active', 'suspended') then
    raise exception 'status must be active or suspended (pending is set automatically)';
  end if;

  select * into v_before from tenants where id = p_tenant_id for update;
  if not found then
    raise exception 'tenant not found';
  end if;

  if p_status = 'suspended' and v_reason is null then
    raise exception 'A reason is required to suspend a company';
  end if;

  if v_before.status = p_status then
    return v_before;  -- no-op, nothing to audit
  end if;

  update tenants
  set status = p_status,
      status_changed_at = now()
  where id = p_tenant_id
  returning * into v_row;

  perform log_platform_event(
    case when p_status = 'suspended' then 'tenant.suspend' else 'tenant.activate' end,
    p_tenant_id, 'tenant', p_tenant_id::text, v_reason,
    jsonb_build_object('status', v_before.status),
    jsonb_build_object('status', v_row.status, 'tenant_name', v_row.name)
  );

  return v_row;
end;
$$;


--
-- Name: set_ticket_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ticket_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if NEW.ticket_number is null then
    NEW.ticket_number := next_ticket_number(NEW.tenant_id);
  end if;
  if NEW.category = 'Access' then
    NEW.requires_approval := true;
    NEW.approval_status := 'pending';
