$$;


--
-- Name: start_impersonation(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_impersonation(p_tenant_id uuid, p_reason text, p_user_id uuid) RETURNS public.impersonation_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_session impersonation_sessions;
  v_reason  text := nullif(btrim(p_reason), '');
  v_tenant  tenants%rowtype;
  v_target  app_users%rowtype;
begin
  perform require_platform_admin('Impersonation');

  if v_reason is null or length(v_reason) < 5 then
    raise exception 'A reason (at least 5 characters) is required to view a company as its users';
  end if;

  select * into v_tenant from tenants where id = p_tenant_id;
  if not found then
    raise exception 'No such tenant';
  end if;

  if p_user_id is not null then
    select * into v_target from app_users where id = p_user_id;
    if not found or v_target.tenant_id <> p_tenant_id then
      raise exception 'No such user in this company';
    end if;
    if v_target.is_platform_admin then
      raise exception 'Platform admins cannot be impersonated';
    end if;
  end if;

  update impersonation_sessions
  set ended_at = now()
  where platform_admin_id = auth.uid() and ended_at is null;

  insert into impersonation_sessions (platform_admin_id, tenant_id, reason, expires_at, impersonated_user_id)
  values (auth.uid(), p_tenant_id, v_reason, now() + interval '2 hours', p_user_id)
  returning * into v_session;

  insert into impersonation_logs (platform_admin_id, platform_admin_email, tenant_id, action)
  values (auth.uid(), (select email from auth.users where id = auth.uid()), p_tenant_id, 'start');

  perform log_platform_event(
    'impersonation.start', p_tenant_id,
    case when p_user_id is null then 'tenant' else 'app_user' end,
    coalesce(p_user_id::text, p_tenant_id::text),
    v_reason,
    null,
    jsonb_build_object(
      'session_id', v_session.id,
      'tenant_name', v_tenant.name,
      'expires_at', v_session.expires_at,
      'as_user_id', p_user_id,
      'as_user_email', v_target.email
    )
  );

  return v_session;
end;
$$;


--
-- Name: submit_contract_for_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_contract_for_approval(p_contract_id uuid) RETURNS public.law_contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contract public.law_contracts%rowtype;
begin
  if not has_module_role('legal', array['admin', 'manager', 'member']) then
    raise exception 'not authorized: legal module role required';
  end if;

  select * into v_contract from law_contracts
  where id = p_contract_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'contract not found in this tenant';
  end if;
  if v_contract.status <> 'draft' then
    raise exception 'only draft contracts can be submitted for approval (current status: %)', v_contract.status;
  end if;

  perform set_config('app.allow_law_status_change', 'true', true);
  update law_contracts
  set status = 'pending_approval', updated_at = now()
  where id = v_contract.id
  returning * into v_contract;
  perform set_config('app.allow_law_status_change', 'false', true);

  insert into law_contract_decisions (tenant_id, contract_id, decision, decided_by, notes)
  values (v_contract.tenant_id, v_contract.id, 'submitted', effective_user_id(), null);

  return v_contract;
end;
$$;


