    CONSTRAINT requests_status_check CHECK ((status = ANY (ARRAY['open'::text, 'rejected'::text, 'closed'::text, 'cancelled'::text])))
);


--
-- Name: submit_offers_for_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_offers_for_approval(p_request_id uuid) RETURNS public.requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request     requests%rowtype;
  v_stage       workflow_stages%rowtype;
  v_next_stage  workflow_stages%rowtype;
  v_offer_count int;
begin
  select * into v_request from requests where id = p_request_id for update;
  if not found then
    raise exception 'request not found';
  end if;
  if v_request.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this request';
  end if;
  if v_request.status != 'open' then
    raise exception 'request is not open (status: %)', v_request.status;
  end if;

  select * into v_stage from workflow_stages where id = v_request.current_stage_id;
  if not v_stage.requires_offer_entry then
    raise exception 'this request is not at an offer-entry stage';
  end if;
  if not can_act_on_stage(v_stage.id) then
    raise exception 'not authorized to submit offers on this request';
  end if;

  select count(*) into v_offer_count from request_offers where request_id = p_request_id;
  if v_offer_count < 2 then
    raise exception 'at least 2 competing offers are required before sending to Budget Controller (currently %)', v_offer_count;
  end if;

  if v_stage.next_stage_low_id is null then
    raise exception 'stage % has no next stage configured', v_stage.name;
  end if;

  update requests
  set current_stage_id = v_stage.next_stage_low_id, updated_at = now()
  where id = p_request_id
  returning * into v_request;

  select * into v_next_stage from workflow_stages where id = v_stage.next_stage_low_id;

  insert into notifications (tenant_id, recipient_id, type, title, body, request_id)
  select distinct
    v_request.tenant_id,
    recipient_id,
    'approval_needed',
    'Offers submitted -- approval needed',
    format('%s competing offers were submitted for request "%s" and are awaiting your review.',
           v_offer_count, v_request.item_description),
    p_request_id
  from (
    select aa.user_id as recipient_id
    from approval_assignments aa
    where aa.workflow_stage_id = v_next_stage.id

    union

    select d.delegate_user_id as recipient_id
    from approval_delegations d
    join approval_assignments aa on aa.user_id = d.delegator_user_id
    where d.status = 'active'
      and now() between d.starts_at and d.ends_at
      and aa.workflow_stage_id = v_next_stage.id
      and (d.workflow_stage_id is null or d.workflow_stage_id = v_next_stage.id)
  ) recipients;

  return v_request;
end;
$$;


--
-- Name: submit_payroll_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_payroll_run(p_run_id uuid) RETURNS public.hr_payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row hr_payroll_runs%ROWTYPE;
BEGIN
  IF NOT is_hr_team_member() THEN
    RAISE EXCEPTION 'not authorized to submit payroll';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM hr_payroll_items WHERE payroll_run_id = p_run_id) THEN
    RAISE EXCEPTION 'cannot submit a payroll run with no line items';
  END IF;

  UPDATE hr_payroll_runs
  SET status = 'pending_approval', submitted_at = now()
  WHERE id = p_run_id AND tenant_id = get_my_tenant_id() AND status = 'draft'
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'payroll run not found, or not in draft';
  END IF;

  RETURN v_row;
END;
$$;


--
-- Name: submit_pmo_project_for_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_pmo_project_for_approval(p_project_id uuid) RETURNS public.pmo_projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project public.pmo_projects%rowtype;
begin
  if not has_module_role('pmo', array['admin', 'manager', 'member']) then
    raise exception 'not authorized: pmo module role required';
  end if;

  select * into v_project from pmo_projects
  where id = p_project_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'project not found in this tenant';
  end if;
  if v_project.status not in ('not_started', 'rejected') then
    raise exception 'only not_started or rejected projects can be submitted (current status: %)', v_project.status;
  end if;

  update pmo_projects
  set status = 'pending_approval', updated_at = now()
  where id = v_project.id
  returning * into v_project;

  insert into pmo_project_decisions (tenant_id, project_id, decision, decided_by, notes)
  values (v_project.tenant_id, v_project.id, 'submitted', auth.uid(), null);

  return v_project;
end;
$$;


--
-- Name: submit_request_with_line_items(text, integer, uuid, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_request_with_line_items(p_item_description text, p_quantity integer, p_cost_center_id uuid, p_delivery_date date, p_subcontractor text, p_line_items jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request_id uuid;
  v_item jsonb;
BEGIN
  IF p_line_items IS NULL OR jsonb_array_length(p_line_items) = 0 THEN
    RAISE EXCEPTION 'at least one line item is required';
  END IF;

  -- tenant_id, requester_id, department_id, status, current_stage_id are all
  -- set server-side by trg_set_request_defaults, same as a direct insert.
  INSERT INTO requests (item_description, quantity, cost_center_id, delivery_date, subcontractor)
  VALUES (p_item_description, p_quantity, p_cost_center_id, p_delivery_date, p_subcontractor)
  RETURNING id INTO v_request_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_line_items)
  LOOP
    IF NULLIF(v_item->>'material_service', '') IS NULL THEN
      RAISE EXCEPTION 'each line item requires material_service';
    END IF;

    INSERT INTO request_line_items (
      request_id, material_service, cost_code, group_code, place_of_use,
      quantity, unit_price, currency
    )
    VALUES (
      v_request_id,
      v_item->>'material_service',
      NULLIF(v_item->>'cost_code', ''),
      NULLIF(v_item->>'group_code', ''),
      NULLIF(v_item->>'place_of_use', ''),
      (v_item->>'quantity')::numeric,
      NULLIF(v_item->>'unit_price', '')::numeric,
      COALESCE(NULLIF(v_item->>'currency', ''), 'UGX')
    );
  END LOOP;

  RETURN v_request_id;
END;
$$;


--
-- Name: supplier_invoice_outstanding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_outstanding(p_invoice_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select si.amount_incl_vat
    - coalesce((select sum(cbt.amount) from cash_bank_transactions cbt
                where cbt.reference_type = 'supplier_invoice' and cbt.reference_id = si.id), 0)
    - coalesce((select sum(apa.applied_amount) from advance_payment_applications apa
                where apa.reference_type = 'supplier_invoice' and apa.reference_id = si.id), 0)
  from supplier_invoices si
  where si.id = p_invoice_id;
$$;


--
-- Name: supplier_invoice_payable_now(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_payable_now(p_invoice_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT GREATEST(0,
    LEAST(
      supplier_invoice_receipt_cap(p_invoice_id) - (si.amount_incl_vat - supplier_invoice_outstanding(p_invoice_id)),
      supplier_invoice_outstanding(p_invoice_id)
    )
  )
  FROM supplier_invoices si WHERE si.id = p_invoice_id;
$$;


--
-- Name: supplier_invoice_receipt_cap(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_invoice_receipt_cap(p_invoice_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice supplier_invoices%ROWTYPE;
  v_ordered_value numeric;
  v_received_value numeric;
  v_ordered_qty numeric;
  v_received_qty numeric;
BEGIN
  SELECT * INTO v_invoice FROM supplier_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  SELECT
    COALESCE(SUM(rli.quantity * rli.unit_price), 0),
    COALESCE(SUM(LEAST(rec.received_qty, rli.quantity) * rli.unit_price), 0),
    COALESCE(SUM(rli.quantity), 0),
    COALESCE(SUM(LEAST(rec.received_qty, rli.quantity)), 0)
  INTO v_ordered_value, v_received_value, v_ordered_qty, v_received_qty
  FROM request_line_items rli
  JOIN requests r ON r.id = rli.request_id
  LEFT JOIN (
    SELECT line_item_id, SUM(received_qty) AS received_qty
    FROM line_item_receipts GROUP BY line_item_id
  ) rec ON rec.line_item_id = rli.id
  JOIN purchase_orders po ON po.request_id = r.id
  WHERE po.id = v_invoice.purchase_order_id;

  IF v_ordered_value > 0 THEN
    RETURN LEAST(v_invoice.amount_incl_vat, v_invoice.amount_incl_vat * (v_received_value / v_ordered_value));
  ELSIF v_ordered_qty > 0 THEN
    RETURN LEAST(v_invoice.amount_incl_vat, v_invoice.amount_incl_vat * (v_received_qty / v_ordered_qty));
  ELSE
    RETURN 0; -- no line items / nothing ordered -- nothing payable yet
  END IF;
END;
$$;


--
-- Name: sustainability_cert_expiry_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sustainability_cert_expiry_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n integer;
begin
  v_n := sustainability_cert_expiry_sweep_impl();
  if has_module_role('sustainability', array['admin', 'manager', 'member']) then
    perform platform_record_job_run('sustainability_cert_expiry_sweep', get_my_tenant_id(), 'ok', v_n);
  end if;
  return v_n;
end;
$$;


--
-- Name: sustainability_cert_expiry_sweep_impl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sustainability_cert_expiry_sweep_impl() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cert record;
  v_count int := 0;
begin
  if not has_module_role('sustainability', array['admin', 'manager', 'member']) then
    return 0; -- outsiders just get nothing
  end if;

  -- (a) past-due valids lapse, once
  for v_cert in
    update sustainability_certifications
    set status = 'expired'
    where tenant_id = get_my_tenant_id()
      and status = 'valid'
      and expiry_date is not null
      and expiry_date < current_date
    returning id, tenant_id, name, standard, expiry_date, created_by
  loop
    insert into notifications (tenant_id, recipient_id, type, title, body)
    select distinct on (recipient) v_cert.tenant_id, recipient,
      'certification_expired',
      'Certification expired: ' || v_cert.name,
      format('Certification "%s"%s expired on %s. Status was set to expired.',
        v_cert.name,
        case when v_cert.standard is not null then ' (' || v_cert.standard || ')' else '' end,
        v_cert.expiry_date::text)
    from (
      values (v_cert.created_by::uuid)
      union
      select sr.user_id from staff_roles sr
      where sr.tenant_id = v_cert.tenant_id
        and sr.module = 'sustainability'
        and sr.role in ('admin', 'manager')
    ) as rec(recipient)
    where recipient is not null;

    v_count := v_count + 1;
  end loop;

  -- (b) renewals due within 30 days: remind admins once, keep status
  for v_cert in
    select id, tenant_id, name, standard, expiry_date, created_by
    from sustainability_certifications
    where tenant_id = get_my_tenant_id()
      and status = 'valid'
      and expiry_date is not null
      and expiry_date >= current_date
      and expiry_date <= current_date + 30
      and renewal_reminded_at is null
  loop
    insert into notifications (tenant_id, recipient_id, type, title, body)
    select distinct on (recipient) v_cert.tenant_id, recipient,
      'certification_expiring',
      'Certification expiring soon: ' || v_cert.name,
      format('Certification "%s"%s expires on %s (%s day(s) away). Consider renewal or set pending_renewal.',
        v_cert.name,
        case when v_cert.standard is not null then ' (' || v_cert.standard || ')' else '' end,
        v_cert.expiry_date::text, (v_cert.expiry_date - current_date)::text)
    from (
      values (v_cert.created_by::uuid)
      union
      select sr.user_id from staff_roles sr
      where sr.tenant_id = v_cert.tenant_id
        and sr.module = 'sustainability'
        and sr.role in ('admin', 'manager')
    ) as rec(recipient)
    where recipient is not null;

    update sustainability_certifications
    set renewal_reminded_at = now()
    where id = v_cert.id;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


--
-- Name: tenant_ledger_settings_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_ledger_settings_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and new.tenant_id is distinct from old.tenant_id then
    raise exception 'FX_TENANT_IMMUTABLE: a ledger setting cannot move to another company';
  end if;
  if (tg_op = 'INSERT' or new.functional_currency is distinct from old.functional_currency)
     and exists (select 1 from journal_entries where tenant_id = new.tenant_id) then
    raise exception 'FX_FUNCTIONAL_LOCKED: this company has already posted journal entries; its functional currency can no longer change';
  end if;
  return new;
end;
$$;


--
-- Name: tenant_read_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_read_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant_id uuid;
  v_read_only boolean;
  v_reason    text;
  v_name      text;
begin
  if coalesce(platform_request_role(), '') <> 'authenticated' then
    return coalesce(new, old);
  end if;
  if platform_admin_bypass() then
    return coalesce(new, old);
  end if;

  v_tenant_id := coalesce(
    case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end,
    get_my_tenant_id()
  );
  if v_tenant_id is null then
    return coalesce(new, old);
  end if;

  select read_only, read_only_reason, name
  into v_read_only, v_reason, v_name
  from tenants where id = v_tenant_id;

  if coalesce(v_read_only, false) then
    raise exception 'TENANT_READ_ONLY: % is currently in read-only mode (%). Changes are not being accepted.',
      coalesce(v_name, 'This company'), coalesce(v_reason, 'no reason recorded')
      using errcode = 'insufficient_privilege';
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: law_regulatory_filings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.law_regulatory_filings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    title text NOT NULL,
    filing_type text,
    reference_no text,
    status text DEFAULT 'pending'::text NOT NULL,
    filing_date date,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    due_date date,
    CONSTRAINT law_regulatory_filings_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'filed'::text, 'approved'::text, 'rejected'::text])))
);


--
-- Name: transition_filing(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_filing(p_filing_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS public.law_regulatory_filings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_filing public.law_regulatory_filings%rowtype;
  v_allowed boolean;
begin
  if not has_module_role('legal', array['admin', 'manager']) then
    raise exception 'not authorized: filing transitions require a legal admin or manager role';
  end if;

  select * into v_filing from law_regulatory_filings
  where id = p_filing_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'filing not found in this tenant';
  end if;

  v_allowed := (v_filing.status = 'pending'  and p_status in ('filed', 'rejected'))
            or (v_filing.status = 'filed'    and p_status in ('approved', 'rejected'))
            or (v_filing.status = 'rejected' and p_status = 'pending');

  if not v_allowed then
    raise exception 'invalid filing transition: % -> %', v_filing.status, p_status;
  end if;

  update law_regulatory_filings
  set status = p_status,
      filing_date = case when p_status = 'filed' and filing_date is null
                         then current_date else filing_date end
  where id = v_filing.id
  returning * into v_filing;

  insert into law_filing_events (tenant_id, filing_id, status, actor_id, note)
  values (v_filing.tenant_id, v_filing.id, p_status, auth.uid(), nullif(btrim(coalesce(p_note, '')), ''));

  return v_filing;
end;
$$;


--
-- Name: maintenance_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.maintenance_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    machine_id uuid NOT NULL,
    type text NOT NULL,
    description text NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    requested_by uuid,
    scheduled_date date,
    completed_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_to uuid,
    actual_cost numeric(14,2),
    overdue_notified_at timestamp with time zone,
    CONSTRAINT maintenance_requests_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT maintenance_requests_type_check CHECK ((type = ANY (ARRAY['preventive'::text, 'corrective'::text, 'inspection'::text])))
);


--
-- Name: transition_maintenance_request(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_maintenance_request(p_request_id uuid, p_status text, p_note text DEFAULT NULL::text, p_actual_cost numeric DEFAULT NULL::numeric) RETURNS public.maintenance_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_req public.maintenance_requests%rowtype;
  v_allowed boolean;
  v_expense uuid;
  v_ap uuid;
  v_lines jsonb;
  v_machine_label text;
begin
  if not has_module_role('machine_operation', array['admin', 'manager', 'member']) then
    raise exception 'not authorized: machine operation role required';
  end if;

  select * into v_req from maintenance_requests
  where id = p_request_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'maintenance request not found in this tenant';
  end if;

  v_allowed := (v_req.status = 'scheduled'   and p_status = 'in_progress')
            or (v_req.status = 'in_progress' and p_status = 'completed')
            or (v_req.status in ('scheduled', 'in_progress') and p_status = 'cancelled');

  if not v_allowed then
    raise exception 'invalid maintenance transition: % -> %', v_req.status, p_status;
  end if;

  -- Completing books money to the GL when a cost is given, so it needs
  -- the same tier that writes every other machine money record.
  if p_status = 'completed' and p_actual_cost is not null then
    if p_actual_cost < 0 then
      raise exception 'actual_cost cannot be negative';
    end if;
    if not has_module_role('machine_operation', array['admin', 'manager']) then
      raise exception 'completing with a cost requires a machine operation admin or manager role';
    end if;
  end if;

  update maintenance_requests
  set status = p_status,
      completed_date = case when p_status = 'completed' then current_date else completed_date end,
      actual_cost = case when p_status = 'completed' then coalesce(p_actual_cost, actual_cost) else actual_cost end,
      updated_at = now()
  where id = v_req.id
  returning * into v_req;

  insert into machine_maintenance_events (tenant_id, request_id, status, actor_id, note, actual_cost)
  values (v_req.tenant_id, v_req.id, p_status, auth.uid(), nullif(btrim(coalesce(p_note, '')), ''), p_actual_cost);

  -- Notify the requester and/or assignee (deduped) about the change.
  insert into notifications (tenant_id, recipient_id, type, title, body)
  select distinct on (recipient) v_req.tenant_id, recipient,
    'maintenance_' || p_status,
    'Maintenance ' || p_status || ': ' || m.machine_no,
    format('Maintenance request "%s" on machine %s - %s is now %s.%s',
      left(v_req.description, 80), m.machine_no, m.name, p_status,
      case when p_status = 'completed' and v_req.actual_cost is not null
           then ' Actual cost recorded: ' || v_req.actual_cost::text else '' end)
  from machines m,
       (values (v_req.requested_by), (v_req.assigned_to)) as rec(recipient)
  where m.id = v_req.machine_id
    and recipient is not null
    and recipient <> auth.uid(); -- don't notify yourself about your own action

  -- GL posting on completion with a cost: Dr default expense / Cr AP
  -- control, same legs as a non-VAT supplier invoice, resolved through
  -- gl_posting_rules (20260904100000 replaced gl_control_accounts). Skip
  -- silently when the tenant hasn't finished their posting rules yet
  -- (mirror of trg_post_supplier_invoice's behaviour).
  if p_status = 'completed' and v_req.actual_cost is not null and v_req.actual_cost > 0 then
    v_expense := get_posting_account(v_req.tenant_id, 'default_expense');
    v_ap := get_posting_account(v_req.tenant_id, 'ap_control');
    if v_expense is not null and v_ap is not null then
      select machine_no || ' - ' || name into v_machine_label from machines where id = v_req.machine_id;
      v_lines := jsonb_build_array(
        jsonb_build_object('gl_account_id', v_expense, 'debit', v_req.actual_cost),
        jsonb_build_object('gl_account_id', v_ap, 'credit', v_req.actual_cost)
      );
      perform post_journal_entry(v_req.tenant_id, 'machine_maintenance_request', v_req.id,
        coalesce(v_req.completed_date, current_date),
        'Machine maintenance: ' || coalesce(v_machine_label, v_req.machine_id::text) || ' -- ' || left(v_req.description, 90), v_lines);
    end if;
  end if;

  return v_req;
end;
$$;


--
-- Name: bd_tenders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bd_tenders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    tender_no text,
    title text NOT NULL,
    client_id uuid,
    type_id uuid,
    status text DEFAULT 'open'::text NOT NULL,
    submission_deadline timestamp with time zone,
    estimated_value numeric(14,2),
    currency text DEFAULT 'USD'::text NOT NULL,
    portal_url text,
    description text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bd_tenders_status_check CHECK ((status = ANY (ARRAY['open'::text, 'submitted'::text, 'under_evaluation'::text, 'awarded'::text, 'lost'::text, 'cancelled'::text])))
);


--
-- Name: transition_tender(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_tender(p_tender_id uuid, p_status text, p_ref text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS public.bd_tenders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tender public.bd_tenders%rowtype;
  v_allowed boolean;
begin
  if not has_module_role('bd', array['admin', 'manager', 'member']) then
    raise exception 'not authorized: bd role required';
  end if;

  select * into v_tender from bd_tenders
  where id = p_tender_id and tenant_id = get_my_tenant_id()
  for update;

  if not found then
    raise exception 'tender not found in this tenant';
  end if;

  v_allowed := (v_tender.status = 'open'             and p_status = 'submitted')
            or (v_tender.status = 'submitted'        and p_status in ('under_evaluation', 'awarded', 'lost', 'cancelled'))
            or (v_tender.status = 'under_evaluation' and p_status in ('awarded', 'lost', 'cancelled'))
            or (v_tender.status = 'open'             and p_status = 'cancelled');

  if not v_allowed then
    raise exception 'invalid tender transition: % -> %', v_tender.status, p_status;
  end if;

  update bd_tenders
  set status = p_status, updated_at = now()
  where id = v_tender.id
  returning * into v_tender;

  if p_status = 'submitted' then
    -- the submission event: portal/tracking reference + note, exactly
    -- once (unique tender_id -- a second submit is an invalid transition
    -- anyway since status is no longer 'open').
    insert into bd_tender_submissions (tenant_id, tender_id, submitted_by, submission_ref, note)
    values (v_tender.tenant_id, v_tender.id, auth.uid(),
            nullif(btrim(coalesce(p_ref, '')), ''),
            nullif(btrim(coalesce(p_note, '')), ''));
  end if;

  if p_status in ('awarded', 'lost', 'cancelled')
     and v_tender.created_by is not null
     and v_tender.created_by <> auth.uid() then
    insert into notifications (tenant_id, recipient_id, type, title, body)
    values (
      v_tender.tenant_id,
      v_tender.created_by,
      'tender_' || p_status,
      'Tender ' || p_status || ': ' || v_tender.title,
      format('Tender "%s" (%s) is now %s.%s',
        v_tender.title,
        coalesce(v_tender.tender_no, 'no number'),
        p_status,
        case when nullif(btrim(coalesce(p_note, '')), '') is not null
             then ' ' || btrim(p_note) else '' end)
    );
  end if;

  return v_tender;
end;
$$;


--
-- Name: trg_audit_platform_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_platform_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform log_platform_event(
    'platform_settings.update', null, 'platform_settings', 'singleton', null,
    jsonb_build_object('branding', old.branding, 'notifications', old.notifications, 'security', old.security),
    jsonb_build_object('branding', new.branding, 'notifications', new.notifications, 'security', new.security)
  );
  new.updated_by := auth.uid();
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: trg_bd_opportunity_probability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_bd_opportunity_probability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.probability is null then
    select s.probability_default into new.probability
    from bd_opportunity_stages s
    where s.tenant_id = new.tenant_id
      and s.stage = new.stage
      and s.is_active;
    -- tenant without a seeded lookup: keep the pipeline math working
    new.probability := coalesce(new.probability, 10);
  end if;
  return new;
end;
$$;


--
-- Name: trg_post_cash_bank_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_post_cash_bank_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_cash_side    uuid;
  v_other_side   uuid;
  v_other_role   text;
  v_lines        jsonb;
  v_functional   text;
  v_ccy          text;
  v_invoice_ccy  text;
  v_invoice_found boolean := false;
  v_orig_entry   uuid;
  v_orig_rate    numeric;
  v_settle       record;
  v_other_line   jsonb;
  v_cash_line    jsonb;
  v_fx_line      jsonb;
begin
  v_other_role := case new.reference_type
    when 'supplier_invoice' then 'ap_control'
    when 'receivable_invoice' then 'ar_control'
    when 'expenditure_slip' then 'default_expense'
    when 'payroll_run' then 'salaries_payable'
    else null
  end;
  if v_other_role is null then
    return new;
  end if;

  v_cash_side := get_posting_account(new.tenant_id, case when new.payment_method = 'bank' then 'bank' else 'cash' end);
  v_other_side := get_posting_account(new.tenant_id, v_other_role);
  if v_cash_side is null or v_other_side is null then
    return new;  -- e.g. this role not mapped yet
  end if;

  v_functional := fin_ledger_currency(new.tenant_id);
  v_ccy := coalesce(nullif(btrim(new.currency), ''), v_functional);

  -- Payroll is accrued in the functional currency only.
  if new.reference_type = 'payroll_run' and v_ccy <> v_functional then
    raise exception 'CASH_PAYROLL_CURRENCY: payroll is accrued in %, so a payroll payment cannot be in %', v_functional, v_ccy;
  end if;

  -- An invoice is settled in the currency it was issued in.
  if new.reference_type = 'supplier_invoice' then
    select true, coalesce(nullif(btrim(currency), ''), v_functional) into v_invoice_found, v_invoice_ccy
      from supplier_invoices where id = new.reference_id and tenant_id = new.tenant_id;
  elsif new.reference_type = 'receivable_invoice' then
    select true, coalesce(nullif(btrim(currency), ''), v_functional) into v_invoice_found, v_invoice_ccy
      from receivable_invoices where id = new.reference_id and tenant_id = new.tenant_id;
  end if;
  if v_invoice_found and v_invoice_ccy <> v_ccy then
    raise exception 'CASH_CURRENCY_MISMATCH: this % is in %, so the transaction must be in %, not %',
      replace(new.reference_type, '_', ' '), v_invoice_ccy, v_invoice_ccy, v_ccy;
  end if;

  -- Foreign settlement of an invoice that was booked: take the invoice's original rate.
  if v_invoice_found and v_ccy <> v_functional then
    select e.id, l.fx_rate into v_orig_entry, v_orig_rate
      from journal_entries e
      join journal_entry_lines l on l.journal_entry_id = e.id
     where e.tenant_id = new.tenant_id
       and e.source_type = new.reference_type
       and e.source_id = new.reference_id
       and e.status <> 'void'
       and l.gl_account_id = v_other_side
       and l.currency = v_ccy
     order by e.created_at
     limit 1;
  end if;

  v_other_line := jsonb_build_object('gl_account_id', v_other_side, 'currency', new.currency);
  v_cash_line  := jsonb_build_object('gl_account_id', v_cash_side,  'currency', new.currency);
  if new.transaction_type = 'payment' then
    v_other_line := v_other_line || jsonb_build_object('debit', new.amount);
    v_cash_line  := v_cash_line  || jsonb_build_object('credit', new.amount);
  else -- 'receipt'
    v_other_line := v_other_line || jsonb_build_object('credit', new.amount);
    v_cash_line  := v_cash_line  || jsonb_build_object('debit', new.amount);
  end if;

  if v_orig_entry is not null then
    v_other_line := v_other_line || jsonb_build_object('rate_from_entry', v_orig_entry, 'fx_rate', v_orig_rate);
    select * into v_settle from platform_fx_settlement(
      new.tenant_id, v_ccy, new.amount, v_orig_rate, new.transaction_date, new.transaction_type = 'payment');
    v_fx_line := platform_fx_realised_line(new.tenant_id, v_settle.result);
  end if;

  v_lines := jsonb_build_array(v_other_line, v_cash_line);
  if v_fx_line is not null then
    v_lines := v_lines || v_fx_line;
  end if;

  perform post_journal_entry(new.tenant_id, 'cash_bank_transaction', new.id, new.transaction_date,
    coalesce(new.description, initcap(new.transaction_type) || ' - ' || new.reference_type), v_lines);

  return new;
end;
$$;


--
-- Name: trg_post_machine_fuel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_post_machine_fuel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_expense uuid;
  v_ap uuid;
  v_lines jsonb;
  v_machine_label text;
BEGIN
  IF NEW.cost IS NULL OR NEW.cost <= 0 THEN
    RETURN NEW; -- uncosted fuel: quantity tracking only
  END IF;

  v_expense := get_posting_account(NEW.tenant_id, 'default_expense');
  v_ap := get_posting_account(NEW.tenant_id, 'ap_control');
  IF v_expense IS NULL OR v_ap IS NULL THEN
    RETURN NEW; -- posting rules not set up yet; skip, don't fail the insert
  END IF;

  SELECT machine_no || ' - ' || name INTO v_machine_label
  FROM machines WHERE id = NEW.machine_id;

  v_lines := jsonb_build_array(
    jsonb_build_object('gl_account_id', v_expense, 'debit', NEW.cost),
    jsonb_build_object('gl_account_id', v_ap, 'credit', NEW.cost)
  );

  PERFORM post_journal_entry(NEW.tenant_id, 'machine_fuel_log', NEW.id, NEW.log_date,
    'Machine fuel: ' || coalesce(v_machine_label, NEW.machine_id::text), v_lines);

  RETURN NEW;
END;
$$;


--
-- Name: trg_post_payroll_run_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_post_payroll_run_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_salaries_expense uuid; v_salaries_payable uuid; v_paye_payable uuid; v_nssf_payable uuid;
  v_totals record;
  v_lines jsonb;
begin
  if new.status != 'approved' or old.status = 'approved' then
    return new;
  end if;

  v_salaries_expense := get_posting_account(new.tenant_id, 'salaries_expense');
  v_salaries_payable := get_posting_account(new.tenant_id, 'salaries_payable');
  v_paye_payable := get_posting_account(new.tenant_id, 'paye_payable');
  v_nssf_payable := get_posting_account(new.tenant_id, 'nssf_payable');
  if v_salaries_expense is null or v_salaries_payable is null
     or v_paye_payable is null or v_nssf_payable is null then
    -- Payroll roles not fully mapped yet -- skip posting rather than
    -- guess. The run still approves normally.
    return new;
  end if;

  select
    coalesce(sum(basic_salary + allowances - deductions), 0) as gross_expense,
    coalesce(sum(nssf_employer), 0) as employer_nssf,
    coalesce(sum(net_pay), 0) as total_net_pay,
    coalesce(sum(paye_amount), 0) as total_paye,
    coalesce(sum(nssf_employee + nssf_employer), 0) as total_nssf
  into v_totals
  from hr_payroll_items
  where payroll_run_id = new.id;

  if v_totals.gross_expense = 0 then
    return new;  -- nothing to post (no line items)
  end if;

  v_lines := jsonb_build_array(
    jsonb_build_object('gl_account_id', v_salaries_expense, 'debit', v_totals.gross_expense)
  );
  if v_totals.employer_nssf > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_salaries_expense, 'debit', v_totals.employer_nssf);
  end if;
  if v_totals.total_net_pay > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_salaries_payable, 'credit', v_totals.total_net_pay);
  end if;
  if v_totals.total_paye > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_paye_payable, 'credit', v_totals.total_paye);
  end if;
  if v_totals.total_nssf > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_nssf_payable, 'credit', v_totals.total_nssf);
  end if;

  perform post_journal_entry(new.tenant_id, 'payroll_run', new.id, coalesce(new.approved_at::date, current_date),
    'Payroll run ' || new.period, v_lines);

  return new;
end;
$$;


--
-- Name: trg_post_receivable_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_post_receivable_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ar uuid; v_revenue uuid; v_vat_out uuid;
  v_net numeric;
  v_lines jsonb;
begin
  v_ar := get_posting_account(new.tenant_id, 'ar_control');
  v_revenue := get_posting_account(new.tenant_id, 'default_revenue');
  if v_ar is null or v_revenue is null then
    return new;
  end if;

  v_net := new.amount_incl_vat - new.vat_amount;

  v_lines := jsonb_build_array(
    jsonb_build_object('gl_account_id', v_ar, 'debit', new.amount_incl_vat, 'currency', new.currency),
    jsonb_build_object('gl_account_id', v_revenue, 'credit', v_net, 'currency', new.currency)
  );
  if new.vat_amount > 0 then
    v_vat_out := get_posting_account(new.tenant_id, 'vat_output');
    if v_vat_out is null then
      return new;
    end if;
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_vat_out, 'credit', new.vat_amount, 'currency', new.currency);
  end if;

  perform post_journal_entry(new.tenant_id, 'receivable_invoice', new.id, new.invoice_date,
    'Receivable invoice ' || new.invoice_number, v_lines);

  return new;
end;
$$;


--
-- Name: trg_post_supplier_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_post_supplier_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_expense uuid; v_vat_in uuid; v_wht uuid; v_ap uuid;
  v_net numeric;
  v_ap_amount numeric;
  v_lines jsonb;
begin
  v_expense := get_posting_account(new.tenant_id, 'default_expense');
  v_ap := get_posting_account(new.tenant_id, 'ap_control');
  if v_expense is null or v_ap is null then
    -- Tenant hasn't set up (or hasn't finished setting up) their
    -- posting rules yet -- skip posting rather than fail the insert.
    return new;
  end if;

  if new.wht_amount > 0 then
    v_wht := get_posting_account(new.tenant_id, 'wht_payable');
    if v_wht is null then
      -- Can't post correctly without knowing where the withheld
      -- amount goes -- skip the whole entry.
      return new;
    end if;
  end if;

  v_net := new.amount_incl_vat - new.vat_amount;
  v_ap_amount := new.amount_incl_vat - new.wht_amount;

  v_lines := jsonb_build_array(
    jsonb_build_object('gl_account_id', v_expense, 'debit', v_net, 'currency', new.currency)
  );
  if new.vat_amount > 0 then
    v_vat_in := get_posting_account(new.tenant_id, 'vat_input');
    if v_vat_in is null then
      return new;
    end if;
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_vat_in, 'debit', new.vat_amount, 'currency', new.currency);
  end if;
  if new.wht_amount > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_wht, 'credit', new.wht_amount, 'currency', new.currency);
  end if;
  if v_ap_amount > 0 then
    v_lines := v_lines || jsonb_build_object('gl_account_id', v_ap, 'credit', v_ap_amount, 'currency', new.currency);
  end if;

  perform post_journal_entry(new.tenant_id, 'supplier_invoice', new.id, new.invoice_date,
    'Supplier invoice ' || new.invoice_number, v_lines);

  return new;
end;
$$;


--
-- Name: try_complete_po(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_complete_po(p_purchase_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_po      purchase_orders%rowtype;
  v_invoice supplier_invoices%rowtype;
  v_request requests%rowtype;
begin
  select * into v_po from purchase_orders where id = p_purchase_order_id;
  if not found or v_po.completed_at is not null or v_po.delivered_at is null then
    return; -- nothing to do: unknown PO, already settled, or not yet delivered
  end if;

  select * into v_invoice from supplier_invoices where purchase_order_id = p_purchase_order_id;
  if not found then
    return; -- no invoice recorded against this PO yet
  end if;

  if supplier_invoice_outstanding(v_invoice.id) > 0 then
    return; -- still owing
  end if;

  update purchase_orders set completed_at = now() where id = p_purchase_order_id;

  select * into v_request from requests where id = v_po.request_id;
  insert into notifications (tenant_id, recipient_id, type, title, body, request_id, purchase_order_id)
  values (
    v_request.tenant_id,
    v_request.requester_id,
    'po_completed',
    'Purchase order settled',
    format('PO %s (%s) has been paid in full and is now complete.', v_po.po_number, v_po.vendor_name),
    v_request.id,
    v_po.id
  );
end;
$$;


--
-- Name: unlink_ticket_from_problem(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlink_ticket_from_problem(p_problem_id uuid, p_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_it_support() then
    raise exception 'not authorized to unlink tickets from problems';
  end if;
  delete from problem_tickets
  where problem_id = p_problem_id and ticket_id = p_ticket_id and tenant_id = get_my_tenant_id();
end;
$$;


--
-- Name: unmatch_bank_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmatch_bank_reconciliation(p_reconciliation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare pid uuid; sid uuid;
begin
 select settlement_id into sid from bank_reconciliations where id=p_reconciliation_id and tenant_id=get_my_tenant_id();
 select c.policy_id into pid from ins_policy_cancellations c where c.tenant_id=get_my_tenant_id() and
 (exists(select 1 from ins_cancellation_cash_requests q where q.cancellation_id=c.id and sid in(q.settlement_id,q.to_settlement_id)) or exists(select 1 from ins_policy_cash_items k join fin_allocations a on a.open_item_id=k.id where k.source_id=c.policy_id and a.settlement_id=sid));
 if pid is not null then perform ins_policy_cash_require_finance(); perform id from ins_policies where id=pid for update; end if;
 perform platform_ins_cxl_before_unmatch(p_reconciliation_id);
end $$;


--
-- Name: update_app_user(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_app_user(p_user_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_role_title text DEFAULT NULL::text, p_is_platform_admin boolean DEFAULT NULL::boolean) RETURNS public.app_users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user public.app_users%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to manage accounts';
  end if;
  select * into v_user from app_users where id = p_user_id for update;
  if not found or v_user.tenant_id != get_my_tenant_id() then
    raise exception 'user not found';
  end if;
  if p_is_platform_admin is not null and p_is_platform_admin is distinct from v_user.is_platform_admin then
    raise exception 'Platform admin status is managed from the platform console (Team), not from account management';
  end if;

  update app_users
  set department_id = coalesce(p_department_id, department_id),
      role_title = coalesce(p_role_title, role_title)
  where id = p_user_id
  returning * into v_user;

  return v_user;
end;
$$;


--
-- Name: update_asset(uuid, text, text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_asset(p_asset_id uuid, p_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_serial_number text DEFAULT NULL::text, p_vendor text DEFAULT NULL::text, p_purchase_cost numeric DEFAULT NULL::numeric, p_status text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS public.assets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_asset public.assets%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to update assets';
  end if;
  select * into v_asset from assets where id = p_asset_id for update;
  if not found then
    raise exception 'asset not found';
  end if;
  if v_asset.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this asset';
  end if;
  -- 'assigned' status is only set via assign_asset/return_asset, not here
  if p_status is not null and p_status not in ('in_stock','maintenance','retired') then
    raise exception 'invalid status for direct update: %', p_status;
  end if;
  if p_status is not null and v_asset.status = 'assigned' then
    raise exception 'asset is currently assigned; return it before changing status';
  end if;

  update assets
  set name = coalesce(p_name, name),
      category = coalesce(p_category, category),
      serial_number = coalesce(p_serial_number, serial_number),
      vendor = coalesce(p_vendor, vendor),
      purchase_cost = coalesce(p_purchase_cost, purchase_cost),
      status = coalesce(p_status, status),
      notes = coalesce(p_notes, notes),
      updated_at = now()
  where id = p_asset_id
  returning * into v_asset;

  return v_asset;
end;
$$;


