--
-- Name: update_ticket_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_ticket_status(p_ticket_id uuid, p_status text, p_resolution_notes text DEFAULT NULL::text) RETURNS public.it_tickets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ticket public.it_tickets%rowtype;
begin
  if p_status not in ('open','in_progress','resolved','closed') then
    raise exception 'invalid status: %', p_status;
  end if;
  if not is_it_support() then
    raise exception 'not authorized to update ticket status';
  end if;

  select * into v_ticket from it_tickets where id = p_ticket_id for update;
  if not found then
    raise exception 'ticket not found';
  end if;
  if v_ticket.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this ticket';
  end if;
  if v_ticket.approval_status = 'pending' and p_status = 'in_progress' then
    raise exception 'ticket is awaiting approval and cannot be actioned yet';
  end if;

  update it_tickets
  set status = p_status,
      resolution_notes = coalesce(p_resolution_notes, resolution_notes),
      resolved_at = case when p_status = 'resolved' and resolved_at is null then now() else resolved_at end,
      closed_at = case when p_status = 'closed' and closed_at is null then now() else closed_at end,
      updated_at = now()
  where id = p_ticket_id
  returning * into v_ticket;

  insert into notifications (tenant_id, recipient_id, type, title, body)
  values (
    v_ticket.tenant_id,
    v_ticket.requester_id,
    'ticket_status_changed',
    'Ticket ' || v_ticket.ticket_number || ' updated',
    format('Your ticket "%s" is now %s.', v_ticket.subject, p_status)
  );

  return v_ticket;
end;
$$;


--
-- Name: update_workflow_stage_approver_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_workflow_stage_approver_role(p_stage_id uuid, p_approver_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_stage workflow_stages%rowtype;
  v_new_role text;
begin
  perform require_platform_admin('Editing workflow stage approver labels');

  v_new_role := btrim(p_approver_role);
  if v_new_role is null or v_new_role = '' then
    raise exception 'approver_role must not be blank';
  end if;

  select * into v_stage
  from workflow_stages
  where id = p_stage_id;

  if not found then
    raise exception 'workflow stage not found';
  end if;

  if v_stage.approver_role = v_new_role then
    return;
  end if;

  update workflow_stages
  set approver_role = v_new_role
  where id = p_stage_id;

  perform log_platform_event(
    'workflow.approver_role.update', v_stage.tenant_id, 'workflow_stage', p_stage_id::text, null,
    jsonb_build_object('stage_name', v_stage.name, 'approver_role', v_stage.approver_role),
    jsonb_build_object('stage_name', v_stage.name, 'approver_role', v_new_role)
  );
end;
$$;


--
-- Name: update_workflow_stage_threshold(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_workflow_stage_threshold(p_stage_id uuid, p_threshold_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_stage workflow_stages%rowtype;
begin
  perform require_platform_admin('Editing workflow stage thresholds');

  if p_threshold_amount is null or p_threshold_amount < 0 then
    raise exception 'threshold_amount must be a non-negative number';
  end if;

  select * into v_stage
  from workflow_stages
  where id = p_stage_id;

  if not found then
    raise exception 'workflow stage not found';
  end if;

  if v_stage.threshold_amount is null then
    raise exception 'this stage has no threshold branch to edit';
  end if;

  if v_stage.threshold_amount = p_threshold_amount then
    return;
  end if;

  update workflow_stages
  set threshold_amount = p_threshold_amount
  where id = p_stage_id;

  perform log_platform_event(
    'workflow.threshold.update', v_stage.tenant_id, 'workflow_stage', p_stage_id::text, null,
    jsonb_build_object('stage_name', v_stage.name, 'threshold_amount', v_stage.threshold_amount),
    jsonb_build_object('stage_name', v_stage.name, 'threshold_amount', p_threshold_amount)
  );
end;
$$;


--
-- Name: upsert_sla_policy(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_sla_policy(p_priority text, p_target_hours integer, p_description text DEFAULT NULL::text) RETURNS public.sla_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.sla_policies%rowtype;
begin
  if not is_it_support() then
    raise exception 'not authorized to manage SLA policies';
  end if;
  if p_priority not in ('low','medium','high','urgent') then
    raise exception 'invalid priority: %', p_priority;
  end if;

  insert into sla_policies (tenant_id, priority, target_hours, description)
  values (get_my_tenant_id(), p_priority, p_target_hours, p_description)
  on conflict (tenant_id, priority)
  do update set target_hours = excluded.target_hours, description = excluded.description, updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: void_journal_entry(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_journal_entry(p_entry_id uuid, p_reason text) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_entry journal_entries%rowtype;
  v_reversal journal_entries%rowtype;
  v_lines jsonb;
  v_reason text := nullif(btrim(p_reason), '');
begin
  if v_reason is null or length(v_reason) < 5 then
    raise exception 'A reason (at least 5 characters) is required to void a journal entry';
  end if;

  if not is_finance_team_member('finance') then
    raise exception 'not authorized to void journal entries';
  end if;

  select * into v_entry from journal_entries where id = p_entry_id for update;
  if not found then
    raise exception 'journal entry not found';
  end if;
  if v_entry.tenant_id != get_my_tenant_id() then
    raise exception 'not authorized for this journal entry';
  end if;
  if v_entry.status = 'void' then
    return v_entry;
  end if;

  -- Check closed period for reversal date (today)
  if exists (
    select 1 from accounting_periods
    where tenant_id = v_entry.tenant_id
      and status = 'closed'
      and current_date between period_start and period_end
  ) then
    raise exception 'cannot void in closed period - current date % is in closed period', current_date;
  end if;

  -- Build reversal lines (swap debit/credit), keeping each line's currency, its
  -- original rate and its rounding flag so the base amounts negate exactly.
  select jsonb_agg(
    jsonb_build_object(
      'gl_account_id', jel.gl_account_id,
      'debit', jel.credit,
      'credit', jel.debit,
      'currency', jel.currency,
      'fx_rate', jel.fx_rate,
      'is_rounding', jel.is_rounding,
      'description', 'Reversal of ' || v_entry.id::text || ': ' || coalesce(jel.description, '')
    )
  ) into v_lines
  from journal_entry_lines jel
  where jel.journal_entry_id = v_entry.id;

  -- Allow status update via session variable
  perform set_config('app.allow_journal_void', 'true', true);
  update journal_entries set status = 'void' where id = p_entry_id returning * into v_entry;
  perform set_config('app.allow_journal_void', 'false', true);

  -- Post reversal in reversal mode: the line guard keeps the original rates, but
  -- only rates the entry being reversed already used.
  perform set_config('fin.reversal_of', v_entry.id::text, true);
  select * into v_reversal from post_journal_entry(
    v_entry.tenant_id,
    'manual',
    null,
    current_date,
    'Reversal of ' || v_entry.id::text || ' — ' || v_reason,
    v_lines
  );
  perform set_config('fin.reversal_of', '', true);

  perform log_platform_event(
    'journal.void', v_entry.tenant_id, 'journal_entry', p_entry_id::text, v_reason,
    jsonb_build_object('original_entry', v_entry.id, 'original_status', 'posted'),
    jsonb_build_object('reversal_entry', v_reversal.id, 'reason', v_reason)
  );

  return v_reversal;
end;
$$;


