--
-- Name: fin_open_item_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fin_open_item_balances WITH (security_invoker='true') AS
 SELECT i.id,
    i.tenant_id,
    i.party_account_id,
    i.side,
    i.control_role,
    i.source_type,
    i.source_id,
    i.document_no,
    i.document_date,
    i.due_date,
    i.currency,
    i.amount,
    i.description,
    COALESCE(a.allocated, (0)::numeric) AS allocated_amount,
    ((i.amount - COALESCE(a.allocated, (0)::numeric)) - COALESCE(c.credited, (0)::numeric)) AS outstanding_amount,
        CASE
            WHEN ((COALESCE(a.allocated, (0)::numeric) + COALESCE(c.credited, (0)::numeric)) = (0)::numeric) THEN 'open'::text
            WHEN ((COALESCE(a.allocated, (0)::numeric) + COALESCE(c.credited, (0)::numeric)) < i.amount) THEN 'partly_settled'::text
            ELSE 'settled'::text
        END AS settlement_status,
    COALESCE(c.credited, (0)::numeric) AS credited_amount,
    i.fx_rate,
    round((((i.amount - COALESCE(a.allocated, (0)::numeric)) - COALESCE(c.credited, (0)::numeric)) * i.fx_rate), 2) AS base_outstanding_amount
   FROM ((public.fin_open_items i
     LEFT JOIN LATERAL ( SELECT sum(al.amount) AS allocated
           FROM (public.fin_allocations al
             JOIN public.fin_settlements s ON ((s.id = al.settlement_id)))
          WHERE ((al.open_item_id = i.id) AND (s.status = 'posted'::text))) a ON (true))
     LEFT JOIN LATERAL ( SELECT sum(ca.amount) AS credited
           FROM (public.fin_credit_applications ca
             JOIN public.fin_credit_notes cn ON ((cn.id = ca.credit_note_id)))
          WHERE ((ca.open_item_id = i.id) AND (cn.status = 'posted'::text))) c ON (true));


--
-- Name: fin_unregistered_bank_accounts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fin_unregistered_bank_accounts WITH (security_invoker='true') AS
 SELECT tenant_id,
    name,
    (count(*))::integer AS row_count,
    array_agg(DISTINCT source ORDER BY source) AS sources,
    max(seen_on) AS last_seen_on
   FROM ( SELECT t.tenant_id,
            btrim(t.bank_account) AS name,
            'cash_bank_transactions'::text AS source,
            t.transaction_date AS seen_on
           FROM public.cash_bank_transactions t
          WHERE ((t.bank_account IS NOT NULL) AND (btrim(t.bank_account) <> ''::text))
        UNION ALL
         SELECT l.tenant_id,
            btrim(l.bank_account) AS btrim,
            'bank_statement_lines'::text,
            l.statement_date
           FROM public.bank_statement_lines l
          WHERE ((l.bank_account IS NOT NULL) AND (btrim(l.bank_account) <> ''::text))) u
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.fin_bank_accounts b
          WHERE ((b.tenant_id = u.tenant_id) AND (b.name = u.name)))))
  GROUP BY tenant_id, name;


