--

CREATE TABLE public.ins_cancellation_insurer_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    cancellation_id uuid NOT NULL,
    insurer_id uuid NOT NULL,
    insurer_share_id uuid,
    original_item_id uuid NOT NULL,
    original_commission_entry_id uuid,
    original_commission_state jsonb,
    return_premium numeric(18,2) NOT NULL,
    commission_clawback numeric(18,2) NOT NULL,
    pass_through_refund numeric(18,2) NOT NULL,
    total_insurer_credit numeric(18,2) NOT NULL,
    payable_credit numeric(18,2) NOT NULL,
    recovery_due numeric(18,2) NOT NULL,
    recovery_item_id uuid,
    retained_commission numeric(18,2) NOT NULL,
    retained_commission_status text NOT NULL,
    transferred_clawback_due numeric(18,2) NOT NULL,
    CONSTRAINT ins_cancellation_insurer_adjus_retained_commission_status_check CHECK ((retained_commission_status = ANY (ARRAY['deferred'::text, 'earned'::text, 'transferred'::text, 'legacy'::text]))),
    CONSTRAINT ins_cancellation_insurer_adjustm_transferred_clawback_due_check CHECK ((transferred_clawback_due >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_check CHECK ((total_insurer_credit = ((return_premium - commission_clawback) + pass_through_refund))),
    CONSTRAINT ins_cancellation_insurer_adjustments_check1 CHECK ((total_insurer_credit = (payable_credit + recovery_due))),
    CONSTRAINT ins_cancellation_insurer_adjustments_commission_clawback_check CHECK ((commission_clawback >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_pass_through_refund_check CHECK ((pass_through_refund >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_payable_credit_check CHECK ((payable_credit >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_recovery_due_check CHECK ((recovery_due >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_retained_commission_check CHECK ((retained_commission >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_return_premium_check CHECK ((return_premium >= (0)::numeric)),
    CONSTRAINT ins_cancellation_insurer_adjustments_total_insurer_credit_check CHECK ((total_insurer_credit >= (0)::numeric))
);


