    revised_by uuid DEFAULT auth.uid(),
    revised_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ins_claim_reserve_history_amount_check CHECK (((new_amount >= (0)::numeric) AND ((previous_amount IS NULL) OR (previous_amount >= (0)::numeric)))),
    CONSTRAINT ins_claim_reserve_history_kind_check CHECK ((kind = ANY (ARRAY['initial'::text, 'revision'::text]))),
    CONSTRAINT ins_claim_reserve_history_reason_check CHECK ((char_length(btrim(reason)) >= 5)),
    CONSTRAINT ins_claim_reserve_history_shape_check CHECK ((((kind = 'initial'::text) AND (previous_amount IS NULL)) OR ((kind = 'revision'::text) AND (previous_amount IS NOT NULL) AND (previous_amount <> new_amount))))
);


--
-- Name: ins_client_statement; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_client_statement AS
 SELECT p.tenant_id,
    p.id AS policy_id,
    p.policy_no,
    p.client_id,
    bd.name AS client_name,
    p.currency,
    (p.gross_premium + COALESCE(e.delta, (0)::numeric)) AS billed_amount,
    COALESCE(r.received, (0)::numeric) AS received_amount,
    ((p.gross_premium + COALESCE(e.delta, (0)::numeric)) - COALESCE(r.received, (0)::numeric)) AS balance_amount,
    (p.bound_at)::date AS bound_date,
    p.expiry_date,
    p.status
   FROM ((((public.ins_policies p
     JOIN public.ins_clients c ON ((c.id = p.client_id)))
     JOIN public.bd_clients bd ON ((bd.id = c.client_id)))
     LEFT JOIN LATERAL ( SELECT sum(((x.calculation ->> 'premium_delta'::text))::numeric) AS delta
           FROM public.ins_policy_endorsements x
          WHERE ((x.tenant_id = p.tenant_id) AND (x.policy_id = p.id) AND (x.status = 'posted'::text))) e ON (true))
     LEFT JOIN LATERAL ( SELECT (( SELECT COALESCE(sum(q.amount), (0)::numeric) AS "coalesce"
                   FROM public.ins_policy_cash_requests q
                  WHERE ((q.tenant_id = p.tenant_id) AND (q.policy_id = p.id) AND (q.kind = 'receipt'::text) AND (q.status = 'posted'::text))) + ( SELECT COALESCE(sum(a.amount), (0)::numeric) AS "coalesce"
                   FROM (((public.ins_policy_endorsements x
                     JOIN public.fin_open_items oi ON (((oi.source_id = x.id) AND (oi.tenant_id = x.tenant_id) AND (oi.source_type = 'ins_policy_endorsement'::text))))
                     JOIN public.fin_allocations a ON (((a.open_item_id = oi.id) AND (a.tenant_id = oi.tenant_id))))
                     JOIN public.fin_settlements s ON (((s.id = a.settlement_id) AND (s.tenant_id = a.tenant_id))))
                  WHERE ((x.policy_id = p.id) AND (x.tenant_id = p.tenant_id) AND (s.status = 'posted'::text) AND (s.direction = 'in'::text)))) AS received) r ON (true))
  WHERE ((p.status = ANY (ARRAY['active'::text, 'renewed'::text])) AND (p.tenant_id = public.get_my_tenant_id()) AND public.can_access_insurance());


