    reviewed boolean DEFAULT false NOT NULL,
    CONSTRAINT ins_policy_insurer_shares_commission_rate_pct_check CHECK (((commission_rate_pct >= (0)::numeric) AND (commission_rate_pct < (100)::numeric))),
    CONSTRAINT ins_policy_insurer_shares_share_pct_check CHECK (((share_pct > (0)::numeric) AND (share_pct <= (100)::numeric)))
);


--
-- Name: ins_commission_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_commission_ledger WITH (security_invoker='true') AS
 SELECT e.id,
    e.tenant_id,
    e.policy_id,
    p.policy_no,
    COALESCE(s.insurer_id, p.insurer_id) AS insurer_id,
    p.client_id,
    COALESCE(a.retained_commission, e.amount) AS amount,
        CASE
            WHEN (a.id IS NULL) THEN e.status
            WHEN (a.retained_commission_status = 'transferred'::text) THEN 'transferred'::text
            WHEN ((COALESCE(w.amount, (0)::numeric) >= a.retained_commission) AND (a.retained_commission > (0)::numeric)) THEN 'transferred'::text
            WHEN ((a.retained_commission_status = 'deferred'::text) AND (COALESCE(r.amount, (0)::numeric) = (0)::numeric)) THEN 'deferred'::text
            ELSE 'earned'::text
        END AS status,
    COALESCE(e.earned_on,
        CASE
            WHEN (a.retained_commission_status = 'earned'::text) THEN c.posting_date
            WHEN (COALESCE(r.amount, (0)::numeric) > (0)::numeric) THEN r.earned_on
            ELSE NULL::date
        END) AS earned_on,
    e.transfer_id,
    t.transfer_no,
    t.transfer_date,
    e.created_at,
    e.updated_at,
    e.insurer_share_id,
    ((COALESCE(s.premium_amount, p.gross_premium) - COALESCE(a.return_premium, (0)::numeric)))::numeric(18,2) AS allocated_premium,
    COALESCE(s.commission_rate_pct, p.commission_rate_pct) AS commission_rate_pct,
        CASE
            WHEN (a.id IS NULL) THEN
            CASE
                WHEN (e.status = ANY (ARRAY['earned'::text, 'transferred'::text])) THEN e.amount
                ELSE (0)::numeric
            END
            WHEN ((a.retained_commission_status <> 'deferred'::text) OR (COALESCE(r.amount, (0)::numeric) > (0)::numeric)) THEN a.retained_commission
            ELSE (0)::numeric
        END AS earned_commission,
        CASE
            WHEN (a.id IS NULL) THEN
            CASE
                WHEN (e.status = 'transferred'::text) THEN (0)::numeric
                ELSE e.amount
            END
            WHEN (a.retained_commission_status = 'transferred'::text) THEN (0)::numeric
            ELSE GREATEST((a.retained_commission - COALESCE(w.amount, (0)::numeric)), (0)::numeric)
        END AS untransferred_commission,
    c.id AS cancellation_id
   FROM (((((((public.ins_commission_entries e
     JOIN public.ins_policies p ON ((p.id = e.policy_id)))
     LEFT JOIN public.ins_policy_insurer_shares s ON (((s.id = e.insurer_share_id) AND (s.tenant_id = e.tenant_id))))
     LEFT JOIN public.ins_commission_transfers t ON ((t.id = e.transfer_id)))
     LEFT JOIN public.ins_cancellation_insurer_adjustments a ON ((a.original_commission_entry_id = e.id)))
     LEFT JOIN public.ins_policy_cancellations c ON ((c.id = a.cancellation_id)))
     LEFT JOIN LATERAL ( SELECT sum(ev.amount) AS amount,
            max(j.entry_date) FILTER (WHERE (ev.amount > (0)::numeric)) AS earned_on
           FROM (public.ins_cancellation_commission_events ev
             JOIN public.journal_entries j ON ((j.id = ev.journal_entry_id)))
          WHERE (ev.adjustment_id = a.id)) r ON (true))
     LEFT JOIN LATERAL ( SELECT sum(ins_cancellation_cash_requests.amount) AS amount
           FROM public.ins_cancellation_cash_requests
          WHERE ((ins_cancellation_cash_requests.adjustment_id = a.id) AND (ins_cancellation_cash_requests.kind = 'commission_withdrawal'::text) AND (ins_cancellation_cash_requests.status = 'posted'::text))) w ON (true))
  WHERE (p.status <> 'reversed'::text);


--
-- Name: ins_commission_position; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_commission_position WITH (security_invoker='true') AS
 SELECT tenant_id,
    COALESCE(sum(amount) FILTER (WHERE (status = 'deferred'::text)), (0)::numeric) AS unearned_amount,
    COALESCE(sum(untransferred_commission) FILTER (WHERE (status = 'earned'::text)), (0)::numeric) AS earned_in_client_money,
    COALESCE(sum((amount - untransferred_commission)) FILTER (WHERE (status = ANY (ARRAY['earned'::text, 'transferred'::text]))), (0)::numeric) AS transferred_amount
   FROM public.ins_commission_ledger
  GROUP BY tenant_id;


