--
-- Name: ins_policy_cash_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_policy_cash_items WITH (security_invoker='true') AS
 SELECT i.id,
    i.tenant_id,
    i.party_account_id,
    i.side,
    i.control_role,
        CASE i.source_type
            WHEN 'ins_policy_share_insurer'::text THEN 'ins_policy_insurer'::text
            ELSE i.source_type
        END AS source_type,
        CASE i.source_type
            WHEN 'ins_policy_share_insurer'::text THEN s.policy_id
            ELSE i.source_id
        END AS source_id,
    s.id AS insurer_share_id
   FROM (public.fin_open_items i
     LEFT JOIN public.ins_policy_insurer_shares s ON (((i.source_type = 'ins_policy_share_insurer'::text) AND (s.id = i.source_id) AND (s.tenant_id = i.tenant_id))));


