--
-- Name: ins_production_book; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_production_book AS
 SELECT p.tenant_id,
    p.id AS policy_id,
    p.policy_no,
    p.status,
    p.transaction_type,
    (p.bound_at)::date AS bound_date,
    p.client_id,
    bd.name AS client_name,
    p.insurer_id,
    i.name AS insurer_name,
    p.product_line_id,
    pl.name AS product_line_name,
    p.branch_id,
    o.site_name AS branch_name,
    p.agent_id,
    m.name AS agent_name,
    p.currency,
    p.gross_premium,
    p.commission_amount,
    p.net_premium_to_insurer
   FROM ((((((public.ins_policies p
     JOIN public.ins_clients c ON ((c.id = p.client_id)))
     LEFT JOIN public.bd_clients bd ON ((bd.id = c.client_id)))
     JOIN public.ins_insurers i ON ((i.id = p.insurer_id)))
     JOIN public.ins_product_lines pl ON ((pl.id = p.product_line_id)))
     LEFT JOIN public.organizations o ON ((o.id = p.branch_id)))
     LEFT JOIN public.ins_intermediaries m ON ((m.id = p.agent_id)))
  WHERE ((p.status = ANY (ARRAY['active'::text, 'renewed'::text])) AND (p.tenant_id = public.get_my_tenant_id()) AND public.can_access_insurance());


--
-- Name: ins_renewal_pipeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ins_renewal_pipeline WITH (security_invoker='true') AS
 SELECT p.tenant_id,
    p.id AS policy_id,
    p.policy_no,
    p.client_id AS ins_client_id,
    bc.name AS client_name,
    p.insurer_id,
    i.name AS insurer_name,
    p.product_line_id,
    pl.name AS product_name,
    p.inception_date,
    p.expiry_date,
    (p.expiry_date - CURRENT_DATE) AS days_to_expiry,
    p.gross_premium,
    p.commission_rate_pct,
    p.currency,
    ( SELECT d.id
           FROM public.ins_policies d
          WHERE ((d.renewal_of_id = p.id) AND (d.status = 'draft'::text))
         LIMIT 1) AS renewal_draft_id,
    ( SELECT o.outcome
           FROM public.ins_renewal_outcomes o
          WHERE ((o.policy_id = p.id) AND (o.tenant_id = p.tenant_id))) AS renewal_outcome,
    ( SELECT o.reason
           FROM public.ins_renewal_outcomes o
          WHERE ((o.policy_id = p.id) AND (o.tenant_id = p.tenant_id))) AS renewal_outcome_reason
   FROM ((((public.ins_policies p
     JOIN public.ins_clients c ON ((c.id = p.client_id)))
     JOIN public.bd_clients bc ON ((bc.id = c.client_id)))
     JOIN public.ins_insurers i ON ((i.id = p.insurer_id)))
     JOIN public.ins_product_lines pl ON ((pl.id = p.product_line_id)))
  WHERE ((p.status = 'active'::text) AND (p.expiry_date <= (CURRENT_DATE + 120)));


