    CONSTRAINT ins_risks_description_check CHECK ((length(btrim(description)) > 0)),
    CONSTRAINT ins_risks_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT ins_risks_sum_check CHECK ((sum_insured >= (0)::numeric)),
    CONSTRAINT ins_risks_type_check CHECK ((risk_type = ANY (ARRAY['vehicle'::text, 'property'::text, 'other'::text]))),
    CONSTRAINT ins_risks_year_check CHECK (((year_made IS NULL) OR ((year_made >= 1950) AND (year_made <= 2100))))
