--
-- Name: journal_entry_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entry_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    journal_entry_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    gl_account_id uuid NOT NULL,
    debit numeric DEFAULT 0 NOT NULL,
    credit numeric DEFAULT 0 NOT NULL,
    currency text NOT NULL,
    description text,
    fx_rate numeric(20,8) DEFAULT 1 NOT NULL,
    base_debit numeric GENERATED ALWAYS AS (
CASE
    WHEN (fx_rate = (1)::numeric) THEN debit
    ELSE round((debit * fx_rate), 2)
END) STORED,
    base_credit numeric GENERATED ALWAYS AS (
CASE
    WHEN (fx_rate = (1)::numeric) THEN credit
    ELSE round((credit * fx_rate), 2)
END) STORED,
    is_rounding boolean DEFAULT false NOT NULL,
    CONSTRAINT journal_entry_lines_credit_check CHECK ((credit >= (0)::numeric)),
    CONSTRAINT journal_entry_lines_debit_check CHECK ((debit >= (0)::numeric)),
    CONSTRAINT journal_entry_lines_fx_rate_8dp CHECK ((fx_rate = round(fx_rate, 8))),
    CONSTRAINT journal_entry_lines_fx_rate_check CHECK ((fx_rate > (0)::numeric)),
    CONSTRAINT journal_entry_lines_one_side_check CHECK ((((debit > (0)::numeric) AND (credit = (0)::numeric)) OR ((credit > (0)::numeric) AND (debit = (0)::numeric))))
);


