    CONSTRAINT supplier_invoices_vat_amount_check CHECK ((vat_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_wht_amount_check CHECK (((wht_amount >= (0)::numeric) AND (wht_amount <= amount_incl_vat))),
    CONSTRAINT supplier_invoices_wht_rate_check CHECK (((wht_rate IS NULL) OR ((wht_rate >= (0)::numeric) AND (wht_rate <= (100)::numeric))))
