--
-- Name: v_account_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_account_ledger WITH (security_invoker='true') AS
 SELECT jel.tenant_id,
    jel.gl_account_id AS account_id,
    je.source_type,
    je.source_id,
    je.description AS reference_no,
    je.entry_date AS transaction_date,
    jel.debit,
    jel.credit,
    jel.currency,
    jel.base_debit,
    jel.base_credit,
    jel.fx_rate
   FROM (public.journal_entry_lines jel
     JOIN public.journal_entries je ON ((je.id = jel.journal_entry_id)))
  WHERE (je.status = 'posted'::text);


--
-- Name: v_advance_payments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_advance_payments AS
 SELECT ap.id,
    ap.tenant_id,
    ap.account_id,
    a.account_code,
    a.name AS account_name,
    ap.direction,
    ap.amount,
    ap.currency,
    ap.payment_date,
    ap.payment_method,
    ap.description,
    COALESCE(applied.total_applied, (0)::numeric) AS total_applied,
    (ap.amount - COALESCE(applied.total_applied, (0)::numeric)) AS remaining_amount
   FROM ((public.advance_payments ap
     JOIN public.accounts a ON ((a.id = ap.account_id)))
     LEFT JOIN ( SELECT advance_payment_applications.advance_payment_id,
            sum(advance_payment_applications.applied_amount) AS total_applied
           FROM public.advance_payment_applications
          GROUP BY advance_payment_applications.advance_payment_id) applied ON ((applied.advance_payment_id = ap.id)));


--
-- Name: v_bank_possible_double_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bank_possible_double_entries WITH (security_invoker='true') AS
 SELECT l.id AS statement_line_id,
    l.tenant_id,
    l.bank_account,
    l.statement_date,
    l.description,
    l.reference,
    l.amount,
    l.currency,
    c.cash_bank_transaction_ids,
    c.settlement_ids,
    c.transfer_ids
   FROM ((public.bank_statement_lines l
     LEFT JOIN public.bank_reconciliations r ON ((r.bank_statement_line_id = l.id)))
     CROSS JOIN LATERAL ( SELECT array_agg(x.candidate_id) FILTER (WHERE (x.source = 'cash_bank'::text)) AS cash_bank_transaction_ids,
            array_agg(x.candidate_id) FILTER (WHERE (x.source = 'settlement'::text)) AS settlement_ids,
            array_agg(x.candidate_id) FILTER (WHERE (x.source = ANY (ARRAY['transfer_from'::text, 'transfer_to'::text]))) AS transfer_ids
           FROM public.fin_bank_line_candidates(l.id, l.tenant_id) x(source, candidate_id)) c)
  WHERE ((r.id IS NULL) AND (c.cash_bank_transaction_ids IS NOT NULL) AND ((c.settlement_ids IS NOT NULL) OR (c.transfer_ids IS NOT NULL)));


--
-- Name: v_bank_reconciliation_variance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bank_reconciliation_variance WITH (security_invoker='true') AS
 SELECT r.id AS reconciliation_id,
    r.tenant_id,
    r.match_type,
    r.variance,
    r.matched_at,
    l.bank_account,
    l.statement_date,
    l.description AS statement_description,
    l.amount AS statement_amount,
    COALESCE(t.transaction_date, s.settlement_date, ct.transfer_date) AS transaction_date,
    COALESCE(t.description, s.reference, s.notes, ct.notes, ct.transfer_no) AS transaction_description,
    COALESCE(t.amount, s.amount, ct.amount) AS transaction_amount,
    COALESCE(t.transaction_type,
        CASE
            WHEN (ct.id IS NOT NULL) THEN 'transfer'::text
            WHEN (s.direction = 'in'::text) THEN 'receipt'::text
            ELSE 'payment'::text
        END) AS transaction_type,
        CASE
            WHEN (r.commission_transfer_id IS NOT NULL) THEN 'commission_transfer'::text
            WHEN (r.settlement_id IS NULL) THEN 'cash_bank'::text
            ELSE 'settlement'::text
        END AS source,
    r.cash_bank_transaction_id,
    r.settlement_id,
    r.commission_transfer_id
   FROM ((((public.bank_reconciliations r
     JOIN public.bank_statement_lines l ON ((l.id = r.bank_statement_line_id)))
     LEFT JOIN public.cash_bank_transactions t ON ((t.id = r.cash_bank_transaction_id)))
     LEFT JOIN public.fin_settlements s ON ((s.id = r.settlement_id)))
     LEFT JOIN public.ins_commission_transfers ct ON ((ct.id = r.commission_transfer_id)))
  WHERE (r.variance <> (0)::numeric);


--
-- Name: v_bank_statement_unmatched; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_bank_statement_unmatched AS
 SELECT l.id,
    l.tenant_id,
    l.bank_account,
    l.statement_date,
    l.description,
    l.reference,
    l.amount,
    l.currency,
    l.imported_by,
    l.imported_at
   FROM (public.bank_statement_lines l
     LEFT JOIN public.bank_reconciliations r ON ((r.bank_statement_line_id = l.id)))
  WHERE (r.id IS NULL);


--
-- Name: v_cash_bank_unmatched; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cash_bank_unmatched AS
 SELECT t.id,
    t.tenant_id,
    t.transaction_type,
    t.payment_method,
    t.reference_type,
    t.reference_id,
    t.amount,
    t.currency,
    t.transaction_date,
    t.bank_account,
    t.description,
    t.recorded_by,
    t.created_at
   FROM (public.cash_bank_transactions t
     LEFT JOIN public.bank_reconciliations r ON ((r.cash_bank_transaction_id = t.id)))
  WHERE ((t.payment_method = 'bank'::text) AND (r.id IS NULL));


--
-- Name: v_cost_transactions_inquiry; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cost_transactions_inquiry AS
 SELECT supplier_invoices.tenant_id,
    supplier_invoices.cost_center_id,
    'supplier_invoice'::text AS source_type,
    supplier_invoices.id AS source_id,
    supplier_invoices.invoice_number AS reference_no,
    supplier_invoices.invoice_date AS transaction_date,
    supplier_invoices.amount_incl_vat AS amount,
    supplier_invoices.currency
   FROM public.supplier_invoices
  WHERE (supplier_invoices.cost_center_id IS NOT NULL)
UNION ALL
 SELECT expenditure_slips.tenant_id,
    expenditure_slips.cost_center_id,
    'expenditure_slip'::text AS source_type,
    expenditure_slips.id AS source_id,
    expenditure_slips.slip_number AS reference_no,
    expenditure_slips.slip_date AS transaction_date,
    expenditure_slips.amount,
    expenditure_slips.currency
   FROM public.expenditure_slips
UNION ALL
 SELECT r.tenant_id,
    r.cost_center_id,
    'purchase_order'::text AS source_type,
    po.id AS source_id,
    po.po_number AS reference_no,
    (po.generated_at)::date AS transaction_date,
    po.amount,
    'UGX'::text AS currency
   FROM (public.purchase_orders po
     JOIN public.requests r ON ((r.id = po.request_id)))
  WHERE (r.cost_center_id IS NOT NULL);


--
-- Name: v_durations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_durations AS
 SELECT ri.tenant_id,
    'receivable_invoice'::text AS source_type,
    ri.id AS source_id,
    ri.invoice_number,
    ri.invoice_date,
    ri.amount_incl_vat AS outstanding_amount,
    ri.currency,
    ri.status,
    (CURRENT_DATE - ri.invoice_date) AS days_outstanding
   FROM public.receivable_invoices ri
  WHERE (ri.status = 'open'::text)
UNION ALL
 SELECT si.tenant_id,
    'supplier_invoice'::text AS source_type,
    si.id AS source_id,
    si.invoice_number,
    si.invoice_date,
    (si.amount_incl_vat - COALESCE(paid.total_paid, (0)::numeric)) AS outstanding_amount,
    si.currency,
    'open'::text AS status,
    (CURRENT_DATE - si.invoice_date) AS days_outstanding
   FROM (public.supplier_invoices si
     LEFT JOIN ( SELECT cash_bank_transactions.reference_id,
            sum(cash_bank_transactions.amount) AS total_paid
           FROM public.cash_bank_transactions
          WHERE (cash_bank_transactions.reference_type = 'supplier_invoice'::text)
          GROUP BY cash_bank_transactions.reference_id) paid ON ((paid.reference_id = si.id)))
  WHERE ((si.amount_incl_vat - COALESCE(paid.total_paid, (0)::numeric)) > (0)::numeric);


--
-- Name: v_paye_nssf_remittance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_paye_nssf_remittance AS
 SELECT r.tenant_id,
    r.id AS payroll_run_id,
    r.period,
    r.status,
    r.approved_at,
    count(i.id) AS employee_count,
    COALESCE(sum((i.basic_salary + i.allowances)), (0)::numeric) AS total_gross,
    COALESCE(sum(i.paye_amount), (0)::numeric) AS total_paye,
    COALESCE(sum(i.nssf_employee), (0)::numeric) AS total_nssf_employee,
    COALESCE(sum(i.nssf_employer), (0)::numeric) AS total_nssf_employer,
    COALESCE(sum((i.nssf_employee + i.nssf_employer)), (0)::numeric) AS total_nssf,
    COALESCE(sum(i.net_pay), (0)::numeric) AS total_net_pay,
        CASE
            WHEN (r.approved_at IS NOT NULL) THEN (((date_trunc('month'::text, ((r.approved_at)::date)::timestamp with time zone) + '1 mon'::interval) + '14 days'::interval))::date
            ELSE NULL::date
        END AS remittance_due_date
   FROM (public.hr_payroll_runs r
     LEFT JOIN public.hr_payroll_items i ON ((i.payroll_run_id = r.id)))
  WHERE (r.status = ANY (ARRAY['approved'::text, 'disbursed'::text]))
  GROUP BY r.tenant_id, r.id, r.period, r.status, r.approved_at;


--
-- Name: v_payment_plan; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_payment_plan AS
 SELECT si.tenant_id,
    'supplier_invoice'::text AS source_type,
    si.id AS source_id,
    si.invoice_number,
    si.invoice_date,
    si.due_date,
    si.currency,
    (si.amount_incl_vat - COALESCE(paid.total_paid, (0)::numeric)) AS outstanding_amount
   FROM (public.supplier_invoices si
     LEFT JOIN ( SELECT cash_bank_transactions.reference_id,
            sum(cash_bank_transactions.amount) AS total_paid
           FROM public.cash_bank_transactions
          WHERE (cash_bank_transactions.reference_type = 'supplier_invoice'::text)
          GROUP BY cash_bank_transactions.reference_id) paid ON ((paid.reference_id = si.id)))
  WHERE ((si.due_date IS NOT NULL) AND ((si.amount_incl_vat - COALESCE(paid.total_paid, (0)::numeric)) > (0)::numeric))
UNION ALL
 SELECT ri.tenant_id,
    'receivable_invoice'::text AS source_type,
    ri.id AS source_id,
    ri.invoice_number,
    ri.invoice_date,
    ri.due_date,
    ri.currency,
    ri.amount_incl_vat AS outstanding_amount
   FROM public.receivable_invoices ri
  WHERE ((ri.due_date IS NOT NULL) AND (ri.status = 'open'::text));


--
-- Name: workflow_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    sequence_order integer NOT NULL,
    approver_role text NOT NULL,
    threshold_amount numeric(14,2),
    next_stage_low_id uuid,
    next_stage_high_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    requires_offer_entry boolean DEFAULT false NOT NULL,
    blocks_offer_submitter_approval boolean DEFAULT false NOT NULL,
    is_finance_terminal_stage boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    applies_to text DEFAULT 'requests'::text NOT NULL,
    requires_offer_selection boolean DEFAULT false NOT NULL,
    CONSTRAINT workflow_stages_applies_to_check CHECK ((applies_to = ANY (ARRAY['requests'::text, 'invoices'::text])))
);


--
-- Name: v_request_tracking; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_request_tracking AS
 SELECT r.id AS request_id,
    r.mr_number,
    r.created_at AS mr_date,
    r.item_description AS mr_title,
    r.subcontractor,
    r.status,
    r.delivery_date,
    r.organization_id,
    org.company_code,
    org.site_name,
    r.requester_id,
    ru.name AS mr_originator,
    li.cost_code,
    li.place_of_use,
    ws.name AS pending_authority,
    po.id AS purchase_order_id,
    po.po_number,
    po.initial_po_number,
    po.vendor_name AS company,
    po.amount AS po_total,
    po.currency,
    po.generated_by AS po_requester_id,
    gu.name AS po_requester_name,
    po.generated_at AS po_date,
    po.delivered_at,
    po.completed_at AS closing_date
   FROM ((((((public.requests r
     LEFT JOIN public.organizations org ON ((org.id = r.organization_id)))
     LEFT JOIN public.app_users ru ON ((ru.id = r.requester_id)))
     LEFT JOIN LATERAL ( SELECT request_line_items.cost_code,
            request_line_items.place_of_use
           FROM public.request_line_items
          WHERE (request_line_items.request_id = r.id)
          ORDER BY request_line_items.created_at
         LIMIT 1) li ON (true))
     LEFT JOIN public.workflow_stages ws ON ((ws.id = r.current_stage_id)))
     LEFT JOIN public.purchase_orders po ON ((po.request_id = r.id)))
     LEFT JOIN public.app_users gu ON ((gu.id = po.generated_by)));


--
-- Name: v_trial_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_trial_balance AS
 SELECT a.tenant_id,
    a.id AS account_id,
    a.account_code,
    a.name AS account_name,
    a.account_type AS category_name,
    l.currency,
    sum(l.debit) AS total_debit,
    sum(l.credit) AS total_credit,
    (sum(l.debit) - sum(l.credit)) AS balance
   FROM (public.gl_accounts a
     LEFT JOIN public.v_account_ledger l ON ((l.account_id = a.id)))
  GROUP BY a.tenant_id, a.id, a.account_code, a.name, a.account_type, l.currency;


--
-- Name: v_vat_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_vat_report AS
 SELECT supplier_invoices.tenant_id,
