--
-- Name: ins_claim_cash_position _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.ins_claim_cash_position WITH (security_invoker='true') AS
 SELECT c.id AS claim_id,
    c.tenant_id,
    c.claim_no,
    c.status,
    c.payment_mode,
    c.approved_amount,
    c.paid_amount,
    COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'insurer_receipt'::text)), (0)::numeric) AS received_from_insurer,
    COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'client_payout'::text)), (0)::numeric) AS paid_to_client,
    COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'insurer_direct'::text)), (0)::numeric) AS paid_by_insurer_direct,
    (COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'insurer_receipt'::text)), (0)::numeric) - COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'client_payout'::text)), (0)::numeric)) AS held_for_client,
        CASE
            WHEN (c.payment_mode = 'via_broker'::text) THEN (c.approved_amount - COALESCE(sum(p.amount) FILTER (WHERE (p.kind = 'insurer_receipt'::text)), (0)::numeric))
            ELSE NULL::numeric
        END AS due_from_insurer
   FROM (public.ins_claims c
     LEFT JOIN public.ins_claim_payments p ON (((p.claim_id = c.id) AND (p.status = 'posted'::text))))
  WHERE (c.approved_amount IS NOT NULL)
  GROUP BY c.id;


