   FROM public.requests r
  WHERE ((r.id = request_offers.request_id) AND (r.tenant_id = public.get_my_tenant_id()) AND ((r.requester_id = ( SELECT auth.uid() AS uid)) OR public.can_act_on_stage(r.current_stage_id))))));


